    AND l.display_order = seed.lesson_order AND l.title = seed.meaning_vi;

-- JPD123 / Chapter 5 / Ngữ pháp: 17 mục.
INSERT INTO grammar (lesson_id, structure_name, meaning_vi, usage_explanation, example_jp, example_vi, display_order, status)
SELECT l.id, seed.structure_name, seed.meaning_vi, seed.usage_explanation, seed.example_jp, seed.example_vi, 1 AS display_order, seed.status
FROM (
    SELECT 'Vます → Vました。' AS structure_name, 'Động từ quá khứ khẳng định' AS meaning_vi, 'Động từ quá khứ khẳng định (Slot 8–39).' AS usage_explanation, '昨日、デパートへ行きました。' AS example_jp, 'Hôm qua tôi đã đến trung tâm thương mại.' AS example_vi, 1 AS lesson_order, 'PUBLISHED' AS status
    UNION ALL
    SELECT 'Vません → Vませんでした。', 'Động từ quá khứ phủ định', 'Động từ quá khứ phủ định (Slot 8–39).', '昨日、ご飯を食べませんでした。', 'Hôm qua tôi đã không ăn cơm.', 2, 'PUBLISHED'
    UNION ALL
    SELECT 'どこか（へ）Vます／Vましたか。', 'Diễn tả đi đâu đó', 'Diễn tả đi đâu đó (Slot 8–39).', '昨日、どこかへ行きましたか。', 'Hôm qua bạn có đi đâu không?', 3, 'PUBLISHED'
    UNION ALL
    SELECT 'Người と Vます／Vました。', 'Làm hành động cùng ai', 'Làm hành động cùng ai (Slot 8–39).', '友達とサッカーをしました。', 'Tôi đã chơi bóng đá với bạn.', 4, 'PUBLISHED'
    UNION ALL
    SELECT 'S1。それから、S2。', 'Nối các hành động theo trình tự', 'Nối các hành động theo trình tự (Slot 9–40).', '友達の家へ行きました。それから、ゲームをしました。', 'Tôi đã đến nhà bạn. Sau đó chơi game.', 5, 'PUBLISHED'
    UNION ALL
    SELECT 'Aい → Aかったです。', 'Tính từ い – quá khứ khẳng định', 'Tính từ い – quá khứ khẳng định (Slot 10–41).', '昨日は暑かったです。', 'Hôm qua trời đã nóng.', 6, 'PUBLISHED'
    UNION ALL
    SELECT 'Aい → Aくなかったです。', 'Tính từ い – quá khứ phủ định', 'Tính từ い – quá khứ phủ định (Slot 10–41).', '旅行は楽しくなかったです。', 'Chuyến du lịch đã không vui.', 7, 'PUBLISHED'
    UNION ALL
    SELECT 'Aな → Aでした。', 'Tính từ な – quá khứ khẳng định', 'Tính từ な – quá khứ khẳng định (Slot 10–41).', 'テストは簡単でした。', 'Bài kiểm tra đã dễ.', 8, 'PUBLISHED'
    UNION ALL
    SELECT 'Aな → Aじゃありませんでした。', 'Tính từ な – quá khứ phủ định', 'Tính từ な – quá khứ phủ định (Slot 10–41).', 'テストは簡単じゃありませんでした。', 'Bài kiểm tra đã không dễ.', 9, 'PUBLISHED'
    UNION ALL
    SELECT 'Nでした／Nじゃありませんでした。', 'Danh từ – quá khứ', 'Danh từ – quá khứ (Slot 10–41).', '昨日は休みでした。', 'Hôm qua là ngày nghỉ.', 10, 'PUBLISHED'
    UNION ALL
    SELECT 'N はどうでしたか。', 'Hỏi cảm nhận trong quá khứ', 'Hỏi cảm nhận trong quá khứ (Slot 10–41).', '映画はどうでしたか。', 'Bộ phim đã xem thế nào?', 11, 'PUBLISHED'
    UNION ALL
    SELECT 'どうして～か。／Lý do + から。', 'Hỏi và giải thích nguyên nhân', 'Hỏi và giải thích nguyên nhân (Slot 11–42).', 'どうして買いませんでしたか。高かったですから。', 'Tại sao bạn không mua? Vì đắt.', 12, 'PUBLISHED'
    UNION ALL
    SELECT 'N がほしいです。', 'Mong muốn sở hữu', 'Mong muốn sở hữu (Slot 12–43).', '私は自転車がほしいです。', 'Tôi muốn có xe đạp.', 13, 'PUBLISHED'
    UNION ALL
    SELECT 'N がほしくないです。', 'Phủ định mong muốn sở hữu', 'Phủ định mong muốn sở hữu (Slot 12–43).', '今、お金はあまりほしくないです。', 'Bây giờ tôi không muốn có tiền lắm.', 14, 'PUBLISHED'
    UNION ALL
    SELECT 'N が好き／嫌いです。', 'Thích hoặc ghét', 'Thích hoặc ghét (Slot 12–43).', '野菜が好きです。', 'Tôi thích rau.', 15, 'PUBLISHED'
    UNION ALL
    SELECT 'Vます bỏ ます + たいです。', 'Muốn thực hiện hành động', 'Muốn thực hiện hành động (Slot 12–43).', '日本へ行きたいです。', 'Tôi muốn đi Nhật Bản.', 16, 'PUBLISHED'
    UNION ALL
    SELECT 'Địa điểm へ + Vます bỏ ます + に行きます。', 'Đi đến đâu để thực hiện hành động', 'Đi đến đâu để thực hiện hành động (Slot 13–44).', '図書館へ本を借りに行きます。', 'Tôi đến thư viện để mượn sách.', 17, 'PUBLISHED'
) AS seed
JOIN course AS c ON c.code = 'JPD123'
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR'
    AND l.display_order = seed.lesson_order AND l.title = seed.meaning_vi;

-- JPD123 / Chapter 6 / Ngữ pháp: 15 mục.
INSERT INTO grammar (lesson_id, structure_name, meaning_vi, usage_explanation, example_jp, example_vi, display_order, status)
SELECT l.id, seed.structure_name, seed.meaning_vi, seed.usage_explanation, seed.example_jp, seed.example_vi, 1 AS display_order, seed.status
FROM (
    SELECT 'Vます → Vませんか。' AS structure_name, 'Rủ rê, mời người khác' AS meaning_vi, 'Rủ rê, mời người khác (Slot 16–46).' AS usage_explanation, '一緒にご飯を食べませんか。' AS example_jp, 'Cùng ăn cơm nhé?' AS example_vi, 1 AS lesson_order, 'PUBLISHED' AS status
    UNION ALL
    SELECT 'Vます → Vましょう。', 'Đề nghị cùng làm hành động', 'Đề nghị cùng làm hành động (Slot 16–46).', '一緒に行きましょう。', 'Chúng ta cùng đi nhé.', 2, 'PUBLISHED'
    UNION ALL
    SELECT 'Thời gian はちょっと……。', 'Từ chối lời mời lịch sự', 'Từ chối lời mời lịch sự (Slot 16–46).', 'すみません。週末はちょっと……。', 'Xin lỗi, cuối tuần thì hơi khó...', 3, 'PUBLISHED'
    UNION ALL
    SELECT 'Địa điểm で Sự kiện があります。', 'Diễn tả sự kiện ở địa điểm', 'Diễn tả sự kiện ở địa điểm (Slot 17–47).', 'FPT大学でコンサートがあります。', 'Có buổi hòa nhạc tại Đại học FPT.', 4, 'PUBLISHED'
    UNION ALL
    SELECT 'N が số + 枚 あります。', 'Trợ số từ 枚（まい）', 'Trợ số từ 枚（まい） (Slot 17–47).', 'チケットが2枚あります。', 'Có 2 tấm vé.', 5, 'PUBLISHED'
    UNION ALL
    SELECT 'N1 で N2 がいちばん Aです。', 'So sánh nhất trong một nhóm', 'So sánh nhất trong một nhóm (Slot 18–48).', '食べ物でラーメンがいちばん好きです。', 'Trong các món ăn, tôi thích ramen nhất.', 6, 'PUBLISHED'
    UNION ALL
    SELECT 'N1 と N2 とどちらが Aですか。', 'Hỏi so sánh giữa hai đối tượng', 'Hỏi so sánh giữa hai đối tượng (Slot 18–48).', '肉と魚とどちらが好きですか。', 'Thịt và cá, bạn thích cái nào hơn?', 7, 'PUBLISHED'
    UNION ALL
    SELECT 'N のほうが Aです。', 'Trả lời so sánh hơn', 'Trả lời so sánh hơn (Slot 18–48).', '魚のほうが好きです。', 'Tôi thích cá hơn.', 8, 'PUBLISHED'
    UNION ALL
    SELECT 'どちらも Aです。', 'Cả hai đều có cùng đặc điểm', 'Cả hai đều có cùng đặc điểm (Slot 18–48).', 'どちらもおいしいです。', 'Cả hai đều ngon.', 9, 'PUBLISHED'
    UNION ALL
    SELECT 'N1 は N2 より Aです。', 'So sánh hơn với より', 'So sánh hơn với より (Slot 19–49).', '飛行機は新幹線より速いです。', 'Máy bay nhanh hơn tàu Shinkansen.', 10, 'PUBLISHED'
    UNION ALL
    SELECT 'もう Vましたか。', 'Hỏi đã làm hành động chưa', 'Hỏi đã làm hành động chưa (Slot 20–50).', 'もうお好み焼きを食べましたか。', 'Bạn đã ăn okonomiyaki chưa?', 11, 'PUBLISHED'
    UNION ALL
    SELECT 'いいえ、まだです。', 'Trả lời chưa thực hiện hành động', 'Trả lời chưa thực hiện hành động (Slot 20–50).', 'いいえ、まだです。', 'Chưa, vẫn chưa.', 12, 'PUBLISHED'
    UNION ALL
    SELECT 'S + よ。', 'Trợ từ よ – thông báo, nhấn mạnh', 'Trợ từ よ – thông báo, nhấn mạnh (Slot 20–50).', 'お好み焼きはおいしいですよ。', 'Okonomiyaki ngon đấy!', 13, 'PUBLISHED'
    UNION ALL
    SELECT 'N はどうですか。', 'Đưa ra lời gợi ý', 'Đưa ra lời gợi ý (Slot 20–50).', '日曜日はどうですか。', 'Chủ nhật thì sao?', 14, 'PUBLISHED'
    UNION ALL
    SELECT 'S + ね。', 'Trợ từ ね – xác nhận thông tin', 'Trợ từ ね – xác nhận thông tin (Slot 20–50).', '6時ですね。わかりました。', '6 giờ đúng không nhỉ? Tôi hiểu rồi.', 15, 'PUBLISHED'
) AS seed
JOIN course AS c ON c.code = 'JPD123'
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR'
    AND l.display_order = seed.lesson_order AND l.title = seed.meaning_vi;

-- JPD123 / Chapter 7 / Ngữ pháp: 15 mục.
INSERT INTO grammar (lesson_id, structure_name, meaning_vi, usage_explanation, example_jp, example_vi, display_order, status)
SELECT l.id, seed.structure_name, seed.meaning_vi, seed.usage_explanation, seed.example_jp, seed.example_vi, 1 AS display_order, seed.status
FROM (
    SELECT 'Địa điểm に N がいます。' AS structure_name, 'Sự tồn tại của người, động vật' AS meaning_vi, 'Sự tồn tại của người, động vật (Slot 23–53).' AS usage_explanation, '公園に犬がいます。' AS example_jp, 'Có con chó trong công viên.' AS example_vi, 1 AS lesson_order, 'PUBLISHED' AS status
    UNION ALL
    SELECT 'N は địa điểm にあります／います。', 'Nói vị trí tồn tại', 'Nói vị trí tồn tại (Slot 23–53).', '私は交番の前にいます。', 'Tôi đang ở trước đồn cảnh sát.', 2, 'PUBLISHED'
    UNION ALL
    SELECT 'N1 は N2 の + vị trí + にあります／います。', 'Nói vị trí tương đối', 'Nói vị trí tương đối (Slot 23–53).', '本屋はレストランの前にあります。', 'Hiệu sách ở trước nhà hàng.', 3, 'PUBLISHED'
    UNION ALL
    SELECT 'だれもいません。', 'Phủ định hoàn toàn với だれも', 'Phủ định hoàn toàn với だれも (Slot 24–54).', '教室にだれもいません。', 'Không có ai trong lớp học.', 4, 'PUBLISHED'
    UNION ALL
    SELECT 'なにもありません。', 'Phủ định hoàn toàn với なにも', 'Phủ định hoàn toàn với なにも (Slot 24–54).', '箱の中になにもありません。', 'Trong hộp không có gì cả.', 5, 'PUBLISHED'
    UNION ALL
    SELECT 'Vます → Vて', 'Chuyển động từ sang thể て', 'Chuyển động từ sang thể て (Slot 25–55).', '書きます → 書いて', 'Viết → dạng て của động từ viết.', 6, 'PUBLISHED'
    UNION ALL
    SELECT 'Vてください。', 'Yêu cầu, nhờ vả lịch sự', 'Yêu cầu, nhờ vả lịch sự (Slot 25–55).', '野菜を洗ってください。', 'Hãy rửa rau giúp tôi.', 7, 'PUBLISHED'
    UNION ALL
    SELECT 'Công cụ で Vます／Vてください。', 'Trợ từ で chỉ công cụ, cách thức', 'Trợ từ で chỉ công cụ, cách thức (Slot 25–55).', 'ペンで名前を書いてください。', 'Hãy viết tên bằng bút.', 8, 'PUBLISHED'
    UNION ALL
    SELECT 'Vます bỏ ます + 方（かた）', 'Diễn tả cách làm việc gì', 'Diễn tả cách làm việc gì (Slot 26–56).', 'カレーの作り方を教えてください。', 'Hãy chỉ cho tôi cách làm cà ri.', 9, 'PUBLISHED'
    UNION ALL
    SELECT 'どの + N ですか。', 'Hỏi danh từ nào', 'Hỏi danh từ nào (Slot 26–56).', 'どのお皿ですか。', 'Là chiếc đĩa nào?', 10, 'PUBLISHED'
    UNION ALL
    SELECT 'どれですか。', 'Hỏi cái nào', 'Hỏi cái nào (Slot 26–56).', '塩はどれですか。', 'Muối là cái nào?', 11, 'PUBLISHED'
    UNION ALL
    SELECT 'Vています。', 'Hành động đang diễn ra', 'Hành động đang diễn ra (Slot 27–57).', '日本語を勉強しています。', 'Tôi đang học tiếng Nhật.', 12, 'PUBLISHED'
    UNION ALL
    SELECT 'Vます → Vましょうか。', 'Chủ động đề nghị giúp đỡ', 'Chủ động đề nghị giúp đỡ (Slot 27–57).', '写真を撮りましょうか。', 'Để tôi chụp ảnh giúp nhé?', 13, 'PUBLISHED'
    UNION ALL
    SELECT 'だれが Vましたか。', 'Hỏi ai thực hiện hành động', 'Hỏi ai thực hiện hành động (Slot 27–57).', 'だれがこのケーキを作りましたか。', 'Ai đã làm chiếc bánh này?', 14, 'PUBLISHED'
    UNION ALL
    SELECT 'まだあります／もうありません。', 'Diễn tả vẫn còn hoặc đã hết', 'Diễn tả vẫn còn hoặc đã hết (Slot 27–57).', 'ビールはまだありますか。いいえ、もうありません。', 'Vẫn còn bia không? Không, hết rồi.', 15, 'PUBLISHED'
) AS seed
JOIN course AS c ON c.code = 'JPD123'
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR'
    AND l.display_order = seed.lesson_order AND l.title = seed.meaning_vi;

-- =============================================================================
-- NGHE HIỂU JPD113 / JPD123
-- =============================================================================
-- Mỗi chương có một bài nghe, một đoạn hội thoại và bốn câu trắc nghiệm.
-- Nguồn: doc/migrations/20261122_listening_seed.sql

START TRANSACTION;

INSERT INTO lesson (chapter_id, skill_type, lesson_no, title, description, display_order, status)
SELECT ch.id, seed.skill_type, 1, seed.title, seed.description, seed.display_order, 'PUBLISHED'
FROM (
    SELECT 'JPD113' AS course_code, 1 AS chapter_no, 'LISTENING' AS skill_type, 'Nghe hiểu bài 1' AS title, 'Hội thoại giới thiệu bản thân, nghề nghiệp, sở thích.' AS description, 10 AS display_order
    UNION ALL SELECT 'JPD113', 2, 'LISTENING', 'Nghe hiểu bài 2', 'Hội thoại mua sắm và hỏi vị trí.', 10
    UNION ALL SELECT 'JPD113', 3, 'LISTENING', 'Nghe hiểu bài 3', 'Hội thoại về giờ giấc, lịch trình, thói quen.', 10
    UNION ALL SELECT 'JPD123', 4, 'LISTENING', 'Nghe hiểu bài 4', 'Hội thoại về quê hương, thời tiết và vị trí.', 10
    UNION ALL SELECT 'JPD123', 5, 'LISTENING', 'Nghe hiểu bài 5', 'Hội thoại về ngày nghỉ, cảm nhận và mong muốn.', 10
    UNION ALL SELECT 'JPD123', 6, 'LISTENING', 'Nghe hiểu bài 6', 'Hội thoại rủ rê, hẹn gặp và so sánh.', 10
    UNION ALL SELECT 'JPD123', 7, 'LISTENING', 'Nghe hiểu bài 7', 'Hội thoại ở nhà bạn: vị trí, nhờ vả, giúp đỡ.', 10
) AS seed
JOIN course AS c ON c.code = seed.course_code
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = seed.chapter_no
WHERE NOT EXISTS (
    SELECT 1 FROM lesson AS l
    WHERE l.chapter_id = ch.id AND l.skill_type = seed.skill_type AND l.lesson_no = 1
);

INSERT INTO listening_exercise (chapter_id, lesson_id, title, script_jp, script_vi, display_order, status)
SELECT ch.id, l.id, seed.title, seed.script_jp, seed.script_vi, 1, 'PUBLISHED'
FROM (
    SELECT 'JPD113' AS course_code, 1 AS chapter_no, 'はじめまして' AS title,
      'はじめまして。わたしはリンです。ベトナムからきました。だいがくせいです。\nはじめまして。たなかです。かいしゃいんです。どうぞよろしく。\nたなかさんのしゅみはなんですか。\nサッカーです。リンさんは？\nわたしのしゅみはりょうりです。' AS script_jp,
      'Linh: Rất vui được gặp anh. Tôi là Linh. Tôi đến từ Việt Nam. Tôi là sinh viên đại học.\nTanaka: Rất vui được gặp chị. Tôi là Tanaka. Tôi là nhân viên công ty. Rất mong được giúp đỡ.\nLinh: Sở thích của anh Tanaka là gì?\nTanaka: Là bóng đá. Còn chị Linh?\nLinh: Sở thích của tôi là nấu ăn.' AS script_vi
    UNION ALL SELECT 'JPD113', 2, 'デパートで',
      'いらっしゃいませ。\nすみません、このかばんはいくらですか。\n3000えんです。\nじゃ、これをください。それから、トイレはどこですか。\nトイレはあそこです。エレベーターのとなりです。\nレストランはなんがいですか。\n7かいです。',
      'Nhân viên: Xin mời quý khách.\nKhách: Xin lỗi, cái túi này bao nhiêu tiền?\nNhân viên: 3000 yên.\nKhách: Vậy cho tôi cái này. Còn nữa, nhà vệ sinh ở đâu?\nNhân viên: Nhà vệ sinh ở đằng kia. Bên cạnh thang máy.\nKhách: Nhà hàng ở tầng mấy?\nNhân viên: Tầng 7.'
    UNION ALL SELECT 'JPD113', 3, 'マイさんのいちにち',
      'マイさん、まいあさなんじにおきますか。\n6じにおきます。7じはんにがっこうへいきます。\nなんじまでべんきょうしますか。\nごご4じまでです。それから、としょかんでべんきょうします。\nどようびはなにをしますか。\nともだちとえいがをみます。',
      'A: Chị Mai, mỗi sáng chị dậy lúc mấy giờ?\nMai: Tôi dậy lúc 6 giờ. 7 giờ rưỡi tôi đi đến trường.\nA: Chị học đến mấy giờ?\nMai: Đến 4 giờ chiều. Sau đó tôi học ở thư viện.\nA: Thứ bảy chị làm gì?\nMai: Tôi xem phim với bạn.'
    UNION ALL SELECT 'JPD123', 4, 'わたしのまち',
      'ハンさんのまちはどんなまちですか。\nダナンです。きれいなまちです。うみがあります。\nてんきはどうですか。\nなつはとてもあついです。でも、ふゆはあまりさむくないです。\nハンさんのうちはどこにありますか。\nうみのちかくにあります。',
      'A: Thành phố của anh Hân là thành phố như thế nào?\nHân: Là Đà Nẵng. Là một thành phố đẹp. Có biển.\nA: Thời tiết thế nào?\nHân: Mùa hè rất nóng. Nhưng mùa đông không lạnh lắm.\nA: Nhà anh Hân ở đâu?\nHân: Ở gần biển.'
    UNION ALL SELECT 'JPD123', 5, 'やすみのひ',
      'やすみのひ、なにをしましたか。\nきょうとへいきました。おてらをみました。\nどうでしたか。\nとてもたのしかったです。でも、ひとがおおかったです。\nつぎのやすみはなにをしたいですか。\nやまへいきたいです。しずかですから。',
      'A: Ngày nghỉ bạn đã làm gì?\nB: Tôi đã đi Kyoto. Tôi đã ngắm chùa.\nA: Thấy thế nào?\nB: Rất vui. Nhưng đông người.\nA: Kỳ nghỉ tới bạn muốn làm gì?\nB: Tôi muốn đi núi. Vì ở đó yên tĩnh.'
    UNION ALL SELECT 'JPD123', 6, 'いっしょにいきませんか',
      'キムさん、こんどのにちようび、いっしょにえいがをみませんか。\nいいですね。みましょう。\nどこであいましょうか。\nえきのまえであいましょう。10じはどうですか。\nいいですよ。ところで、キムさんはえいがとコンサートとどちらがすきですか。\nコンサートのほうがすきです。',
      'A: Chị Kim, chủ nhật tới cùng đi xem phim không?\nKim: Hay quá. Đi xem nhé.\nA: Gặp nhau ở đâu nhỉ?\nKim: Gặp ở trước nhà ga đi. 10 giờ được không?\nA: Được đấy. À này, chị Kim thích phim hay buổi hòa nhạc hơn?\nKim: Tôi thích buổi hòa nhạc hơn.'
    UNION ALL SELECT 'JPD123', 7, 'ともだちのうちで',
      'どうぞ、はいってください。\nおじゃまします。わあ、ひろいへやですね。\nありがとう。ここにすわってください。おちゃをいれます。\nてつだいましょうか。\nじゃ、つくえのうえのコップをとってください。\nはい。あ、ねこがいすのしたにいますね。',
      'A: Mời vào.\nB: Tôi xin phép. Ồ, căn phòng rộng quá nhỉ.\nA: Cảm ơn. Bạn ngồi ở đây nhé. Tôi đi pha trà.\nB: Để tôi giúp nhé?\nA: Vậy bạn lấy giúp tôi cái cốc trên bàn.\nB: Vâng. A, con mèo ở dưới ghế kìa.'
) AS seed
JOIN course AS c ON c.code = seed.course_code
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = seed.chapter_no
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'LISTENING' AND l.lesson_no = 1
WHERE NOT EXISTS (SELECT 1 FROM listening_exercise AS le WHERE le.lesson_id = l.id);

-- MySQL string literals treat \n as a newline, so scripts above keep one sentence per line.

INSERT INTO question (skill, question_type, lesson_id, listening_exercise_id, content, explanation,
                      answer_data, difficulty, is_exercise_question, display_order, status)
SELECT 'LISTENING', 'MCQ', l.id, le.id, seed.content, seed.explanation,
       JSON_OBJECT('options', JSON_OBJECT('A', seed.a, 'B', seed.b, 'C', seed.c, 'D', seed.d),
                   'correctAnswer', seed.correct_answer),
       'EASY', TRUE, seed.display_order, 'ACTIVE'
FROM (
    SELECT 'JPD113' AS course_code, 1 AS chapter_no, 1 AS display_order, 'リンさんはどこからきましたか。' AS content,
           'にほん' AS a, 'ベトナム' AS b, 'ちゅうごく' AS c, 'かんこく' AS d, 'B' AS correct_answer,
           'Linh nói 「ベトナムからきました」: tôi đến từ Việt Nam.' AS explanation
    UNION ALL SELECT 'JPD113', 1, 2, 'たなかさんのしごとはなんですか。', 'だいがくせい', 'せんせい', 'かいしゃいん', 'いしゃ', 'C',
           '「かいしゃいんです」 nghĩa là "tôi là nhân viên công ty".'
    UNION ALL SELECT 'JPD113', 1, 3, 'たなかさんのしゅみはなんですか。', 'りょうり', 'サッカー', 'どくしょ', 'おんがく', 'B',
           'Tanaka trả lời 「サッカーです」: bóng đá.'
    UNION ALL SELECT 'JPD113', 1, 4, 'リンさんのしゅみはなんですか。', 'りょうり', 'サッカー', 'りょこう', 'えいが', 'A',
           '「わたしのしゅみはりょうりです」: sở thích của tôi là nấu ăn.'

    UNION ALL SELECT 'JPD113', 2, 1, 'おきゃくさんはなにのねだんをききましたか。', 'かさ', 'とけい', 'かばん', 'くつ', 'C',
           '「このかばんはいくらですか」: cái túi này bao nhiêu tiền?'
    UNION ALL SELECT 'JPD113', 2, 2, 'それはいくらですか。', '300えん', '3000えん', '13000えん', '30000えん', 'B',
           'Nhân viên nói 「3000えんです」.'
    UNION ALL SELECT 'JPD113', 2, 3, 'トイレはどこですか。', 'エレベーターのとなり', 'レストランのまえ', '7かい', 'レジのとなり', 'A',
           '「エレベーターのとなりです」: bên cạnh thang máy.'
    UNION ALL SELECT 'JPD113', 2, 4, 'レストランはなんがいですか。', '1かい', '4かい', '6かい', '7かい', 'D',
           '「7かいです」: tầng 7.'

    UNION ALL SELECT 'JPD113', 3, 1, 'マイさんはまいあさなんじにおきますか。', '5じ', '6じ', '7じ', '7じはん', 'B',
           '「6じにおきます」: tôi dậy lúc 6 giờ.'
    UNION ALL SELECT 'JPD113', 3, 2, 'マイさんはなんじにがっこうへいきますか。', '6じ', '6じはん', '7じ', '7じはん', 'D',
           '「7じはんにがっこうへいきます」: 7 giờ rưỡi đi đến trường.'
    UNION ALL SELECT 'JPD113', 3, 3, 'マイさんはごご4じから、なにをしますか。', 'うちへかえります', 'としょかんでべんきょうします', 'アルバイトをします', 'スポーツをします', 'B',
           '「それから、としょかんでべんきょうします」: sau đó học ở thư viện.'
    UNION ALL SELECT 'JPD113', 3, 4, 'マイさんはどようびになにをしますか。', 'ともだちとえいがをみます', 'かいものをします', 'がっこうでべんきょうします', 'うちでりょうりをします', 'A',
           '「ともだちとえいがをみます」: xem phim với bạn.'

    UNION ALL SELECT 'JPD123', 4, 1, 'ハンさんのまちはどこですか。', 'ハノイ', 'フエ', 'ダナン', 'ホーチミン', 'C',
           '「ダナンです」: là Đà Nẵng.'
    UNION ALL SELECT 'JPD123', 4, 2, 'ハンさんのまちはどんなまちですか。', 'きれいで、うみがあります', 'にぎやかで、ひとがおおいです', 'ちいさくて、やまがあります', 'あたらしくて、かわがあります', 'A',
           '「きれいなまちです。うみがあります」: thành phố đẹp, có biển.'
    UNION ALL SELECT 'JPD123', 4, 3, 'ふゆはどうですか。', 'とてもさむいです', 'あまりさむくないです', 'とてもあついです', 'よくあめがふります', 'B',
           '「ふゆはあまりさむくないです」: mùa đông không lạnh lắm.'
    UNION ALL SELECT 'JPD123', 4, 4, 'ハンさんのうちはどこにありますか。', 'えきのちかく', 'やまのちかく', 'うみのちかく', 'がっこうのちかく', 'C',
           '「うみのちかくにあります」: ở gần biển.'

    UNION ALL SELECT 'JPD123', 5, 1, 'やすみのひ、どこへいきましたか。', 'とうきょう', 'きょうと', 'おおさか', 'やま', 'B',
           '「きょうとへいきました」: đã đi Kyoto.'
    UNION ALL SELECT 'JPD123', 5, 2, 'りょこうはどうでしたか。', 'とてもたのしかったです', 'つかれました', 'つまらなかったです', 'あまりたのしくなかったです', 'A',
           '「とてもたのしかったです」: rất vui.'
    UNION ALL SELECT 'JPD123', 5, 3, 'なにがよくなかったですか。', 'あめがふりました', 'たかかったです', 'ひとがおおかったです', 'りょうりがおいしくなかったです', 'C',
           '「ひとがおおかったです」: đông người.'
    UNION ALL SELECT 'JPD123', 5, 4, 'つぎのやすみはなにをしたいですか。どうしてですか。', 'うみへいきたいです。すずしいですから。', 'やまへいきたいです。しずかですから。', 'うちにいたいです。つかれましたから。', 'きょうとへいきたいです。きれいですから。', 'B',
           '「やまへいきたいです。しずかですから」: muốn đi núi vì yên tĩnh.'

    UNION ALL SELECT 'JPD123', 6, 1, 'ふたりはいっしょになにをしますか。', 'しょくじをします', 'えいがをみます', 'コンサートへいきます', 'かいものをします', 'B',
           '「いっしょにえいがをみませんか」: cùng xem phim không?'
    UNION ALL SELECT 'JPD123', 6, 2, 'ふたりはいつあいますか。', 'どようび', 'にちようび', 'きんようび', 'きょう', 'B',
           '「こんどのにちようび」: chủ nhật tới.'
    UNION ALL SELECT 'JPD123', 6, 3, 'ふたりはどこで、なんじにあいますか。', 'えきのまえで、10じに', 'えいがかんで、10じに', 'えきのまえで、2じに', 'がっこうで、9じに', 'A',
           '「えきのまえであいましょう。10じはどうですか」.'
    UNION ALL SELECT 'JPD123', 6, 4, 'キムさんはえいがとコンサートとどちらがすきですか。', 'えいがのほうがすきです', 'コンサートのほうがすきです', 'どちらもすきです', 'どちらもすきじゃありません', 'B',
           '「コンサートのほうがすきです」: thích buổi hòa nhạc hơn.'

    UNION ALL SELECT 'JPD123', 7, 1, 'へやはどうですか。', 'せまいです', 'ひろいです', 'ふるいです', 'くらいです', 'B',
           '「ひろいへやですね」: căn phòng rộng nhỉ.'
    UNION ALL SELECT 'JPD123', 7, 2, 'おちゃをいれるとき、おきゃくさんはなんといいましたか。', 'しつれいします', 'てつだいましょうか', 'みずをください', 'みちをおしえてください', 'B',
           '「てつだいましょうか」: để tôi giúp nhé?'
    UNION ALL SELECT 'JPD123', 7, 3, 'なにをとってくださいといいましたか。', 'つくえのうえのコップ', 'いす', 'ちゃわん', 'つくえのしたのコップ', 'A',
           '「つくえのうえのコップをとってください」: lấy giúp cái cốc trên bàn.'
    UNION ALL SELECT 'JPD123', 7, 4, 'ねこはどこにいますか。', 'つくえのうえ', 'いすのうえ', 'いすのした', 'ドアのそば', 'C',
           '「ねこがいすのしたにいますね」: con mèo ở dưới ghế.'
) AS seed
JOIN course AS c ON c.code = seed.course_code
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = seed.chapter_no
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'LISTENING' AND l.lesson_no = 1
JOIN listening_exercise AS le ON le.lesson_id = l.id
WHERE NOT EXISTS (
    SELECT 1 FROM question AS q
    WHERE q.listening_exercise_id = le.id AND q.display_order = seed.display_order
);

COMMIT;

-- Tình huống luyện nói AI mẫu, gắn vào chương PUBLISHED đầu tiên (Chương 1 - Nhật 1).
-- sample_script: mảng JSON {speaker: AI|STUDENT, segments: [{text, free?}], translation, hint?};
-- "free": true đánh dấu phần học viên có thể thay bằng từ của mình.
SET @chapter_id = (SELECT id FROM chapter WHERE status = 'PUBLISHED' ORDER BY display_order, id LIMIT 1);

INSERT INTO speaking_scenario
  (chapter_id, title, situation, ai_role, student_role, max_turns, sample_script, display_order, status)
VALUES
(@chapter_id, 'Gọi món ở quán ramen',
 'Bạn vào một quán ramen ở Nhật. Nhân viên đón khách, hỏi số người và nhận gọi món.',
 'nhân viên 店員', 'khách 客', 20,
 '[
  {"speaker":"AI","segments":[{"text":"いらっしゃいませ。何名様ですか？"}],"translation":"Xin chào quý khách. Quý khách đi mấy người ạ?"},
  {"speaker":"STUDENT","segments":[{"text":"一人","free":true},{"text":"です。"}],"translation":"Tôi đi một mình.","hint":"Có thể thay: 二人 (hai người), 三人 (ba người)."},
  {"speaker":"AI","segments":[{"text":"こちらへどうぞ。ご注文はお決まりですか？"}],"translation":"Mời quý khách đi lối này. Quý khách đã chọn món chưa ạ?"},
  {"speaker":"STUDENT","segments":[{"text":"すみません。"},{"text":"ラーメン","free":true},{"text":"を"},{"text":"一つ","free":true},{"text":"お願いします。"}],"translation":"Xin lỗi, cho tôi một bát ramen.","hint":"Có thể thay món (うどん, カレー) và số lượng (二つ, 三つ)."},
  {"speaker":"AI","segments":[{"text":"かしこまりました。お飲み物はいかがですか？"}],"translation":"Vâng ạ. Quý khách có dùng đồ uống không ạ?"},
  {"speaker":"STUDENT","segments":[{"text":"お水","free":true},{"text":"をください。"}],"translation":"Cho tôi nước lọc.","hint":"Có thể thay: お茶 (trà), コーラ (cola)."},
  {"speaker":"AI","segments":[{"text":"お待たせしました。ラーメンとお水です。"}],"translation":"Xin lỗi đã để quý khách đợi. Ramen và nước của quý khách đây ạ."},
  {"speaker":"STUDENT","segments":[{"text":"ありがとうございます。","free":true}],"translation":"Cảm ơn.","hint":"Có thể cảm ơn theo cách khác, ví dụ どうも。"},
  {"speaker":"AI","segments":[{"text":"ごゆっくりどうぞ。"}],"translation":"Chúc quý khách ngon miệng."}
 ]', 1, 'PUBLISHED'),
(@chapter_id, 'Tự giới thiệu ngày đầu đi học',
 'Ngày đầu tiên ở trường tiếng Nhật, giáo viên hỏi thăm và mời bạn tự giới thiệu.',
 'giáo viên 先生', 'học viên 学生', 20,
 '[
  {"speaker":"AI","segments":[{"text":"はじめまして。お名前は何ですか？"}],"translation":"Rất vui được gặp em. Em tên là gì?"},
  {"speaker":"STUDENT","segments":[{"text":"はじめまして。"},{"text":"アン","free":true},{"text":"です。"}],"translation":"Rất vui được gặp cô. Em là An.","hint":"Thay アン bằng tên của bạn."},
  {"speaker":"AI","segments":[{"text":"お国はどちらですか？"}],"translation":"Em đến từ nước nào?"},
  {"speaker":"STUDENT","segments":[{"text":"ベトナム","free":true},{"text":"から来ました。"}],"translation":"Em đến từ Việt Nam.","hint":"Có thể nói thêm thành phố: ハノイ, ホーチミン."},
  {"speaker":"AI","segments":[{"text":"そうですか。お仕事は何ですか？"}],"translation":"Vậy à. Em làm nghề gì?"},
  {"speaker":"STUDENT","segments":[{"text":"学生","free":true},{"text":"です。"}],"translation":"Em là sinh viên.","hint":"Có thể thay: エンジニア (kỹ sư), 会社員 (nhân viên công ty)."},
  {"speaker":"AI","segments":[{"text":"これからよろしくお願いします。"}],"translation":"Từ nay mong được giúp đỡ nhé."},
  {"speaker":"STUDENT","segments":[{"text":"どうぞよろしくお願いします。"}],"translation":"Rất mong được cô giúp đỡ."}
 ]', 2, 'PUBLISHED');

