    UNION ALL SELECT 2033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B khẳng định thông tin hiện tại.', _utf8mb4 0x0a, _utf8mb4'A：何年何組ですか。', _utf8mb4 0x0a, _utf8mb4'B：私は一年二組（　）。'), _utf8mb4'です kết thúc câu danh từ khẳng định lịch sự ở hiện tại.', _utf8mb4'{"options":{"A":"ですか","B":"じゃありません","C":"でしたか","D":"です"},"correctAnswer":"D"}'
    UNION ALL SELECT 2041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B khẳng định thông tin hiện tại.', _utf8mb4 0x0a, _utf8mb4'A：お二人は何年生ですか。', _utf8mb4 0x0a, _utf8mb4'B：姉は三年生です。私（　）一年生です。'), _utf8mb4'は nêu chủ đề được giới thiệu. Danh từ theo sau cho biết người hoặc vật đó là gì.', _utf8mb4'{"options":{"A":"は","B":"を","C":"に","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 2049, _utf8mb4'EASY', CONCAT(_utf8mb4'B khẳng định thông tin hiện tại.', _utf8mb4 0x0a, _utf8mb4'A：昼の予定は何ですか。', _utf8mb4 0x0a, _utf8mb4'B：昼（　）友達と食事です。'), _utf8mb4'は nêu chủ đề được giới thiệu. Danh từ theo sau cho biết người hoặc vật đó là gì.', _utf8mb4'{"options":{"A":"へ","B":"は","C":"を","D":"で"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 です。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 2 (おくには どちらですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：お父さんのお国は（　）ですか。ドイツですか。', _utf8mb4 0x0a, _utf8mb4'B：はい、ドイツです。') AS content, _utf8mb4'どちら sau お国は là cách hỏi lịch sự về quốc gia của người đối thoại.' AS explanation, _utf8mb4'{"options":{"A":"どなた","B":"いくら","C":"いつ","D":"どちら"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ご出身は（　）ですか。国の名前をお願いします。', _utf8mb4 0x0a, _utf8mb4'B：フランスです。パリの近くで生まれました。'), _utf8mb4'どちら sau お国は là cách hỏi lịch sự về quốc gia của người đối thoại.', _utf8mb4'{"options":{"A":"どなた","B":"どちら","C":"いくら","D":"いつ"},"correctAnswer":"B"}'
