    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：はじめまして。お国（　）どちらですか。', _utf8mb4 0x0a, _utf8mb4'B：ベトナムです。ハノイから来ました。'), _utf8mb4'は nêu お国 hoặc ご出身 làm chủ đề. どちら hỏi thông tin về quê quán.', _utf8mb4'{"options":{"A":"へ","B":"は","C":"を","D":"から"},"correctAnswer":"B"}'
