    UNION ALL SELECT 2034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：お母さんのお国は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：母はカナダから来ました。'), _utf8mb4'どちら sau お国は là cách hỏi lịch sự về quốc gia của người đối thoại.', _utf8mb4'{"options":{"A":"いつ","B":"どなた","C":"どちら","D":"いくら"},"correctAnswer":"C"}'
    UNION ALL SELECT 2042, _utf8mb4'EASY', CONCAT(_utf8mb4'A：失礼ですが、お国は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：インドです。家族は今もそこにいます。'), _utf8mb4'どちら sau お国は là cách hỏi lịch sự về quốc gia của người đối thoại.', _utf8mb4'{"options":{"A":"どちら","B":"いくら","C":"いつ","D":"どなた"},"correctAnswer":"A"}'
    UNION ALL SELECT 2050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：先生のお国は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：アメリカです。学生はフランスから来ました。'), _utf8mb4'どちら sau お国は là cách hỏi lịch sự về quốc gia của người đối thoại.', _utf8mb4'{"options":{"A":"いくら","B":"どちら","C":"どなた","D":"いつ"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 2 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'おくには どちらですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 3 (N1 は N2 じゃありません。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'B đính chính bằng câu phủ định.', _utf8mb4 0x0a, _utf8mb4'A：これは水ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）') AS content, _utf8mb4'Danh từ + じゃありません phủ định lịch sự ở hiện tại. です sẽ đổi thành khẳng định.' AS explanation, _utf8mb4'{"options":{"A":"いいえ。それは水でしたか。お茶です。","B":"いいえ。それは水ですか。お茶です。","C":"いいえ。それは水じゃありません。お茶です。","D":"いいえ。それは水です。お茶です。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B đính chính bằng câu phủ định.', _utf8mb4 0x0a, _utf8mb4'A：これは水ですか。', _utf8mb4 0x0a, _utf8mb4'B：いいえ。それは水（　）。お茶です。'), _utf8mb4'Danh từ + じゃありません phủ định lịch sự ở hiện tại. です sẽ đổi thành khẳng định.', _utf8mb4'{"options":{"A":"です","B":"ですか","C":"でしたか","D":"じゃありません"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'B đính chính bằng câu phủ định.', _utf8mb4 0x0a, _utf8mb4'A：この町がご出身ですか。', _utf8mb4 0x0a, _utf8mb4'B：はい。でも今の住所はこの町（　）。'), _utf8mb4'Danh từ + じゃありません phủ định lịch sự ở hiện tại. です sẽ đổi thành khẳng định.', _utf8mb4'{"options":{"A":"じゃありません","B":"です","C":"ですか","D":"でしたか"},"correctAnswer":"A"}'
