    UNION ALL SELECT 2035, _utf8mb4'EASY', CONCAT(_utf8mb4'B đính chính bằng câu phủ định.', _utf8mb4 0x0a, _utf8mb4'A：この赤いカードが学生証ですか。', _utf8mb4 0x0a, _utf8mb4'B：それは学生証（　）。図書カードです。'), _utf8mb4'Danh từ + じゃありません phủ định lịch sự ở hiện tại. です sẽ đổi thành khẳng định.', _utf8mb4'{"options":{"A":"じゃありません","B":"でしたか","C":"ですか","D":"です"},"correctAnswer":"A"}'
    UNION ALL SELECT 2043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「じゃありません」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'いいえ。最後の日は今日じゃありません。明日です。'), _utf8mb4'Danh từ + じゃありません phủ định lịch sự ở hiện tại. です sẽ đổi thành khẳng định.', _utf8mb4'{"options":{"A":"Hỏi xem sự việc xảy ra lúc nào.","B":"Đề nghị người nghe làm gì đó.","C":"Bác bỏ việc chủ đề thuộc loại vừa được nhắc tới.","D":"Xác nhận thông tin là đúng."},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 3 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 じゃありません。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 4 (N1 は N2 ですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A đặt câu hỏi trung lập để xác nhận.', _utf8mb4 0x0a, _utf8mb4'A：失礼ですが、学生です（　）。', _utf8mb4 0x0a, _utf8mb4'B：はい、学生です。') AS content, _utf8mb4'か đứng sau です để hỏi xác nhận. よ biểu thị lời thông báo của người nói.' AS explanation, _utf8mb4'{"options":{"A":"か","B":"を","C":"に","D":"よ"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'A đặt câu hỏi trung lập để xác nhận.', _utf8mb4 0x0a, _utf8mb4'A：こちらは山田先生です（　）。', _utf8mb4 0x0a, _utf8mb4'B：はい、こちらは山田先生です。'), _utf8mb4'か đứng sau です để hỏi xác nhận. よ biểu thị lời thông báo của người nói.', _utf8mb4'{"options":{"A":"よ","B":"か","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A đặt câu hỏi trung lập để xác nhận.', _utf8mb4 0x0a, _utf8mb4'A：駅の前の建物は郵便局（　）。', _utf8mb4 0x0a, _utf8mb4'B：いいえ、銀行です。'), _utf8mb4'ですか hỏi xác nhận. Người nghe có thể đáp はい hoặc いいえ.', _utf8mb4'{"options":{"A":"じゃありません","B":"でしたね","C":"でした","D":"ですか"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A đặt câu hỏi trung lập để xác nhận.', _utf8mb4 0x0a, _utf8mb4'A：これはお兄さんのかばんです（　）。', _utf8mb4 0x0a, _utf8mb4'B：いいえ、それは弟のです。'), _utf8mb4'か đứng sau です để hỏi xác nhận. よ biểu thị lời thông báo của người nói.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"か","D":"よ"},"correctAnswer":"C"}'
