    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A đặt câu hỏi trung lập để xác nhận.', _utf8mb4 0x0a, _utf8mb4'A：このパンは百円（　）。', _utf8mb4 0x0a, _utf8mb4'B：はい、一つ百円です。'), _utf8mb4'ですか hỏi xác nhận. Người nghe có thể đáp はい hoặc いいえ.', _utf8mb4'{"options":{"A":"ですか","B":"でしたね","C":"じゃありません","D":"でした"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A đặt câu hỏi trung lập để xác nhận.', _utf8mb4 0x0a, _utf8mb4'Chọn câu hỏi đúng.', _utf8mb4 0x0a, _utf8mb4'B：はい。次の停留所は大学です。'), _utf8mb4'ですか hỏi xác nhận. Người nghe có thể đáp はい hoặc いいえ.', _utf8mb4'{"options":{"A":"これが大学行きのバスでした。","B":"これが大学行きのバスじゃありません。","C":"これが大学行きのバスですか。","D":"これが大学行きのバスでしたね。"},"correctAnswer":"C"}'
