) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 ですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 5 (N1 は N2 の N3 です。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'A：これはだれの本ですか。', _utf8mb4 0x0a, _utf8mb4'B：田中さん（　）本です。') AS content, _utf8mb4'の đặt giữa hai danh từ để danh từ đứng trước bổ nghĩa cho danh từ đứng sau.' AS explanation, _utf8mb4'{"options":{"A":"に","B":"を","C":"の","D":"へ"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：これはだれの本ですか。', _utf8mb4 0x0a, _utf8mb4'B：田中さん（　）です。'), _utf8mb4'Trong N1 の N2, N2 là danh từ chính. N1 đứng trước の để bổ nghĩa cho N2.', _utf8mb4'{"options":{"A":"の本","B":"に本","C":"を本","D":"へ本"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どの大学の学生証ですか。', _utf8mb4 0x0a, _utf8mb4'B：さくら大学（　）学生証です。'), _utf8mb4'の đặt giữa hai danh từ để danh từ đứng trước bổ nghĩa cho danh từ đứng sau.', _utf8mb4'{"options":{"A":"の","B":"を","C":"で","D":"へ"},"correctAnswer":"A"}'
