    UNION ALL SELECT 2015, _utf8mb4'EASY', CONCAT(_utf8mb4'A：この袋には何が入りますか。', _utf8mb4 0x0a, _utf8mb4'B：ノート（　）ペンのセットです。'), _utf8mb4'と nối các danh từ ngang hàng thành danh sách đầy đủ theo ngữ cảnh.', _utf8mb4'{"options":{"A":"へ","B":"と","C":"を","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 2023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：町の写真を二枚選んでください。'), _utf8mb4'N1 と N2 gộp cả hai thành phần. Các câu có 二つ, 二人 hoặc だけ xác định phạm vi liệt kê.', _utf8mb4'{"options":{"A":"駅へ公園の写真にします。","B":"駅を公園の写真にします。","C":"駅と公園の写真にします。","D":"駅から公園の写真にします。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：明日持っていく物は？'), _utf8mb4'N1 と N2 gộp cả hai thành phần. Các câu có 二つ, 二人 hoặc だけ xác định phạm vi liệt kê.', _utf8mb4'{"options":{"A":"帽子へタオルを持っていきます。この二つです。","B":"帽子をタオルを持っていきます。この二つです。","C":"帽子からタオルを持っていきます。この二つです。","D":"帽子とタオルを持っていきます。この二つです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2039, _utf8mb4'EASY', CONCAT(_utf8mb4'A：おやつは何にしますか。二つ選べますよ。', _utf8mb4 0x0a, _utf8mb4'B：プリン（　）ケーキをお願いします。'), _utf8mb4'と nối các danh từ ngang hàng thành danh sách đầy đủ theo ngữ cảnh.', _utf8mb4'{"options":{"A":"で","B":"と","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 2047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：どの授業に出ますか。'), _utf8mb4'N1 と N2 gộp cả hai thành phần. Các câu có 二つ, 二人 hoặc だけ xác định phạm vi liệt kê.', _utf8mb4'{"options":{"A":"英語へ数学の二つです。","B":"英語を数学の二つです。","C":"英語と数学の二つです。","D":"英語から数学の二つです。"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 と N2' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 1 / NGỮ PHÁP / Mẫu 8 (N1 は N2 です。N3 も N2 です。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'B nhấn mạnh trường hợp thứ hai cũng vậy.', _utf8mb4 0x0a, _utf8mb4'A：私は学生です。あなたは？', _utf8mb4 0x0a, _utf8mb4'B：私（　）学生です。') AS content, _utf8mb4'も bổ sung một trường hợp có cùng đặc điểm. Khi đi sau に hoặc で, nó giữ vai trò của trợ từ trước.' AS explanation, _utf8mb4'{"options":{"A":"へ","B":"を","C":"も","D":"に"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B nhấn mạnh trường hợp thứ hai cũng vậy.', _utf8mb4 0x0a, _utf8mb4'A：この道は駅に行きます。あちらの道は？', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N + も đưa thêm một đối tượng vào nhận định đã có ở lượt trước.', _utf8mb4'{"options":{"A":"あちらを駅へ行きます。","B":"あちらへ駅へ行きます。","C":"あちらに駅へ行きます。","D":"あちらも駅へ行きます。"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B nhấn mạnh trường hợp thứ hai cũng vậy.', _utf8mb4 0x0a, _utf8mb4'A：土曜日は店を開けます。日曜は？', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N + も đưa thêm một đối tượng vào nhận định đã có ở lượt trước.', _utf8mb4'{"options":{"A":"日曜日を開けます。","B":"日曜日に開けます。","C":"日曜日も開けます。","D":"日曜日へ開けます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'B nhấn mạnh trường hợp thứ hai cũng vậy.', _utf8mb4 0x0a, _utf8mb4'A：私は学生です。あなたは？', _utf8mb4 0x0a, _utf8mb4'B：私（　）。'), _utf8mb4'N + も đưa thêm một đối tượng vào nhận định đã có ở lượt trước.', _utf8mb4'{"options":{"A":"へ学生です","B":"も学生です","C":"を学生です","D":"に学生です"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B nhấn mạnh trường hợp thứ hai cũng vậy.', _utf8mb4 0x0a, _utf8mb4'A：先生はお茶を飲みます。あなたも同じ？', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N + も đưa thêm một đối tượng vào nhận định đã có ở lượt trước.', _utf8mb4'{"options":{"A":"はい。私へお茶を飲みます。","B":"はい。私もお茶を飲みます。","C":"はい。私をお茶を飲みます。","D":"はい。私にお茶を飲みます。"},"correctAnswer":"B"}'
