    UNION ALL SELECT 2048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B nhấn mạnh trường hợp thứ hai cũng vậy.', _utf8mb4 0x0a, _utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：英語のメニューがあります。日本語は？'), _utf8mb4'N + も đưa thêm một đối tượng vào nhận định đã có ở lượt trước.', _utf8mb4'{"options":{"A":"日本語のメニューにあります。","B":"日本語のメニューへあります。","C":"日本語のメニューをあります。","D":"日本語のメニューもあります。"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 1
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 です。N3 も N2 です。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 1 (N は số + かいです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：会議室に行きます。何階のボタンを押しましょうか。', _utf8mb4 0x0a, _utf8mb4'B：（　）') AS content, _utf8mb4'Gắn 階 sau số để chỉ tầng. 五階 trả lời cho 何階, còn 回 dùng để đếm số lần.' AS explanation, _utf8mb4'{"options":{"A":"会議室は五回です。ありがとうございます。","B":"会議室は五階です。ありがとうございます。","C":"会議室は五台です。ありがとうございます。","D":"会議室は五人です。ありがとうございます。"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'A：会議室に行きます。何階のボタンを押しましょうか。', _utf8mb4 0x0a, _utf8mb4'B：会議室は（　）です。ありがとうございます。'), _utf8mb4'Gắn 階 sau số để chỉ tầng. 五階 trả lời cho 何階, còn 回 dùng để đếm số lần.', _utf8mb4'{"options":{"A":"五人","B":"五台","C":"五階","D":"五回"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：食堂へ行きたいんですが、何階ですか。', _utf8mb4 0x0a, _utf8mb4'B：食堂（　）二階です。階段はあちらです。'), _utf8mb4'は nêu nơi cần tìm. Số + 階 ở vị ngữ cho biết nơi đó ở tầng nào.', _utf8mb4'{"options":{"A":"は","B":"へ","C":"を","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：面会に来ました。病室は何階ですか。', _utf8mb4 0x0a, _utf8mb4'B：山田さんの病室（　）三階です。'), _utf8mb4'は nêu nơi cần tìm. Số + 階 ở vị ngữ cho biết nơi đó ở tầng nào.', _utf8mb4'{"options":{"A":"に","B":"を","C":"は","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'A：薬売り場へ行きたいです。上の階ですか。', _utf8mb4 0x0a, _utf8mb4'B：いいえ。薬売り場は（　）です。'), _utf8mb4'Gắn 階 sau số để chỉ tầng. 地下一階 trả lời cho 何階, còn 回 dùng để đếm số lần.', _utf8mb4'{"options":{"A":"地下一階","B":"一人","C":"一番","D":"一回"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：受付へ行くのに階段を上りますか。', _utf8mb4 0x0a, _utf8mb4'B：いいえ。受付（　）一階です。入口の横ですよ。'), _utf8mb4'は nêu nơi cần tìm. Số + 階 ở vị ngữ cho biết nơi đó ở tầng nào.', _utf8mb4'{"options":{"A":"と","B":"へ","C":"は","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：薬売り場へ行きたいです。上の階ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'Gắn 階 sau số để chỉ tầng. 地下一階 trả lời cho 何階, còn 回 dùng để đếm số lần.', _utf8mb4'{"options":{"A":"いいえ。薬売り場は一回です。","B":"いいえ。薬売り場は地下一階です。","C":"いいえ。薬売り場は一番です。","D":"いいえ。薬売り場は一人です。"},"correctAnswer":"B"}'
