    UNION ALL SELECT 2019, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「số + 階」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'図書室は五階です。'), _utf8mb4'Gắn 階 sau số để chỉ tầng. 五階 trả lời cho 何階, còn 回 dùng để đếm số lần.', _utf8mb4'{"options":{"A":"Thông báo tầng của địa điểm đang được tìm.","B":"Thông báo số người trong tòa nhà.","C":"Nêu số lần thực hiện một hoạt động.","D":"Hỏi giá thuê phòng."},"correctAnswer":"A"}'
    UNION ALL SELECT 2037, _utf8mb4'EASY', CONCAT(_utf8mb4'A：二階に着きました。音楽室もこの階ですか。', _utf8mb4 0x0a, _utf8mb4'B：もう一つ上です。音楽室は（　）です。'), _utf8mb4'Gắn 階 sau số để chỉ tầng. 三階 trả lời cho 何階, còn 回 dùng để đếm số lần.', _utf8mb4'{"options":{"A":"三枚","B":"三時","C":"三回","D":"三階"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は số + かいです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 2 (N は なんかいですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：教室（　）何階ですか。', _utf8mb4 0x0a, _utf8mb4'B：三階です。') AS content, _utf8mb4'は nêu địa điểm đã biết, còn 何階 thay cho số tầng chưa biết.' AS explanation, _utf8mb4'{"options":{"A":"は","B":"へ","C":"から","D":"を"},"correctAnswer":"A"}' AS answers
