    UNION ALL SELECT 2020, _utf8mb4'EASY', CONCAT(_utf8mb4'A：駐車場は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：地下二階ですよ。'), _utf8mb4'何階 hỏi tầng mấy. 何回 hỏi số lần dù cách đọc gần giống nhau.', _utf8mb4'{"options":{"A":"何人","B":"何階","C":"何時","D":"何回"},"correctAnswer":"B"}'
    UNION ALL SELECT 2038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：部屋番号は分かりました。お部屋は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：二階です。階段の近くですよ。'), _utf8mb4'何階 hỏi tầng mấy. 何回 hỏi số lần dù cách đọc gần giống nhau.', _utf8mb4'{"options":{"A":"何時","B":"何回","C":"何階","D":"何人"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 2 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は なんかいですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 3 (N は ここ／そこ／あそこです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'B đứng ngay cửa vào.', _utf8mb4 0x0a, _utf8mb4'A：入口はどこですか。', _utf8mb4 0x0a, _utf8mb4'B：入口は（　）です。もう着きましたよ。') AS content, _utf8mb4'ここ chỉ nơi chốn. Dùng khi đối tượng gần người nói.' AS explanation, _utf8mb4'{"options":{"A":"そこ","B":"あそこ","C":"ここ","D":"どこ"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B chỉ chỗ ngay sau lưng A.', _utf8mb4 0x0a, _utf8mb4'A：出口はどこですか。', _utf8mb4 0x0a, _utf8mb4'B：出口は（　）です。お客さんのすぐ後ろです。'), _utf8mb4'そこ chỉ nơi chốn. Dùng khi đối tượng gần người nghe.', _utf8mb4'{"options":{"A":"あそこ","B":"ここ","C":"そこ","D":"どこ"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B đứng ngay cửa vào.', _utf8mb4 0x0a, _utf8mb4'A：入口はどこですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'ここ chỉ nơi chốn. Dùng khi đối tượng gần người nói.', _utf8mb4'{"options":{"A":"入口はここです。もう着きましたよ。","B":"入口はどこです。もう着きましたよ。","C":"入口はそこです。もう着きましたよ。","D":"入口はあそこです。もう着きましたよ。"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai người cùng nhìn về tòa nhà trắng ở xa.', _utf8mb4 0x0a, _utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：病院は？'), _utf8mb4'あそこ chỉ nơi chốn. Dùng khi đối tượng ở xa cả người nói và người nghe.', _utf8mb4'{"options":{"A":"病院はそこです。遠くの白い建物です。","B":"病院はここです。遠くの白い建物です。","C":"病院はあそこです。遠くの白い建物です。","D":"病院はどこです。遠くの白い建物です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai người trông thấy cây cầu ở phía xa.', _utf8mb4 0x0a, _utf8mb4'A：バス停は？', _utf8mb4 0x0a, _utf8mb4'B：バス停は（　）です。橋のそばです。'), _utf8mb4'あそこ chỉ nơi chốn. Dùng khi đối tượng ở xa cả người nói và người nghe.', _utf8mb4'{"options":{"A":"どこ","B":"あそこ","C":"ここ","D":"そこ"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「あそこ」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'集合場所はあそこです。向こうの門の前です。'), _utf8mb4'あそこ chỉ nơi chốn. Dùng khi đối tượng ở xa cả người nói và người nghe.', _utf8mb4'{"options":{"A":"Đếm số tầng cần đi lên.","B":"Hỏi tên một vật đang cầm.","C":"Thông báo quốc tịch của một người.","D":"Chỉ vị trí bằng khoảng cách so với hai người đang nói."},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B đứng tại quầy tiếp tân.', _utf8mb4 0x0a, _utf8mb4'A：受付はどこですか。', _utf8mb4 0x0a, _utf8mb4'B：受付（　）ここです。私の目の前です。'), _utf8mb4'は nêu nơi cần định vị làm chủ đề. Từ chỉ vị trí hoặc hướng đứng ở phần sau.', _utf8mb4'{"options":{"A":"は","B":"を","C":"へ","D":"から"},"correctAnswer":"A"}'
