    UNION ALL SELECT 2040, _utf8mb4'EASY', CONCAT(_utf8mb4'A：先生、次の教室（　）どこですか。', _utf8mb4 0x0a, _utf8mb4'B：この廊下の奥ですよ。'), _utf8mb4'は đưa nơi cần tìm ra làm chủ đề. どこ hỏi vị trí chưa biết của nơi đó.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"を","D":"は"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は どこですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

