    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Máy bán vé ở sát bên khách A.', _utf8mb4 0x0a, _utf8mb4'A：券売機はどちらですか。', _utf8mb4 0x0a, _utf8mb4'B：券売機は（　）です。切符はそこで買えます。') AS content, _utf8mb4'そちら chỉ hướng theo lối lịch sự. Dùng khi đối tượng gần người nghe.' AS explanation, _utf8mb4'{"options":{"A":"どちら","B":"こちら","C":"あちら","D":"そちら"},"correctAnswer":"D"}' AS answers
