    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn câu hỏi đúng.', _utf8mb4 0x0a, _utf8mb4'B：そちらです。荷物をお持ちしましょうか。') AS content, _utf8mb4'どちらですか trong lời hỏi đường là cách hỏi lịch sự về vị trí. Lời đáp nêu hướng đi.' AS explanation, _utf8mb4'{"options":{"A":"荷物を預ける所はいくらですか。","B":"荷物を預ける所はいつですか。","C":"荷物を預ける所はどなたですか。","D":"荷物を預ける所はどちらですか。"},"correctAnswer":"D"}' AS answers
