    UNION ALL SELECT 2025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「どちらですか」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'すみません、郵便局はどちらですか。'), _utf8mb4'どちらですか trong lời hỏi đường là cách hỏi lịch sự về vị trí. Lời đáp nêu hướng đi.', _utf8mb4'{"options":{"A":"Hỏi tên một nhân viên bằng lối thân mật.","B":"Nêu số lần cần đi lại.","C":"Hỏi đường hoặc vị trí một cách lịch sự.","D":"Khẳng định một địa điểm ở xa cả hai."},"correctAnswer":"C"}'
    UNION ALL SELECT 2043, _utf8mb4'EASY', CONCAT(_utf8mb4'A：面接の会場は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：そちらのドアからお入りください。'), _utf8mb4'どちらですか trong lời hỏi đường là cách hỏi lịch sự về vị trí. Lời đáp nêu hướng đi.', _utf8mb4'{"options":{"A":"いくら","B":"どちら","C":"いつ","D":"どなた"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は どちらですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

