    UNION ALL SELECT 2046, _utf8mb4'EASY', CONCAT(_utf8mb4'A：この小さい紙は（　）ですか。', _utf8mb4 0x0a, _utf8mb4'B：駅の切符ですよ。'), _utf8mb4'これは何ですか hỏi vật trước mắt là gì. Câu trả lời gọi tên vật, không nêu nơi chốn.', _utf8mb4'{"options":{"A":"いくら","B":"何","C":"いつ","D":"どこ"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 10 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'これは なんですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 11 (この／その／あの + N)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Quyển sách nằm trong tay A.', _utf8mb4 0x0a, _utf8mb4'A：何を借りたいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）本をお願いします。') AS content, _utf8mb4'その đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nghe.' AS explanation, _utf8mb4'{"options":{"A":"この","B":"その","C":"これ","D":"あの"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chiếc xe đỏ ở xa cả hai người.', _utf8mb4 0x0a, _utf8mb4'A：先生の車はどれですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）車は先生のです。'), _utf8mb4'あの đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng ở xa cả người nói và người nghe.', _utf8mb4'{"options":{"A":"その","B":"この","C":"これ","D":"あの"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B lấy tấm thẻ màu trắng trong tay mình ra.', _utf8mb4 0x0a, _utf8mb4'A：切符の代わりに何を使いますか。', _utf8mb4 0x0a, _utf8mb4'B：切符の代わりに（　）カードを使います。'), _utf8mb4'この đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nói.', _utf8mb4'{"options":{"A":"この","B":"あの","C":"その","D":"これ"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'A, nhân viên cửa hàng, đang cầm chiếc áo.', _utf8mb4 0x0a, _utf8mb4'A：どのシャツをお見せしましょうか。', _utf8mb4 0x0a, _utf8mb4'B：（　）シャツを見せてください。'), _utf8mb4'その đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nghe.', _utf8mb4'{"options":{"A":"あの","B":"これ","C":"その","D":"この"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Quyển sách nằm trong tay A.', _utf8mb4 0x0a, _utf8mb4'A：何を借りたいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'その đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nghe.', _utf8mb4'{"options":{"A":"あの本をお願いします。","B":"これ本をお願いします。","C":"この本をお願いします。","D":"その本をお願いします。"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ngọn núi ở xa cả hai.', _utf8mb4 0x0a, _utf8mb4'A：どの山の写真ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）山の写真を撮りました。'), _utf8mb4'あの đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng ở xa cả người nói và người nghe.', _utf8mb4'{"options":{"A":"その","B":"この","C":"あの","D":"これ"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'B đưa ra tờ giấy ở ngay trước mặt mình.', _utf8mb4 0x0a, _utf8mb4'A：どこに名前を書きますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）紙に名前を書いてください。'), _utf8mb4'この đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nói.', _utf8mb4'{"options":{"A":"この","B":"これ","C":"その","D":"あの"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B đưa ra tờ giấy ở ngay trước mặt mình.', _utf8mb4 0x0a, _utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：どこに名前を書きますか。'), _utf8mb4'この đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nói.', _utf8mb4'{"options":{"A":"この紙に名前を書いてください。","B":"あの紙に名前を書いてください。","C":"これ紙に名前を書いてください。","D":"その紙に名前を書いてください。"},"correctAnswer":"A"}'
