    UNION ALL SELECT 2029, _utf8mb4'EASY', CONCAT(_utf8mb4'B đang chìa đồng xu trong tay mình.', _utf8mb4 0x0a, _utf8mb4'A：どのお金を見ていますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）百円玉を見ています。今年のお金ですよ。'), _utf8mb4'この đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nói.', _utf8mb4'{"options":{"A":"この","B":"あの","C":"その","D":"これ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'B đang cầm quyển vở muốn hỏi giá.', _utf8mb4 0x0a, _utf8mb4'A：どのノートの値段を知りたいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）ノートの値段を教えてください。'), _utf8mb4'この đứng trực tiếp trước danh từ chỉ vật. Dùng khi đối tượng gần người nói.', _utf8mb4'{"options":{"A":"その","B":"あの","C":"これ","D":"この"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 11 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'この／その／あの + N' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 12 (N を ください。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：何をお持ちしましょうか。', _utf8mb4 0x0a, _utf8mb4'B：お水（　）ください。') AS content, _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.' AS explanation, _utf8mb4'{"options":{"A":"へ","B":"を","C":"に","D":"と"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：何か足りませんか。', _utf8mb4 0x0a, _utf8mb4'B：すみません、はし（　）ください。お弁当に使います。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"と","B":"に","C":"を","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'A：何をお持ちしましょうか。', _utf8mb4 0x0a, _utf8mb4'B：お水（　）。'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"がいます","B":"をください","C":"へ行きます","D":"にいます"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：お支払いはこれで結構です。ほかに何か？'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"領収書へ行きます。会社で使います。","B":"領収書がいます。会社で使います。","C":"領収書にいます。会社で使います。","D":"領収書をください。会社で使います。"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：温かいのと冷たいの、どちらですか。'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"冷たいコーヒーにいます。","B":"冷たいコーヒーへ行きます。","C":"冷たいコーヒーをください。","D":"冷たいコーヒーがいます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', CONCAT(_utf8mb4'A：何か足りませんか。', _utf8mb4 0x0a, _utf8mb4'B：すみません、はし（　）。お弁当に使います。'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"がいます","B":"へ行きます","C":"にいます","D":"をください"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：お飲み物は何になさいますか。', _utf8mb4 0x0a, _utf8mb4'B：あたたかいお茶（　）ください。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"を","B":"に","C":"へ","D":"と"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：手紙を出すのですね。', _utf8mb4 0x0a, _utf8mb4'B：はい、切手（　）ください。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"と","B":"へ","C":"を","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', CONCAT(_utf8mb4'A：どちらの色にしますか。', _utf8mb4 0x0a, _utf8mb4'B：赤い方（　）ください。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"に","B":"へ","C":"を","D":"と"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：手紙を出すのですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"はい、切手へ行きます。","B":"はい、切手がいます。","C":"はい、切手にいます。","D":"はい、切手をください。"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：パンをお包みしましょうか。'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"はい、袋がいます。","B":"はい、袋へ行きます。","C":"はい、袋にいます。","D":"はい、袋をください。"},"correctAnswer":"D"}'
