    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：カレーですか、それともラーメンですか。', _utf8mb4 0x0a, _utf8mb4'B：カレー（　）ください。ご飯は少しでいいです。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"に","B":"を","C":"と","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1006, _utf8mb4'EASY', CONCAT(_utf8mb4'A：この町の地図がありますよ。', _utf8mb4 0x0a, _utf8mb4'B：では、駅の近くの地図（　）ください。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"と","B":"に","C":"を","D":"へ"},"correctAnswer":"C"}'
