    UNION ALL SELECT 1018, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ノートは大きい物と小さい物があります。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"では、小さいノートへ行きます。","B":"では、小さいノートをください。","C":"では、小さいノートにいます。","D":"では、小さいノートがいます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1024, _utf8mb4'EASY', CONCAT(_utf8mb4'A：ミルクは使いますか。', _utf8mb4 0x0a, _utf8mb4'B：ええ、ミルク（　）ください。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"と","B":"へ","C":"を","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 1030, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：甘いお菓子はいかがですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"それでは、このクッキーをください。","B":"それでは、このクッキーへ行きます。","C":"それでは、このクッキーがいます。","D":"それでは、このクッキーにいます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「をください」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'すみません、紙をください。ノートを忘れました。'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"Mời người nghe cùng đi mua sắm.","B":"Hỏi giá của đồ vật.","C":"Cho biết đồ vật tồn tại ở đâu.","D":"Yêu cầu người nghe đưa món đồ vừa nêu."},"correctAnswer":"D"}'
    UNION ALL SELECT 1042, _utf8mb4'EASY', CONCAT(_utf8mb4'A：お飲み物は何になさいますか。', _utf8mb4 0x0a, _utf8mb4'B：あたたかいお茶（　）。'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"がいます","B":"にいます","C":"へ行きます","D":"をください"},"correctAnswer":"D"}'
    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この写真を印刷しますか。', _utf8mb4 0x0a, _utf8mb4'B：はい、大きいサイズの写真（　）ください。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"と","B":"を","C":"に","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 2012, _utf8mb4'EASY', CONCAT(_utf8mb4'A：新しいタオルが必要ですか。', _utf8mb4 0x0a, _utf8mb4'B：はい、タオル（　）ください。プールに持って行きます。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"に","B":"へ","C":"と","D":"を"},"correctAnswer":"D"}'
    UNION ALL SELECT 2030, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ペンは赤と黒があります。', _utf8mb4 0x0a, _utf8mb4'B：黒いペン（　）ください。名前を書きます。'), _utf8mb4'を đánh dấu vật muốn nhận trong mẫu N を ください.', _utf8mb4'{"options":{"A":"と","B":"を","C":"へ","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 2048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：切符売り場です。どちらまでですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N を ください là lời xin hoặc gọi một món. Dùng を trước ください để nêu vật muốn nhận.', _utf8mb4'{"options":{"A":"東京までの切符へ行きます。","B":"東京までの切符がいます。","C":"東京までの切符をください。","D":"東京までの切符にいます。"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N を ください。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 13 (N1 の N2)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：何のジャムですか。', _utf8mb4 0x0a, _utf8mb4'B：いちご（　）ジャムです。パンにどうぞ。') AS content, _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.' AS explanation, _utf8mb4'{"options":{"A":"へ","B":"を","C":"に","D":"の"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'A：このジュースは何で作りますか。', _utf8mb4 0x0a, _utf8mb4'B：りんご（　）ジュースです。砂糖は入れません。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：牛乳を使うお菓子はどれですか。', _utf8mb4 0x0a, _utf8mb4'B：これが牛乳（　）プリンです。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"に","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「N の N」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'妹はバナナのパンが好きです。バナナを入れて焼きます。'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"Nêu thời điểm hoàn thành sản phẩm.","B":"Nêu nơi mua sản phẩm.","C":"Nêu nguyên liệu dùng để làm sản phẩm.","D":"Nêu chủ sở hữu của sản phẩm."},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'A：木で作った机ですね。', _utf8mb4 0x0a, _utf8mb4'B：はい。木（　）机は教室で使います。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"の","B":"に","C":"を","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：竹で作る物を見せてください。'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"こちらは竹にかごです。","B":"こちらは竹へかごです。","C":"こちらは竹のかごです。","D":"こちらは竹をかごです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：紙で作った箱もありますか。', _utf8mb4 0x0a, _utf8mb4'B：はい、紙（　）箱は軽いですよ。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"を","D":"の"},"correctAnswer":"D"}'
