    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：木で作った机ですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"はい。木の机は教室で使います。","B":"はい。木を机は教室で使います。","C":"はい。木に机は教室で使います。","D":"はい。木へ机は教室で使います。"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：紙袋ですか。'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"いいえ、布へ袋です。何度も使えます。","B":"いいえ、布の袋です。何度も使えます。","C":"いいえ、布に袋です。何度も使えます。","D":"いいえ、布を袋です。何度も使えます。"},"correctAnswer":"B"}'
