    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'A：いちごではなく桃を入れました。', _utf8mb4 0x0a, _utf8mb4'B：では、桃（　）アイスですね。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"に","B":"の","C":"で","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：竹で作る物を見せてください。', _utf8mb4 0x0a, _utf8mb4'B：こちらは竹（　）かごです。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"の","B":"に","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：紙で作った箱もありますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"はい、紙へ箱は軽いですよ。","B":"はい、紙を箱は軽いですよ。","C":"はい、紙に箱は軽いですよ。","D":"はい、紙の箱は軽いですよ。"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'A：紙袋ですか。', _utf8mb4 0x0a, _utf8mb4'B：いいえ、布（　）袋です。何度も使えます。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：みかんを使っていますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"はい。みかんをゼリーです。","B":"はい。みかんへゼリーです。","C":"はい。みかんのゼリーです。","D":"はい。みかんにゼリーです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：このスープには何を使いますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"魚のスープです。野菜も入れます。","B":"魚をスープです。野菜も入れます。","C":"魚にスープです。野菜も入れます。","D":"魚へスープです。野菜も入れます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'A：ぶどうをしぼって作りました。', _utf8mb4 0x0a, _utf8mb4'B：ぶどう（　）ジュースですね。少し飲んでもいいですか。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：このジュースは何で作りますか。', _utf8mb4 0x0a, _utf8mb4'B：りんご（　）です。砂糖は入れません。'), _utf8mb4'N1 の N2 xác định N2 làm từ nguyên liệu N1. Thứ tự hai danh từ thể hiện vai trò của chúng.', _utf8mb4'{"options":{"A":"にジュース","B":"へジュース","C":"をジュース","D":"のジュース"},"correctAnswer":"D"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：妹さんは何のパンが好きですか。', _utf8mb4 0x0a, _utf8mb4'B：妹はバナナ（　）パンが好きです。バナナを入れて焼きます。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"で","B":"を","C":"の","D":"に"},"correctAnswer":"C"}'
