    UNION ALL SELECT 1031, _utf8mb4'EASY', CONCAT(_utf8mb4'A：いもを使った料理はありますか。', _utf8mb4 0x0a, _utf8mb4'B：じゃがいも（　）サラダがあります。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"の","B":"で","C":"へ","D":"を"},"correctAnswer":"A"}'
