    UNION ALL SELECT 1043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：赤いソースは何から作りましたか。', _utf8mb4 0x0a, _utf8mb4'B：トマト（　）ソースです。パスタに使います。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"に","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 1049, _utf8mb4'EASY', CONCAT(_utf8mb4'A：この皿はプラスチックですか。', _utf8mb4 0x0a, _utf8mb4'B：いいえ、ガラス（　）皿です。落とさないでください。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"を","B":"に","C":"の","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 2013, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：運動会で紙を巻いて花を作りました。', _utf8mb4 0x0a, _utf8mb4'B：きれいな紙（　）花ですね。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"に","B":"を","C":"へ","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 2031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：チョコレートを入れて焼いたんです。', _utf8mb4 0x0a, _utf8mb4'B：チョコレート（　）ケーキですね。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2049, _utf8mb4'EASY', CONCAT(_utf8mb4'A：何の味ですか。コーヒーを使いましたか。', _utf8mb4 0x0a, _utf8mb4'B：はい、コーヒー（　）ゼリーです。'), _utf8mb4'の đứng giữa tên nguyên liệu và tên sản phẩm. Danh từ sau の chỉ thành phẩm.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"に"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 13 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 の N2' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 14 (N1 は なんの N2 ですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：（　）', _utf8mb4 0x0a, _utf8mb4'B：バナナを使って焼きます。') AS content, _utf8mb4'何の + tên món hoặc vật hỏi nó làm từ gì khi câu trả lời nêu nguyên liệu.' AS explanation, _utf8mb4'{"options":{"A":"いつ作りましたか。","B":"だれが作りましたか。","C":"あれは何のケーキですか。","D":"どこで買いましたか。"},"correctAnswer":"C"}' AS answers
