    UNION ALL SELECT 9, _utf8mb4'EASY', CONCAT(_utf8mb4'A：「teacher」は日本語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「先生」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"に","B":"で","C":"へ","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「パン」はベトナム語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「bánh mì」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"を","B":"に","C":"へ","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：辞書を忘れました。「電車」は英語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「train」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"で","B":"に","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', CONCAT(_utf8mb4'A：猫の絵を見てください。これは日本語（　）。', _utf8mb4 0x0a, _utf8mb4'B：「ねこ」と言います。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"に何ですか","B":"で何ですか","C":"へ何ですか","D":"から何ですか"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：地図に「hospital」と書いてあります。日本語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「病院」と言います。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"に","B":"へ","C":"を","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「学校」はベトナム語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「trường học」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"で","B":"に","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', CONCAT(_utf8mb4'A：「おはよう」は英語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「good morning」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：（　）', _utf8mb4 0x0a, _utf8mb4'B：「bánh mì」です。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"「パン」はベトナム語で何ですか。","B":"「パン」はベトナム語へ何ですか。","C":"「パン」はベトナム語から何ですか。","D":"「パン」はベトナム語に何ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：案内に「exit」とありますね。日本語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「出口」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', CONCAT(_utf8mb4'A：飲み物の「コーヒー」は英語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「coffee」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"に","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「rain」は日本語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「雨」と言います。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"を","B":"で","C":"に","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu hỏi đúng.', _utf8mb4 0x0a, _utf8mb4'B：「good morning」です。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"「おはよう」は英語から何ですか。","B":"「おはよう」は英語へ何ですか。","C":"「おはよう」は英語に何ですか。","D":"「おはよう」は英語で何ですか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1003, _utf8mb4'EASY', CONCAT(_utf8mb4'A：メニューの「魚」はベトナム語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「cá」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「で何ですか」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'飲み物の「コーヒー」は英語で何ですか。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"Hỏi người trả lời đang ở nước nào.","B":"Hỏi một từ được nói như thế nào trong một ngôn ngữ.","C":"Đề nghị dịch toàn bộ một cuốn sách.","D":"Hỏi từ ấy thuộc về người nào."},"correctAnswer":"B"}'
    UNION ALL SELECT 1015, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この「駅」という言葉は英語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「station」と言います。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"を","B":"で","C":"へ","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1021, _utf8mb4'EASY', CONCAT(_utf8mb4'A：地図の「library」は日本語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「図書館」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"を","B":"に","C":"で","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：（　）', _utf8mb4 0x0a, _utf8mb4'B：「train」です。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"辞書を忘れました。「電車」は英語で何ですか。","B":"辞書を忘れました。「電車」は英語へ何ですか。","C":"辞書を忘れました。「電車」は英語から何ですか。","D":"辞書を忘れました。「電車」は英語に何ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：家族の言い方を教えてください。「母」はベトナム語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「mẹ」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"を","B":"に","C":"へ","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 1039, _utf8mb4'EASY', CONCAT(_utf8mb4'A：「ありがとう」は英語（　）。', _utf8mb4 0x0a, _utf8mb4'B：「thank you」です。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"に何ですか","B":"から何ですか","C":"へ何ですか","D":"で何ですか"},"correctAnswer":"D"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu hỏi đúng.', _utf8mb4 0x0a, _utf8mb4'B：「出口」です。'), _utf8mb4'Tên ngôn ngữ + で何ですか hỏi cách gọi một ý trong ngôn ngữ đó.', _utf8mb4'{"options":{"A":"案内に「exit」とありますね。日本語で何ですか。","B":"案内に「exit」とありますね。日本語へ何ですか。","C":"案内に「exit」とありますね。日本語に何ですか。","D":"案内に「exit」とありますね。日本語から何ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2015, _utf8mb4'EASY', CONCAT(_utf8mb4'A：ここに書いた「花」は英語（　）何ですか。', _utf8mb4 0x0a, _utf8mb4'B：「flower」です。'), _utf8mb4'で sau tên ngôn ngữ chỉ ngôn ngữ dùng để diễn đạt một từ hoặc ý.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"を","D":"に"},"correctAnswer":"B"}'
