) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 15 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は ～ごで なんですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 16 (N1 の N2)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：このチョコレートはどこの国から来ましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）') AS content, _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.' AS explanation, _utf8mb4'{"options":{"A":"ベルギーをチョコレートです。","B":"ベルギーへチョコレートです。","C":"ベルギーにチョコレートです。","D":"ベルギーのチョコレートです。"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'A：日本で作られた時計をください。', _utf8mb4 0x0a, _utf8mb4'B：では、日本（　）時計をお見せします。'), _utf8mb4'の nối địa danh hoặc tên nước với sản phẩm để nêu xuất xứ trong ngữ cảnh này.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"の","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：京都で作ったお菓子を買えますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.', _utf8mb4'{"options":{"A":"ええ、京都にお菓子があります。","B":"ええ、京都のお菓子があります。","C":"ええ、京都をお菓子があります。","D":"ええ、京都へお菓子があります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：タイでとれたお茶ですか。', _utf8mb4 0x0a, _utf8mb4'B：ええ、タイ（　）お茶を買いました。'), _utf8mb4'の nối địa danh hoặc tên nước với sản phẩm để nêu xuất xứ trong ngữ cảnh này.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'A：このワインはどこの国の物ですか。', _utf8mb4 0x0a, _utf8mb4'B：フランス（　）ワインです。お祝いに買いました。'), _utf8mb4'の nối địa danh hoặc tên nước với sản phẩm để nêu xuất xứ trong ngữ cảnh này.', _utf8mb4'{"options":{"A":"の","B":"に","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「N の N」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'ええ、インドの布で作りました。'), _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.', _utf8mb4'{"options":{"A":"Nêu nguyên liệu tạo ra sản phẩm.","B":"Nêu xuất xứ của sản phẩm.","C":"Nêu người đang sở hữu sản phẩm.","D":"Nêu số lượng sản phẩm được mua."},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ベトナムで作ったコーヒーを探しています。', _utf8mb4 0x0a, _utf8mb4'B：こちらがベトナム（　）コーヒーです。'), _utf8mb4'の nối địa danh hoặc tên nước với sản phẩm để nêu xuất xứ trong ngữ cảnh này.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'A：日本で作られた時計をください。', _utf8mb4 0x0a, _utf8mb4'B：では、日本（　）をお見せします。'), _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.', _utf8mb4'{"options":{"A":"へ時計","B":"を時計","C":"に時計","D":"の時計"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：かばんに「イタリア製」とありますね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.', _utf8mb4'{"options":{"A":"はい。イタリアにかばんです。","B":"はい。イタリアへかばんです。","C":"はい。イタリアのかばんです。","D":"はい。イタリアをかばんです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：中国から届いたお皿はどれですか。'), _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.', _utf8mb4'{"options":{"A":"この白いのが中国へお皿です。","B":"この白いのが中国にお皿です。","C":"この白いのが中国のお皿です。","D":"この白いのが中国をお皿です。"},"correctAnswer":"C"}'
