    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ベトナムで作ったコーヒーを探しています。', _utf8mb4 0x0a, _utf8mb4'B：こちらがベトナム（　）です。'), _utf8mb4'N nơi chốn + の + N sản phẩm cho biết sản phẩm có xuất xứ từ nơi đó.', _utf8mb4'{"options":{"A":"にコーヒー","B":"のコーヒー","C":"へコーヒー","D":"をコーヒー"},"correctAnswer":"B"}'
