    UNION ALL SELECT 2016, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：スペインで作った油をください。', _utf8mb4 0x0a, _utf8mb4'B：はい。これがスペイン（　）油です。'), _utf8mb4'の nối địa danh hoặc tên nước với sản phẩm để nêu xuất xứ trong ngữ cảnh này.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"の","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 2034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どこの国のお金ですか。', _utf8mb4 0x0a, _utf8mb4'B：これはカナダ（　）お金です。'), _utf8mb4'の nối địa danh hoặc tên nước với sản phẩm để nêu xuất xứ trong ngữ cảnh này.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 16 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 の N2' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 17 (N を số lượng (～つ) ください。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'A：パンはいくつですか。', _utf8mb4 0x0a, _utf8mb4'B：バターパン（　）二つください。') AS content, _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.' AS explanation, _utf8mb4'{"options":{"A":"に","B":"と","C":"へ","D":"を"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：スープは四人分ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'四つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"はい、スープを四回ください。","B":"はい、スープを五つください。","C":"はい、スープを四つください。","D":"はい、スープを七つください。"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：三人分ですね。おにぎりは一人一つですか。', _utf8mb4 0x0a, _utf8mb4'B：はい、おにぎり（　）三つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"に","B":"を","C":"と","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'A：りんごを一つだけ買いますか。', _utf8mb4 0x0a, _utf8mb4'B：はい。りんご（　）一つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"に","B":"を","C":"と","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：箱は一人一つです。五人ですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'五つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"はい、小さい箱を五つください。","B":"はい、小さい箱を五人ください。","C":"はい、小さい箱を六つください。","D":"はい、小さい箱を八つください。"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「～つください」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'はい、しゃけのおにぎりを七つください。'), _utf8mb4'七つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"Xin biết món đó ở tầng mấy.","B":"Chỉ nơi đã sản xuất đồ vật.","C":"Hỏi một món có giá bao nhiêu.","D":"Yêu cầu một số lượng đồ vật cụ thể."},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'A：スープは四人分ですか。', _utf8mb4 0x0a, _utf8mb4'B：はい、スープ（　）四つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"を","D":"と"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：パンはいくつですか。', _utf8mb4 0x0a, _utf8mb4'B：バターパンを（　）ください。'), _utf8mb4'二つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"二時","B":"二人","C":"二つ","D":"二階"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：箱は一人一つです。五人ですね。', _utf8mb4 0x0a, _utf8mb4'B：はい、小さい箱（　）五つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"へ","B":"と","C":"に","D":"を"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'A：プリンを二つ持っています。もう一つですか。', _utf8mb4 0x0a, _utf8mb4'B：ええ、プリン（　）一つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"と","B":"を","C":"へ","D":"に"},"correctAnswer":"B"}'
