    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu đáp đúng.', _utf8mb4 0x0a, _utf8mb4'A：お子さん二人とご自分に、一つずつですね。'), _utf8mb4'三つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"はい、そのクッキーを六つください。","B":"はい、そのクッキーを三つください。","C":"はい、そのクッキーを三時ください。","D":"はい、そのクッキーを四つください。"},"correctAnswer":"B"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', CONCAT(_utf8mb4'A：お子さん二人とご自分に、一つずつですね。', _utf8mb4 0x0a, _utf8mb4'B：はい、そのクッキー（　）三つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"に","B":"を","C":"へ","D":"と"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：お子さん二人に一つずつですか。', _utf8mb4 0x0a, _utf8mb4'B：ええ、このおもちゃ（　）二つください。'), _utf8mb4'を đánh dấu món cần lấy. Số lượng đặt sau món và trước ください.', _utf8mb4'{"options":{"A":"へ","B":"と","C":"に","D":"を"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：プリンを二つ持っています。もう一つですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'一つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"ええ、プリンを一つください。","B":"ええ、プリンを四つください。","C":"ええ、プリンを二つください。","D":"ええ、プリンを一時ください。"},"correctAnswer":"A"}'
