    UNION ALL SELECT 2035, _utf8mb4'EASY', CONCAT(_utf8mb4'A：りんごを一つだけ買いますか。', _utf8mb4 0x0a, _utf8mb4'B：はい。りんごを（　）ください。'), _utf8mb4'一つ là số lượng đồ vật theo cách đếm ～つ. Lượng từ đứng trước ください.', _utf8mb4'{"options":{"A":"四つ","B":"二つ","C":"一時","D":"一つ"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 2
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 17 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N を số lượng (～つ) ください。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 2 / NGỮ PHÁP / Mẫu 18 (N1 の N2／だれの N2 ですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：（　）', _utf8mb4 0x0a, _utf8mb4'B：先生のかばんです。') AS content, _utf8mb4'だれの + tên vật hỏi vật thuộc về ai. Người đáp nêu chủ sở hữu bằng N の (です).' AS explanation, _utf8mb4'{"options":{"A":"どこで買いましたか。","B":"この品はいくらですか。","C":"机の上に置いてありました。あれはだれのかばんですか。","D":"いつ買いましたか。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'「だれの」 có vai trò gì trong câu sau?', _utf8mb4 0x0a, _utf8mb4'窓のそばに置いてあるのはだれの帽子ですか。'), _utf8mb4'だれの + tên vật hỏi vật thuộc về ai. Người đáp nêu chủ sở hữu bằng N の (です).', _utf8mb4'{"options":{"A":"Hỏi ai là chủ sở hữu của vật.","B":"Hỏi nên mua vật ở đâu.","C":"Hỏi ai đã sản xuất vật.","D":"Hỏi vật được làm từ gì."},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu hỏi đúng.', _utf8mb4 0x0a, _utf8mb4'B：友達のです。今日だけ借りました。'), _utf8mb4'だれの + tên vật hỏi vật thuộc về ai. Người đáp nêu chủ sở hữu bằng N の (です).', _utf8mb4'{"options":{"A":"駅まで乗るんですね。それはだれの自転車ですか。","B":"駅まで乗るんですね。それはどこの自転車ですか。","C":"駅まで乗るんですね。それはいつの自転車ですか。","D":"駅まで乗るんですね。それは何の自転車ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：これはだれ（　）傘ですか。', _utf8mb4 0x0a, _utf8mb4'B：山田さんのです。'), _utf8mb4'Trong だれの + N, の nối từ hỏi だれ với vật cần xác định chủ sở hữu.', _utf8mb4'{"options":{"A":"を","B":"に","C":"へ","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：拾った物です。これはだれ（　）手帳ですか。', _utf8mb4 0x0a, _utf8mb4'B：私のです。返してくれてありがとう。'), _utf8mb4'Trong だれの + N, の nối từ hỏi だれ với vật cần xác định chủ sở hữu.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：（　）', _utf8mb4 0x0a, _utf8mb4'B：父の時計です。'), _utf8mb4'だれの + tên vật hỏi vật thuộc về ai. Người đáp nêu chủ sở hữu bằng N の (です).', _utf8mb4'{"options":{"A":"どこで買いましたか。","B":"この品はいくらですか。","C":"金色ですね。それはだれの時計ですか。","D":"いつ買いましたか。"},"correctAnswer":"C"}'
