    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', _utf8mb4'Hỏi tháng diễn ra lễ hội mùa thu.', _utf8mb4'「何月」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"秋祭りは何分ですか。","B":"秋祭りは何歳ですか。","C":"秋祭りは何月ですか。","D":"秋祭りは何階ですか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1033, _utf8mb4'EASY', _utf8mb4'「カードは（　）使えますか。」「今年の十二月までです。」', _utf8mb4'「いつまで」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"だれから","B":"どこまで","C":"いくらで","D":"いつまで"},"correctAnswer":"D"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', _utf8mb4'「りんごが赤くなるのは（　）ですか。」「秋です。」', _utf8mb4'「いつ」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"どこ","B":"いつ","C":"いくら","D":"だれ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1043, _utf8mb4'MEDIUM', _utf8mb4'お祭り（　）いつですか。「お祭り」を話題にして日程を聞きます。', _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 1048, _utf8mb4'EASY', _utf8mb4'「運動会は（　）にありますか。」「次の日曜日です。」', _utf8mb4'「何曜日」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"何階","B":"何人","C":"何曜日","D":"何時間"},"correctAnswer":"C"}'
    UNION ALL SELECT 2003, _utf8mb4'MEDIUM', _utf8mb4'「日本に来たのは何年の（　）ですか。」「二〇二五年の八月です。」', _utf8mb4'「何月」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"何歳","B":"何月","C":"何分","D":"何階"},"correctAnswer":"B"}'
    UNION ALL SELECT 2017, _utf8mb4'MEDIUM', _utf8mb4'実習はいつ（　）始まりますか。開始時期を尋ねます。', _utf8mb4'「から」. から đánh dấu mốc bắt đầu.', _utf8mb4'{"options":{"A":"から","B":"だけ","C":"まで","D":"ほど"},"correctAnswer":"A"}'
    UNION ALL SELECT 2031, _utf8mb4'EASY', _utf8mb4'「次の注文は（　）できますか。」「明日の朝からです。」', _utf8mb4'「いつから」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"いつから","B":"どこから","C":"何名で","D":"どの駅へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2045, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：卒業式はいつでしたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「先週の水曜日でした」. いつ hỏi thời điểm. Thêm から để hỏi lúc bắt đầu, まで để hỏi hạn cuối.', _utf8mb4'{"options":{"A":"とても楽しかったです。","B":"朝から一時間でした。","C":"体育館の中でした。","D":"先週の水曜日でした。"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 3 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は いつですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 4 (N は Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'毎朝、果物（　）食べます。食べる対象は果物です。' AS content, _utf8mb4'「を」. を đặt sau đối tượng trực tiếp của hành động.' AS explanation, _utf8mb4'{"options":{"A":"が","B":"の","C":"を","D":"へ"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'毎朝、新聞を（　）。「読む」を普段の習慣として丁寧に言います。'), _utf8mb4'Dùng 読みます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"読みません","B":"読みませんでした","C":"読みました","D":"読みます"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：朝、市場で何をしますか。花屋さんですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい。店で売る花を買います」. ます là dạng lịch sự khẳng định dùng cho thói quen hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"花の店は駅の前です。","B":"朝七時までです。","C":"はい。店で売る花を買います。","D":"花は昨日届きました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'「弟は毎朝走ります。」ます kết hợp với 毎朝 diễn đạt gì?', _utf8mb4'ます là dạng lịch sự khẳng định dùng cho thói quen hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"Một lần em đã chạy hôm qua.","B":"Lệnh yêu cầu em chạy ngay.","C":"Thói quen chạy mỗi sáng của em trai.","D":"Mong muốn được đi bộ của em."},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'朝食にパンを（　）。今の習慣です。〔食べる〕'), _utf8mb4'Dùng 食べます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"食べました","B":"食べます","C":"食べませんでした","D":"食べません"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ふだん、だれがお弁当を作りますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「父が作ります」. ます là dạng lịch sự khẳng định dùng cho thói quen hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"台所で作ります。","B":"お昼の分を作ります。","C":"朝六時に作ります。","D":"父が作ります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'家が近いので、駅まで（　）。〔歩く・ふだん〕'), _utf8mb4'Dùng 歩きます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"歩きます","B":"歩きません","C":"歩きました","D":"歩きませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'雨の日、教室で静かに本を（　）。〔見る・いつも〕'), _utf8mb4'Dùng 見ます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"見ませんでした","B":"見ます","C":"見ません","D":"見ました"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'母は自転車（　）働きに行きます。移動の手段です。', _utf8mb4'「で」. で cho biết nơi, cách thức hoặc phương tiện thực hiện hành động.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'私は郵便局で（　）。〔働く・現在の仕事〕'), _utf8mb4'Dùng 働きます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"働きます","B":"働きました","C":"働きませんでした","D":"働きません"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'週に一度、家族に手紙を（　）。〔書く・いつも〕'), _utf8mb4'Dùng 書きます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"書きません","B":"書きます","C":"書きました","D":"書きませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：これから郵便局で何をしますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「友達に荷物を送ります」. ます là dạng lịch sự khẳng định dùng cho thói quen hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"友達に荷物を送ります。","B":"きのう届きました。","C":"友達に送りましたか。","D":"荷物は重かったです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'昼休みに同僚（　）話します。会話の相手を表します。', _utf8mb4'「と」. と đánh dấu người cùng tham gia hành động hoặc hội thoại.', _utf8mb4'{"options":{"A":"の","B":"を","C":"と","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'電車が来るまでここで（　）。〔待つ・これから〕'), _utf8mb4'Dùng 待ちます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"待ちます","B":"待ちません","C":"待ちました","D":"待ちませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'次の休日は友達と山に（　）。〔登る・予定〕'), _utf8mb4'Dùng 登ります để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"登ります","B":"登りません","C":"登りませんでした","D":"登りました"},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'日が暮れると寮（　）帰ります。帰る方向を示します。', _utf8mb4'「へ」. へ nêu hướng di chuyển hoặc nơi đang hướng tới.', _utf8mb4'{"options":{"A":"で","B":"を","C":"の","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'父は毎朝、牛乳を（　）。〔飲む・普段〕'), _utf8mb4'Dùng 飲みます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"飲みました","B":"飲みませんでした","C":"飲みます","D":"飲みません"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'祖母は朝早く（　）。〔起きる・習慣〕'), _utf8mb4'Dùng 起きます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"起きません","B":"起きませんでした","C":"起きました","D":"起きます"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'あした、転校する友達に（　）。〔会う・予定〕'), _utf8mb4'Dùng 会います để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"会いました","B":"会いませんでした","C":"会いません","D":"会います"},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'店員は毎朝、入口を（　）。〔掃除する・習慣〕'), _utf8mb4'Dùng 掃除します để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"掃除しませんでした","B":"掃除します","C":"掃除しません","D":"掃除しました"},"correctAnswer":"B"}'
    UNION ALL SELECT 1004, _utf8mb4'MEDIUM', _utf8mb4'「来週、港で働きます。」Người nói cho biết gì?', _utf8mb4'来週 xác định tương lai, nên 働きます ở đây nêu kế hoạch làm việc.', _utf8mb4'{"options":{"A":"Kế hoạch làm việc ở cảng tuần sau.","B":"Thói quen đã bỏ từ tuần trước.","C":"Công việc ở cảng đã kết thúc.","D":"Lời mời cùng nghỉ làm."},"correctAnswer":"A"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', _utf8mb4'Báo việc thường làm mỗi chiều bằng lối lịch sự.', _utf8mb4'「歩きます」. ます là dạng lịch sự khẳng định dùng cho thói quen hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"毎夕、犬と近所を歩きませんでした。","B":"毎夕、犬と近所を歩きました。","C":"毎夕、犬と近所を歩きます。","D":"毎夕、犬と近所を歩きません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1014, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'姉は毎週、近所の子に英語を（　）。〔教える・習慣〕'), _utf8mb4'Dùng 教えます để nêu khẳng định lịch sự về việc thường làm hoặc việc sắp làm.', _utf8mb4'{"options":{"A":"教えません","B":"教えました","C":"教えませんでした","D":"教えます"},"correctAnswer":"D"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', _utf8mb4'毎晩八時（　）ラジオを聞きます。開始時刻を示します。', _utf8mb4'「に」. に nêu mốc giờ, nơi tồn tại hoặc đích tiếp nhận tùy ngữ cảnh.', _utf8mb4'{"options":{"A":"を","B":"に","C":"で","D":"の"},"correctAnswer":"B"}'
