    UNION ALL SELECT 2019, _utf8mb4'MEDIUM', _utf8mb4'試食コーナーで小さいパン（　）食べます。', _utf8mb4'「を」. を theo sau thứ hoặc người chịu tác động trực tiếp của động từ.', _utf8mb4'{"options":{"A":"が","B":"を","C":"へ","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 2033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：先生に何を渡しましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「書いたレポートを渡しました」. を theo sau thứ hoặc người chịu tác động trực tiếp của động từ.', _utf8mb4'{"options":{"A":"授業の後で渡しました。","B":"教室の前で渡しました。","C":"一人で渡しました。","D":"書いたレポートを渡しました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2047, _utf8mb4'EASY', _utf8mb4'発表で新しい商品（　）紹介します。', _utf8mb4'「を」. を theo sau thứ hoặc người chịu tác động trực tiếp của động từ.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"が"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N を Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 6 (Địa điểm へ いきます／かえります。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'Diễn đạt hướng đi đến cổng phía đông.' AS content, _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.' AS explanation, _utf8mb4'{"options":{"A":"大勢の人が東門へ向かいます。","B":"大勢の人が東門の向かいます。","C":"大勢の人が東門を向かいます。","D":"大勢の人が東門で向かいます。"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'「山へ向かいます。」へ nói lên điều gì?', _utf8mb4'へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"Nơi bắt đầu di chuyển.","B":"Công cụ dùng để leo núi.","C":"Địa điểm đang làm việc.","D":"Hướng đi về phía núi."},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'放課後、自宅に戻るので「家へ（　）」と言います。〔帰る・これから〕'), _utf8mb4'「帰ります」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"帰りません","B":"帰ります","C":"帰りませんでした","D":"帰りました"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'本を返しに図書館（　）行きます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"で","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：もう仕事は終わりました。今からどこへ帰りますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「自分の家へ帰ります」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"同僚と帰ります。","B":"電車で帰ります。","C":"自分の家へ帰ります。","D":"五時に帰ります。"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'入院していた父は午後、家（　）帰ります。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"で","C":"へ","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'Nói người nói về quê sau khi tốt nghiệp.', _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"卒業したら故郷の帰ります。","B":"卒業したら故郷で帰ります。","C":"卒業したら故郷を帰ります。","D":"卒業したら故郷へ帰ります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'教科書を忘れたので教室（　）戻ります。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"で","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', _utf8mb4'「これからどちらへ（　）。」「市役所へ行きます。」行き先を聞く形です。', _utf8mb4'「行きますか」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"行きました","B":"行きましょう","C":"行きますか","D":"行きませんでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'手紙を出しに郵便局（　）行きます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"を","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'船に乗って海の向こうの島（　）向かいます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"で","C":"へ","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'卒業したら自分の国（　）帰ります。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'日曜日は試合の応援に競技場（　）行きます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu dùng trợ từ chỉ hướng để nói đi đến rạp hát.', _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"夕方、初めての劇場の行きます。","B":"夕方、初めての劇場へ行きます。","C":"夕方、初めての劇場を行きます。","D":"夕方、初めての劇場で行きます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'「次は山の中の駅へ（　）。」〔向かう・これから〕'), _utf8mb4'「向かいます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"向かいました","B":"向かいません","C":"向かいませんでした","D":"向かいます"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'雨が強くなったので宿（　）戻ります。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"を","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：足をけがしました。まずどこへ行きますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「病院へ行きます」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"病院へ行きます。","B":"三時に行きます。","C":"五分で行きます。","D":"足で行きます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'会議の後、みんなで食堂（　）移動します。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"を","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'今年の夏は涼しい山（　）旅行します。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'留学のため、来月日本（　）出発します。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 1001, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'診察を受けに町の病院（　）行きます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 1006, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この矢印は何ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「出口へ進む方向を示しています」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"出口で休む時間です。","B":"出口へ進む方向を示しています。","C":"出口を作る人です。","D":"出口から来た人の名前です。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1011, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'赤ちゃんを迎えに保育園（　）行きます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"を","B":"で","C":"の","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 1016, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'乗り換えのため地下のホーム（　）向かいます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"で","B":"の","C":"へ","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'最後の客を送って店（　）戻ります。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"で","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1026, _utf8mb4'MEDIUM', _utf8mb4'Nói người đi bộ quay lại lối vào.', _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"道を間違えて入口へ戻ります。","B":"道を間違えて入口の戻ります。","C":"道を間違えて入口を戻ります。","D":"道を間違えて入口で戻ります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1031, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'祖父に会いに田舎（　）帰ります。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"で","B":"の","C":"へ","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'案内板の矢印を見て出口（　）進みます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"を","B":"の","C":"で","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 1041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どうして教室へ戻るんですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ノートを置いてきたからです」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"三冊持っていますか。","B":"ノートを置いてきたからです。","C":"教室へ戻る方角です。","D":"いいえ、図書館の二階です。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1046, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'地図を教室に置いてきました。今から教室へ（　）。〔戻る〕'), _utf8mb4'「戻ります」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"戻ります","B":"戻りません","C":"戻りませんでした","D":"戻りました"},"correctAnswer":"A"}'
    UNION ALL SELECT 2006, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：切手を買いたいです。どこへ行けばいいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「郵便局へ行きましょう」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"切手から帰りましょう。","B":"郵便局へ行きましょう。","C":"郵便局を行きましょう。","D":"切手を戻りましょう。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2020, _utf8mb4'MEDIUM', _utf8mb4'「この廊下を通って出口へ行きます。」出口 là gì trong lộ trình?', _utf8mb4'へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"Nơi đã rời đi lúc đầu.","B":"Đích hướng tới sau khi đi qua hành lang.","C":"Thời điểm kết thúc giờ nghỉ.","D":"Phương tiện dùng để đi qua hành lang."},"correctAnswer":"B"}'
    UNION ALL SELECT 2034, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'必要な資料を取りに事務室（　）行きます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 2048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu hướng di chuyển.', _utf8mb4 0x0a, _utf8mb4'朝、寮を出て大学（　）歩いていきます。'), _utf8mb4'「へ」. へ theo sau đích đến, chỉ hướng của hành động di chuyển.', _utf8mb4'{"options":{"A":"を","B":"で","C":"の","D":"へ"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 6 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm へ いきます／かえります。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 7 (Vます → Vません。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'今月は節約します。タクシーには（　）。〔乗る・今後の方針〕') AS content, _utf8mb4'「乗りません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.' AS explanation, _utf8mb4'{"options":{"A":"乗りませんでした","B":"乗ります","C":"乗りません","D":"乗りました"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'体を冷やすので、夜は氷水を（　）。〔飲む・いつも〕'), _utf8mb4'「飲みません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"飲みません","B":"飲みます","C":"飲みませんでした","D":"飲みました"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'おなかが痛いので今日は冷たい物（　）食べません。', _utf8mb4'「を」. を đặt sau đối tượng trực tiếp của hành động.', _utf8mb4'{"options":{"A":"を","B":"の","C":"が","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'車は使いません。バス（　）出かけます。移動手段を示します。', _utf8mb4'「で」. で cho biết nơi, cách thức hoặc phương tiện thực hiện hành động.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'私は日曜日は（　）。店が休みです。〔働く〕'), _utf8mb4'「働きません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"働きませんでした","B":"働きません","C":"働きます","D":"働きました"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'肉が苦手なので牛肉は（　）。〔食べる・普段〕'), _utf8mb4'「食べません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"食べます","B":"食べました","C":"食べませんでした","D":"食べません"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'明日は休みなので早く（　）。〔起きる〕'), _utf8mb4'「起きません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"起きました","B":"起きません","C":"起きませんでした","D":"起きます"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', _utf8mb4'身分証が必要な店です。今日はその店（　）行きません。行き先を示します。', _utf8mb4'「へ」. へ nêu hướng di chuyển hoặc nơi đang hướng tới.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"を","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：夕飯を外で食べますか。今日は家で食べたいです。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「では、外では食べません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"では、外では食べません。","B":"では、外で食べましょう。","C":"では、家では食べません。","D":"では、外で食べました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：バスに乗りますか。ここから近いので歩きたいです。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいですね。バスには乗りません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"いいですね。タクシーで来ました。","B":"いいですね。バスに乗りました。","C":"いいですね。バスには乗りません。","D":"いいですね。歩きません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'この時間は赤ちゃんが寝ています。テレビは（　）。〔見る〕'), _utf8mb4'「見ません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"見ませんでした","B":"見ます","C":"見ません","D":"見ました"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：今夜も残業しますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、今日は残業しません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"いいえ、今日は残業しましたか。","B":"いいえ、今日は残業しません。","C":"いいえ、明日は残業でした。","D":"いいえ、毎日残業します。"},"correctAnswer":"B"}'
