    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'授業中は個人のメールを（　）。〔読む・規則〕'), _utf8mb4'「読みません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"読みます","B":"読みませんでした","C":"読みました","D":"読みません"},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'今日は電車が止まっています。駅には（　）。〔行く〕'), _utf8mb4'「行きません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"行きます","B":"行きませんでした","C":"行きました","D":"行きません"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'Nói về thói quen không đánh thức em bé.', _utf8mb4'「起こしません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"昼寝の間は赤ちゃんを起こしません。","B":"昼寝の間は赤ちゃんを起こします。","C":"昼寝の間は赤ちゃんを起こしませんでした。","D":"昼寝の間は赤ちゃんを起こしました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', _utf8mb4'病院で大きな声（　）話しません。話し方を表します。', _utf8mb4'「で」. で cho biết nơi, cách thức hoặc phương tiện thực hiện hành động.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この池で泳ぎますか。遊泳は禁止ですよ。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「もちろん泳ぎません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"泳ぎたいので入ります。","B":"では泳ぎましょう。","C":"もちろん泳ぎません。","D":"毎日ここで泳ぎます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'「平日はテレビを見ません。」Chọn ý đúng về lối nói này.', _utf8mb4'ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"Phủ định thói quen xem ti vi ngày thường một cách lịch sự.","B":"Mời người nghe cùng xem ngày nghỉ.","C":"Khẳng định đã xem ti vi hôm qua.","D":"Phủ định một lần đã xem từ năm ngoái."},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'この鉛筆は短すぎます。試験では（　）。〔使う〕'), _utf8mb4'「使いません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"使いました","B":"使います","C":"使いませんでした","D":"使いません"},"correctAnswer":"D"}'
    UNION ALL SELECT 1002, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'雨の日の練習はありません。外では（　）。〔走る〕'), _utf8mb4'「走りません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"走りませんでした","B":"走ります","C":"走りました","D":"走りません"},"correctAnswer":"D"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'ここは禁煙です。たばこを（　）。〔吸う〕'), _utf8mb4'「吸いません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"吸いました","B":"吸いません","C":"吸いませんでした","D":"吸います"},"correctAnswer":"B"}'
    UNION ALL SELECT 1012, _utf8mb4'EASY', _utf8mb4'「荷物は持ちません（　）」と、持つかどうかを尋ねます。', _utf8mb4'「か」. か ở cuối câu biểu thị câu hỏi.', _utf8mb4'{"options":{"A":"か","B":"を","C":"に","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：明日は朝早く起きますか。休みだからゆっくり寝ますね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ええ、早くは起きません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"ええ、早く起きました。","B":"ええ、寝ませんでした。","C":"ええ、今朝起きてください。","D":"ええ、早くは起きません。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1022, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'試着だけです。今日は服を（　）。〔買う〕'), _utf8mb4'「買いません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"買いました","B":"買いません","C":"買います","D":"買いませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 1027, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'静かな部屋なので、大きな声で（　）。〔話す〕'), _utf8mb4'「話しません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"話しませんでした","B":"話しました","C":"話しません","D":"話します"},"correctAnswer":"C"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', _utf8mb4'「明日は出勤しません。」Người nói báo điều gì?', _utf8mb4'ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"Ngày mai mình sẽ không đi làm.","B":"Ngày nào mình cũng đi làm.","C":"Ngày mai hãy cùng đi làm.","D":"Hôm qua mình đã nghỉ làm."},"correctAnswer":"A"}'
    UNION ALL SELECT 1037, _utf8mb4'MEDIUM', _utf8mb4'Máy bận, bạn định không gọi lại tối nay.', _utf8mb4'「かけません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"今夜はもう電話をかけます。","B":"今夜はもう電話をかけませんでした。","C":"今夜はもう電話をかけません。","D":"今夜はもう電話をかけました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1042, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'しばらく連絡は手紙だけです。電話は（　）。〔かける〕'), _utf8mb4'「かけません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"かけませんでした","B":"かけました","C":"かけません","D":"かけます"},"correctAnswer":"C"}'
    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'風邪なので、今週の大会には（　）。〔出る〕'), _utf8mb4'「出ません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"出ませんでした","B":"出ません","C":"出ました","D":"出ます"},"correctAnswer":"B"}'
    UNION ALL SELECT 2007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'妹はまだ小さいので、一人では道を（　）。〔渡る〕'), _utf8mb4'「渡りません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"渡りません","B":"渡ります","C":"渡りませんでした","D":"渡りました"},"correctAnswer":"A"}'
    UNION ALL SELECT 2021, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'水曜日は閉館日です。ドアは（　）。〔開く〕'), _utf8mb4'「開きません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"開きません","B":"開きます","C":"開きませんでした","D":"開きました"},"correctAnswer":"A"}'
    UNION ALL SELECT 2035, _utf8mb4'MEDIUM', _utf8mb4'Diễn đạt quy tắc không chụp ảnh trong bảo tàng.', _utf8mb4'「撮りません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"展示室では写真を撮ります。","B":"展示室では写真を撮りませんでした。","C":"展示室では写真を撮りません。","D":"展示室では写真を撮りました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'紙がもったいないので、この資料は（　）。〔印刷する〕'), _utf8mb4'「印刷しません」. ません là dạng phủ định lịch sự của động từ ở hiện tại hoặc tương lai.', _utf8mb4'{"options":{"A":"印刷します","B":"印刷しませんでした","C":"印刷しました","D":"印刷しません"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます → Vません。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 8 (Địa điểm で N を Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'食堂（　）昼ご飯を食べてから教室に戻ります。') AS content, _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.' AS explanation, _utf8mb4'{"options":{"A":"で","B":"を","C":"の","D":"へ"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'予約した本は図書館の受付（　）受け取ります。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'新しいカフェで日記を（　）。〔書く・いつも〕'), _utf8mb4'「書きます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"書きません","B":"書きます","C":"書きました","D":"書きませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'映画館（　）古い日本映画を見ました。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"を","B":"で","C":"へ","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どこで切符を買いましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「駅の自動販売機で買いました」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"友達の分を買いました。","B":"二枚買いました。","C":"朝の九時に買いました。","D":"駅の自動販売機で買いました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'Bạn muốn nói đã đổi tiền ở ngân hàng.', _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"銀行をお金を換えました。","B":"銀行へお金を換えました。","C":"銀行でお金を換えました。","D":"銀行のお金を換えました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'台所（　）夕飯を作っています。いいにおいです。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'Nêu địa điểm diễn ra buổi biểu diễn.', _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"学校のホールへ演奏します。","B":"学校のホールで演奏します。","C":"学校のホールの演奏します。","D":"学校のホールを演奏します。"},"correctAnswer":"B"}'
