    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'公園のベンチ（　）木の絵を描きます。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"を","B":"で","C":"へ","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'校庭（　）体操をしてから走ります。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"で"},"correctAnswer":"D"}'
