    UNION ALL SELECT 1003, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どこでこの写真を撮りましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「湖のそばで撮りました」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"スマホで撮りました。","B":"父が撮りました。","C":"日曜日に撮りました。","D":"湖のそばで撮りました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1008, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'市民プール（　）子どもたちが泳ぎます。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 1013, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'会議室（　）次の行事について相談します。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"を","D":"の"},"correctAnswer":"A"}'
