    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'次の停留所でバスを（　）。〔降りる・これから〕'), _utf8mb4'「降ります」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"降りませんでした","B":"降ります","C":"降りました","D":"降りません"},"correctAnswer":"B"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：雨でもどこで遊べますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「屋内の体育館で遊べます」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"屋内の体育館で遊べます。","B":"ボールで遊べます。","C":"二人で遊べます。","D":"五時まで遊べます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1038, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'本屋（　）新しい雑誌を探しています。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"で","D":"を"},"correctAnswer":"C"}'
