    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'玄関（　）靴を脱いでから入ってください。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 2008, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'学校のホールで歌を（　）。〔歌う・これから〕'), _utf8mb4'「歌います」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"歌いませんでした","B":"歌いました","C":"歌いません","D":"歌います"},"correctAnswer":"D"}'
    UNION ALL SELECT 2022, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'山の上（　）景色の写真を撮りました。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"の","B":"で","C":"へ","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 2036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'畑（　）家族と野菜を育てます。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 2050, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu nơi diễn ra hành động.', _utf8mb4 0x0a, _utf8mb4'ホテルのロビー（　）重いかばんを預けました。'), _utf8mb4'「で」. で theo sau địa điểm nơi hành động diễn ra.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"で"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm で N を Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 9 (まいにち／まいあさ／まいばん + Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'起きたら必ず水を飲みます。（　）の習慣です。' AS content, _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.' AS explanation, _utf8mb4'{"options":{"A":"毎朝","B":"来月だけ","C":"昨日だけ","D":"毎晩"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'「毎晩、戸を閉めます。」Việc đóng cửa diễn ra khi nào?', _utf8mb4'毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"Mỗi tối.","B":"Chỉ tối hôm qua.","C":"Mỗi cuối tháng.","D":"Mỗi sáng."},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', _utf8mb4'寝る前にはいつも日記をつけます。（　）書きます。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝","B":"先月だけ","C":"一度だけ","D":"毎晩"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'「毎日電話します。」Câu này khẳng định điều gì?', _utf8mb4'毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"Chỉ gọi vào đúng buổi sáng.","B":"Đã ngừng việc gọi điện.","C":"Gọi điện hằng ngày, chưa nêu giờ cụ thể.","D":"Chỉ gọi một lần trong tuần."},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu nói bạn lau kính mỗi sáng.', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"来月だけ、起きてすぐ眼鏡をふきます。","B":"毎朝、起きてすぐ眼鏡をふきます。","C":"毎晩、起きてすぐ眼鏡をふきます。","D":"昨日だけ、起きてすぐ眼鏡をふきます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', _utf8mb4'曜日に関係なく犬を散歩させます。（　）の大事な仕事です。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"月に一度","B":"毎日","C":"年に一度","D":"週に一度"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：お父さんは何時に新聞を読みますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「毎朝、朝食の前に読みます」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝、朝食の前に読みます。","B":"通勤の電車の中です。","C":"一部だけです。","D":"地元の新聞です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：寝る前に、いつも何をしますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「毎晩、明日の予定を確認します」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝、目覚ましで起きます。","B":"明後日は休みです。","C":"昨夜だけ予定を決めました。","D":"毎晩、明日の予定を確認します。"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', _utf8mb4'朝食の後はいつも歯をみがきます。私は（　）歯をみがきます。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝","B":"来月だけ","C":"昨日だけ","D":"毎晩"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'Nói về việc lặp lại tất cả các ngày trong tuần.', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"年に一度、朝か晩に猫の世話をします。","B":"毎日、朝か晩に猫の世話をします。","C":"月に一度、朝か晩に猫の世話をします。","D":"週に一度、朝か晩に猫の世話をします。"},"correctAnswer":"B"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'月曜も火曜も休みません。一日も欠かさず（　）漢字を三つ書きます。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"年に一度","B":"月に一度","C":"毎日","D":"週に一度"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', _utf8mb4'夜になると、いつも家族に電話します。（　）、寝る前にかけています。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"先月だけ","B":"一度だけ","C":"毎朝","D":"毎晩"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'新聞は朝刊だけです。父は（　）起きてすぐ読みます。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"昨日だけ","B":"来月だけ","C":"毎晩","D":"毎朝"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'暗くなってから、いつも戸締まりを確かめます。（　）の仕事です。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"先月だけ","B":"毎朝","C":"毎晩","D":"一度だけ"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', _utf8mb4'一年中、朝から薬を飲んでいます。起きるたびに（　）飲みます。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝","B":"昨日だけ","C":"来月だけ","D":"毎晩"},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'一日一回、花に水をやります。時間は朝でも夜でもよく、（　）続けます。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"年に一度","B":"月に一度","C":"毎日","D":"週に一度"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：ラジオ体操は土日も続けていますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、毎日続けています」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"はい、日曜はしません。","B":"はい、毎日続けています。","C":"はい、一度だけしました。","D":"はい、来年から始めます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', _utf8mb4'夕食の後、寝るまでの間に単語を五つ覚えます。これを（　）続けます。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"先月だけ","B":"毎朝","C":"一度だけ","D":"毎晩"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'朝日が出たら必ず窓を開けます。（　）部屋に風を入れます。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎晩","B":"毎朝","C":"昨日だけ","D":"来月だけ"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：薬は朝だけですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、毎朝一回飲みます」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"はい、毎月一度だけです。","B":"はい、夜だけです。","C":"はい、毎朝一回飲みます。","D":"はい、毎晩一回飲みます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1004, _utf8mb4'EASY', _utf8mb4'土曜も日曜も店を開けます。私の店は（　）営業しています。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"月に一度","B":"週に一度","C":"毎日","D":"年に一度"},"correctAnswer":"C"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', _utf8mb4'夜の九時に必ず明日の持ち物を確かめます。（　）準備します。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎晩","B":"先月だけ","C":"毎朝","D":"一度だけ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1014, _utf8mb4'MEDIUM', _utf8mb4'Nói về thói quen nghe nhạc vào mỗi tối.', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"一度だけ、寝る前に静かな曲を聞きます。","B":"先月だけ、寝る前に静かな曲を聞きます。","C":"毎朝、寝る前に静かな曲を聞きます。","D":"毎晩、寝る前に静かな曲を聞きます。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1019, _utf8mb4'EASY', _utf8mb4'朝ご飯にはいつも果物を食べます。弟は（　）果物を切ります。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝","B":"毎晩","C":"昨日だけ","D":"来月だけ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1024, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：水やりは週末だけですか。土にも毎日水が必要ですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、毎日水をやります」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"いいえ、毎週末だけです。","B":"ええ、きのう一度だけです。","C":"いいえ、毎日水をやります。","D":"ええ、毎年一度です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1029, _utf8mb4'MEDIUM', _utf8mb4'一日も休まず鳥の数を記録します。私は（　）観察します。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"年に一度","B":"週に一度","C":"月に一度","D":"毎日"},"correctAnswer":"D"}'
    UNION ALL SELECT 1034, _utf8mb4'EASY', _utf8mb4'朝の電車でラジオを聞くのが習慣です。（　）駅でイヤホンを出します。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝","B":"来月だけ","C":"昨日だけ","D":"毎晩"},"correctAnswer":"A"}'
    UNION ALL SELECT 1039, _utf8mb4'MEDIUM', _utf8mb4'学校がある日も休みの日も、体温を測ります。（　）記録します。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"年に一度","B":"毎日","C":"月に一度","D":"週に一度"},"correctAnswer":"B"}'
    UNION ALL SELECT 1044, _utf8mb4'MEDIUM', _utf8mb4'パジャマに着替えてから古い時計にねじを巻きます。（　）欠かしません。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"一度だけ","B":"毎晩","C":"先月だけ","D":"毎朝"},"correctAnswer":"B"}'
    UNION ALL SELECT 1049, _utf8mb4'EASY', _utf8mb4'目を覚ますと最初に天気を確かめます。（　）空を見ます。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎晩","B":"来月だけ","C":"毎朝","D":"昨日だけ"},"correctAnswer":"C"}'
    UNION ALL SELECT 2009, _utf8mb4'MEDIUM', _utf8mb4'一週間ずっと同じ作業をします。月曜から日曜まで（　）写真を整理します。', _utf8mb4'「毎日」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"年に一度","B":"月に一度","C":"週に一度","D":"毎日"},"correctAnswer":"D"}'
    UNION ALL SELECT 2023, _utf8mb4'MEDIUM', _utf8mb4'寝室の灯りを消す前に水を用意します。（　）の習慣です。', _utf8mb4'「毎晩」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"毎朝","B":"毎晩","C":"先月だけ","D":"一度だけ"},"correctAnswer":"B"}'
    UNION ALL SELECT 2037, _utf8mb4'EASY', _utf8mb4'朝の市場が開くと、いつも野菜を仕入れます。（　）店の車で出かけます。', _utf8mb4'「毎朝」. 毎 diễn đạt sự lặp lại. 毎朝 là mỗi sáng, 毎晩 là mỗi tối, 毎日 là mỗi ngày.', _utf8mb4'{"options":{"A":"来月だけ","B":"毎晩","C":"昨日だけ","D":"毎朝"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 9 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'まいにち／まいあさ／まいばん + Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 10 (N1 や N2 など)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：この箱には何がありますか。全部は言わなくてもいいですよ。', _utf8mb4 0x0a, _utf8mb4'B：（　）') AS content, _utf8mb4'「切手や封筒などがあります」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.' AS explanation, _utf8mb4'{"options":{"A":"切手は三時までです。","B":"封筒だけで、ほかには何もありませんでした。","C":"切手や封筒などがあります。","D":"切手から封筒まで歩きます。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', _utf8mb4'朝ご飯にはパン（　）卵などを食べます。ほかに果物もあります。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"や","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'救急箱に包帯や薬（　）があります。これは中身の一例です。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"など","B":"から","C":"へ","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：朝市で何を売りますか。例えば？', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「野菜や果物などを売ります」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"野菜や果物などを売ります。","B":"手伝いの学生が売ります。","C":"九時まで売ります。","D":"駅のそばで売ります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', _utf8mb4'旅行には帽子（　）地図などを持っていきます。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"や","B":"を","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'公園ではランニングや体操（　）ができます。活動はほかにもあります。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"へ","B":"まで","C":"から","D":"など"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'Nêu vở và bút chỉ là vài ví dụ về đồ mang đi.', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"ノートからペンなどを持っていきます。","B":"ノートやペンなどを持っていきます。","C":"ノートへペンなどを持っていきます。","D":"ノートをペンなどを持っていきます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'港町で魚や貝などを（　）。〔買う・予定〕'), _utf8mb4'「買います」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"買いませんでした","B":"買います","C":"買いません","D":"買いました"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'展示では写真や地図などを（　）。〔見る・これから〕'), _utf8mb4'「見ます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"見ません","B":"見ませんでした","C":"見ます","D":"見ました"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'売店に切手（　）はがきなどが並んでいます。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"から","D":"や"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', _utf8mb4'妹はピアノやギター（　）を習っています。楽器の例を挙げています。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"まで","D":"など"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'店に小皿（　）茶わんなどを注文しました。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"を","D":"や"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「本や地図などを買った」とあるので、ほかの物も買ったかもしれませんか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、二つは例です」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"いいえ、何も買っていません。","B":"はい、二つは例です。","C":"はい、本は買っていません。","D":"いいえ、必ず二つだけです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', _utf8mb4'引き出しには消しゴムや定規（　）を入れます。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"から","B":"まで","C":"など","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'休みの日は釣り（　）登山などを楽しみます。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"を","D":"や"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：旅行の持ち物を二つほど例に挙げてください。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「タオルや着替えなどです」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"二泊三日です。","B":"タオルや着替えなどです。","C":"集合は七時です。","D":"新幹線で行きます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', _utf8mb4'野菜では、にんじんや大根（　）をよく買います。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"など","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'「スーパーで牛乳やチーズなどを買う。」Người nói đã liệt kê thế nào?', _utf8mb4'や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"So sánh giá của đúng hai món.","B":"Nêu vài ví dụ trong số đồ mua.","C":"Nêu thứ tự thời gian mua hàng.","D":"Khẳng định chỉ mua hai món."},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'Liệt kê một vài môn thể thao, còn môn khác nữa.', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"テニスや水泳などを楽しみます。","B":"テニスや水泳からを楽しみます。","C":"テニスや水泳までを楽しみます。","D":"テニスや水泳へを楽しみます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', _utf8mb4'写真に橋（　）お寺などが写っています。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"や","B":"を","C":"へ","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'毎朝、パンやヨーグルトなどを（　）。〔食べる・習慣〕'), _utf8mb4'「食べます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"食べませんでした","B":"食べます","C":"食べました","D":"食べません"},"correctAnswer":"B"}'
    UNION ALL SELECT 1010, _utf8mb4'MEDIUM', _utf8mb4'見学できる施設には、図書館や体育館（　）があります。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"から","D":"など"},"correctAnswer":"D"}'
    UNION ALL SELECT 1015, _utf8mb4'EASY', _utf8mb4'教室のそうじでは、机ふき（　）ごみ集めなどをします。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"や","B":"から","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1020, _utf8mb4'MEDIUM', _utf8mb4'Diễn đạt danh sách món quà chưa kể hết.', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"花や果物などを届けました。","B":"花を果物などを届けました。","C":"花から果物などを届けました。","D":"花へ果物などを届けました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：パンと卵だけですか。「パンや卵など」と書いてあります。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ほかにもあるかもしれません」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"ほかの物は絶対ありません。","B":"卵だけが一つあります。","C":"ほかにもあるかもしれません。","D":"パンも卵もありません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1030, _utf8mb4'EASY', _utf8mb4'日本語では、敬語や漢字（　）に興味があります。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"から","B":"など","C":"へ","D":"まで"},"correctAnswer":"B"}'
    UNION ALL SELECT 1035, _utf8mb4'MEDIUM', _utf8mb4'文化祭では歌（　）ダンスなどを発表しました。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"や","B":"を","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', _utf8mb4'「鳥や魚などがいます。」など bổ sung sắc thái gì?', _utf8mb4'や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"Chim đến trước cá.","B":"Đây là câu hỏi về số loài.","C":"Có thể còn những loại khác ngoài chim và cá.","D":"Chỉ cá xuất hiện, không có chim."},"correctAnswer":"C"}'
    UNION ALL SELECT 1045, _utf8mb4'EASY', _utf8mb4'駅の近くには銀行やホテル（　）があります。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"まで","D":"など"},"correctAnswer":"D"}'
    UNION ALL SELECT 1050, _utf8mb4'MEDIUM', _utf8mb4'和食なら、すし（　）そばなどをよく食べます。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"や","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 2010, _utf8mb4'MEDIUM', _utf8mb4'お祝いに、お菓子や花（　）が届きました。手紙もありました。', _utf8mb4'「など」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"へ","B":"など","C":"から","D":"まで"},"correctAnswer":"B"}'
    UNION ALL SELECT 2024, _utf8mb4'EASY', _utf8mb4'工房では、紙（　）木などを使っておもちゃを作ります。', _utf8mb4'「や」. や và など giúp nêu ví dụ. Danh sách vẫn có thể gồm các mục khác.', _utf8mb4'{"options":{"A":"を","B":"から","C":"や","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 2038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'夏は海や山などへ（　）。〔行く・普段〕'), _utf8mb4'「行きます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"行きませんでした","B":"行きました","C":"行きません","D":"行きます"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 10 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 や N2 など' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 11 (なにも Vません。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, _utf8mb4'朝食の前です。まだ何（　）食べていません。' AS content, _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.' AS explanation, _utf8mb4'{"options":{"A":"が","B":"も","C":"へ","D":"の"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'財布を忘れたので、店で何（　）買いませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"の","B":"も","C":"へ","D":"が"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'箱を開けましたが、中には何（　）入っていません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"が","C":"も","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', _utf8mb4'真っ暗で、窓の外は何（　）見えません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"が","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'耳をすましても何（　）聞こえませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"も","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'財布が空です。売店では何も（　）。〔買う・これから〕', _utf8mb4'「買いません」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"買いません","B":"買いませんでした","C":"買いました","D":"買います"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', _utf8mb4'おなかがいっぱいです。もう何（　）注文しません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"が","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu báo màn hình trống, không thấy bất cứ thứ gì.', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"画面には何が見えません。","B":"画面には何も見えません。","C":"画面には何の見えません。","D":"画面には何へ見えません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'答えが分からなくて、解答用紙に何（　）書きませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"の","D":"が"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', _utf8mb4'朝は検査です。病院に行くまでは何も（　）。〔食べる・これから〕', _utf8mb4'「食べません」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"食べません","B":"食べます","C":"食べませんでした","D":"食べました"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'Nói bạn không viết bất kỳ thứ gì lên tường.', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"壁には何も書きません。","B":"壁には何の書きません。","C":"壁には何へ書きません。","D":"壁には何が書きません。"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'遠足は学校が準備します。自分では何（　）用意しません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"の","D":"が"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', _utf8mb4'画面が消えていて何（　）読めません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"が","B":"の","C":"も","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'雨のため、庭では何（　）しませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"の","B":"が","C":"へ","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：朝、何か食べましたか。検査で朝食は禁止でしたね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、何も食べませんでした」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"朝食はパンにしましょう。","B":"いつもは朝六時です。","C":"はい、食堂で朝ご飯を食べました。","D":"いいえ、何も食べませんでした。"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', _utf8mb4'店は空っぽです。棚には何（　）ありません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"も","D":"が"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'急いで家を出たので朝は何（　）飲みませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"が","B":"の","C":"も","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Sau bữa tối bạn không ăn gì thêm.', _utf8mb4'「食べません」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"夕食の後は何も食べました。","B":"夕食の後は何も食べます。","C":"夕食の後は何も食べませんでした。","D":"夕食の後は何も食べません。"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', _utf8mb4'きのうは声が出ませんでした。会議で何も（　）。〔話す・過去〕', _utf8mb4'「話しませんでした」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"話しましょう","B":"話しませんでした","C":"話します","D":"話しました"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'「朝から何も飲んでいません。」何も có tác dụng gì?', _utf8mb4'何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"Chỉ phủ định uống cà phê.","B":"Phủ định mọi thứ có thể đã uống từ sáng.","C":"Khẳng định đã uống một chút.","D":"Hỏi tên đồ uống buổi sáng."},"correctAnswer":"B"}'
    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', _utf8mb4'人前では緊張して、発表で何（　）言えませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"も","C":"が","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 1005, _utf8mb4'EASY', _utf8mb4'机を片付けました。上にはもう何（　）置いていません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"の","B":"も","C":"が","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：財布に何か入っていますか。空っぽにしたつもりです。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「何も入っていません」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"だれも来ません。","B":"何も入っていません。","C":"いつも持っています。","D":"どこへも行きません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1013, _utf8mb4'MEDIUM', _utf8mb4'持ち物は全部送りました。手には何（　）持っていません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"も","D":"が"},"correctAnswer":"C"}'
    UNION ALL SELECT 1017, _utf8mb4'EASY', _utf8mb4'まだ決めていません。旅行については何（　）予約していません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"の","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：音声が消えました。何か聞こえますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、何も聞こえません」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"いいえ、何も聞こえません。","B":"音をいつ録音したんですか。","C":"はい、音が大きくなりました。","D":"はい、はっきり聞こえます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：お土産は買いましたか。財布をホテルに忘れたそうですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ええ、何も買えませんでした」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"はい、家族全員の分を買いました。","B":"いいえ、全部現金で払いました。","C":"ええ、何も買えませんでした。","D":"お土産は何時まで売っていますか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1029, _utf8mb4'EASY', _utf8mb4'今日は休むと決めました。午後は何（　）勉強しません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"が","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', _utf8mb4'「何も書きませんでした。」Kết quả là gì?', _utf8mb4'何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"Chưa đọc nội dung đã viết.","B":"Đã viết mọi thứ được yêu cầu.","C":"Có viết nhưng viết rất ít.","D":"Không viết nội dung nào."},"correctAnswer":"D"}'
    UNION ALL SELECT 1037, _utf8mb4'MEDIUM', _utf8mb4'鍵を探しましたが、かばんから何（　）出てきませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"も","C":"の","D":"が"},"correctAnswer":"B"}'
    UNION ALL SELECT 1041, _utf8mb4'EASY', _utf8mb4'展示の前日です。壁にはまだ何（　）かかっていません。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"の","D":"が"},"correctAnswer":"A"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', _utf8mb4'Báo hôm qua đã không mua bất cứ thứ gì.', _utf8mb4'「買いませんでした」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"昨日の買い物では何も買います。","B":"昨日の買い物では何も買いました。","C":"昨日の買い物では何も買いませんでした。","D":"昨日の買い物では何も買いましょう。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', _utf8mb4'店員に聞きましたが、商品のことは何（　）知りませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"が","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 2011, _utf8mb4'EASY', _utf8mb4'音が小さくて、説明は何（　）分かりませんでした。', _utf8mb4'「も」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"も","B":"の","C":"が","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2025, _utf8mb4'MEDIUM', _utf8mb4'のどが痛くないので、今は薬を何も（　）。〔飲む・現在〕', _utf8mb4'「飲みません」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"飲みます","B":"飲みませんでした","C":"飲みました","D":"飲みません"},"correctAnswer":"D"}'
    UNION ALL SELECT 2039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：緊張して声が出なかったそうですね。質問の時間に何か言えましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、何も言えませんでした」. 何も kết hợp với động từ phủ định mang nghĩa “không gì cả”.', _utf8mb4'{"options":{"A":"はい、三人で質問をしました。","B":"机には何も置いてありません。","C":"いいえ、何も言えませんでした。","D":"どこにも行きませんでした。"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD113' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 3
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 11 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'なにも Vません。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD113 / Chương 3 / NGỮ PHÁP / Mẫu 12 (Thời gian に Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
