    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：村までぴったり二十分ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）') AS content, _utf8mb4'「いいえ、二十分くらいです」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.' AS explanation, _utf8mb4'{"options":{"A":"はい、二十分発です。","B":"いいえ、二時二十分です。","C":"いいえ、二十分くらいです。","D":"はい、二十分前までです。"},"correctAnswer":"C"}' AS answers
