    UNION ALL SELECT 1011, _utf8mb4'MEDIUM', _utf8mb4'Nói thời gian đi đường chỉ là ước lượng.', _utf8mb4'「くらいです」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"家から山小屋までは二時間からです。","B":"家から山小屋までは二時間前です。","C":"家から山小屋までは二時間おきです。","D":"家から山小屋までは二時間くらいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1018, _utf8mb4'EASY', _utf8mb4'バス停から祖母の家（　）坂道を十分くらい歩きます。', _utf8mb4'「まで」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"から","B":"だけ","C":"ほど","D":"まで"},"correctAnswer":"D"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', _utf8mb4'Nêu rõ ga trung tâm là điểm bắt đầu.', _utf8mb4'「から」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"中央駅だけ港まで四十分ほどです。","B":"中央駅から港まで四十分ほどです。","C":"中央駅まで港まで四十分ほどです。","D":"中央駅ほど港まで四十分ほどです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この列車で終点までおよそ半時間ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、三十分ほどです」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"はい、三十分ほどです。","B":"はい、半日です。","C":"はい、三十分前です。","D":"はい、三時半です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1039, _utf8mb4'EASY', _utf8mb4'隣の県（　）ここまで高速バスで三時間ほどです。', _utf8mb4'「から」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"まで","B":"だけ","C":"から","D":"ほど"},"correctAnswer":"C"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', _utf8mb4'Nói bệnh viện là điểm cuối của quãng đường.', _utf8mb4'「まで」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"家から病院から歩いて二十分くらいです。","B":"家から病院ほど歩いて二十分くらいです。","C":"家から病院まで歩いて二十分くらいです。","D":"家から病院だけ歩いて二十分くらいです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2004, _utf8mb4'EASY', _utf8mb4'駐車場から講堂（　）ゆっくり歩いて七分くらいです。', _utf8mb4'「まで」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"から","B":"まで","C":"ほど","D":"だけ"},"correctAnswer":"B"}'
    UNION ALL SELECT 2025, _utf8mb4'MEDIUM', _utf8mb4'体育館（　）プールまでの移動は三分くらいです。', _utf8mb4'「から」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"から","B":"ほど","C":"だけ","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 2046, _utf8mb4'MEDIUM', _utf8mb4'山小屋から次の休憩所（　）一時間くらい歩きます。', _utf8mb4'「まで」. Sau thời lượng, くらい／ほど cho biết con số ước chừng.', _utf8mb4'{"options":{"A":"だけ","B":"ほど","C":"から","D":"まで"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 から N2 まで + thời gian + くらいです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 5 (Phương tiện で Vます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'濡れたくないので、駅まではタクシー（　）行きます。') AS content, _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.' AS explanation, _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"で"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'Nêu phương tiện đến trung tâm là tàu điện ngầm.', _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"地下鉄へ中心街へ行きました。","B":"地下鉄で中心街へ行きました。","C":"地下鉄の中心街へ行きました。","D":"地下鉄を中心街へ行きました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：空港まで何で行きますか。荷物があるので車を呼びました。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「タクシーで行きます」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"午後に行きます。","B":"旅行者と行きます。","C":"タクシーで行きます。","D":"空港へ行きます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'飛行機で島へ（　）。〔行く・来週の予定〕'), _utf8mb4'「行きます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"行きませんでした","B":"行きました","C":"行きません","D":"行きます"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'「自転車で市場へ行く。」自転車で chỉ gì?', _utf8mb4'で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"Phương tiện đến chợ.","B":"Hướng đi của cái chợ.","C":"Địa điểm mua xe.","D":"Thời gian ở chợ."},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'荷物が多い日は車（　）会社へ行きます。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'橋がないため、小さな船（　）川を渡ります。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'遅れそうなので、今日は特急（　）向かいます。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"で","B":"の","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：橋がない島へはどうやって行きますか。船着き場が見えます。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「船で渡ります」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"船で渡ります。","B":"船から海を見ます。","C":"島の中を歩きます。","D":"島で船を見ます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'渋滞を避けて地下鉄（　）移動します。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：今日は地下鉄を使いましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、バスで来ました」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"いいえ、バスで来ました。","B":"いいえ、バスを二台見ました。","C":"いいえ、地下鉄は三駅です。","D":"いいえ、地下鉄で来ました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'空港から市内へはバス（　）行けます。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'自転車（　）学校に通うので、毎日ヘルメットをかぶります。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"を","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「電車で学校へ行きます」の「で」は場所ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、移動の手段です」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"はい、勉強する場所です。","B":"いいえ、移動の手段です。","C":"はい、出発する方角です。","D":"いいえ、到着する時刻です。"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'Nói đoàn sẽ di chuyển bằng thuyền nhỏ.', _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"小さな船の向こう岸へ渡ります。","B":"小さな船で向こう岸へ渡ります。","C":"小さな船へ向こう岸へ渡ります。","D":"小さな船を向こう岸へ渡ります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'国際会議のため、飛行機（　）タイに行きました。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"を","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'山の上のホテルへはロープウェー（　）上がります。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'赤ちゃんと一緒なので、急がず普通列車（　）帰ります。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"を","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'船で港へ（　）。〔戻る・これから〕'), _utf8mb4'「戻ります」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"戻りませんでした","B":"戻りました","C":"戻ります","D":"戻りません"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'歩くと二時間ですから、バイク（　）湖に行きます。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', _utf8mb4'Bạn đến sân bóng bằng xe đạp.', _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"自転車をグラウンドへ行きます。","B":"自転車でグラウンドへ行きます。","C":"自転車へグラウンドへ行きます。","D":"自転車のグラウンドへ行きます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1012, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'フェリー（　）島へ渡りました。車も一緒に乗せました。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"で","B":"を","C":"へ","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'雪山の上まではリフト（　）行きました。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 1026, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'市電（　）町の中心を回るツアーに参加します。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"を","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 1033, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'エレベーター（　）七階へ上がってください。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"の","B":"を","C":"で","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'救急車（　）病院に運ばれました。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"を","B":"の","C":"へ","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'明日の出張は新幹線で（　）。〔向かう〕'), _utf8mb4'「向かいます」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"向かいませんでした","B":"向かいました","C":"向かいます","D":"向かいません"},"correctAnswer":"C"}'
    UNION ALL SELECT 2005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'きのうは終電を逃し、タクシーで（　）。〔帰る・過去〕'), _utf8mb4'「帰りました」. ました biểu thị hành động đã xảy ra.', _utf8mb4'{"options":{"A":"帰りましょう","B":"帰りました","C":"帰りませんでした","D":"帰ります"},"correctAnswer":"B"}'
    UNION ALL SELECT 2026, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'深夜バス（　）夜のうちに別の県へ向かいます。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"で","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 2047, _utf8mb4'EASY', CONCAT(_utf8mb4'Nêu phương tiện đi lại.', _utf8mb4 0x0a, _utf8mb4'駅から会場までは送迎車（　）お送りします。'), _utf8mb4'「で」. で sau tên phương tiện cho biết người nói di chuyển bằng cách nào.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"を","D":"の"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Phương tiện で Vます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 6 (N は Aいです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'この井戸（　）水は冷たいです。水がどこのものかを示します。' AS content, _utf8mb4'「の」. の nối danh từ chỉ mốc với danh từ đứng sau.' AS explanation, _utf8mb4'{"options":{"A":"を","B":"の","C":"へ","D":"が"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng khẳng định lịch sự.', _utf8mb4 0x0a, _utf8mb4'雪が降っています。今朝はとても（　）。〔寒い・今〕'), _utf8mb4'「寒いです」. Tính từ い làm vị ngữ khẳng định bằng cách giữ đuôi い và thêm です.', _utf8mb4'{"options":{"A":"寒いです","B":"寒いなです","C":"寒くないです","D":"寒かったです"},"correctAnswer":"A"}'
