    UNION ALL SELECT 2010, _utf8mb4'EASY', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'電車の中で（　）小説を読みました。〔面白い〕'), _utf8mb4'Tính từ い bổ nghĩa trực tiếp cho danh từ ngay sau chỗ trống, không đổi đuôi い.', _utf8mb4'{"options":{"A":"面白く","B":"面白いな","C":"面白いの","D":"面白い"},"correctAnswer":"D"}'
    UNION ALL SELECT 2031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：夜道で暗い場所を避けたいです。どちらの通りがいいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「明るい通りがいいです」. Tính từ い giữ nguyên đuôi い và đứng ngay trước danh từ.', _utf8mb4'{"options":{"A":"明るく通りがいいです。","B":"明るいな通りがいいです。","C":"明るい通りがいいです。","D":"明るいの通りがいいです。"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 10 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aい + N' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 11 (Aな (gốc từ) + な + N)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'眠るときは（　）部屋がいいです。〔静か〕') AS content, _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.' AS explanation, _utf8mb4'{"options":{"A":"静かに","B":"静かく","C":"静かな","D":"静かい"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'駅の近くの（　）駐車場を使いました。〔便利〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"便利に","B":"便利な","C":"便利く","D":"便利い"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：予約するならどんな部屋がいいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「静かな部屋がいいです」. Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"静か部屋がいいです。","B":"静かに部屋がいいです。","C":"静かい部屋がいいです。","D":"静かな部屋がいいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'目印は（　）花が咲いている家です。〔きれい〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"きれいな","B":"きれいく","C":"きれいに","D":"きれいい"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：重い本を入れてもこわれない袋はありますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、この丈夫な袋をどうぞ」. Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"はい、この丈夫な袋をどうぞ。","B":"はい、この丈夫く袋をどうぞ。","C":"はい、この丈夫に袋をどうぞ。","D":"はい、この丈夫い袋をどうぞ。"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'祭りの日、（　）通りを歩きました。〔にぎやか〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"にぎやかに","B":"にぎやかい","C":"にぎやかく","D":"にぎやかな"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'小学生が（　）道を通って帰ります。〔安全〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"安全く","B":"安全い","C":"安全な","D":"安全に"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'初めは（　）問題を解きましょう。〔簡単〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"簡単く","B":"簡単に","C":"簡単な","D":"簡単い"},"correctAnswer":"C"}'
