    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'Giới thiệu ngôi nhà yên tĩnh bằng cụm tính từ + danh từ.'), _utf8mb4'「静かな」. Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"これは川の近くの静かく家です。","B":"これは川の近くの静かい家です。","C":"これは川の近くの静かな家です。","D":"これは川の近くの静かに家です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'Nói cô giáo chọn một ví dụ đơn giản.'), _utf8mb4'「簡単な」. Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"先生は簡単に例を選びました。","B":"先生は簡単い例を選びました。","C":"先生は簡単く例を選びました。","D":"先生は簡単な例を選びました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'母は（　）布を選んで袋を作りました。〔丈夫〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"丈夫に","B":"丈夫な","C":"丈夫い","D":"丈夫く"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'会場で（　）演奏を聞きました。〔すてき〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"すてきい","B":"すてきな","C":"すてきに","D":"すてきく"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'「有名な橋を見た。」な có vai trò gì?', _utf8mb4'Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"Nối gốc tính từ 有名 với danh từ 橋.","B":"Đánh dấu chủ thể đi xem.","C":"Đánh dấu động từ quá khứ.","D":"Phủ định sự nổi tiếng của cây cầu."},"correctAnswer":"A"}'
    UNION ALL SELECT 1004, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'説明書に（　）図が載っています。〔複雑〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"複雑い","B":"複雑く","C":"複雑に","D":"複雑な"},"correctAnswer":"D"}'
    UNION ALL SELECT 1011, _utf8mb4'EASY', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'（　）書類は鍵のかかる所に入れます。〔大切〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"大切い","B":"大切に","C":"大切な","D":"大切く"},"correctAnswer":"C"}'
    UNION ALL SELECT 1018, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'班の代表には（　）学生を選びます。〔まじめ〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"まじめに","B":"まじめい","C":"まじめな","D":"まじめく"},"correctAnswer":"C"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'昔はここに（　）門がありました。〔立派〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"立派な","B":"立派に","C":"立派い","D":"立派く"},"correctAnswer":"A"}'
    UNION ALL SELECT 1032, _utf8mb4'EASY', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'（　）時間に町を歩きました。〔自由〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"自由に","B":"自由な","C":"自由く","D":"自由い"},"correctAnswer":"B"}'
    UNION ALL SELECT 1039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'Mô tả chiếc túi bền cất trong tủ.'), _utf8mb4'「丈夫な」. Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"棚には丈夫にかばんが一つあります。","B":"棚には丈夫なかばんが一つあります。","C":"棚には丈夫くかばんが一つあります。","D":"棚には丈夫いかばんが一つあります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'登山前に（　）道具をそろえます。〔必要〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"必要な","B":"必要い","C":"必要に","D":"必要く"},"correctAnswer":"A"}'
    UNION ALL SELECT 2011, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn dạng bổ nghĩa cho danh từ.', _utf8mb4 0x0a, _utf8mb4'歓迎会で（　）歌を聞きました。〔上手〕'), _utf8mb4'Để bổ nghĩa cho danh từ ngay sau chỗ trống, dùng gốc tính từ + な.', _utf8mb4'{"options":{"A":"上手い","B":"上手く","C":"上手に","D":"上手な"},"correctAnswer":"D"}'
    UNION ALL SELECT 2032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：紹介してくれた先生はどんな人ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「親切な方です」. Cần な giữa gốc tính từ な và danh từ mà nó bổ nghĩa.', _utf8mb4'{"options":{"A":"親切に方です。","B":"親切く方です。","C":"親切い方です。","D":"親切な方です。"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 11 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aな (gốc từ) + な + N' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 12 (N はどんな N ですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'「この町（　）どんな町ですか」。この町を話題にします。' AS content, _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.' AS explanation, _utf8mb4'{"options":{"A":"へ","B":"の","C":"は","D":"を"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'Hỏi đặc điểm của công viên sắp đến.', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"今から行くのはどれ公園ですか。","B":"今から行くのはどう公園ですか。","C":"今から行くのはどんな公園ですか。","D":"今から行くのはどこ公園ですか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', _utf8mb4'「生まれた町は（　）町ですか。」「坂が多い町です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どんな","B":"どう","C":"どこ","D":"どれ"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'「泊まった所は（　）宿でしたか。」「古い木の家でした。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どんな","B":"どれ","C":"どこ","D":"どう"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'値段ではなく雰囲気を聞きます。「（　）店ですか。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どれ","B":"どう","C":"どんな","D":"どこ"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', _utf8mb4'「新しい先生は（　）方ですか。」「話しやすい方です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どれ","B":"どう","C":"どんな","D":"どこ"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'「その話は（　）話ですか。」「小さな島の話です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どこ","B":"どんな","C":"どう","D":"どれ"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どんな町で育ちましたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「山が近い静かな町です」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"三人で育ちました。","B":"山が近い静かな町です。","C":"五月五日です。","D":"三年ぐらいです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', _utf8mb4'どんな色（　）好きですか。好みに合う色を尋ねます。', _utf8mb4'「が」. が đánh dấu chủ thể hoặc đối tượng mang đặc điểm đang xét.', _utf8mb4'{"options":{"A":"に","B":"を","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'「写真の祭りは（　）祭りですか。」「みんなで踊る祭りです。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どこ","B":"どう","C":"どれ","D":"どんな"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'来年はどんな家（　）住みたいですか。住む場所を示します。', _utf8mb4'「に」. に nêu mốc giờ, nơi tồn tại hoặc đích tiếp nhận tùy ngữ cảnh.', _utf8mb4'{"options":{"A":"に","B":"を","C":"の","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', _utf8mb4'「次の部屋は（　）部屋ですか。」「日当たりのいい部屋です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どこ","B":"どれ","C":"どう","D":"どんな"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：どんな本が好きですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「旅の写真が多い本です」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"旅の写真が多い本です。","B":"図書館の二階です。","C":"きのう読みました。","D":"一冊八百円です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'どんな音楽（　）よく聞きますか。聞く対象を示します。', _utf8mb4'「を」. を đặt sau đối tượng trực tiếp của hành động.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"が"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', _utf8mb4'「この雑誌は（　）雑誌ですか。」「旅を紹介する雑誌です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どれ","B":"どんな","C":"どこ","D":"どう"},"correctAnswer":"B"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：来月住むのはどんな家ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「庭のある小さな家です」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"二時に出ます。","B":"庭のある小さな家です。","C":"三日間泊まりました。","D":"家賃は来月です。"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'「泊まりたいのは（　）ホテルですか。」「駅に近いホテルです。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どう","B":"どこ","C":"どれ","D":"どんな"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', _utf8mb4'「妹さんは（　）人ですか。」「明るくて元気です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どんな","B":"どれ","C":"どこ","D":"どう"},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'「夏の山は（　）所ですか。」「夜は涼しい所です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どこ","B":"どれ","C":"どう","D":"どんな"},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'「どこの学校ですか」ではなく校風を知りたい。「（　）学校ですか。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どう","B":"どれ","C":"どこ","D":"どんな"},"correctAnswer":"D"}'
    UNION ALL SELECT 1005, _utf8mb4'EASY', _utf8mb4'「先生はどんな方です（　）」。先生を知らない人の質問です。', _utf8mb4'「か」. か ở cuối câu biểu thị câu hỏi.', _utf8mb4'{"options":{"A":"の","B":"か","C":"を","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1012, _utf8mb4'MEDIUM', _utf8mb4'「どんな映画が好きですか。」Câu hỏi yêu cầu thông tin nào?', _utf8mb4'どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"Giá vé cho một bộ phim.","B":"Rạp nào ở gần nhất.","C":"Thể loại hoặc đặc điểm phim ưa thích.","D":"Giờ bắt đầu chiếu phim."},"correctAnswer":"C"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', _utf8mb4'Hỏi bạn thích thể loại sách nào.', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どこ本をよく読みますか。","B":"どれ本をよく読みますか。","C":"どんな本をよく読みますか。","D":"どう本をよく読みますか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1026, _utf8mb4'EASY', _utf8mb4'「好きなのは（　）音楽ですか。」「静かな音楽です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どんな","B":"どこ","C":"どう","D":"どれ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', _utf8mb4'「新しい職場は（　）所ですか。」「窓から海が見える所です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どう","B":"どんな","C":"どこ","D":"どれ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：地図の場所でなく、映画館の特徴を知りたいです。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「どんな映画館ですか」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"映画館はいくらですか。","B":"映画館はどこですか。","C":"映画は何時からですか。","D":"どんな映画館ですか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1047, _utf8mb4'EASY', _utf8mb4'「手術の後は（　）食事ですか。」「柔らかい物です。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どんな","B":"どう","C":"どれ","D":"どこ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2012, _utf8mb4'MEDIUM', _utf8mb4'Hỏi về tính cách người bạn cùng phòng.', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"同じ部屋の人はどんな人ですか。","B":"同じ部屋の人はどこ人ですか。","C":"同じ部屋の人はどれ人ですか。","D":"同じ部屋の人はどう人ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2033, _utf8mb4'EASY', _utf8mb4'「贈り物には（　）かばんがいいですか。」「軽くて丈夫なものです。」', _utf8mb4'「どんな」. どんな đứng trước danh từ, dùng để hỏi loại hoặc đặc điểm.', _utf8mb4'{"options":{"A":"どれ","B":"どこ","C":"どう","D":"どんな"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N はどんな N ですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 13 (N が多い／少ないです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'この町は公園（　）多いです。遊ぶ場所に困りません。' AS content, _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.' AS explanation, _utf8mb4'{"options":{"A":"が","B":"に","C":"を","D":"へ"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', _utf8mb4'冬は島へ来る観光客（　）少ないです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"を","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この町で何が多いですか。緑が目立ちますね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「木が多いです」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"木へ多いです。","B":"木を多いです。","C":"木が多いです。","D":"木まで多いです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'今年は台風（　）多くて船がよく休みます。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"に","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', _utf8mb4'この学校は海外からの学生（　）多いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"に","B":"へ","C":"を","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'山の上は木（　）少なく、景色がよく見えます。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"に","B":"が","C":"へ","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：朝の車内は混んでいますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、乗客が多いです」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"はい、乗客が多いです。","B":"はい、車内にはだれもいません。","C":"はい、車内は空っぽです。","D":"はい、乗客が一人だけです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', _utf8mb4'夕方の駅前は車（　）多いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"へ","B":"が","C":"に","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'この辺りには商店が百軒もあります。「店が（　）。」', _utf8mb4'「多いです」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"一つだけです","B":"少なかったです","C":"少ないです","D":"多いです"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'Nói trong khu vườn có nhiều cây cao.', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"この庭は高い木へ多いです。","B":"この庭は高い木を多いです。","C":"この庭は高い木が多いです。","D":"この庭は高い木に多いです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', _utf8mb4'この川には魚（　）多く、釣り人が集まります。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"を","B":"が","C":"に","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'田舎では夜開いている店（　）少ないです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"が","B":"を","C":"に","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'兄の仕事は出張（　）多いです。今週もいません。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', _utf8mb4'秋の空は雲（　）少なくて青いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"が","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：今月は雨の日が二日だけでした。多いほうですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、少ないです」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"いいえ、降らない日はありません。","B":"はい、一日も晴れませんでした。","C":"いいえ、少ないです。","D":"はい、毎日でした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'Nói bình thường ở vùng này có ít mưa.', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"この地方は雨に少ないです。","B":"この地方は雨を少ないです。","C":"この地方は雨が少ないです。","D":"この地方は雨へ少ないです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', _utf8mb4'あの公園は桜の木（　）多いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"に","B":"へ","C":"を","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Nhận xét có ít xe đạp trên tuyến đường.', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"この道は自転車に少ないです。","B":"この道は自転車が少ないです。","C":"この道は自転車へ少ないです。","D":"この道は自転車を少ないです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'この路線は朝の電車（　）少なくて不便です。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"に","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', _utf8mb4'子ども向けの本は絵（　）多いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"に","B":"が","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1006, _utf8mb4'MEDIUM', _utf8mb4'料理に使う塩（　）少なく、やさしい味です。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"を","B":"が","C":"に","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1013, _utf8mb4'MEDIUM', _utf8mb4'最終バスには二人しか乗っていません。乗客が（　）。', _utf8mb4'「少ないです」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"大勢です","B":"多いです","C":"満員です","D":"少ないです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1020, _utf8mb4'EASY', _utf8mb4'この村では子どもの数が増えています。前より子どもが（　）。', _utf8mb4'「多くなりました」. ました biểu thị hành động đã xảy ra.', _utf8mb4'{"options":{"A":"多くなりました","B":"いなくなりました","C":"減りました","D":"少なくなりました"},"correctAnswer":"A"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', _utf8mb4'北の町は冬、雪（　）多いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1034, _utf8mb4'MEDIUM', _utf8mb4'「この町は橋が少ないです。」少ない nhận xét đối tượng nào?', _utf8mb4'が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"Số lượng cầu trong thị trấn.","B":"Chất lượng của đường đi.","C":"Khoảng cách từ cầu tới thị trấn.","D":"Chiều dài của mỗi cây cầu."},"correctAnswer":"A"}'
    UNION ALL SELECT 1041, _utf8mb4'EASY', _utf8mb4'このアパートは窓（　）多くて明るいです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"を","B":"が","C":"へ","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', _utf8mb4'平日の昼は客（　）少ないので、ゆっくり買えます。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"を","B":"に","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 2013, _utf8mb4'EASY', _utf8mb4'この漢字の練習帳は例（　）多いです。', _utf8mb4'「が」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"が","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 2034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「この辺は坂が多い」と聞きました。自転車で走りやすいですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「上り下りが多くて大変です」. が đánh dấu đối tượng được nhận xét là có nhiều hay ít.', _utf8mb4'{"options":{"A":"坂が一つもありません。","B":"上り下りが多くて大変です。","C":"平らな道だけです。","D":"はい、下り坂だけです。"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 13 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N が多い／少ないです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 14 (Địa điểm に N があります。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, _utf8mb4'改札の横（　）案内板があります。' AS content, _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.' AS explanation, _utf8mb4'{"options":{"A":"を","B":"に","C":"の","D":"で"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'右の引き出しに予備の鍵（　）あります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"が","B":"に","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'ベンチの下にボールが（　）。動物ではなく物です。', _utf8mb4'「あります」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"寝ます","B":"来ます","C":"います","D":"あります"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', _utf8mb4'この地図の真ん中（　）小さな湖があります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"の","B":"を","C":"で","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この建物にエレベーターはありますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、受付の奥にあります」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"はい、受付から歩きます。","B":"はい、受付の奥にあります。","C":"はい、受付で昼食を食べます。","D":"はい、受付の人が来ます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：鉛筆を置く所はありますか。机の上の箱は、確か鉛筆用ですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「その箱がありますよ」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"あの箱には消しゴムしか入れられません。","B":"その箱がありますよ。","C":"箱を開ける時間はいつですか。","D":"いいえ、鉛筆をまだ買っていません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', _utf8mb4'会議室には白い机（　）三つあります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"に","B":"へ","C":"を","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'Nói có một đài phun nước trong sân.', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"中庭で噴水があります。","B":"中庭の噴水があります。","C":"中庭を噴水があります。","D":"中庭に噴水があります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：駅の近くに何がありますか。古い建物が見えます。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「郵便局があります」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"バスで行きます。","B":"友達と行きます。","C":"郵便局があります。","D":"先生がいます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', _utf8mb4'靴箱の上（　）だれかの手袋があります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"の","B":"で","C":"に","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'丘の上に古い風車（　）あります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"が","B":"に","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu nói có ghế dài cạnh quầy.', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"受付の横に長いすへあります。","B":"受付の横に長いすにあります。","C":"受付の横に長いすがあります。","D":"受付の横に長いすをあります。"},"correctAnswer":"C"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', _utf8mb4'古い時計は先月ここに（　）。今は別の部屋です。', _utf8mb4'「ありました」. ました biểu thị hành động đã xảy ra.', _utf8mb4'{"options":{"A":"ありたいです","B":"ありました","C":"あります","D":"いました"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'ホテルの一階（　）郵便ポストがあります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'角を曲がると大きな交番（　）あります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"が","B":"を","C":"に","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', _utf8mb4'体育館の後ろ（　）倉庫があります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"に","B":"を","C":"で","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'Thông báo phía sau ngôi nhà có một cái giếng.', _utf8mb4'「あります」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"家の後ろに井戸があります。","B":"家の後ろに井戸がいます。","C":"家の後ろに井戸が寝ます。","D":"家の後ろに井戸が来ます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「公園に時計があります」の「に」は何を表しますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「時計がある場所です」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"時計を作る道具です。","B":"時計の持ち主です。","C":"時計を見る時刻です。","D":"時計がある場所です。"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', _utf8mb4'庭に赤い花（　）たくさんあります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"が","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'教科書の最後（　）便利な単語表があります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"を","B":"に","C":"で","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', _utf8mb4'道の向こうに新しい薬局（　）あります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"を","B":"が","C":"へ","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1014, _utf8mb4'EASY', _utf8mb4'上着のポケット（　）切符があります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"を","B":"に","C":"の","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', _utf8mb4'森の奥に小さな橋（　）あります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"に","B":"を","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', _utf8mb4'探しましたが棚は空です。ここに辞書は（　）。', _utf8mb4'「ありません」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"あります","B":"います","C":"いません","D":"ありません"},"correctAnswer":"D"}'
    UNION ALL SELECT 1035, _utf8mb4'EASY', _utf8mb4'自転車置き場（　）空気入れがあります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"を","B":"で","C":"の","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 1042, _utf8mb4'MEDIUM', _utf8mb4'売り場の隣に休むためのベンチ（　）あります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"が","B":"を","C":"に","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', _utf8mb4'「部屋の隅に箱があります。」Câu này giới thiệu điều gì?', _utf8mb4'に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"Sự có mặt của một chiếc hộp ở góc phòng.","B":"Ai đang đặt hộp vào phòng.","C":"Hướng mà chiếc hộp di chuyển.","D":"Giờ bắt đầu dọn phòng."},"correctAnswer":"A"}'
    UNION ALL SELECT 2014, _utf8mb4'MEDIUM', _utf8mb4'受付の向かい側（　）入り口があります。', _utf8mb4'「に」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"で","B":"の","C":"に","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 2035, _utf8mb4'MEDIUM', _utf8mb4'町の南に広い工場（　）二つあります。', _utf8mb4'「が」. に đánh dấu nơi tồn tại, が đánh dấu vật được giới thiệu với あります.', _utf8mb4'{"options":{"A":"へ","B":"に","C":"が","D":"を"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 14 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm に N があります。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 15 (S1。そして、S2。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'この宿は安いです。（　）、駅にも近いです。長所をもう一つ加えます。' AS content, _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.' AS explanation, _utf8mb4'{"options":{"A":"ところが","B":"なぜなら","C":"しかし","D":"そして"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：その宿は駅に近いのですね。他にもよい点がありますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「そして、部屋も安いです」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"では、近くないのですね。","B":"そして、部屋も安いです。","C":"駅までは何時ですか。","D":"駅から遠いからです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'妹は明るいです。（　）、いつも親切です。二つ目の長所です。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"そして","B":"ところが","C":"なぜなら","D":"しかし"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'市場には野菜があります。（　）、魚もあります。品物を付け足します。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"なぜなら","B":"そして","C":"ところが","D":"しかし"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この町には動物園があります。別の見どころも付け加えてください。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「そして、水族館もあります」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"そして、水族館もあります。","B":"動物園は何時まででしょうか。","C":"この町へは車で来ました。","D":"いいえ、水族館は月曜休みです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'この部屋は広いです。（　）、窓も大きいです。よい点を続けます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"そして","B":"ところが","C":"しかし","D":"なぜなら"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'Giới thiệu hai ưu điểm độc lập của việc thuê nhà, dùng phép nối cùng chiều.', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"部屋は安いです。なぜなら、庭もあります。","B":"部屋は安いです。そして、庭もあります。","C":"部屋は安いです。しかし、庭もあります。","D":"部屋は安いです。ところが、庭もあります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：新しい机は広いですね。良い点をもう一つ紹介してもらえますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ええ。そして、高さも変えられます」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"机はいつ届いたんですか。","B":"机は何台買いましたか。","C":"でも、幅が広すぎて困ります。","D":"ええ。そして、高さも変えられます。"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'町には海があります。（　）、山もあります。地形をもう一つ紹介します。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"しかし","B":"そして","C":"なぜなら","D":"ところが"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'かばんは軽いです。（　）、丈夫です。二つともよい点です。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"しかし","C":"なぜなら","D":"そして"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'生地は柔らかいです。（　）、色もきれいです。店員が長所を加えます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"そして","C":"なぜなら","D":"しかし"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'祖父は英語を話します。（　）、中国語も話します。もう一つの言語を加えます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"しかし","B":"ところが","C":"なぜなら","D":"そして"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'冬は日が短いです。（　）、夜はとても寒いです。季節の特徴を加えます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"しかし","B":"なぜなら","C":"ところが","D":"そして"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'この店のカレーは安いです。（　）、量も多いです。友達に長所を二つ伝えます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"なぜなら","C":"そして","D":"しかし"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'「軽いです。そして、安いです。」そして nối hai ý ra sao?', _utf8mb4'そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"Bổ sung ưu điểm thứ hai cho ưu điểm thứ nhất.","B":"Giải thích rằng rẻ gây ra nhẹ.","C":"Bác bỏ ý món đồ nhẹ.","D":"So sánh hai thời điểm khác nhau."},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'新しい公園には池があります。（　）、小さな森もあります。施設を付け足します。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"そして","B":"ところが","C":"なぜなら","D":"しかし"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'教室は暗いです。（　）、狭いです。どちらも困る点です。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"しかし","B":"ところが","C":"そして","D":"なぜなら"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Thêm thông tin nhà ăn còn bán trái cây.', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"食堂はパンを売っています。ところが、果物も売っています。","B":"食堂はパンを売っています。なぜなら、果物も売っています。","C":"食堂はパンを売っています。そして、果物も売っています。","D":"食堂はパンを売っています。しかし、果物も売っています。"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'ホテルで自転車を借りられます。（　）、地図ももらえます。サービスを追加します。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"なぜなら","B":"しかし","C":"そして","D":"ところが"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'会場は駅から遠いです。（　）、駐車場もありません。二つ目の不便を述べます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"なぜなら","B":"ところが","C":"そして","D":"しかし"},"correctAnswer":"C"}'
    UNION ALL SELECT 1001, _utf8mb4'EASY', _utf8mb4'ピアノの音が聞こえます。（　）、歌声もします。聞こえる音を加えます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"そして","C":"なぜなら","D":"しかし"},"correctAnswer":"B"}'
    UNION ALL SELECT 1008, _utf8mb4'MEDIUM', _utf8mb4'果物は甘いです。（　）、香りもいいです。味に続いて香りをほめます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"しかし","B":"なぜなら","C":"ところが","D":"そして"},"correctAnswer":"D"}'
    UNION ALL SELECT 1015, _utf8mb4'MEDIUM', _utf8mb4'Nêu thêm việc bảo tàng có thư viện sau khi giới thiệu phòng tranh.', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ここには絵の部屋があります。ところが、図書室もあります。","B":"ここには絵の部屋があります。なぜなら、図書室もあります。","C":"ここには絵の部屋があります。そして、図書室もあります。","D":"ここには絵の部屋があります。しかし、図書室もあります。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1022, _utf8mb4'EASY', _utf8mb4'図書館は広くなりました。（　）、本も増えました。変化をもう一つ挙げます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"そして","B":"ところが","C":"なぜなら","D":"しかし"},"correctAnswer":"A"}'
    UNION ALL SELECT 1029, _utf8mb4'MEDIUM', _utf8mb4'この辞書は文字が大きいです。（　）、例文も豊富です。二つ目の利点です。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"なぜなら","B":"そして","C":"ところが","D":"しかし"},"correctAnswer":"B"}'
    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：昨日は風が強かったです。同じ日の様子をもう一つ教えてください。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「そして、雨も強かったです」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"では、風はいつ来ますか。","B":"しかし、昨日ではありません。","C":"そして、雨も強かったです。","D":"だから、一昨日は休みでした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1043, _utf8mb4'EASY', _utf8mb4'祭りは土曜にあります。（　）、日曜にもあります。日程を付け加えます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"そして","B":"なぜなら","C":"しかし","D":"ところが"},"correctAnswer":"A"}'
    UNION ALL SELECT 1050, _utf8mb4'MEDIUM', _utf8mb4'作業は複雑です。（　）、時間もかかります。難しい点を重ねます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"しかし","C":"なぜなら","D":"そして"},"correctAnswer":"D"}'
    UNION ALL SELECT 2015, _utf8mb4'MEDIUM', _utf8mb4'この村は静かです。（　）、空気もきれいです。魅力をもう一つ述べます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"しかし","C":"そして","D":"なぜなら"},"correctAnswer":"C"}'
    UNION ALL SELECT 2036, _utf8mb4'EASY', _utf8mb4'橋は古いです。（　）、道幅も狭いです。橋の特徴を二つ並べます。', _utf8mb4'「そして」. そして thêm một ý cùng chiều với ý trước.', _utf8mb4'{"options":{"A":"ところが","B":"なぜなら","C":"しかし","D":"そして"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 15 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S1。そして、S2。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 16 (S1 が、S2。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'A：この服はいいですか。色は好きなのですが、値段は高いですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）') AS content, _utf8mb4'「はい、きれいですが、高いです」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.' AS explanation, _utf8mb4'{"options":{"A":"はい、色も値段も嫌いです。","B":"はい、安いですから買いました。","C":"はい、きれいですが、高いです。","D":"はい、高くないし安いです。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'部屋は狭いです（　）、窓は大きいです。欠点から長所へ話を変えます。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"から","C":"し","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'Nêu ý đối lập giữa vị ngon và giá cao.', _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"料理はおいしいですので、値段は高いです。","B":"料理はおいしいですが、値段は高いです。","C":"料理はおいしいですから、値段は高いです。","D":"料理はおいしいですし、値段は高いです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'この店は高いです（　）、味はいいです。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"が","B":"ので","C":"から","D":"し"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'駅から遠いです（　）、バスがあるので便利です。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"から","C":"が","D":"し"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'今日はりんごが安いです（　）。値段のよさと不便な点を対比します。', _utf8mb4'「が、数は少ないです」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"から、安いです","B":"ので、たくさんあります","C":"し、値段も安いです","D":"が、数は少ないです"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'新しい部屋は明るいです（　）。よい点に続いて残念な点を伝えます。', _utf8mb4'「が、狭いです」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"し、窓も明るいです","B":"が、狭いです","C":"から、暗いです","D":"ので、広かったですか"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'漢字は読めます（　）、まだ書けません。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"し","B":"から","C":"ので","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'雨はやみました（　）、風はまだ強いです。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"が","B":"ので","C":"から","D":"し"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：新しい部屋は静かで便利ですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「静かですが、駅から遠くて不便です」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"駅から遠くないから不便ですか。","B":"駅が静かに着きました。","C":"静かですが、駅から遠くて不便です。","D":"静かですから静かです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'道は長いです（　）、坂はありません。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"から","B":"が","C":"ので","D":"し"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'Đối chiếu việc biết địa điểm nhưng chưa từng đến.', _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"場所は知っていますから、行ったことはありません。","B":"場所は知っていますが、行ったことはありません。","C":"場所は知っていますし、行ったことはありません。","D":"場所は知っていますので、行ったことはありません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'財布は古いです（　）、まだ丈夫です。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"から","B":"ので","C":"が","D":"し"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'「古いですが、使いやすいです。」が nối hai ý theo quan hệ nào?', _utf8mb4'が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"Nét bất lợi đối lập với ưu điểm.","B":"Người nói phủ định cả hai đặc điểm.","C":"Cái cũ là nguyên nhân bắt buộc của việc dễ dùng.","D":"Hai hành động nối tiếp nhau."},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'優勝はできませんでした（　）、いい試合でした。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"から","C":"し","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：山の道は短いですか。地図では短いけど坂が急ですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ええ、短いですが大変です」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ええ、短いですが大変です。","B":"ええ、長いですから短いです。","C":"ええ、坂はなくて平らです。","D":"いいえ、短い道しかありません。"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'日本へ行きたいです（　）、今はお金がありません。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"から","B":"が","C":"ので","D":"し"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Nói hôm nay là ngày nghỉ nhưng bạn sẽ làm việc.', _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"今日は休みですので、私は仕事をします。","B":"今日は休みですし、私は仕事をします。","C":"今日は休みですから、私は仕事をします。","D":"今日は休みですが、私は仕事をします。"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'坂は急です（　）、上の景色はきれいです。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"から","C":"が","D":"し"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'父は料理をします（　）、片付けは苦手です。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"が","B":"し","C":"から","D":"ので"},"correctAnswer":"A"}'
    UNION ALL SELECT 1002, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'この辞書は小さいです（　）、言葉がたくさん載っています。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"から","C":"し","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'入力は簡単です（　）、印刷には時間がかかります。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"が","B":"から","C":"し","D":"ので"},"correctAnswer":"A"}'
    UNION ALL SELECT 1016, _utf8mb4'EASY', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'今日は平日です（　）、祭りで学校は休みです。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"し","C":"が","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：読める漢字なら全部書けますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、読めますが、書けない字もあります」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"いいえ、読めますが、書けない字もあります。","B":"はい、読めませんから全部書けません。","C":"はい、書けない字だけ読めませんか。","D":"いいえ、読んだ人はいません。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1030, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'試着しました（　）、サイズが合いませんでした。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"し","B":"から","C":"が","D":"ので"},"correctAnswer":"C"}'
    UNION ALL SELECT 1037, _utf8mb4'EASY', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'冬は寒いです（　）、雪はあまり降りません。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"から","B":"が","C":"ので","D":"し"},"correctAnswer":"B"}'
    UNION ALL SELECT 1044, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'売り場は開いています（　）、食堂はもう閉まりました。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"し","B":"ので","C":"から","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 2016, _utf8mb4'EASY', _utf8mb4'弟は字が読めます（　）。できることとできないことを対比します。', _utf8mb4'「が、まだ書けません」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"ので、全く読めません","B":"が、まだ書けません","C":"から、読めません","D":"し、字も読めます"},"correctAnswer":"B"}'
    UNION ALL SELECT 2037, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nối hai ý tương phản.', _utf8mb4 0x0a, _utf8mb4'二人とも学生です（　）、学部は違います。'), _utf8mb4'「が」. が nối hai nhận xét đối lập, nghĩa là “nhưng”.', _utf8mb4'{"options":{"A":"ので","B":"が","C":"から","D":"し"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 16 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S1 が、S2。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 17 (S + ね。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'二人で雪を見ながら「きれいです（　）」と、相手にも同意を求めました。' AS content, _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.' AS explanation, _utf8mb4'{"options":{"A":"よ","B":"かな","C":"か","D":"ね"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'「今日は暑いですね。」Người nói dùng ね với mục đích gì?', _utf8mb4'Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"Mong người nghe đồng tình với cảm nhận trời nóng.","B":"Ra lệnh người nghe ra ngoài.","C":"Hỏi số đo nhiệt độ cụ thể.","D":"Bác bỏ lời người nghe về thời tiết."},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'同じ坂を登った友達に「急でした（　）」と言って感想を分かち合います。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"か","C":"ね","D":"かな"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人とも料理の味を知っています。「このスープ、やさしい味です（　）。」'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"ね","B":"よ","C":"か","D":"かな"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'二人で桜を見ながら「（　）」と、同じ感動を分かち合います。', _utf8mb4'「きれいですね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"きれいにしてください","B":"きれいですね","C":"きれいにします","D":"きれいだそうですか"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'一緒に階段を上り終えて「（　）」と言い、お互いの気持ちを確かめます。', _utf8mb4'「疲れましたね」. Dùng thân động từ và đuôi ます để nói lịch sự về việc thường làm hoặc sắp làm.', _utf8mb4'{"options":{"A":"疲れますか","B":"疲れましたね","C":"疲れましたっけ","D":"疲れさせてください"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'Cùng nhìn cá với bạn. Chọn cách gợi sự đồng tình.', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"この魚はきれいですよ。","B":"この魚はきれいですか。","C":"この魚はきれいですかな。","D":"この魚はきれいですね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'外の強い風を一緒に感じて「風が強いです（　）」とうなずき合いました。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"か","C":"かな","D":"ね"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'花火を見終わって、隣の人に「すばらしかったです（　）」と共感を求めます。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"か","B":"ね","C":"よ","D":"かな"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'一緒に電車を待ちながら「今日は人が多いです（　）」と話しかけました。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"ね","B":"かな","C":"よ","D":"か"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'試験を受けた同級生に「最後の問題は難しかったです（　）」と感想を合わせます。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"かな","B":"よ","C":"か","D":"ね"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：同じ桜を見ながら、相手もそう思うか聞きたいです。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「きれいですね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"きれいですね。","B":"きれいでしたか。","C":"きれいにします。","D":"きれいな桜を買います。"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'Hai người cùng chờ. Bạn muốn người kia đồng tình rằng chờ lâu.', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"ずいぶん長く待ちましたよ。","B":"ずいぶん長く待ちましたかな。","C":"ずいぶん長く待ちましたか。","D":"ずいぶん長く待ちましたね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人で小さな子の絵を見て「かわいいです（　）」と言いました。相手も同感です。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"かな","C":"ね","D":"か"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'同じバスを降りた友達に「遠かったです（　）」と、返事を期待して言います。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"か","D":"かな"},"correctAnswer":"B"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'空を見上げている相手に「星がよく見えます（　）」と共感を求めます。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"かな","B":"よ","C":"ね","D":"か"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'二人で同じメニューを見て「安いです（　）」と驚きを共有しました。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"か","B":"ね","C":"よ","D":"かな"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'久しぶりに会った同級生に「懐かしいです（　）」と気持ちを共有します。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"かな","B":"よ","C":"ね","D":"か"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：今日はずいぶん暖かいですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「本当ですね。上着はいりませんね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"暖房は何時に消しますか。","B":"上着を買ったのは先月です。","C":"本当ですね。上着はいりませんね。","D":"暖房器具は一万円です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'一緒に片付けた後「きれいになりました（　）」と相手もうなずくように言います。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"ね","B":"か","C":"かな","D":"よ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1003, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：海、静かですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「そうですね。波の音しか聞こえません」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"そうですね。波の音しか聞こえません。","B":"漁船は今朝出ました。","C":"波が何回ありましたか。","D":"海まで二時間かかります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1010, _utf8mb4'EASY', _utf8mb4'ホームで二人が雨を見て「よく降ります（　）」と言いました。同意を求めます。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"ね","B":"かな","C":"か","D":"よ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', _utf8mb4'同じ部屋に入った友達に「ここは涼しいです（　）」と共感を求めます。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"か","B":"かな","C":"ね","D":"よ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1024, _utf8mb4'MEDIUM', _utf8mb4'Muốn chia sẻ cảm nhận về không khí mát sau mưa.', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"雨の後は涼しいですかな。","B":"雨の後は涼しいですか。","C":"雨の後は涼しいですよ。","D":"雨の後は涼しいですね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1031, _utf8mb4'EASY', _utf8mb4'会場を出た二人。「今日の演奏、よかったです（　）」と感想を共有します。', _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"かな","C":"ね","D":"か"},"correctAnswer":"C"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人とも朝焼けを見ました。「空が赤いです（　）」と、相手にもそう感じるか尋ねます。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"かな","C":"か","D":"ね"},"correctAnswer":"D"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', _utf8mb4'味見した二人。「（　）」。相手も感じた甘さを話題にします。', _utf8mb4'「甘いですね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"甘いでしょうか","B":"甘いですね","C":"甘くします","D":"甘くしてください"},"correctAnswer":"B"}'
    UNION ALL SELECT 2017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：長い階段でしたね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ええ、二人ともよく登りましたね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"ええ、二人ともよく登りましたね。","B":"階段の工事は来月です。","C":"切符は先に買いました。","D":"階段は二階の右です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe đồng tình.', _utf8mb4 0x0a, _utf8mb4'友達と山頂へ着き「空気がきれいです（　）」と言います。感動を分け合いたいです。'), _utf8mb4'「ね」. Trợ từ cuối câu ね mời người nghe đồng tình hoặc chia sẻ cảm nhận.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"か","D":"かな"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 17 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S + ね。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 18 (N は thời gian、Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'毎年一月、この村は冷え込みます。気候を今の形でまとめます。「この村は（　）。」' AS content, _utf8mb4'Dùng mốc 一月 rồi tính từ い ở dạng thường gặp 寒いです để tả khí hậu hằng năm.' AS explanation, _utf8mb4'{"options":{"A":"一月の寒くなります","B":"一月、寒くです","C":"一月、寒いでした","D":"一月、寒いです"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'七月は毎年三十五度です。表の傾向を否定せずに述べます。「この地域は（　）。」', _utf8mb4'七月 đặt bối cảnh thời gian. 暑いです là vị ngữ khẳng định ở hiện tại.', _utf8mb4'{"options":{"A":"七月、暑いです","B":"七月、暑いなです","C":"七月の暑くです","D":"七月、暑くないです"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', _utf8mb4'春は日差しが心地よいです。春の特徴として「このあたりは（　）」と言います。', _utf8mb4'春 có thể đứng trực tiếp làm mốc cho 暖かいです.', _utf8mb4'{"options":{"A":"春、暖かいです","B":"春に暖かいなです","C":"春、暖かくです","D":"春を暖かいです"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'Nhìn biểu đồ tháng hai có nhiều tuyết, chọn câu tả đúng.', _utf8mb4'「雪が多いです」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"この村は二月、雪は全然降りません。","B":"この村は二月、雪が少ないです。","C":"この村は二月、雪が多いです。","D":"この村は二月、雪はありません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'Theo nhật ký, tháng bảy có nhiều ngày mưa.', _utf8mb4'「雨が多いです」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"ここは七月、ずっと晴れです。","B":"ここは七月、雨は降りません。","C":"ここは七月、雨が少ないです。","D":"ここは七月、雨が多いです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', _utf8mb4'夏は昼と夜で気温が違います。「昼は暑いですが、（　）。」夜の性質を対比します。', _utf8mb4'夜は đối chiếu với 昼は, sau đó là vị ngữ hoàn chỉnh 涼しいです.', _utf8mb4'{"options":{"A":"夜を涼しいです","B":"夜は涼しいでした","C":"夜の涼しくです","D":"夜は涼しいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：冬の朝は池が凍ります。その村の冬はどうですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「とても寒いです」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"とても蒸し暑いです。","B":"冬はいつも真夏日です。","C":"冬も暑くて氷はできません。","D":"とても寒いです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'Miêu tả mùa thu mát mẻ, không phải lạnh buốt.', _utf8mb4'「涼しいです」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"この辺は秋、うだるほど暑いです。","B":"この辺は秋、涼しいです。","C":"この辺は秋、蒸し暑いです。","D":"この辺は秋、寒くて凍ります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', _utf8mb4'年ごとの傾向を説明します。この町は二月、湖が凍るほど（　）。〔寒い・現在の肯定〕', _utf8mb4'Giữ nguyên đuôi い trước です khi nêu đặc điểm khẳng định theo tháng.', _utf8mb4'{"options":{"A":"寒いなです","B":"寒いです","C":"寒くです","D":"寒くないです"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'「この町は一月、雪が多いです。」一月 giới hạn thông tin gì?', _utf8mb4'一月 đứng trước nhận xét về tuyết, giới hạn nhận xét đó vào tháng một.', _utf8mb4'{"options":{"A":"Khoảng thời gian nhận xét về tuyết trong năm.","B":"Giờ bắt đầu có tuyết.","C":"Số tháng liên tiếp tuyết rơi.","D":"Địa điểm có tuyết."},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'梅雨の六月は雨の多さが特徴です。「この島は（　）。」毎年の気候を述べます。', _utf8mb4'Sau 六月, cụm 雨が多いです diễn đạt lượng mưa nhiều trong thời gian đó.', _utf8mb4'{"options":{"A":"六月の雨が多いなです","B":"六月、雨が多いです","C":"六月、雨を多いです","D":"六月、雨が多くです"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', _utf8mb4'海辺では朝だけ風が強く、夜はおだやかです。朝を取り立てて言います。「海辺は（　）。」', _utf8mb4'朝は giới hạn thời điểm nhận xét, 風が強いです mô tả gió trong thời điểm ấy.', _utf8mb4'{"options":{"A":"朝は風が強いです","B":"朝が風を強いです","C":"朝の風を強いです","D":"朝は風が強くです"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'東京（　）八月は蒸し暑いです。どこの八月かを示します。', _utf8mb4'「の」. の nối danh từ chỉ mốc với danh từ đứng sau.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"が"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'いつもの八月について、丁寧な肯定文を作ります。「盆地は八月、（　）。」〔蒸し暑い〕', _utf8mb4'Nói đặc điểm tháng tám hằng năm nên dùng 蒸し暑いです ở dạng phi quá khứ.', _utf8mb4'{"options":{"A":"蒸し暑くないです","B":"蒸し暑かったです","C":"蒸し暑いです","D":"蒸し暑いなです"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', _utf8mb4'山の上は昼は暖かいですが、夜（　）寒いです。昼と対比します。', _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.', _utf8mb4'{"options":{"A":"を","B":"の","C":"は","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'この島では冬に風（　）強いです。「何が強いか」を示します。', _utf8mb4'「が」. が đánh dấu chủ thể hoặc đối tượng mang đặc điểm đang xét.', _utf8mb4'{"options":{"A":"を","B":"が","C":"に","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：夏でも山へ行くと長袖が要るそうですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「ええ、山の夜は涼しいです」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"はい、一年中真夏日です。","B":"ええ、山の夜は涼しいです。","C":"いいえ、山に夜はありません。","D":"はい、汗が止まらないからです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', _utf8mb4'山では四月も雪が残ります。春と夏を対比します。「平地と違い、この山は（　）。」', _utf8mb4'春は đánh dấu mùa được đối chiếu, 寒いです làm vị ngữ.', _utf8mb4'{"options":{"A":"春は寒なです","B":"春を寒いです","C":"春は寒いです","D":"春の寒くです"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'七月も八月（　）蒸し暑いです。両方の月に共通しています。', _utf8mb4'「も」. も cho biết đặc điểm đúng với cả đối tượng được thêm vào.', _utf8mb4'{"options":{"A":"の","B":"が","C":"へ","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'秋の夜の気候を説明します。「私の村は（　）。」季節と時間を順に示してください。', _utf8mb4'秋の夜 ghép mùa và buổi trong ngày bằng の trước lời nhận xét.', _utf8mb4'{"options":{"A":"秋を夜、涼しいです","B":"秋が夜の涼しくです","C":"秋の夜、涼しいです","D":"秋の夜、涼しいでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 1004, _utf8mb4'EASY', _utf8mb4'五月の日中は上着がいりません。毎年の特徴を言います。「この町は五月、（　）。」〔暖かい〕', _utf8mb4'暖かい là tính từ い, dùng trực tiếp với です để miêu tả tháng năm.', _utf8mb4'{"options":{"A":"暖かいにです","B":"暖かいなです","C":"暖かくです","D":"暖かいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1011, _utf8mb4'MEDIUM', _utf8mb4'七月の昼は三十五度ですが、夜は涼しいです。昼に限った言い方は「（　）」。', _utf8mb4'昼は giới hạn nhận xét vào ban ngày để đối chiếu với 夜は.', _utf8mb4'{"options":{"A":"昼の暑いなです","B":"昼は暑いです","C":"昼を暑いです","D":"昼は暑くです"},"correctAnswer":"B"}'
    UNION ALL SELECT 1018, _utf8mb4'MEDIUM', _utf8mb4'「冬は雪が多いです（　）」。冬の様子を知りたいので質問します。', _utf8mb4'「か」. か ở cuối câu biểu thị câu hỏi.', _utf8mb4'{"options":{"A":"に","B":"か","C":"を","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 1025, _utf8mb4'EASY', _utf8mb4'過去の一日ではなく、毎年の風の特徴を言います。「この港は秋、（　）。」', _utf8mb4'Mô tả khí hậu thường lệ dùng 風が強いです, không chia quá khứ.', _utf8mb4'{"options":{"A":"風が強いなです","B":"風が強かったです","C":"風が強いです","D":"風を強いです"},"correctAnswer":"C"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', _utf8mb4'気候表によると七月は雨の日が多いです。「この地方は七月、（　）。」', _utf8mb4'七月 nêu thời gian, が sau 雨 đánh dấu thứ có số lượng nhiều.', _utf8mb4'{"options":{"A":"雨が多いです","B":"雨を多いです","C":"雨に多いです","D":"雨が多かったでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 1039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：今月は一日しか雨が降りませんでした。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「雨が少ない月でしたね」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"晴れた日は一日でしたね。","B":"雨が多い月でしたね。","C":"毎日雨の月でしたね。","D":"雨が少ない月でしたね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1046, _utf8mb4'EASY', _utf8mb4'雨上がりの夏の午後は湿度も気温も高いです。文を完成します。「この町は（　）。」', _utf8mb4'夏の午後 chỉ buổi chiều mùa hè, theo sau bằng vị ngữ 蒸し暑いです.', _utf8mb4'{"options":{"A":"夏の午後、蒸し暑いです","B":"夏を午後、蒸し暑いです","C":"夏の午後、蒸し暑くです","D":"夏に午後を蒸し暑いです"},"correctAnswer":"A"}'
    UNION ALL SELECT 2018, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：島では六月に傘が必要ですか。梅雨で雨の日が続くそうです。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、六月は雨が多いです」. Nêu địa điểm và thời gian để xác định nhận xét về thời tiết.', _utf8mb4'{"options":{"A":"はい、雪しか降りません。","B":"いいえ、いつも青空です。","C":"はい、六月は雨が多いです。","D":"いいえ、一度も降りません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2039, _utf8mb4'EASY', _utf8mb4'山村では冬に何度も雪かきが必要です。季節を話題にして「冬は（　）」と言います。', _utf8mb4'冬は nêu mùa. Sau đó 雪が多いです diễn đạt có nhiều tuyết.', _utf8mb4'{"options":{"A":"雪が多いです","B":"雪が多いでした","C":"雪を多いです","D":"雪が多くです"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 18 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は thời gian、Aです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 19 (とても／少し + A)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'この薬は一口で顔をしかめるほどです。（　）苦いです。強い程度を言います。' AS content, _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.' AS explanation, _utf8mb4'{"options":{"A":"少し","B":"とても","C":"あまり","D":"全然"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', _utf8mb4'いつもより一枚だけ服を重ねます。今朝は（　）寒いです。弱い程度です。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"とても","B":"いちばん","C":"少し","D":"すっかり"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：辛さは強いですか。舌が痛くなるほどですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「はい、とても辛いです」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"いいえ、辛くないです。","B":"はい、とても辛いです。","C":"いいえ、味がありません。","D":"はい、少し甘いだけです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：大きさはぴったりですか。袖が一センチだけ長いですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「少し長いです」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"少し長いです。","B":"一年前は短かったです。","C":"色は少し暗いです。","D":"明日から販売します。"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', _utf8mb4'この地方（　）夏はとても短いです。「どこの夏」かを示します。', _utf8mb4'「の」. の nối danh từ chỉ mốc với danh từ đứng sau.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"の","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'階段を一段上がるのも大変です。荷物は（　）重いです。強調します。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"あまり","B":"少し","C":"とても","D":"全然"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'今朝の駅前は人が二、三人増えただけです。先週より（　）にぎやかです。弱く言います。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"とても","B":"すっかり","C":"いちばん","D":"少し"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', _utf8mb4'一口飲めば汗が出るほどです。このスープは（　）辛いです。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"あまり","B":"とても","C":"少し","D":"全然"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'二つの温泉のうち、こちらのほう（　）少し熱いです。', _utf8mb4'「が」. が đánh dấu chủ thể hoặc đối tượng mang đặc điểm đang xét.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'この服はあと一センチだけ大きいとちょうどです。今は（　）小さいです。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"いちばん","B":"とても","C":"少し","D":"すっかり"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', _utf8mb4'出口を全ての人がふさぐほどです。会場は（　）にぎやかです。強く言います。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"少し","B":"全然","C":"あまり","D":"とても"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'昼に比べて気温が一度だけ下がりました。今は（　）涼しいです。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"とても","B":"すっかり","C":"いちばん","D":"少し"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'Diễn đạt mức độ mạnh vì món ăn cay đến chảy nước mắt.', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"このカレーはとても辛いです。","B":"このカレーは全然辛いです。","C":"このカレーは少し辛いです。","D":"このカレーはあまり辛いです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', _utf8mb4'照明がまぶしくて目を開けにくいです。この部屋は（　）明るいです。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"全然","B":"少し","C":"あまり","D":"とても"},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'ちょうどいい長さより一センチ短いです。このひもは（　）短いです。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"いちばん","B":"少し","C":"とても","D":"すっかり"},"correctAnswer":"B"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'昼はとても暑いですが、朝（　）少し涼しいです。時間を対比します。', _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.', _utf8mb4'{"options":{"A":"へ","B":"は","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', _utf8mb4'何度読んでも分かりません。この文章は（　）難しいです。程度を強めます。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"とても","B":"少し","C":"全然","D":"あまり"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Nói tay áo dài hơn mong muốn một chút.', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"この服の袖は少し長いです。","B":"この服の袖はとても長いです。","C":"この服の袖はすっかり長いです。","D":"この服の袖はいちばん長いです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「少し寒い」と「とても寒い」、上着をもう二枚着たいほどなら？', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「「とても寒い」です」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"「とても寒い」です。","B":"「寒くない」です。","C":"「とても暖かい」です。","D":"「少し寒い」です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', _utf8mb4'机を五センチ動かしました。作業できる場所は前より（　）広いです。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"いちばん","B":"とても","C":"少し","D":"すっかり"},"correctAnswer":"C"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', _utf8mb4'手が届かないほど上にあります。あの棚は（　）高いです。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"全然","B":"少し","C":"あまり","D":"とても"},"correctAnswer":"D"}'
    UNION ALL SELECT 1012, _utf8mb4'MEDIUM', _utf8mb4'Nói màu áo chỉ hơi tối so với màu mong muốn.', _utf8mb4'少し trước 暗いです chỉ độ tối chênh lệch nhẹ.', _utf8mb4'{"options":{"A":"このシャツの色はとても暗いです。","B":"このシャツの色はいちばん暗いです。","C":"このシャツの色は全く暗くないです。","D":"このシャツの色は少し暗いです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1019, _utf8mb4'EASY', _utf8mb4'シャツに小さなシミが一つあります。（　）汚れていますが、着られます。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"とても","B":"すっかり","C":"少し","D":"いちばん"},"correctAnswer":"C"}'
    UNION ALL SELECT 1026, _utf8mb4'MEDIUM', _utf8mb4'見渡すかぎり白い花です。この花畑は（　）きれいです。強くほめます。', _utf8mb4'「とても」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"あまり","B":"とても","C":"全然","D":"少し"},"correctAnswer":"B"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：きのうより首の痛みはよくなりましたか。軽い痛みだけ残っていますね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'少し diễn đạt mức nhẹ, phù hợp với 軽い痛みだけ còn lại.', _utf8mb4'{"options":{"A":"はい、痛くて全く動けません。","B":"はい、まだ少し痛いです。","C":"はい、痛みは全くありません。","D":"いいえ、ずっと激しく痛みます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1040, _utf8mb4'EASY', _utf8mb4'疲れは軽く、まだ歩けます。「（　）疲れました」と、弱く伝えます。', _utf8mb4'「少し」. とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"少し","B":"とても","C":"いちばん","D":"すっかり"},"correctAnswer":"A"}'
    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', _utf8mb4'妹の部屋（　）とても狭いです。私の部屋のほかに付け加えます。', _utf8mb4'「も」. も cho biết đặc điểm đúng với cả đối tượng được thêm vào.', _utf8mb4'{"options":{"A":"の","B":"が","C":"も","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 2019, _utf8mb4'EASY', _utf8mb4'「道はとても混んでいます（　）」。出発前に尋ねます。', _utf8mb4'「か」. か ở cuối câu biểu thị câu hỏi.', _utf8mb4'{"options":{"A":"の","B":"を","C":"に","D":"か"},"correctAnswer":"D"}'
    UNION ALL SELECT 2040, _utf8mb4'MEDIUM', _utf8mb4'「この坂は少し急です。」少し làm thay đổi mức độ ra sao?', _utf8mb4'とても nhấn mạnh mức độ cao. 少し diễn đạt mức độ nhẹ.', _utf8mb4'{"options":{"A":"Dốc ở mức nhẹ.","B":"Hoàn toàn không dốc.","C":"Dốc ở mức rất cao.","D":"Đã hết dốc từ trước."},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 19 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'とても／少し + A' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 20 (あまり + A phủ định)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'真冬でも十七度くらいです。この地域はあまり（　）。〔寒い〕') AS content, _utf8mb4'「寒くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.' AS explanation, _utf8mb4'{"options":{"A":"寒いです","B":"寒くないです","C":"寒いじゃありません","D":"寒かったです"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：この町は冬、とても寒いですか。軽い上着で十分なんですね。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、あまり寒くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"いいえ、上着を三枚着ます。","B":"はい、氷点下二十度です。","C":"いいえ、あまり寒くないです。","D":"はい、ずっと凍っています。"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'駅からの道（　）あまり長くないです。この道を話題にします。', _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.', _utf8mb4'{"options":{"A":"を","B":"は","C":"へ","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', _utf8mb4'隣村（　）冬はあまり寒くないです。どこの冬かを示します。', _utf8mb4'「の」. の nối danh từ chỉ mốc với danh từ đứng sau.', _utf8mb4'{"options":{"A":"が","B":"を","C":"の","D":"へ"},"correctAnswer":"C"}'
