    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'値引きが大きいので、この靴はあまり（　）。〔高い〕'), _utf8mb4'「高くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"高いです","B":"高いじゃありません","C":"高かったです","D":"高くないです"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'道のりは一キロほどです。ここから駅はあまり（　）。〔遠い〕'), _utf8mb4'「遠くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"遠いじゃありません","B":"遠かったです","C":"遠くないです","D":"遠いです"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'店は夜に一軒しか開きません。この辺はあまり（　）。〔便利〕'), _utf8mb4'「便利じゃありません」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"便利じゃありませんでした","B":"便利じゃあります","C":"便利じゃありました","D":"便利じゃありません"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：「あまり高くない」は「とても高い」と同じですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、値段はそれほど高くないという意味です」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"いいえ、値段はそれほど高くないという意味です。","B":"はい、値段が一番高いという意味です。","C":"はい、無料という意味です。","D":"いいえ、重さがあるという意味です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'見た目ほど力はいりません。この荷物はあまり（　）。〔重い〕'), _utf8mb4'「重くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"重いです","B":"重いじゃありません","C":"重かったです","D":"重くないです"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', _utf8mb4'学校の前も駅前（　）あまり静かじゃありません。二か所を並べます。', _utf8mb4'「も」. も cho biết đặc điểm đúng với cả đối tượng được thêm vào.', _utf8mb4'{"options":{"A":"も","B":"が","C":"へ","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'宿には小さな窓が一つだけです。この部屋はあまり（　）。〔明るい〕'), _utf8mb4'「明るくないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"明るいです","B":"明るいじゃありません","C":"明るくないです","D":"明るかったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'Nói túi thuốc nhỏ này không đắt lắm.', _utf8mb4'「高くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"この薬はあまり高かったです。","B":"この薬はあまり高いです。","C":"この薬はあまり高くないです。","D":"この薬はあまり高いじゃありません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', _utf8mb4'「このカレーはあまり辛くないです（　）」。味を知るために質問します。', _utf8mb4'「か」. か ở cuối câu biểu thị câu hỏi.', _utf8mb4'{"options":{"A":"に","B":"を","C":"の","D":"か"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'買ってまだ一年です。この機械はあまり（　）。〔古い〕'), _utf8mb4'「古くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"古いです","B":"古くないです","C":"古いじゃありません","D":"古かったです"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'基本の単語で書いてあります。この手紙はあまり（　）。〔難しい〕'), _utf8mb4'「難しくないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"難しくないです","B":"難しいです","C":"難しいじゃありません","D":"難しかったです"},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'混んでいるのは昼だけで、朝はあまり（　）。〔にぎやか〕'), _utf8mb4'「にぎやかじゃありません」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"にぎやかじゃあります","B":"にぎやかじゃありません","C":"にぎやかじゃありませんでした","D":"にぎやかじゃありました"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'「あまり難しくないです。」Chọn sắc thái đúng.', _utf8mb4'あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"Không khó lắm, vẫn có thể có chút khó.","B":"Khó nhất trong tất cả.","C":"Hoàn toàn không thể hiểu.","D":"Rất khó."},"correctAnswer":"A"}'
    UNION ALL SELECT 1006, _utf8mb4'MEDIUM', _utf8mb4'Nói hôm nay thị trấn không nhộn nhịp lắm.', _utf8mb4'「にぎやかじゃありません」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"今日は町があまりにぎやかじゃありません。","B":"今日は町があまりにぎやかじゃあります。","C":"今日は町があまりにぎやかじゃありませんでした。","D":"今日は町があまりにぎやかじゃありました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1013, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'七月でも風が涼しく、山の上はあまり（　）。〔暑い〕'), _utf8mb4'「暑くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"暑いです","B":"暑くないです","C":"暑いじゃありません","D":"暑かったです"},"correctAnswer":"B"}'
    UNION ALL SELECT 1020, _utf8mb4'MEDIUM', _utf8mb4'二つの席を比べると、窓側のほう（　）あまり寒くないです。', _utf8mb4'「が」. が đánh dấu chủ thể hoặc đối tượng mang đặc điểm đang xét.', _utf8mb4'{"options":{"A":"に","B":"を","C":"へ","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：駅まで遠いですか。徒歩でちょうど十分です。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、あまり遠くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"いいえ、あまり遠くないです。","B":"はい、何時間もかかります。","C":"はい、外国にあります。","D":"いいえ、どこにもありません。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1034, _utf8mb4'EASY', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'一日に一本しか便がありません。この船はあまり（　）。〔便利〕'), _utf8mb4'「便利じゃありません」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"便利じゃあります","B":"便利じゃありました","C":"便利じゃありませんでした","D":"便利じゃありません"},"correctAnswer":"D"}'
    UNION ALL SELECT 1041, _utf8mb4'MEDIUM', _utf8mb4'Nói phòng khách này không rộng lắm.', _utf8mb4'「広くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"こちらの居間はあまり広いです。","B":"こちらの居間はあまり広いじゃありません。","C":"こちらの居間はあまり広くないです。","D":"こちらの居間はあまり広かったです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'通学時間は十五分です。毎日の移動はあまり（　）。〔長い〕'), _utf8mb4'「長くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"長いじゃありません","B":"長かったです","C":"長くないです","D":"長いです"},"correctAnswer":"C"}'
    UNION ALL SELECT 2020, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：このカレーは辛いですか。子ども向けと書いてあります。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「いいえ、あまり辛くないです」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"はい、辛さが分かりませんでしたか。","B":"いいえ、あまり辛くないです。","C":"いいえ、とても辛いです。","D":"はい、激辛だけです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng dạng phủ định lịch sự.', _utf8mb4 0x0a, _utf8mb4'色はきれいですが、座面が固くてあまり（　）。〔快適〕'), _utf8mb4'「快適じゃありません」. あまり đi cùng dạng phủ định để diễn đạt “không ... lắm”.', _utf8mb4'{"options":{"A":"快適じゃありました","B":"快適じゃありません","C":"快適じゃありませんでした","D":"快適じゃあります"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 20 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'あまり + A phủ định' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 4 / NGỮ PHÁP / Mẫu 21 (N はどうですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'仕事（　）どうですか。仕事を話題にして尋ねます。' AS content, _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.' AS explanation, _utf8mb4'{"options":{"A":"の","B":"へ","C":"は","D":"を"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'新しい仕事の感想を聞きます。「新しい職場は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"いくら","B":"どう","C":"どこ","D":"だれ"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：旅館の部屋はどうでしたか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「静かでよく眠れました」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"玄関から二階へ行きます。","B":"三人で行きました。","C":"六月一日からでした。","D":"静かでよく眠れました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'「新しい町はどうです（　）」。町の感想を質問します。', _utf8mb4'「か」. か ở cuối câu biểu thị câu hỏi.', _utf8mb4'{"options":{"A":"に","B":"を","C":"か","D":"の"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'「新しい職場はどうですか。」Phản hồi phù hợp nên cho biết gì?', _utf8mb4'どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"Phương tiện duy nhất để đi làm.","B":"Số nhà của công ty cũ.","C":"Ngày bắt đầu làm việc trước đây.","D":"Cảm nhận hoặc nhận xét về nơi làm việc mới."},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'初めて料理を食べた友達に「味は（　）ですか」と評価を尋ねます。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どう","B":"だれ","C":"いくら","D":"どこ"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'着心地を知りたい店員は「そのシャツは（　）ですか」と聞きました。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どこ","B":"だれ","C":"どう","D":"いくら"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'旅行を終えた友達に感想を聞きます。「京都は（　）でしたか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"だれ","B":"どこ","C":"どう","D":"いくら"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：日本語の授業はどうですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「難しいですが、おもしろいです」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"火曜日の三時です。","B":"先生の出身は東京です。","C":"教室は二階です。","D":"難しいですが、おもしろいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'入院中の人の体調を聞きます。「お体は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どう","B":"どこ","C":"だれ","D":"いくら"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'Hỏi cảm nhận về chiếc giường mới.', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"新しいベッドはどこですか。","B":"新しいベッドはどうですか。","C":"新しいベッドはだれですか。","D":"新しいベッドはいくらですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'Hỏi ý kiến của bạn về mùi vị món mì vừa nếm.', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"このうどんの味はどうですか。","B":"このうどんの味はだれですか。","C":"このうどんの味はどこですか。","D":"このうどんの味はいくらですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'値段ではなく住み心地を知りたい。「新しい部屋は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どう","B":"どこ","C":"いくら","D":"だれ"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'旅行先（　）食事はどうでしたか。どこの食事かを示します。', _utf8mb4'「の」. の nối danh từ chỉ mốc với danh từ đứng sau.', _utf8mb4'{"options":{"A":"が","B":"を","C":"の","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'Hỏi cảm tưởng về buổi hòa nhạc hôm qua.', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"昨日のコンサートはいくらでしたか。","B":"昨日のコンサートはだれでしたか。","C":"昨日のコンサートはどこでしたか。","D":"昨日のコンサートはどうでしたか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'飼い始めた子猫の様子を知りたい。「子猫は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"いくら","B":"どう","C":"どこ","D":"だれ"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'こちらは便利です。そちら（　）どうですか。こちらとそちらを対比します。', _utf8mb4'「は」. は nêu chủ đề hoặc đối chiếu nó với chủ đề khác.', _utf8mb4'{"options":{"A":"は","B":"へ","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：新しいめがねのかけ心地はどうですか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「軽くて楽です」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"眼鏡屋で買いました。","B":"青い箱に入っていました。","C":"昨日受け取りました。","D":"軽くて楽です。"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'作品を見た人に自分の絵について評価を尋ねます。「この絵は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どこ","B":"どう","C":"いくら","D":"だれ"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'先生（　）「新しい教室はどうですか」と聞きました。質問の相手を示します。', _utf8mb4'「に」. に nêu mốc giờ, nơi tồn tại hoặc đích tiếp nhận tùy ngữ cảnh.', _utf8mb4'{"options":{"A":"で","B":"に","C":"を","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 1007, _utf8mb4'EASY', _utf8mb4'使いやすさを聞くため、「このキーボードは（　）ですか」と尋ねます。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どう","B":"どこ","C":"いくら","D":"だれ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1014, _utf8mb4'MEDIUM', _utf8mb4'天候の様子を電話で聞きたい。「そちらの天気は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"だれ","B":"どう","C":"いくら","D":"どこ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', _utf8mb4'本を読み終えた人に内容の感想を聞きます。「結末は（　）でしたか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どう","B":"だれ","C":"いくら","D":"どこ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1028, _utf8mb4'EASY', _utf8mb4'発表の後で先生に「話す速さは（　）でしたか」と意見を求めます。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"どこ","B":"だれ","C":"いくら","D":"どう"},"correctAnswer":"D"}'
    UNION ALL SELECT 1035, _utf8mb4'MEDIUM', _utf8mb4'スポーツを始めた同僚に「調子は（　）ですか」と尋ねます。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"だれ","B":"どこ","C":"どう","D":"いくら"},"correctAnswer":"C"}'
    UNION ALL SELECT 1042, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'A：味の感想を聞きたいとき、何と言いますか。', _utf8mb4 0x0a, _utf8mb4'B：（　）'), _utf8mb4'「この料理はどうですか」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"この料理はいくつですか。","B":"この料理はどうですか。","C":"この料理はどこですか。","D":"この料理はいつですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1049, _utf8mb4'EASY', _utf8mb4'耳鼻科で薬を替えた後、医師が「耳の具合は（　）ですか」と聞きました。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"いくら","B":"だれ","C":"どこ","D":"どう"},"correctAnswer":"D"}'
    UNION ALL SELECT 2021, _utf8mb4'MEDIUM', _utf8mb4'近所の交通事情を知りたい。「夕方の道の混み方は（　）ですか。」', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"だれ","B":"いくら","C":"どう","D":"どこ"},"correctAnswer":"C"}'
    UNION ALL SELECT 2042, _utf8mb4'EASY', _utf8mb4'新しい靴で少し歩いてもらい、「サイズは（　）ですか」と聞きます。', _utf8mb4'「どう」. どうですか mời người nghe nêu cảm nhận, nhận xét hoặc tình trạng.', _utf8mb4'{"options":{"A":"だれ","B":"どこ","C":"どう","D":"いくら"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 4
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 21 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N はどうですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 1 (Vます → Vました。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'先週、先生に作文を（　）。') AS content, _utf8mb4'「見せました」 là thể quá khứ khẳng định lịch sự của 見せます.' AS explanation, _utf8mb4'{"options":{"A":"見せました","B":"見せましょう","C":"見せます","D":"見せませんでした"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Kể lại việc đã làm.', _utf8mb4 0x0a, _utf8mb4'清掃記録の記録：公園のごみを（　）。'), _utf8mb4'「拾いました」 là thể quá khứ khẳng định lịch sự của 拾います.', _utf8mb4'{"options":{"A":"拾いませんでした","B":"拾いましょう","C":"拾いました","D":"拾います"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'旅行の日には祖母に荷物を送りました。'), _utf8mb4'「送りました」 là thể quá khứ khẳng định lịch sự của 送ります.', _utf8mb4'{"options":{"A":"Tôi sẽ gửi bưu kiện cho bà.","B":"Chúng ta hãy gửi bưu kiện cho bà.","C":"Tôi đã gửi bưu kiện cho bà.","D":"Tôi đã không gửi bưu kiện cho bà."},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xác nhận đã học nấu món địa phương.', _utf8mb4 0x0a, _utf8mb4'A「料理教室には何をしに行きましたか。」 B「（　）」'), _utf8mb4'「習いました」 là thể quá khứ khẳng định lịch sự của 習います.', _utf8mb4'{"options":{"A":"地元の料理を習いませんでした。","B":"地元の料理を習いたいです。","C":"地元の料理を習いましょうか。","D":"地元の料理を習いました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo việc đã xong.', _utf8mb4 0x0a, _utf8mb4'日曜日に、自転車のタイヤを（　）。'), _utf8mb4'「直しました」 là thể quá khứ khẳng định lịch sự của 直します.', _utf8mb4'{"options":{"A":"直します","B":"直しました","C":"直しましょう","D":"直しませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo việc đã làm xong.', _utf8mb4 0x0a, _utf8mb4'きのうは店の掃除当番。ガラスは今ぴかぴかです。'), _utf8mb4'「磨きました」 là thể quá khứ khẳng định lịch sự của 磨きます.', _utf8mb4'{"options":{"A":"開店の準備の記録：店の窓を磨きます。","B":"開店の準備の記録：店の窓を磨きましょう。","C":"開店の準備の記録：店の窓を磨きました。","D":"開店の準備の記録：店の窓を磨きませんでした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xác nhận đã mang quần áo cũ đến tặng.', _utf8mb4 0x0a, _utf8mb4'A「古い服は会館に持っていきましたか。」 B「（　）」'), _utf8mb4'「届けました」 là thể quá khứ khẳng định lịch sự của 届けます.', _utf8mb4'{"options":{"A":"古い服を届けました。","B":"古い服を届けましょうか。","C":"古い服を届けたいです。","D":"古い服を届けませんでした。"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Xác nhận việc đã xảy ra.', _utf8mb4 0x0a, _utf8mb4'土曜の朝のことです。電車の切符を（　）。'), _utf8mb4'「買いました」 là thể quá khứ khẳng định lịch sự của 買います.', _utf8mb4'{"options":{"A":"買いました","B":"買いましょう","C":"買いませんでした","D":"買います"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'先日の午後、会議の資料をコピーしました。'), _utf8mb4'「コピーしました」 là thể quá khứ khẳng định lịch sự của コピーします.', _utf8mb4'{"options":{"A":"Tôi đã sao tài liệu họp.","B":"Tôi sẽ sao tài liệu họp.","C":"Tôi đã không sao tài liệu họp.","D":"Chúng ta hãy sao tài liệu họp."},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'空港の案内の記録：留学生を（　）。'), _utf8mb4'「迎えました」 là thể quá khứ khẳng định lịch sự của 迎えます.', _utf8mb4'{"options":{"A":"迎えます","B":"迎えましょう","C":"迎えませんでした","D":"迎えました"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Ghi việc đã thực hiện.', _utf8mb4 0x0a, _utf8mb4'先週の金曜日には手作りのパンを（　）。'), _utf8mb4'「売りました」 là thể quá khứ khẳng định lịch sự của 売ります.', _utf8mb4'{"options":{"A":"売りませんでした","B":"売りましょう","C":"売りました","D":"売ります"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kể việc tra cứu đã thực hiện.', _utf8mb4 0x0a, _utf8mb4'花の名が分かり、昨日の観察ノートに書きました。'), _utf8mb4'「調べました」 là thể quá khứ khẳng định lịch sự của 調べます.', _utf8mb4'{"options":{"A":"昨日のことです。花の名前を調べませんでした。","B":"昨日のことです。花の名前を調べます。","C":"昨日のことです。花の名前を調べましょう。","D":"昨日のことです。花の名前を調べました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo việc đã xác minh.', _utf8mb4 0x0a, _utf8mb4'試合の日が変わりました。新しい時間は手帳に書いてあります。'), _utf8mb4'「確かめました」 là thể quá khứ khẳng định lịch sự của 確かめます.', _utf8mb4'{"options":{"A":"先週、試合の予定を確かめます。","B":"先週、試合の予定を確かめました。","C":"先週、試合の予定を確かめませんでした。","D":"先週、試合の予定を確かめましょう。"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Kể lại việc đã làm.', _utf8mb4 0x0a, _utf8mb4'家具の組立の記録：本棚を（　）。'), _utf8mb4'「組み立てました」 là thể quá khứ khẳng định lịch sự của 組み立てます.', _utf8mb4'{"options":{"A":"組み立てませんでした","B":"組み立てました","C":"組み立てます","D":"組み立てましょう"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'旅行の日には池の魚にえさを（　）。'), _utf8mb4'「やりました」 là thể quá khứ khẳng định lịch sự của やります.', _utf8mb4'{"options":{"A":"やりませんでした","B":"やります","C":"やりましょう","D":"やりました"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'あの日のことです。写真を大きく（　）。'), _utf8mb4'「印刷しました」 là thể quá khứ khẳng định lịch sự của 印刷します.', _utf8mb4'{"options":{"A":"印刷しましょう","B":"印刷します","C":"印刷しませんでした","D":"印刷しました"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo việc đã xong.', _utf8mb4 0x0a, _utf8mb4'日曜日に、猫の写真を（　）。'), _utf8mb4'「撮りました」 là thể quá khứ khẳng định lịch sự của 撮ります.', _utf8mb4'{"options":{"A":"撮ります","B":"撮りませんでした","C":"撮りました","D":"撮りましょう"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xác nhận đã tập hát hợp xướng.', _utf8mb4 0x0a, _utf8mb4'A「合唱の準備は進みましたか。」 B「（　）」'), _utf8mb4'「しました」 là thể quá khứ khẳng định lịch sự của します.', _utf8mb4'{"options":{"A":"合唱の練習をしましょうか。","B":"合唱の練習をしました。","C":"合唱の練習をしませんでした。","D":"合唱の練習をしたいです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'休みの日には古い雑誌を（　）。'), _utf8mb4'「まとめました」 là thể quá khứ khẳng định lịch sự của まとめます.', _utf8mb4'{"options":{"A":"まとめましょう","B":"まとめました","C":"まとめます","D":"まとめませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Xác nhận việc đã xảy ra.', _utf8mb4 0x0a, _utf8mb4'土曜の朝のことです。黒板の字を（　）。'), _utf8mb4'「消しました」 là thể quá khứ khẳng định lịch sự của 消します.', _utf8mb4'{"options":{"A":"消しました","B":"消します","C":"消しませんでした","D":"消しましょう"},"correctAnswer":"A"}'
    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xác nhận đã viết bưu thiếp.', _utf8mb4 0x0a, _utf8mb4'A「宿で何を書きましたか。」 B「（　）」'), _utf8mb4'「書きました」 là thể quá khứ khẳng định lịch sự của 書きます.', _utf8mb4'{"options":{"A":"絵はがきを書きたいです。","B":"絵はがきを書きましょうか。","C":"絵はがきを書きました。","D":"絵はがきを書きませんでした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'返却の確認の記録：図書館の本を（　）。'), _utf8mb4'「返しました」 là thể quá khứ khẳng định lịch sự của 返します.', _utf8mb4'{"options":{"A":"返しましょう","B":"返しました","C":"返しませんでした","D":"返します"},"correctAnswer":"B"}'
    UNION ALL SELECT 1013, _utf8mb4'EASY', CONCAT(_utf8mb4'Ghi việc đã thực hiện.', _utf8mb4 0x0a, _utf8mb4'先週の金曜日にはポスターを壁に（　）。'), _utf8mb4'「貼りました」 là thể quá khứ khẳng định lịch sự của 貼ります.', _utf8mb4'{"options":{"A":"貼りましょう","B":"貼りませんでした","C":"貼ります","D":"貼りました"},"correctAnswer":"D"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'昨日のことです。新しい靴を（　）。'), _utf8mb4'「選びました」 là thể quá khứ khẳng định lịch sự của 選びます.', _utf8mb4'{"options":{"A":"選びませんでした","B":"選びましょう","C":"選びます","D":"選びました"},"correctAnswer":"D"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'先週、サッカーの試合を（　）。'), _utf8mb4'「見ました」 là thể quá khứ khẳng định lịch sự của 見ます.', _utf8mb4'{"options":{"A":"見ました","B":"見ませんでした","C":"見ます","D":"見ましょう"},"correctAnswer":"A"}'
    UNION ALL SELECT 1031, _utf8mb4'EASY', CONCAT(_utf8mb4'Kể lại việc đã làm.', _utf8mb4 0x0a, _utf8mb4'投函の前の記録：手紙に切手を（　）。'), _utf8mb4'「貼りました」 là thể quá khứ khẳng định lịch sự của 貼ります.', _utf8mb4'{"options":{"A":"貼りませんでした","B":"貼ります","C":"貼りましょう","D":"貼りました"},"correctAnswer":"D"}'
    UNION ALL SELECT 1037, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'旅行の日には紙で鳥を（　）。'), _utf8mb4'「折りました」 là thể quá khứ khẳng định lịch sự của 折ります.', _utf8mb4'{"options":{"A":"折りました","B":"折ります","C":"折りませんでした","D":"折りましょう"},"correctAnswer":"A"}'
