    UNION ALL SELECT 2001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhật ký ghi việc đã hoàn tất.', _utf8mb4 0x0a, _utf8mb4'畑からの報告の記録：畑のトマトを（　）。'), _utf8mb4'「取りました」 là thể quá khứ khẳng định lịch sự của 取ります.', _utf8mb4'{"options":{"A":"取りましょう","B":"取りました","C":"取ります","D":"取りませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 2018, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xác nhận đã tìm chìa khóa ô tô.', _utf8mb4 0x0a, _utf8mb4'A「車の鍵はその後どうしましたか。」 B「（　）」'), _utf8mb4'「探しました」 là thể quá khứ khẳng định lịch sự của 探します.', _utf8mb4'{"options":{"A":"車のかぎを探しませんでした。","B":"車のかぎを探しましょうか。","C":"車のかぎを探しました。","D":"車のかぎを探したいです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2035, _utf8mb4'EASY', CONCAT(_utf8mb4'Xác nhận việc đã xảy ra.', _utf8mb4 0x0a, _utf8mb4'土曜の朝のことです。シャツの代金を（　）。'), _utf8mb4'「払いました」 là thể quá khứ khẳng định lịch sự của 払います.', _utf8mb4'{"options":{"A":"払いました","B":"払いませんでした","C":"払いましょう","D":"払います"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます → Vました。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 2 (Vません → Vませんでした。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
