    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Thấy người quen mang thùng hàng.', _utf8mb4 0x0a, _utf8mb4'この荷物をどこか（　）届けに行きますか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"の","B":"が","C":"を","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Du học sinh sắp về nước, hỏi ý định tham quan.', _utf8mb4 0x0a, _utf8mb4'帰国する前にどこ（　）へ見に行きたいですか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"で","B":"が","C":"か","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi liệu chim có bay đi đâu đó.', _utf8mb4 0x0a, _utf8mb4'雪の朝、庭から鳥が消えました。行き先は分かりません。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"雪が降ると、鳥は何回飛んでいきますか。","B":"雪が降ると、鳥は何時に飛んでいきますか。","C":"雪が降ると、鳥はどこかへ飛んでいきますか。","D":"雪が降ると、鳥はだれと飛んでいきますか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', CONCAT(_utf8mb4'Trước khi rời phố có ghé đâu gửi thư không?', _utf8mb4 0x0a, _utf8mb4'町を出る前にどこ（　）へ手紙を出しに行きますか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"を","B":"か","C":"で","D":"が"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Rủ đi chơi ở một nơi chưa chọn. Hỏi nơi đến.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「いいですね。海はどうですか。」'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"引っ越す前に、何時に遊びに行きませんか。","B":"引っ越す前に、どこかへ遊びに行きませんか。","C":"引っ越す前に、だれと遊びに行きませんか。","D":"引っ越す前に、何回遊びに行きませんか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chưa biết có ai ra ngoài ăn trưa.', _utf8mb4 0x0a, _utf8mb4'昼休みにどこ（　）へ食べに行きますか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"か","B":"が","C":"で","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', CONCAT(_utf8mb4'Hỏi dự định đi ngắm lá đỏ.', _utf8mb4 0x0a, _utf8mb4'寒くなる前に、どこか（　）紅葉を見に行きますか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"の","B":"が","C":"へ","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi có đi đâu tập không.', _utf8mb4 0x0a, _utf8mb4'授業が終わりました。友達はラケットを持っています。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"授業の後はどこかへ練習に行きますか。","B":"授業の後は何時に練習に行きますか。","C":"授業の後はだれと練習に行きますか。","D":"授業の後は何回練習に行きますか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bạn đang chuẩn bị xe đi mua sắm.', _utf8mb4 0x0a, _utf8mb4'今日は車でどこか（　）買い物に行きますか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"の","B":"が","C":"を","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', CONCAT(_utf8mb4'Bạn từ xa tới, hỏi có đưa đi đâu không.', _utf8mb4 0x0a, _utf8mb4'友達が来たら、どこ（　）へ案内しますか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"か","B":"を","C":"が","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi nơi nghỉ sau đợt tập huấn.', _utf8mb4 0x0a, _utf8mb4'合宿の後でどこか（　）休みに行きますか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"が","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bạn trở về sau kỳ nghỉ xuân.', _utf8mb4 0x0a, _utf8mb4'春休みにはどこ（　）へ旅行しましたか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"を","B":"が","C":"か","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', CONCAT(_utf8mb4'Hỏi lớp đã tính đi đâu vào mùa hè chưa.', _utf8mb4 0x0a, _utf8mb4'夏にクラスでどこか（　）行きますか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"が","B":"の","C":"を","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi người chờ tàu có tranh thủ đi đâu.', _utf8mb4 0x0a, _utf8mb4'駅で待つ間、どこ（　）へ行きましたか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"か","B":"を","C":"で","D":"が"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Sau Tết, hỏi chuyện cả nhà. Hỏi nơi đến.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、祖父の家へ行きました。」'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"正月に家族で何回行きましたか。","B":"正月に家族でだれと行きましたか。","C":"正月に家族でどこかへ行きましたか。","D":"正月に家族で何時に行きましたか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', CONCAT(_utf8mb4'Hỏi về chuyến đi của đội trước trận.', _utf8mb4 0x0a, _utf8mb4'試合の前にチームでどこ（　）へ行きましたか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"が","B":"か","C":"で","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'明日の朝どこかへ写真を撮りに行きますか。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"Hỏi đã đi cùng với ai.","B":"Hỏi đã đi từ địa điểm nào.","C":"Hỏi đã đi vào lúc mấy giờ.","D":"Hỏi sáng mai có đi đâu chụp ảnh hay không."},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi có đưa bà đi xem hoa.', _utf8mb4 0x0a, _utf8mb4'祖母を連れてどこ（　）へ花を見に行きましたか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"が","B":"で","C":"を","D":"か"},"correctAnswer":"D"}'
    UNION ALL SELECT 1003, _utf8mb4'EASY', CONCAT(_utf8mb4'Hỏi về điểm dừng trong chuyến đi.', _utf8mb4 0x0a, _utf8mb4'旅行の途中でどこか（　）寄りましたか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"の","B":"が","C":"を","D":"へ"},"correctAnswer":"D"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi chặng tiếp theo sau khi xuống xe.', _utf8mb4 0x0a, _utf8mb4'バスを降りてからどこ（　）へ行きましたか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"か","B":"が","C":"を","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 1015, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đề nghị tạt qua đâu đó trước khi tới phố. Hỏi nơi đến.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「そうですね。川辺はどうですか。」'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"町に着く前にどこかへ寄りませんか。","B":"町に着く前にだれと寄りませんか。","C":"町に着く前に何時に寄りませんか。","D":"町に着く前に何回寄りませんか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1021, _utf8mb4'EASY', CONCAT(_utf8mb4'Đợi mưa tạnh rồi hỏi dự định.', _utf8mb4 0x0a, _utf8mb4'雨がやんだら、どこ（　）へ出かけますか。'), _utf8mb4'どこ + か tạo từ bất định “một nơi nào đó”; không yêu cầu nêu sẵn đích đến.', _utf8mb4'{"options":{"A":"で","B":"か","C":"が","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại buổi sinh nhật.', _utf8mb4 0x0a, _utf8mb4'誕生日に家族とどこか（　）食事に行きましたか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"を","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi có ghé nơi nào sau lễ hội.', _utf8mb4 0x0a, _utf8mb4'お祭りが終わってから（　）寄りましたか。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"だれと","B":"何時に","C":"どこかへ","D":"何回"},"correctAnswer":"C"}'
    UNION ALL SELECT 1039, _utf8mb4'EASY', CONCAT(_utf8mb4'Hỏi có đủ giờ để ghé một nơi nào đó.', _utf8mb4 0x0a, _utf8mb4'次の電車までに（　）行けますか。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"何回","B":"何時に","C":"どこかへ","D":"だれと"},"correctAnswer":"C"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bạn thấy người kia cầm ô ra cửa.', _utf8mb4 0x0a, _utf8mb4'傘を持って、（　）出かけますか。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"だれと","B":"何回","C":"何時に","D":"どこかへ"},"correctAnswer":"D"}'
    UNION ALL SELECT 2003, _utf8mb4'EASY', CONCAT(_utf8mb4'Con mèo vừa rời vườn.', _utf8mb4 0x0a, _utf8mb4'猫は庭を出てどこか（　）行きましたか。'), _utf8mb4'へ đánh dấu hướng đi sau どこか; câu chưa xác định địa điểm cụ thể.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"が","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 2020, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi kế hoạch đi đâu đó.', _utf8mb4 0x0a, _utf8mb4'今日は仕事が早く終わりそうです。行き先はまだ決めていません。'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"仕事が早く終わったら、何回行きますか。","B":"仕事が早く終わったら、だれと行きますか。","C":"仕事が早く終わったら、どこかへ行きますか。","D":"仕事が早く終わったら、何時に行きますか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2037, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trông thấy bạn lấy xe đạp. Hỏi nơi đến.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、図書館まで行きます。」'), _utf8mb4'どこ + か chỉ nơi chưa xác định; へ chỉ hướng di chuyển.', _utf8mb4'{"options":{"A":"今日は自転車でどこかへ行きますか。","B":"今日は自転車でだれと行きますか。","C":"今日は自転車で何回行きますか。","D":"今日は自転車で何時に行きますか。"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 3 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'どこか（へ）Vます／Vましたか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 4 (Người と Vます／Vました。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Cùng đồng nghiệp đón sinh viên quốc tế.', _utf8mb4 0x0a, _utf8mb4'A「だれと一緒にしましたか。」 B「（　）」') AS content, _utf8mb4'と sau 同僚 đánh dấu người cùng thực hiện hành động đón sinh viên quốc tế.' AS explanation, _utf8mb4'{"options":{"A":"同僚のために一人で留学生を迎えました。","B":"同僚の前で一人で留学生を迎えました。","C":"同僚と一緒に留学生を迎えました。","D":"同僚だけが留学生を迎えました。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Cùng mẹ bán bánh mì tự làm.', _utf8mb4 0x0a, _utf8mb4'母（　）手作りのパンを売りました。'), _utf8mb4'と sau 母 đánh dấu người cùng thực hiện hành động bán bánh mì tự làm.', _utf8mb4'{"options":{"A":"と","B":"へ","C":"を","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng bố tra tên loài hoa.', _utf8mb4 0x0a, _utf8mb4'昨日、（　）花の名前を調べました。'), _utf8mb4'と sau 父 đánh dấu người cùng thực hiện hành động tra tên loài hoa.', _utf8mb4'{"options":{"A":"父より先に","B":"父のために","C":"父に代わって","D":"父と一緒に"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng bạn từ Nhật kiểm tra lịch thi đấu.', _utf8mb4 0x0a, _utf8mb4'休みの日には日本から来た友達（　）試合の予定を確かめました。'), _utf8mb4'と sau 日本から来た友達 đánh dấu người cùng thực hiện hành động kiểm tra lịch thi đấu.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"と","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Cùng đồng nghiệp lắp kệ sách.', _utf8mb4 0x0a, _utf8mb4'同僚（　）本棚を組み立てました。'), _utf8mb4'と sau 同僚 đánh dấu người cùng thực hiện hành động lắp kệ sách.', _utf8mb4'{"options":{"A":"と","B":"を","C":"へ","D":"から"},"correctAnswer":"A"}'
