    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Cùng con trai chơi một bản nhạc piano.', _utf8mb4 0x0a, _utf8mb4'旅行の日には息子（　）ピアノの曲を弾きました。'), _utf8mb4'と sau 息子 đánh dấu người cùng thực hiện hành động chơi một bản nhạc piano.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"を","D":"と"},"correctAnswer":"D"}'
    UNION ALL SELECT 1004, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng đàn anh hái cà chua trong vườn.', _utf8mb4 0x0a, _utf8mb4'A「だれと一緒にしましたか。」 B「（　）」'), _utf8mb4'と sau 先輩 đánh dấu người cùng thực hiện hành động hái cà chua trong vườn.', _utf8mb4'{"options":{"A":"先輩だけが畑のトマトを取りました。","B":"先輩のために一人で畑のトマトを取りました。","C":"先輩の前で一人で畑のトマトを取りました。","D":"先輩と一緒に畑のトマトを取りました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1010, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kể lại có người cùng tìm.', _utf8mb4 0x0a, _utf8mb4'鍵がありません。先生が私と一緒に駐車場を見てくれました。'), _utf8mb4'と sau 先生 đánh dấu người cùng thực hiện hành động tìm chìa khóa ô tô.', _utf8mb4'{"options":{"A":"先生と一緒に車のかぎを探しました。","B":"先生のために一人で車のかぎを探しました。","C":"先生だけが車のかぎを探しました。","D":"先生の前で一人で車のかぎを探しました。"},"correctAnswer":"A"}'
