    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng đàn anh chèo thuyền trên sông.', _utf8mb4 0x0a, _utf8mb4'先輩（　）川でボートをこぎました。'), _utf8mb4'と sau 先輩 đánh dấu người cùng thực hiện hành động chèo thuyền trên sông.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"を","D":"と"},"correctAnswer":"D"}'
    UNION ALL SELECT 1034, _utf8mb4'EASY', CONCAT(_utf8mb4'Cùng thầy đi bộ khám phá phố cổ.', _utf8mb4 0x0a, _utf8mb4'先生（　）古い町を歩きました。'), _utf8mb4'と sau 先生 đánh dấu người cùng thực hiện hành động đi bộ khám phá phố cổ.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"と","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'留学生と一緒に木の高さを測りました。'), _utf8mb4'と sau 留学生 đánh dấu người cùng thực hiện hành động đo chiều cao của cây.', _utf8mb4'{"options":{"A":"Tôi cùng du học sinh đo chiều cao của cây.","B":"Tôi đi trước du học sinh.","C":"Tôi hỏi du học sinh về thời gian.","D":"Chỉ có du học sinh thực hiện việc này."},"correctAnswer":"A"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng người hàng xóm cho thầy xem bài văn.', _utf8mb4 0x0a, _utf8mb4'休みの日には近所の人（　）先生に作文を見せました。'), _utf8mb4'と sau 近所の人 đánh dấu người cùng thực hiện hành động cho thầy xem bài văn.', _utf8mb4'{"options":{"A":"から","B":"と","C":"へ","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 2004, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng em trai nhặt rác ở công viên.', _utf8mb4 0x0a, _utf8mb4'弟（　）公園のごみを拾いました。'), _utf8mb4'と sau 弟 đánh dấu người cùng thực hiện hành động nhặt rác ở công viên.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"と","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 2021, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cùng ông gửi bưu kiện cho bà.', _utf8mb4 0x0a, _utf8mb4'A「だれと一緒にしましたか。」 B「（　）」'), _utf8mb4'と sau 祖父 đánh dấu người cùng thực hiện hành động gửi bưu kiện cho bà.', _utf8mb4'{"options":{"A":"祖父のために一人で祖母に荷物を送りました。","B":"祖父の前で一人で祖母に荷物を送りました。","C":"祖父だけが祖母に荷物を送りました。","D":"祖父と一緒に祖母に荷物を送りました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2038, _utf8mb4'EASY', CONCAT(_utf8mb4'Cùng em gái học nấu món địa phương.', _utf8mb4 0x0a, _utf8mb4'妹（　）二人で地元の料理を習いました。'), _utf8mb4'と sau 妹 đánh dấu người cùng thực hiện hành động học nấu món địa phương.', _utf8mb4'{"options":{"A":"へ","B":"と","C":"から","D":"を"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Người と Vます／Vました。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 5 (S1。それから、S2。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Đầu tiên đeo kính, sau đó đọc chữ nhỏ.', _utf8mb4 0x0a, _utf8mb4'眼鏡をかけました。（　）、小さな字を読みました。') AS content, _utf8mb4'それから đặt trước việc tiếp theo: đọc chữ nhỏ.' AS explanation, _utf8mb4'{"options":{"A":"それなのに","B":"それから","C":"そのかわりに","D":"その前に"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên tập trung trước cổng, sau đó khởi hành cùng thầy.', _utf8mb4 0x0a, _utf8mb4'初めに門の前に集まりました。（　）、先生と出発しました。'), _utf8mb4'それから đặt trước việc tiếp theo: khởi hành cùng thầy.', _utf8mb4'{"options":{"A":"それから","B":"そのかわりに","C":"それなのに","D":"その前に"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kể hai bước theo thứ tự đã ghi.', _utf8mb4 0x0a, _utf8mb4'帰りの確認表：①電気　②戸締まり。'), _utf8mb4'それから đặt trước việc tiếp theo: khóa cửa từ bên ngoài.', _utf8mb4'{"options":{"A":"外から鍵をかけました。それから、部屋の電気を消しました。","B":"部屋の電気を消しました。それから、外から鍵をかけました。","C":"部屋の電気を消しませんでした。外から鍵をかけました。","D":"部屋の電気を消しましたが、外から鍵をかけませんでした。"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên cắt bánh, sau đó chia cho mọi người.', _utf8mb4 0x0a, _utf8mb4'ケーキを切りました。（　）、みんなに配りました。'), _utf8mb4'それから đặt trước việc tiếp theo: chia cho mọi người.', _utf8mb4'{"options":{"A":"それから","B":"そのかわりに","C":"それなのに","D":"その前に"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên dọn lớp, sau đó trả chìa khóa cho phòng giáo viên.', _utf8mb4 0x0a, _utf8mb4'A「その時、何をどんな順番でしましたか。」 B「（　）」'), _utf8mb4'それから đặt trước việc tiếp theo: trả chìa khóa cho phòng giáo viên.', _utf8mb4'{"options":{"A":"教室を片付けましたが、職員室に鍵を返しませんでした。","B":"教室を片付けました。それから、職員室に鍵を返しました。","C":"職員室に鍵を返しました。それから、教室を片付けました。","D":"教室を片付けませんでした。職員室に鍵を返しました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên cởi giày, sau đó vào phòng trải chiếu.', _utf8mb4 0x0a, _utf8mb4'A「一つ目の作業の後は、どうしましたか。」 B「（　）」'), _utf8mb4'それから đặt trước việc tiếp theo: vào phòng trải chiếu.', _utf8mb4'{"options":{"A":"靴を脱ぎませんでした。畳の部屋に入りました。","B":"畳の部屋に入りました。それから、靴を脱ぎました。","C":"靴を脱ぎました。それから、畳の部屋に入りました。","D":"靴を脱ぎましたが、畳の部屋に入りませんでした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên lấy số thứ tự, sau đó ngồi xuống ghế.', _utf8mb4 0x0a, _utf8mb4'番号を取りました。（　）、いすに座りました。'), _utf8mb4'それから đặt trước việc tiếp theo: ngồi xuống ghế.', _utf8mb4'{"options":{"A":"それなのに","B":"その前に","C":"そのかわりに","D":"それから"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên đo nhiệt độ, sau đó gọi điện cho thầy.', _utf8mb4 0x0a, _utf8mb4'初めに熱を測りました。（　）、先生に電話しました。'), _utf8mb4'それから đặt trước việc tiếp theo: gọi điện cho thầy.', _utf8mb4'{"options":{"A":"それから","B":"それなのに","C":"そのかわりに","D":"その前に"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên mở túi giấy, sau đó xếp bánh mới nướng vào.', _utf8mb4 0x0a, _utf8mb4'まず紙袋を開きました。（　）、焼いたパンを詰めました。'), _utf8mb4'それから đặt trước việc tiếp theo: xếp bánh mới nướng vào.', _utf8mb4'{"options":{"A":"それから","B":"それなのに","C":"その前に","D":"そのかわりに"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên mở cửa sổ, sau đó lau sàn nhà.', _utf8mb4 0x0a, _utf8mb4'窓を開けました。（　）、床を掃除しました。'), _utf8mb4'それから đặt trước việc tiếp theo: lau sàn nhà.', _utf8mb4'{"options":{"A":"それなのに","B":"そのかわりに","C":"その前に","D":"それから"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên kiểm tra đặt chỗ, sau đó giao thẻ số.', _utf8mb4 0x0a, _utf8mb4'A「その時、何をどんな順番でしましたか。」 B「（　）」'), _utf8mb4'それから đặt trước việc tiếp theo: giao thẻ số.', _utf8mb4'{"options":{"A":"予約を確認しませんでした。番号札を渡しました。","B":"予約を確認しましたが、番号札を渡しませんでした。","C":"予約を確認しました。それから、番号札を渡しました。","D":"番号札を渡しました。それから、予約を確認しました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn câu nối đúng trình tự.', _utf8mb4 0x0a, _utf8mb4'島には橋がありません。船で着いて、島の道を歩きました。'), _utf8mb4'それから đặt trước việc tiếp theo: đi bộ trên đảo.', _utf8mb4'{"options":{"A":"船を降りませんでした。島を歩きました。","B":"島を歩きました。それから、船を降りました。","C":"船を降りましたが、島を歩きませんでした。","D":"船を降りました。それから、島を歩きました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên gấp tờ giấy trắng, sau đó viết tên lên giấy.', _utf8mb4 0x0a, _utf8mb4'白い紙を折りました。（　）、名前を書きました。'), _utf8mb4'それから đặt trước việc tiếp theo: viết tên lên giấy.', _utf8mb4'{"options":{"A":"それなのに","B":"そのかわりに","C":"その前に","D":"それから"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên chọn ảnh, sau đó gửi ảnh cho gia đình.', _utf8mb4 0x0a, _utf8mb4'初めに写真を選びました。（　）、家族に送りました。'), _utf8mb4'それから đặt trước việc tiếp theo: gửi ảnh cho gia đình.', _utf8mb4'{"options":{"A":"その前に","B":"それなのに","C":"それから","D":"そのかわりに"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên mở hộp, sau đó lấy đĩa bên trong ra.', _utf8mb4 0x0a, _utf8mb4'A「一つ目の作業の後は、どうしましたか。」 B「（　）」'), _utf8mb4'それから đặt trước việc tiếp theo: lấy đĩa bên trong ra.', _utf8mb4'{"options":{"A":"箱を開けませんでした。中の皿を取り出しました。","B":"箱を開けましたが、中の皿を取り出しませんでした。","C":"箱を開けました。それから、中の皿を取り出しました。","D":"中の皿を取り出しました。それから、箱を開けました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên bật nguồn, sau đó kiểm tra âm lượng.', _utf8mb4 0x0a, _utf8mb4'電源を入れました。（　）、音の大きさを調べました。'), _utf8mb4'それから đặt trước việc tiếp theo: kiểm tra âm lượng.', _utf8mb4'{"options":{"A":"そのかわりに","B":"その前に","C":"それから","D":"それなのに"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên dựng lều, sau đó chuẩn bị bữa tối.', _utf8mb4 0x0a, _utf8mb4'初めにテントを立てました。（　）、夕飯の準備をしました。'), _utf8mb4'それから đặt trước việc tiếp theo: chuẩn bị bữa tối.', _utf8mb4'{"options":{"A":"それなのに","B":"それから","C":"その前に","D":"そのかわりに"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'本を閉じました。それから、感想をノートに書きました。'), _utf8mb4'それから đặt trước việc tiếp theo: ghi cảm nghĩ vào vở.', _utf8mb4'{"options":{"A":"Trước hết gấp sách, sau đó ghi cảm nghĩ vào vở.","B":"Thay vì gấp sách, chỉ ghi cảm nghĩ vào vở.","C":"Trước hết ghi cảm nghĩ vào vở, sau đó gấp sách.","D":"Chưa thực hiện việc nào."},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên dừng xe đạp, sau đó bơm lốp xe.', _utf8mb4 0x0a, _utf8mb4'自転車を止めました。（　）、空気を入れました。'), _utf8mb4'それから đặt trước việc tiếp theo: bơm lốp xe.', _utf8mb4'{"options":{"A":"その前に","B":"それから","C":"そのかわりに","D":"それなのに"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên điền đơn, sau đó nộp đơn ở quầy.', _utf8mb4 0x0a, _utf8mb4'初めに申込書を書きました。（　）、窓口に出しました。'), _utf8mb4'それから đặt trước việc tiếp theo: nộp đơn ở quầy.', _utf8mb4'{"options":{"A":"その前に","B":"そのかわりに","C":"それなのに","D":"それから"},"correctAnswer":"D"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên mua phiếu ăn, sau đó đưa phiếu cho nhân viên.', _utf8mb4 0x0a, _utf8mb4'まず食券を買いました。（　）、店員に渡しました。'), _utf8mb4'それから đặt trước việc tiếp theo: đưa phiếu cho nhân viên.', _utf8mb4'{"options":{"A":"それなのに","B":"その前に","C":"それから","D":"そのかわりに"},"correctAnswer":"C"}'
    UNION ALL SELECT 1011, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên thay quần áo, sau đó bắt đầu tập thể dục.', _utf8mb4 0x0a, _utf8mb4'服を着替えました。（　）、体操を始めました。'), _utf8mb4'それから đặt trước việc tiếp theo: bắt đầu tập thể dục.', _utf8mb4'{"options":{"A":"それなのに","B":"それから","C":"そのかわりに","D":"その前に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên đào hố trên đất, sau đó gieo hạt hoa.', _utf8mb4 0x0a, _utf8mb4'初めに土に穴を掘りました。（　）、花の種をまきました。'), _utf8mb4'それから đặt trước việc tiếp theo: gieo hạt hoa.', _utf8mb4'{"options":{"A":"それなのに","B":"その前に","C":"そのかわりに","D":"それから"},"correctAnswer":"D"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên dán tem, sau đó bỏ thư vào hòm.', _utf8mb4 0x0a, _utf8mb4'まず切手を貼りました。（　）、手紙をポストに入れました。'), _utf8mb4'それから đặt trước việc tiếp theo: bỏ thư vào hòm.', _utf8mb4'{"options":{"A":"その前に","B":"そのかわりに","C":"それなのに","D":"それから"},"correctAnswer":"D"}'
    UNION ALL SELECT 1029, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên tìm điểm lên xe, sau đó xếp hàng chờ xe buýt.', _utf8mb4 0x0a, _utf8mb4'乗り場を調べました。（　）、バスの列に並びました。'), _utf8mb4'それから đặt trước việc tiếp theo: xếp hàng chờ xe buýt.', _utf8mb4'{"options":{"A":"それなのに","B":"その前に","C":"それから","D":"そのかわりに"},"correctAnswer":"C"}'
    UNION ALL SELECT 1035, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên chuyển nhạc cụ, sau đó xếp lên sân khấu.', _utf8mb4 0x0a, _utf8mb4'初めに楽器を運びました。（　）、舞台に並べました。'), _utf8mb4'それから đặt trước việc tiếp theo: xếp lên sân khấu.', _utf8mb4'{"options":{"A":"それから","B":"そのかわりに","C":"それなのに","D":"その前に"},"correctAnswer":"A"}'
    UNION ALL SELECT 1041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên rửa rau, sau đó thái nhỏ rau.', _utf8mb4 0x0a, _utf8mb4'まず野菜を洗いました。（　）、小さく切りました。'), _utf8mb4'それから đặt trước việc tiếp theo: thái nhỏ rau.', _utf8mb4'{"options":{"A":"その前に","B":"それから","C":"そのかわりに","D":"それなのに"},"correctAnswer":"B"}'
    UNION ALL SELECT 1047, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên cân nguyên liệu, sau đó làm bột bánh.', _utf8mb4 0x0a, _utf8mb4'材料を量りました。（　）、生地を作りました。'), _utf8mb4'それから đặt trước việc tiếp theo: làm bột bánh.', _utf8mb4'{"options":{"A":"それから","B":"それなのに","C":"その前に","D":"そのかわりに"},"correctAnswer":"A"}'
    UNION ALL SELECT 2005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kể tiếp bước sau.', _utf8mb4 0x0a, _utf8mb4'道順を調べるには、まず折りたたんだ地図を開きます。'), _utf8mb4'それから đặt trước việc tiếp theo: xem đường ra sông.', _utf8mb4'{"options":{"A":"地図を広げませんでした。川までの道を確かめました。","B":"川までの道を確かめました。それから、地図を広げました。","C":"地図を広げましたが、川までの道を確かめませんでした。","D":"地図を広げました。それから、川までの道を確かめました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2022, _utf8mb4'EASY', CONCAT(_utf8mb4'Đầu tiên đập trứng, sau đó đánh đều trứng.', _utf8mb4 0x0a, _utf8mb4'まず卵を割りました。（　）、よく混ぜました。'), _utf8mb4'それから đặt trước việc tiếp theo: đánh đều trứng.', _utf8mb4'{"options":{"A":"それから","B":"それなのに","C":"その前に","D":"そのかわりに"},"correctAnswer":"A"}'
    UNION ALL SELECT 2039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đầu tiên tìm ví, sau đó gọi điện cho cửa hàng.', _utf8mb4 0x0a, _utf8mb4'A「最初から順番に教えてください。」 B「（　）」'), _utf8mb4'それから đặt trước việc tiếp theo: gọi điện cho cửa hàng.', _utf8mb4'{"options":{"A":"財布を探しませんでした。店に電話しました。","B":"財布を探しました。それから、店に電話しました。","C":"財布を探しましたが、店に電話しませんでした。","D":"店に電話しました。それから、財布を探しました。"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S1。それから、S2。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 6 (Aい → Aかったです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Ớt trong súp làm tôi cay xé miệng.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。注文したスープは（　）。') AS content, _utf8mb4'Bỏ い cuối 辛い rồi thêm かったです để nói về quá khứ.' AS explanation, _utf8mb4'{"options":{"A":"辛いです","B":"辛かったです","C":"辛くなかったです","D":"辛いでした"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cả đợt tập huấn tôi vui đến mức không muốn về.', _utf8mb4 0x0a, _utf8mb4'A「夏の合宿はどうでしたか。」 B「（　）」'), _utf8mb4'Bỏ い cuối 楽しい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"夏の合宿は楽しいです。","B":"夏の合宿は楽しくなかったです。","C":"夏の合宿は楽しくないです。","D":"夏の合宿は楽しかったです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi rất hài lòng với căn phòng đã thuê.', _utf8mb4 0x0a, _utf8mb4'借りた部屋は（　）。'), _utf8mb4'Quá khứ của いい dùng gốc よ: よかったです。', _utf8mb4'{"options":{"A":"よくなかったです","B":"いいでした","C":"いいです","D":"よかったです"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Món cá nướng ngon đến mức ai cũng xin thêm.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。焼いた魚は（　）。'), _utf8mb4'Bỏ い cuối おいしい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"おいしいです","B":"おいしくなかったです","C":"おいしいでした","D":"おいしかったです"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi vất vả mới thuyết trình xong.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、初めての発表は（　）。'), _utf8mb4'Bỏ い cuối 難しい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"難しくなかったです","B":"難しいです","C":"難しかったです","D":"難しいでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', CONCAT(_utf8mb4'Giày lúc đó vừa khui hộp.', _utf8mb4 0x0a, _utf8mb4'買ったばかりの靴は（　）。'), _utf8mb4'Bỏ い cuối 新しい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"新しかったです","B":"新しいです","C":"新しいでした","D":"新しくなかったです"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói chỉ giải thích trong hai câu.', _utf8mb4 0x0a, _utf8mb4'A「最初の説明はどうでしたか。」 B「（　）」'), _utf8mb4'Bỏ い cuối 短い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"最初の説明は短かったです。","B":"最初の説明は短いです。","C":"最初の説明は短くないです。","D":"最初の説明は短くなかったです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bức ảnh năm ngoái có rất nhiều ánh sáng.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、去年の写真は（　）。'), _utf8mb4'Bỏ い cuối 明るい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"明るくなかったです","B":"明るかったです","C":"明るいでした","D":"明るいです"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', CONCAT(_utf8mb4'Bộ phim cuốn hút khiến tôi xem liền một mạch.', _utf8mb4 0x0a, _utf8mb4'昨日の映画は（　）。'), _utf8mb4'Bỏ い cuối 面白い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"面白いでした","B":"面白いです","C":"面白くなかったです","D":"面白かったです"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dùng tính từ い kể lại đặc điểm.', _utf8mb4 0x0a, _utf8mb4'切符を目に近づけて、やっと字が読めました。'), _utf8mb4'Bỏ い cuối 小さい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"入場券の字は小さくなかったです。","B":"入場券の字は小さくないです。","C":"入場券の字は小さいです。","D":"入場券の字は小さかったです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lúc chia tay ở cuối chuyến đi, tôi thấy trống trải.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、旅行の最終日は（　）。'), _utf8mb4'Bỏ い cuối 寂しい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"寂しくなかったです","B":"寂しかったです","C":"寂しいです","D":"寂しいでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', CONCAT(_utf8mb4'Sảnh sân bay đủ chỗ cho nhiều đoàn.', _utf8mb4 0x0a, _utf8mb4'朝の空港は（　）。'), _utf8mb4'Bỏ い cuối 広い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"広いでした","B":"広かったです","C":"広いです","D":"広くなかったです"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dấu tích nhiều năm thể hiện rõ trên ngôi nhà.', _utf8mb4 0x0a, _utf8mb4'A「昔の家はどうでしたか。」 B「（　）」'), _utf8mb4'Bỏ い cuối 古い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"昔の家は古かったです。","B":"昔の家は古いです。","C":"昔の家は古くないです。","D":"昔の家は古くなかったです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhấc xe lên vai hầu như chẳng tốn sức.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、借りた自転車は（　）。'), _utf8mb4'Bỏ い cuối 軽い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"軽いでした","B":"軽くなかったです","C":"軽かったです","D":"軽いです"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', CONCAT(_utf8mb4'Khăn phơi lúc ấy trắng như giấy.', _utf8mb4 0x0a, _utf8mb4'干したタオルは（　）。'), _utf8mb4'Bỏ い cuối 白い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"白くなかったです","B":"白いでした","C":"白かったです","D":"白いです"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai xe không tránh được nhau trên con đường ấy.', _utf8mb4 0x0a, _utf8mb4'A「昼の道はどうでしたか。」 B「（　）」'), _utf8mb4'Bỏ い cuối 狭い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"昼の道は狭かったです。","B":"昼の道は狭くなかったです。","C":"昼の道は狭くないです。","D":"昼の道は狭いです。"},"correctAnswer":"A"}'
