    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhớ lại cảm xúc ngày nhận thư.', _utf8mb4 0x0a, _utf8mb4'友達から手紙が来た日、笑顔で家族に見せました。'), _utf8mb4'Bỏ い cuối うれしい rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"届いた手紙はうれしいです。","B":"届いた手紙はうれしかったです。","C":"届いた手紙はうれしくなかったです。","D":"届いた手紙はうれしくないです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1042, _utf8mb4'EASY', CONCAT(_utf8mb4'Cát làm bỏng chân nên chúng tôi chạy ngay vào bóng râm.', _utf8mb4 0x0a, _utf8mb4'昼の砂浜は（　）。'), _utf8mb4'Bỏ い cuối 熱い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"熱いでした","B":"熱いです","C":"熱くなかったです","D":"熱かったです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tiền trọ chỉ bằng nửa mức thường thấy.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。駅前の宿は（　）。'), _utf8mb4'Bỏ い cuối 安い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"安いです","B":"安いでした","C":"安かったです","D":"安くなかったです"},"correctAnswer":"C"}'
