    UNION ALL SELECT 2023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mứt ngọt đậm vì bà dùng nhiều đường.', _utf8mb4 0x0a, _utf8mb4'祖母のジャムは（　）。'), _utf8mb4'Bỏ い cuối 甘い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"甘くなかったです","B":"甘いでした","C":"甘いです","D":"甘かったです"},"correctAnswer":"D"}'
    UNION ALL SELECT 2040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tàu cũ mất cả buổi mới tới ga kế tiếp.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。昔の電車は（　）。'), _utf8mb4'Bỏ い cuối 遅い rồi thêm かったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"遅くなかったです","B":"遅いです","C":"遅かったです","D":"遅いでした"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 6 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aい → Aかったです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 7 (Aい → Aくなかったです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Hai xe tải tránh nhau thoải mái trên đường.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。昼の道は（　）。') AS content, _utf8mb4'Bỏ い cuối 狭い rồi thêm くなかったです để nói về quá khứ.' AS explanation, _utf8mb4'{"options":{"A":"狭いでした","B":"狭いです","C":"狭くなかったです","D":"狭かったです"},"correctAnswer":"C"}' AS answers
