    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Vài bước đã hết dốc.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。昨日の坂道は（　）。'), _utf8mb4'Bỏ い cuối 長い rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"長いでした","B":"長いです","C":"長くなかったです","D":"長かったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Sáng ấy trên núi chỉ cần mặc áo mỏng.', _utf8mb4 0x0a, _utf8mb4'山の朝は（　）。'), _utf8mb4'Bỏ い cuối 寒い rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"寒いです","B":"寒いでした","C":"寒くなかったです","D":"寒かったです"},"correctAnswer":"C"}'
