    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Khu vườn hôm xuân ấy vẫn rét buốt.', _utf8mb4 0x0a, _utf8mb4'A「春の庭はどうでしたか。」 B「（　）」'), _utf8mb4'Bỏ い cuối 暖かい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"春の庭は暖かかったです。","B":"春の庭は暖かくないです。","C":"春の庭は暖かいです。","D":"春の庭は暖かくなかったです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Phủ nhận vị cay ở quá khứ.', _utf8mb4 0x0a, _utf8mb4'昨日のスープは唐辛子なし。子どもも平気でした。'), _utf8mb4'Bỏ い cuối 辛い rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"注文したスープは辛かったです。","B":"注文したスープは辛いです。","C":"注文したスープは辛くなかったです。","D":"注文したスープは辛くないです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1013, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi không có một ngày vui trong đợt tập huấn.', _utf8mb4 0x0a, _utf8mb4'夏の合宿は（　）。'), _utf8mb4'Bỏ い cuối 楽しい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"楽しいです","B":"楽しくなかったです","C":"楽しかったです","D":"楽しいでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đánh giá phủ định về lần thuê.', _utf8mb4 0x0a, _utf8mb4'部屋の写真はすてき。でも泊まった日は水も電気も使えませんでした。'), _utf8mb4'Quá khứ của いい dùng gốc よ: よくなかったです。', _utf8mb4'{"options":{"A":"借りた部屋はよくないです。","B":"借りた部屋はいいです。","C":"借りた部屋はよかったです。","D":"借りた部屋はよくなかったです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Món cá nướng cháy khét và rất khó ăn.', _utf8mb4 0x0a, _utf8mb4'今と昔を比べましょう。焼いた魚は（　）。'), _utf8mb4'Bỏ い cuối おいしい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"おいしくなかったです","B":"おいしかったです","C":"おいしいでした","D":"おいしいです"},"correctAnswer":"A"}'
    UNION ALL SELECT 1031, _utf8mb4'EASY', CONCAT(_utf8mb4'Buổi thuyết trình dễ hơn hẳn dự tính.', _utf8mb4 0x0a, _utf8mb4'初めての発表は（　）。'), _utf8mb4'Bỏ い cuối 難しい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"難しかったです","B":"難しいでした","C":"難しくなかったです","D":"難しいです"},"correctAnswer":"C"}'
    UNION ALL SELECT 1037, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Giày mua lại đã được đi nhiều lần.', _utf8mb4 0x0a, _utf8mb4'買ったばかりの靴は（　）。'), _utf8mb4'Bỏ い cuối 新しい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"新しかったです","B":"新しいです","C":"新しいでした","D":"新しくなかったです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn ý đúng với lời nói.', _utf8mb4 0x0a, _utf8mb4'最初の説明は短くなかったです。'), _utf8mb4'Bỏ い cuối 短い rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"Lời giải thích ban đầu khi đó không ngắn.","B":"Người nói hỏi cảm nhận của đối phương.","C":"Hiện giờ: lời giải thích ban đầu ngắn.","D":"Lời giải thích ban đầu khi đó ngắn."},"correctAnswer":"A"}'
    UNION ALL SELECT 1049, _utf8mb4'EASY', CONCAT(_utf8mb4'Bức ảnh tối đến mức khó nhận ra mặt.', _utf8mb4 0x0a, _utf8mb4'去年の写真は（　）。'), _utf8mb4'Bỏ い cuối 明るい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"明るかったです","B":"明るくなかったです","C":"明るいでした","D":"明るいです"},"correctAnswer":"B"}'
    UNION ALL SELECT 2007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bộ phim tẻ nhạt, tôi bỏ về giữa chừng.', _utf8mb4 0x0a, _utf8mb4'昨日の映画は（　）。'), _utf8mb4'Bỏ い cuối 面白い rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"面白いでした","B":"面白かったです","C":"面白くなかったです","D":"面白いです"},"correctAnswer":"C"}'
    UNION ALL SELECT 2024, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Vé in chữ to nên nhìn thấy từ xa.', _utf8mb4 0x0a, _utf8mb4'A「入場券の字はどうでしたか。」 B「（　）」'), _utf8mb4'Bỏ い cuối 小さい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"入場券の字は小さくないです。","B":"入場券の字は小さくなかったです。","C":"入場券の字は小さいです。","D":"入場券の字は小さかったです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2041, _utf8mb4'EASY', CONCAT(_utf8mb4'Ngày cuối chuyến tôi vẫn vui vì sắp về nhà.', _utf8mb4 0x0a, _utf8mb4'旅行の最終日は（　）。'), _utf8mb4'Bỏ い cuối 寂しい rồi thêm くなかったです để nói về quá khứ.', _utf8mb4'{"options":{"A":"寂しくなかったです","B":"寂しいです","C":"寂しかったです","D":"寂しいでした"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aい → Aくなかったです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 8 (Aな → Aでした。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Nếu thiếu buổi đầu thì không thể theo kịp khóa tập.', _utf8mb4 0x0a, _utf8mb4'最初の練習は（　）。') AS content, _utf8mb4'Tính từ な「必要」 đứng trước でした khi khẳng định quá khứ.' AS explanation, _utf8mb4'{"options":{"A":"必要でした","B":"必要じゃありませんでした","C":"必要かったです","D":"必要です"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ngày nhập học tôi mặc bộ đồ đơn giản, kín đáo.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、入学式の服は（　）。'), _utf8mb4'Tính từ な「地味」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"地味じゃありませんでした","B":"地味でした","C":"地味かったです","D":"地味です"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kết quả lần trước khiến tôi thấy đáng tiếc.', _utf8mb4 0x0a, _utf8mb4'先日の結果は（　）。'), _utf8mb4'Tính từ な「残念」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"残念です","B":"残念でした","C":"残念かったです","D":"残念じゃありませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Lễ tân kiên nhẫn dẫn tôi tới tận cửa.', _utf8mb4 0x0a, _utf8mb4'受付の人は（　）。'), _utf8mb4'Tính từ な「親切」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"親切でした","B":"親切かったです","C":"親切じゃありませんでした","D":"親切です"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mô tả danh tiếng khi ấy.', _utf8mb4 0x0a, _utf8mb4'昔は、国中の人がこの港の名前を知っていました。'), _utf8mb4'Tính từ な「有名」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"昔の港は有名でした。","B":"昔の港は有名です。","C":"昔の港は有名じゃありません。","D":"昔の港は有名じゃありませんでした。"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Túi cũ dùng suốt mười năm vẫn chắc.', _utf8mb4 0x0a, _utf8mb4'昔のかばんは（　）。'), _utf8mb4'Tính từ な「丈夫」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"丈夫じゃありませんでした","B":"丈夫です","C":"丈夫かったです","D":"丈夫でした"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Cách đăng ký lần đó gồm quá nhiều bước rắc rối.', _utf8mb4 0x0a, _utf8mb4'受付の方法は（　）。'), _utf8mb4'Tính từ な「複雑」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"複雑じゃありませんでした","B":"複雑です","C":"複雑でした","D":"複雑かったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hồi nhỏ cứ thấy thuốc là tôi quay đi vì ghét.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、子どものころは薬が（　）。'), _utf8mb4'Tính từ な「嫌い」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"嫌いじゃありませんでした","B":"嫌いでした","C":"嫌いかったです","D":"嫌いです"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bộ đồ hôm qua sặc sỡ và thu hút mọi ánh nhìn.', _utf8mb4 0x0a, _utf8mb4'A「昨日の服装はどうでしたか。」 B「（　）」'), _utf8mb4'Tính từ な「派手」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"昨日の服装は派手です。","B":"昨日の服装は派手じゃありません。","C":"昨日の服装は派手じゃありませんでした。","D":"昨日の服装は派手でした。"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'Với số tiền lúc đó chúng tôi không thể thực hiện kế hoạch.', _utf8mb4 0x0a, _utf8mb4'前の計画は（　）。'), _utf8mb4'Tính từ な「無理」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"無理じゃありませんでした","B":"無理です","C":"無理でした","D":"無理かったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bố hồi đó khỏe, ngày nào cũng đi bộ xa.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、昔の父は（　）。'), _utf8mb4'Tính từ な「元気」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"元気でした","B":"元気かったです","C":"元気じゃありませんでした","D":"元気です"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đánh giá sự tiện lợi trong quá khứ.', _utf8mb4 0x0a, _utf8mb4'当時は地下鉄でどこへでも乗り換えなしで行けました。'), _utf8mb4'Tính từ な「便利」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"当時の地下鉄は便利です。","B":"当時の地下鉄は便利じゃありませんでした。","C":"当時の地下鉄は便利でした。","D":"当時の地下鉄は便利じゃありません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', CONCAT(_utf8mb4'Tòa nhà lúc ấy bề thế, khách đến ai cũng trầm trồ.', _utf8mb4 0x0a, _utf8mb4'二年前の建物は（　）。'), _utf8mb4'Tính từ な「立派」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"立派じゃありませんでした","B":"立派でした","C":"立派かったです","D":"立派です"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'先週の午後は暇でした。'), _utf8mb4'Tính từ な「暇」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"Người nói hỏi cảm nhận của đối phương.","B":"Hiện giờ: buổi chiều tuần trước rảnh.","C":"Buổi chiều tuần trước khi đó không rảnh.","D":"Buổi chiều tuần trước khi đó rảnh."},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hồi trước tôi thích đọc sách, tối nào cũng đọc.', _utf8mb4 0x0a, _utf8mb4'A「昔は読書がどうでしたか。」 B「（　）」'), _utf8mb4'Tính từ な「好き」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"昔は読書が好きじゃありません。","B":"昔は読書が好きです。","C":"昔は読書が好きじゃありませんでした。","D":"昔は読書が好きでした。"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', CONCAT(_utf8mb4'Buổi diễn tháng trước thật đặc biệt, chỉ tổ chức một lần.', _utf8mb4 0x0a, _utf8mb4'先月の舞台は（　）。'), _utf8mb4'Tính từ な「特別」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"特別です","B":"特別かったです","C":"特別じゃありませんでした","D":"特別でした"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Con vật hôm ấy hiền, để khách vuốt ve.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、あの店の動物は（　）。'), _utf8mb4'Tính từ な「おとなしい」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"おとなしいです","B":"おとなしいじゃありませんでした","C":"おとなしいでした","D":"おとなしいかったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'祭りの通りはにぎやかでした。'), _utf8mb4'Tính từ な「にぎやか」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"Con phố ngày hội khi đó náo nhiệt.","B":"Người nói hỏi cảm nhận của đối phương.","C":"Con phố ngày hội khi đó không náo nhiệt.","D":"Hiện giờ: con phố ngày hội náo nhiệt."},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Từ nhà cũ ra ga phải đổi ba tuyến xe.', _utf8mb4 0x0a, _utf8mb4'前の住所は（　）。'), _utf8mb4'Tính từ な「不便」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"不便です","B":"不便かったです","C":"不便でした","D":"不便じゃありませんでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lời giải thích hôm qua cặn kẽ từng bước.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、昨日の説明は（　）。'), _utf8mb4'Tính từ な「丁寧」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"丁寧じゃありませんでした","B":"丁寧でした","C":"丁寧かったです","D":"丁寧です"},"correctAnswer":"B"}'
    UNION ALL SELECT 1002, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ca sĩ thời ấy có phong cách rất riêng.', _utf8mb4 0x0a, _utf8mb4'A「当時の歌手はどうでしたか。」 B「（　）」'), _utf8mb4'Tính từ な「個性的」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"当時の歌手は個性的でした。","B":"当時の歌手は個性的です。","C":"当時の歌手は個性的じゃありませんでした。","D":"当時の歌手は個性的じゃありません。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1008, _utf8mb4'EASY', CONCAT(_utf8mb4'Ngồi chỗ lần trước tôi thấy rất thoải mái.', _utf8mb4 0x0a, _utf8mb4'前の席は（　）。'), _utf8mb4'Tính từ な「楽」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"楽じゃありませんでした","B":"楽です","C":"楽でした","D":"楽かったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 1014, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cá mua sáng nay còn rất tươi.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、今朝の魚は（　）。'), _utf8mb4'Tính từ な「新鮮」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"新鮮かったです","B":"新鮮じゃありませんでした","C":"新鮮でした","D":"新鮮です"},"correctAnswer":"C"}'
    UNION ALL SELECT 1020, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trước ngày ra viện tôi lo vì phải tự chăm sóc.', _utf8mb4 0x0a, _utf8mb4'退院の日は（　）。'), _utf8mb4'Tính từ な「心配」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"心配です","B":"心配かったです","C":"心配じゃありませんでした","D":"心配でした"},"correctAnswer":"D"}'
    UNION ALL SELECT 1026, _utf8mb4'EASY', CONCAT(_utf8mb4'Tối đó bảo tàng yên ắng, chỉ nghe tiếng bước chân.', _utf8mb4 0x0a, _utf8mb4'夜の美術館は（　）。'), _utf8mb4'Tính từ な「静か」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"静かです","B":"静かかったです","C":"静かじゃありませんでした","D":"静かでした"},"correctAnswer":"D"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tả độ khó ở quá khứ.', _utf8mb4 0x0a, _utf8mb4'昨日の試験では、最後の問題に全員がすぐ答えました。'), _utf8mb4'Tính từ な「簡単」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"試験の最後の問題は簡単です。","B":"試験の最後の問題は簡単でした。","C":"試験の最後の問題は簡単じゃありません。","D":"試験の最後の問題は簡単じゃありませんでした。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cầu khi đó vững chắc và có lan can hai bên.', _utf8mb4 0x0a, _utf8mb4'A「川の橋はどうでしたか。」 B「（　）」'), _utf8mb4'Tính từ な「安全」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"川の橋は安全でした。","B":"川の橋は安全じゃありませんでした。","C":"川の橋は安全じゃありません。","D":"川の橋は安全です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1044, _utf8mb4'EASY', CONCAT(_utf8mb4'Ngày đầu chuyến đi thật vất vả vì mưa bão.', _utf8mb4 0x0a, _utf8mb4'旅の初日は（　）。'), _utf8mb4'Tính từ な「大変」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"大変です","B":"大変でした","C":"大変かったです","D":"大変じゃありませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 1050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thời sinh viên ca hát là điểm yếu của tôi.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、学生のころは歌が（　）。'), _utf8mb4'Tính từ な「苦手」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"苦手です","B":"苦手じゃありませんでした","C":"苦手かったです","D":"苦手でした"},"correctAnswer":"D"}'
    UNION ALL SELECT 2008, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Giờ nghỉ hôm đó ai cũng được tự chọn hoạt động.', _utf8mb4 0x0a, _utf8mb4'A「休み時間はどうでしたか。」 B「（　）」'), _utf8mb4'Tính từ な「自由」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"休み時間は自由じゃありませんでした。","B":"休み時間は自由じゃありません。","C":"休み時間は自由でした。","D":"休み時間は自由です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2025, _utf8mb4'EASY', CONCAT(_utf8mb4'Khi ấy bữa ăn chỉ có cơm và một món rau.', _utf8mb4 0x0a, _utf8mb4'当時の食事は（　）。'), _utf8mb4'Tính từ な「質素」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"質素じゃありませんでした","B":"質素でした","C":"質素です","D":"質素かったです"},"correctAnswer":"B"}'
    UNION ALL SELECT 2042, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thứ ánh sáng kỳ lạ hôm đó khiến ai cũng ngạc nhiên.', _utf8mb4 0x0a, _utf8mb4'当時を思い出すと、あの日の光は（　）。'), _utf8mb4'Tính từ な「不思議」 đứng trước でした khi khẳng định quá khứ.', _utf8mb4'{"options":{"A":"不思議でした","B":"不思議じゃありませんでした","C":"不思議かったです","D":"不思議です"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aな → Aでした。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 9 (Aな → Aじゃありませんでした。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'先月の舞台は特別じゃありませんでした。') AS content, _utf8mb4'Tính từ な「特別」 đứng trước じゃありませんでした khi phủ định quá khứ.' AS explanation, _utf8mb4'{"options":{"A":"Hiện giờ: sân khấu tháng trước đặc biệt.","B":"Người nói hỏi cảm nhận của đối phương.","C":"Sân khấu tháng trước khi đó không đặc biệt.","D":"Sân khấu tháng trước khi đó đặc biệt."},"correctAnswer":"C"}' AS answers
