    UNION ALL SELECT 2009, _utf8mb4'EASY', CONCAT(_utf8mb4'Thuở nhỏ tôi uống thuốc bình thường, không ghét.', _utf8mb4 0x0a, _utf8mb4'子どものころは薬が（　）。'), _utf8mb4'Tính từ な「嫌い」 đứng trước じゃありませんでした khi phủ định quá khứ.', _utf8mb4'{"options":{"A":"嫌いでした","B":"嫌いです","C":"嫌いじゃありませんでした","D":"嫌いかったです"},"correctAnswer":"C"}'
    UNION ALL SELECT 2026, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hôm qua tôi mặc đồ tối màu, rất giản dị.', _utf8mb4 0x0a, _utf8mb4'昨日の服装は（　）。'), _utf8mb4'Tính từ な「派手」 đứng trước じゃありませんでした khi phủ định quá khứ.', _utf8mb4'{"options":{"A":"派手じゃありませんでした","B":"派手でした","C":"派手かったです","D":"派手です"},"correctAnswer":"A"}'
    UNION ALL SELECT 2043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bác bỏ nhận định “bất khả thi” lúc đó.', _utf8mb4 0x0a, _utf8mb4'前の計画はお金も時間も足りて、実行できました。'), _utf8mb4'Tính từ な「無理」 đứng trước じゃありませんでした khi phủ định quá khứ.', _utf8mb4'{"options":{"A":"前の計画は無理でした。","B":"前の計画は無理です。","C":"前の計画は無理じゃありません。","D":"前の計画は無理じゃありませんでした。"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 9 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Aな → Aじゃありませんでした。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 10 (Nでした／Nじゃありませんでした。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Người đại diện năm đó là đàn anh của tôi.', _utf8mb4 0x0a, _utf8mb4'A「あの年の代表について覚えていますか。」 B「（　）」') AS content, _utf8mb4'Sau danh từ 私の先輩, でした xác nhận một sự thật trong quá khứ.' AS explanation, _utf8mb4'{"options":{"A":"あの年の代表は私の先輩ですか。","B":"あの年の代表は私の先輩じゃありませんでした。","C":"あの年の代表は私の先輩でしょうか。","D":"あの年の代表は私の先輩でした。"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Thông báo hôm trước không phải việc đổi lịch.', _utf8mb4 0x0a, _utf8mb4'先日の連絡は日程の変更（　）。'), _utf8mb4'Sau danh từ 日程の変更, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"ですか","B":"でした","C":"じゃありませんでした","D":"でしょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người trực buổi sáng là tôi.', _utf8mb4 0x0a, _utf8mb4'朝の当番は私（　）。'), _utf8mb4'Sau danh từ 私, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でしょうか","B":"でした","C":"じゃありませんでした","D":"ですか"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tòa nhà trước bệnh viện khi ấy không phải hiệu sách.', _utf8mb4 0x0a, _utf8mb4'病院の前の建物は本屋（　）。'), _utf8mb4'Sau danh từ 本屋, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でした","B":"でしょうか","C":"ですか","D":"じゃありませんでした"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Buổi khám lần trước là buổi sáng.', _utf8mb4 0x0a, _utf8mb4'この前の診察（　）午前中でした。'), _utf8mb4'は nêu chủ đề この前の診察; phần sau cho biết đó từng là gì.', _utf8mb4'{"options":{"A":"は","B":"で","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cơm hộp ngày đó không phải cơm nắm.', _utf8mb4 0x0a, _utf8mb4'その日の弁当はおにぎり（　）。'), _utf8mb4'Sau danh từ おにぎり, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"ですか","B":"じゃありませんでした","C":"でしょうか","D":"でした"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'昔の校舎は木の建物でした。'), _utf8mb4'Sau danh từ 木の建物, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"Người nói hỏi lại để xác nhận.","B":"Trường học ngày xưa không phải tòa nhà bằng gỗ.","C":"Trường học ngày xưa là tòa nhà bằng gỗ.","D":"Đây là dự đoán cho năm sau."},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhân vật chính trong truyện vừa kể không phải chú chó nhỏ.', _utf8mb4 0x0a, _utf8mb4'その話の主人公は小さな犬（　）。'), _utf8mb4'Sau danh từ 小さな犬, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"ですか","B":"でした","C":"でしょうか","D":"じゃありませんでした"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nơi đây mười năm trước là quảng trường ga.', _utf8mb4 0x0a, _utf8mb4'十年前のここは駅の広場（　）。'), _utf8mb4'Sau danh từ 駅の広場, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"じゃありませんでした","B":"でしょうか","C":"でした","D":"ですか"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đính chính địa điểm cũ.', _utf8mb4 0x0a, _utf8mb4'写真の会場は学生食堂でしょうか。記録には市民ホールとあります。'), _utf8mb4'Sau danh từ 学生食堂, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"パーティーの会場は学生食堂じゃありませんでした。","B":"パーティーの会場は学生食堂でした。","C":"パーティーの会場は学生食堂でしょうか。","D":"パーティーの会場は学生食堂ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Hạn nộp tài liệu khi đó là thứ sáu.', _utf8mb4 0x0a, _utf8mb4'資料の提出日（　）金曜日でした。'), _utf8mb4'は nêu chủ đề 資料の提出日; phần sau cho biết đó từng là gì.', _utf8mb4'{"options":{"A":"を","B":"は","C":"で","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tờ giấy trong ngăn kéo hôm ấy không phải vé tàu.', _utf8mb4 0x0a, _utf8mb4'引き出しの中の紙は乗車券（　）。'), _utf8mb4'Sau danh từ 乗車券, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でしょうか","B":"ですか","C":"でした","D":"じゃありませんでした"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Điểm đến đầu tiên là ngôi làng trên núi.', _utf8mb4 0x0a, _utf8mb4'最初の目的地は山の村（　）。'), _utf8mb4'Sau danh từ 山の村, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でした","B":"じゃありませんでした","C":"でしょうか","D":"ですか"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Tiền thuê nhà tháng trước không phải 50.000 yên.', _utf8mb4 0x0a, _utf8mb4'先月の家賃は五万円（　）。'), _utf8mb4'Sau danh từ 五万円, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"じゃありませんでした","B":"でした","C":"ですか","D":"でしょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu hỏi đầu tiên trong bài thi là cách đọc chữ Hán.', _utf8mb4 0x0a, _utf8mb4'A「初めの問題について覚えていますか。」 B「（　）」'), _utf8mb4'Sau danh từ 漢字の読み方, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"初めの問題は漢字の読み方でしょうか。","B":"初めの問題は漢字の読み方ですか。","C":"初めの問題は漢字の読み方でした。","D":"初めの問題は漢字の読み方じゃありませんでした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Phủ nhận bằng danh từ ở quá khứ.', _utf8mb4 0x0a, _utf8mb4'一回目にもらった物はボール。絵本は二回目でした。'), _utf8mb4'Sau danh từ 絵本, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"一回目の賞品は絵本ですか。","B":"一回目の賞品は絵本でしょうか。","C":"一回目の賞品は絵本でした。","D":"一回目の賞品は絵本じゃありませんでした。"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Ngày đầu chuyến du lịch là ngày mưa.', _utf8mb4 0x0a, _utf8mb4'旅行の初日は雨（　）。'), _utf8mb4'Sau danh từ 雨, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でした","B":"ですか","C":"じゃありませんでした","D":"でしょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Giờ tập trung hôm ấy không phải tám giờ rưỡi.', _utf8mb4 0x0a, _utf8mb4'A「集合の時刻について覚えていますか。」 B「（　）」'), _utf8mb4'Sau danh từ 八時半, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"集合の時刻は八時半でした。","B":"集合の時刻は八時半じゃありませんでした。","C":"集合の時刻は八時半でしょうか。","D":"集合の時刻は八時半ですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ước mơ thuở nhỏ là trở thành họa sĩ.', _utf8mb4 0x0a, _utf8mb4'子どものころの夢（　）画家になることでした。'), _utf8mb4'は nêu chủ đề 子どものころの夢; phần sau cho biết đó từng là gì.', _utf8mb4'{"options":{"A":"を","B":"は","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Phòng chờ trước đây không phải chỗ này.', _utf8mb4 0x0a, _utf8mb4'昔の待合室はここ（　）。'), _utf8mb4'Sau danh từ ここ, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でした","B":"でしょうか","C":"じゃありませんでした","D":"ですか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1004, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kết quả cuộc thi khi đó là hạng nhì.', _utf8mb4 0x0a, _utf8mb4'大会の結果は二位（　）。'), _utf8mb4'Sau danh từ 二位, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でしょうか","B":"ですか","C":"でした","D":"じゃありませんでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 1010, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ngày nhập học khi đó không phải mùa hoa anh đào.', _utf8mb4 0x0a, _utf8mb4'入学した日は桜の季節（　）。'), _utf8mb4'Sau danh từ 桜の季節, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"じゃありませんでした","B":"ですか","C":"でしょうか","D":"でした"},"correctAnswer":"A"}'
    UNION ALL SELECT 1016, _utf8mb4'EASY', CONCAT(_utf8mb4'Nơi chơi thuở nhỏ là bãi sông.', _utf8mb4 0x0a, _utf8mb4'子どものころの遊び場は川原（　）。'), _utf8mb4'Sau danh từ 川原, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"じゃありませんでした","B":"でした","C":"ですか","D":"でしょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 1022, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nghề trước khi chuyển việc không phải lái xe.', _utf8mb4 0x0a, _utf8mb4'A「転職前の仕事について覚えていますか。」 B「（　）」'), _utf8mb4'Sau danh từ 運転手, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"転職前の仕事は運転手ですか。","B":"転職前の仕事は運転手でしょうか。","C":"転職前の仕事は運転手でした。","D":"転職前の仕事は運転手じゃありませんでした。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu tên gọi trước đây.', _utf8mb4 0x0a, _utf8mb4'古い地図に「川村」と書いてあります。今の名前は川町です。'), _utf8mb4'Sau danh từ 川村, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"町の昔の名前は川村でした。","B":"町の昔の名前は川村じゃありませんでした。","C":"町の昔の名前は川村でしょうか。","D":"町の昔の名前は川村ですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1034, _utf8mb4'EASY', CONCAT(_utf8mb4'Người đến lớp hôm đó không phải cựu học sinh.', _utf8mb4 0x0a, _utf8mb4'授業に来た人（　）卒業生じゃありませんでした。'), _utf8mb4'は nêu chủ đề 授業に来た人; phần sau cho biết đó từng là gì.', _utf8mb4'{"options":{"A":"で","B":"は","C":"へ","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Giáo viên chủ nhiệm trước đây là giáo viên nhạc.', _utf8mb4 0x0a, _utf8mb4'以前の担任は音楽の先生（　）。'), _utf8mb4'Sau danh từ 音楽の先生, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"ですか","B":"じゃありませんでした","C":"でしょうか","D":"でした"},"correctAnswer":"D"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gói hàng nhận hôm đó không phải quà của mẹ.', _utf8mb4 0x0a, _utf8mb4'届いた荷物は母からの贈り物（　）。'), _utf8mb4'Sau danh từ 母からの贈り物, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"ですか","B":"でした","C":"じゃありませんでした","D":"でしょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 2010, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đối thủ hôm qua là trường bên cạnh.', _utf8mb4 0x0a, _utf8mb4'昨日の相手（　）隣の学校でした。'), _utf8mb4'は nêu chủ đề 昨日の相手; phần sau cho biết đó từng là gì.', _utf8mb4'{"options":{"A":"を","B":"は","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 2027, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thứ tự thuyết trình khi ấy không phải thứ ba.', _utf8mb4 0x0a, _utf8mb4'A「発表の順番について覚えていますか。」 B「（　）」'), _utf8mb4'Sau danh từ 三番目, じゃありませんでした phủ định một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"発表の順番は三番目でしょうか。","B":"発表の順番は三番目ですか。","C":"発表の順番は三番目じゃありませんでした。","D":"発表の順番は三番目でした。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2044, _utf8mb4'EASY', CONCAT(_utf8mb4'Hôm qua là ngày nghỉ.', _utf8mb4 0x0a, _utf8mb4'昨日は休み（　）。'), _utf8mb4'Sau danh từ 休み, でした xác nhận một sự thật trong quá khứ.', _utf8mb4'{"options":{"A":"でした","B":"でしょうか","C":"じゃありませんでした","D":"ですか"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 10 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Nでした／Nじゃありませんでした。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 11 (N はどうでしたか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Hỏi cảm nhận sau cuộc thi hát.', _utf8mb4 0x0a, _utf8mb4'歌のコンテストは（　）。') AS content, _utf8mb4'どうでしたか hỏi cảm nhận sau khi trải nghiệm; でした đánh dấu thời điểm đã qua.' AS explanation, _utf8mb4'{"options":{"A":"だれと行きますか","B":"どうでしたか","C":"いくらですか","D":"いつですか"},"correctAnswer":"B"}' AS answers
