    UNION ALL SELECT 2045, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi cảm nhận sau chợ sáng.', _utf8mb4 0x0a, _utf8mb4'朝市は（　）。'), _utf8mb4'どうでしたか hỏi cảm nhận sau khi trải nghiệm; でした đánh dấu thời điểm đã qua.', _utf8mb4'{"options":{"A":"だれと行きますか","B":"どうでしたか","C":"いつですか","D":"いくらですか"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 11 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N はどうでしたか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 12 (どうして～か。／Lý do + から。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Trả lời lý do trả sách thư viện.', _utf8mb4 0x0a, _utf8mb4'「どうして図書館の本を返しますか」「（　）。」') AS content, _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.' AS explanation, _utf8mb4'{"options":{"A":"返す日ですか","B":"返す日ですから","C":"返しませんか","D":"返しましょう"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'「どうしてポスターを壁に貼りますか」お知らせがありますから。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"Nhờ người nghe cùng hành động.","B":"Hỏi xem có đúng là cần thông báo cho lớp hay không.","C":"Vì cần thông báo cho lớp.","D":"Xác nhận lại thông tin với người nghe."},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Trả lời lý do chọn đôi giày mới.', _utf8mb4 0x0a, _utf8mb4'「どうして新しい靴を選びますか」「（　）。」'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"今の靴は小さいですから","B":"選びませんか","C":"選びましょう","D":"今の靴は小さいですか"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời lý do xem trận bóng đá.', _utf8mb4 0x0a, _utf8mb4'好きなチームが出ます（　）。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"まで","B":"より","C":"だけ","D":"から"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời lý do dán tem lên thư.', _utf8mb4 0x0a, _utf8mb4'手紙を出します（　）。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"より","B":"まで","C":"だけ","D":"から"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời lý do gấp chim bằng giấy.', _utf8mb4 0x0a, _utf8mb4'色紙があります（　）。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"から","B":"だけ","C":"より","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời lý do dạy cách bơi.', _utf8mb4 0x0a, _utf8mb4'妹はまだ泳げません（　）。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"だけ","B":"から","C":"より","D":"まで"},"correctAnswer":"B"}'
