    UNION ALL SELECT 2029, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời lý do cho cá trong hồ ăn.', _utf8mb4 0x0a, _utf8mb4'魚が集まっています（　）。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"から","B":"より","C":"だけ","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 2046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời lý do in ảnh khổ lớn.', _utf8mb4 0x0a, _utf8mb4'部屋に飾ります（　）。'), _utf8mb4'から nối lý do với hành động; trong lời đáp, lý do có thể đứng riêng với から.', _utf8mb4'{"options":{"A":"まで","B":"から","C":"より","D":"だけ"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'どうして～か。／Lý do + から。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 13 (N がほしいです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'暖かい手袋がほしいです。') AS content, _utf8mb4'が chỉ thứ muốn có; ở đây là 暖かい手袋.' AS explanation, _utf8mb4'{"options":{"A":"Trước kia tôi muốn có găng tay ấm.","B":"Bạn có muốn có găng tay ấm không?","C":"Tôi không muốn có găng tay ấm.","D":"Tôi muốn có găng tay ấm."},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Bàn học thiếu đồng hồ. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'小さな時計が（　）。'), _utf8mb4'が chỉ thứ muốn có; ở đây là 小さな時計.', _utf8mb4'{"options":{"A":"ほしかったです","B":"ほしくないです","C":"ほしいです","D":"ほしいですか"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Sắp đi bộ đường dài. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'軽い靴（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: giày nhẹ.', _utf8mb4'{"options":{"A":"が","B":"から","C":"へ","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Sắp đi cắm trại. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'テント（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: lều.', _utf8mb4'{"options":{"A":"で","B":"が","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần một góc để viết. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'木の机（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: bàn gỗ.', _utf8mb4'{"options":{"A":"から","B":"が","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu món đồ hiện muốn có.', _utf8mb4 0x0a, _utf8mb4'音楽部に入ります。まだ楽器を持っていません。'), _utf8mb4'が chỉ thứ muốn có; ở đây là ギター.', _utf8mb4'{"options":{"A":"ギターがほしかったです。","B":"ギターがほしくないです。","C":"ギターがほしいですか。","D":"ギターがほしいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Phải mang nhiều đồ nghề. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'A「今、何かほしい物はありますか。」 B「（　）」'), _utf8mb4'が chỉ thứ muốn có; ở đây là ポケットの多い上着.', _utf8mb4'{"options":{"A":"ポケットの多い上着がほしいです。","B":"ポケットの多い上着がほしかったです。","C":"ポケットの多い上着がほしくないです。","D":"ポケットの多い上着がほしいですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Đeo túi cũ bị đau vai. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'軽いかばん（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: túi nhẹ.', _utf8mb4'{"options":{"A":"で","B":"が","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đang học vẽ. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'色鉛筆（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: bút chì màu.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"から","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đêm trên núi rất lạnh. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'温かい毛布（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: chăn ấm.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"から","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Đi đảo lần đầu. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'旅行用の地図（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: bản đồ du lịch.', _utf8mb4'{"options":{"A":"が","B":"で","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Sắp học nấu ăn. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'包丁（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: dao bếp.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"から","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Phải làm việc ngoài mưa. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'防水の靴が（　）。'), _utf8mb4'が chỉ thứ muốn có; ở đây là 防水の靴.', _utf8mb4'{"options":{"A":"ほしいですか","B":"ほしいです","C":"ほしくないです","D":"ほしかったです"},"correctAnswer":"B"}'
