    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Đang xem các tác phẩm nhiếp ảnh. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'写真集（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: tập sách ảnh.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"が","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Muốn tách riêng ghi chú. Nêu món muốn có.', _utf8mb4 0x0a, _utf8mb4'青いノート（　）ほしいです。'), _utf8mb4'が đánh dấu thứ người nói muốn có: vở xanh.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"が","D":"で"},"correctAnswer":"C"}'
