    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chỉ vẽ bằng mực. Từ chối món này.', _utf8mb4 0x0a, _utf8mb4'A「今、何かほしい物はありますか。」 B「（　）」'), _utf8mb4'ほしい chia phủ định thành ほしくない; ở đây là 色鉛筆.', _utf8mb4'{"options":{"A":"色鉛筆がほしかったです。","B":"色鉛筆がほしくないです。","C":"色鉛筆がほしいです。","D":"色鉛筆がほしいですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2014, _utf8mb4'EASY', CONCAT(_utf8mb4'Khách sạn đã chuẩn bị chăn. Từ chối món này.', _utf8mb4 0x0a, _utf8mb4'温かい毛布（　）ほしくないです。'), _utf8mb4'が đánh dấu thứ người nói không muốn có: chăn ấm.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"が","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 2031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu mong muốn ở thể phủ định.', _utf8mb4 0x0a, _utf8mb4'旅の地図は携帯にあります。紙の物は要りません。'), _utf8mb4'ほしい chia phủ định thành ほしくない; ở đây là 旅行用の地図.', _utf8mb4'{"options":{"A":"旅行用の地図がほしいです。","B":"旅行用の地図がほしかったです。","C":"旅行用の地図がほしくないです。","D":"旅行用の地図がほしいですか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bộ dao đã đầy đủ. Từ chối món này.', _utf8mb4 0x0a, _utf8mb4'包丁（　）ほしくないです。'), _utf8mb4'が đánh dấu thứ người nói không muốn có: dao bếp.', _utf8mb4'{"options":{"A":"が","B":"で","C":"へ","D":"から"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 14 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N がほしくないです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 15 (N が好き／嫌いです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Tôi vui khi viết được chữ đẹp. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'A「漢字の練習についてどう思いますか。」 B「（　）」') AS content, _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích luyện chữ Hán.' AS explanation, _utf8mb4'{"options":{"A":"漢字の練習が好きでした。","B":"漢字の練習が好きですか。","C":"漢字の練習が好きです。","D":"漢字の練習が嫌いです。"},"correctAnswer":"C"}' AS answers
