    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đứng lên hát khiến tôi khó chịu. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'歌を歌うこと（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét ca hát.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"で","D":"が"},"correctAnswer":"D"}'
