    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thấy đứng bếp là mất vui. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'A「料理についてどう思いますか。」 B「（　）」'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét nấu ăn.', _utf8mb4'{"options":{"A":"料理が好きです。","B":"料理が嫌いでした。","C":"料理が嫌いです。","D":"料理が嫌いですか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi thích ngồi nghe tiếng mưa. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'雨の日が（　）。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích ngày mưa.', _utf8mb4'{"options":{"A":"好きですか","B":"好きでした","C":"好きです","D":"嫌いです"},"correctAnswer":"C"}'
