    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ngày nào cũng pha ấm trà. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'A「お茶についてどう思いますか。」 B「（　）」'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích trà.', _utf8mb4'{"options":{"A":"お茶が好きですか。","B":"お茶が好きです。","C":"お茶が好きでした。","D":"お茶が嫌いです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi không thích ngồi viết thư. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'手紙を書くこと（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét viết thư.', _utf8mb4'{"options":{"A":"から","B":"が","C":"で","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi vui vì được vận động sớm. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'朝の体操が（　）。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích thể dục buổi sáng.', _utf8mb4'{"options":{"A":"好きです","B":"嫌いです","C":"好きですか","D":"好きでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Không muốn xem loại ảnh này. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'A「星の写真についてどう思いますか。」 B「（　）」'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét ảnh các vì sao.', _utf8mb4'{"options":{"A":"星の写真が嫌いですか。","B":"星の写真が嫌いです。","C":"星の写真が好きです。","D":"星の写真が嫌いでした。"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', CONCAT(_utf8mb4'Thích sự yên tĩnh ở bờ biển. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'冬の海（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích biển mùa đông.', _utf8mb4'{"options":{"A":"から","B":"で","C":"へ","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn ý đúng với lời nói.', _utf8mb4 0x0a, _utf8mb4'犬が嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét chó.', _utf8mb4'{"options":{"A":"Tôi ghét chó.","B":"Kể về sở thích trước đây.","C":"Hỏi sở thích của người đối diện.","D":"Tôi thích chó."},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi hay chọn quả chua. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'酸っぱい果物（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích trái cây chua.', _utf8mb4'{"options":{"A":"で","B":"から","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhìn thấy bọ là tôi tránh xa. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'虫（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét côn trùng.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"から","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi rất thích các chuyến cuốc bộ. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'長い散歩（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích đi bộ đường dài.', _utf8mb4'{"options":{"A":"で","B":"が","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thấy các vở rối nhàm chán. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'A「人形劇についてどう思いますか。」 B「（　）」'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét kịch rối.', _utf8mb4'{"options":{"A":"人形劇が好きです。","B":"人形劇が嫌いです。","C":"人形劇が嫌いでした。","D":"人形劇が嫌いですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1003, _utf8mb4'EASY', CONCAT(_utf8mb4'Thích cả mùi lẫn vị. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'納豆（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích đậu tương lên men.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"が","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 1008, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Luôn đổi kênh khi nghe jazz. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'ジャズ（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét nhạc jazz.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"が","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 1013, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu sở thích hiện tại.', _utf8mb4 0x0a, _utf8mb4'お菓子を買う時は、いつも砂糖の多い物を選びます。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích bánh kẹo ngọt.', _utf8mb4'{"options":{"A":"甘いお菓子が好きです。","B":"甘いお菓子が好きですか。","C":"甘いお菓子が好きでした。","D":"甘いお菓子が嫌いです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1018, _utf8mb4'EASY', CONCAT(_utf8mb4'Đám đông ở hội làm tôi mệt. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'にぎやかな祭り（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét lễ hội náo nhiệt.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"で","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thực đơn có cá là tôi chọn. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'魚料理が（　）。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích món cá.', _utf8mb4'{"options":{"A":"好きです","B":"好きでした","C":"嫌いです","D":"好きですか"},"correctAnswer":"A"}'
    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Quá yên tĩnh khiến tôi buồn. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'静かな夜（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét đêm yên tĩnh.', _utf8mb4'{"options":{"A":"で","B":"が","C":"から","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1033, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi thường tới sân cổ vũ. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'野球（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích bóng chày.', _utf8mb4'{"options":{"A":"へ","B":"が","C":"で","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chẳng thích xuống bể bơi. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'水泳（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét bơi lội.', _utf8mb4'{"options":{"A":"から","B":"が","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 1043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mong buổi sáng để dạo bộ. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'早起き（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích việc dậy sớm.', _utf8mb4'{"options":{"A":"が","B":"から","C":"へ","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 1048, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi rất ngại những con dốc. Nêu điều mình ghét.', _utf8mb4 0x0a, _utf8mb4'山登り（　）嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét leo núi.', _utf8mb4'{"options":{"A":"から","B":"で","C":"へ","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 2015, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nói về sở thích của bản thân.', _utf8mb4 0x0a, _utf8mb4'休みの日はカメラを持ち、楽しみにして外へ出ます。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích việc chụp ảnh.', _utf8mb4'{"options":{"A":"写真を撮ることが好きです。","B":"写真を撮ることが嫌いです。","C":"写真を撮ることが好きでした。","D":"写真を撮ることが好きですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn ý đúng với lời nói.', _utf8mb4 0x0a, _utf8mb4'古い映画が嫌いです。'), _utf8mb4'が đánh dấu đối tượng của 嫌い; người nói ghét phim cũ.', _utf8mb4'{"options":{"A":"Tôi thích phim cũ.","B":"Hỏi sở thích của người đối diện.","C":"Kể về sở thích trước đây.","D":"Tôi ghét phim cũ."},"correctAnswer":"D"}'
    UNION ALL SELECT 2049, _utf8mb4'EASY', CONCAT(_utf8mb4'Mỗi chuyến đi tôi đều tìm suối nóng. Nêu sở thích.', _utf8mb4 0x0a, _utf8mb4'温泉（　）好きです。'), _utf8mb4'が đánh dấu đối tượng của 好き; người nói thích suối nước nóng.', _utf8mb4'{"options":{"A":"で","B":"から","C":"が","D":"へ"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 15 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N が好き／嫌いです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 16 (Vます bỏ ます + たいです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Máy bay sắp hạ cánh. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'A「次は何をしたいですか。」 B「（　）」') AS content, _utf8mb4'Bỏ ます của 迎えます rồi thêm たいです để nêu hành động bản thân muốn làm.' AS explanation, _utf8mb4'{"options":{"A":"留学生を迎えました。","B":"留学生を迎えたくないです。","C":"留学生を迎えたいです。","D":"留学生を迎えましょうか。"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Bánh mì vừa ra lò. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'手作りのパンを（　）。'), _utf8mb4'Bỏ ます của 売ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"売りましょうか","B":"売りたいです","C":"売りたくないです","D":"売りました"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã thấy một loài hoa lạ. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'花の名前を（　）。'), _utf8mb4'Bỏ ます của 調べます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"調べたいです","B":"調べたくないです","C":"調べましょうか","D":"調べました"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu việc bản thân muốn làm tiếp.', _utf8mb4 0x0a, _utf8mb4'二つの予定表で試合の時刻が違います。'), _utf8mb4'Bỏ ます của 確かめます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"試合の予定を確かめました。","B":"試合の予定を確かめたいです。","C":"試合の予定を確かめましょうか。","D":"試合の予定を確かめたくないです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Đã đủ các linh kiện. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'本棚を（　）。'), _utf8mb4'Bỏ ます của 組み立てます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"組み立てましょうか","B":"組み立てたいです","C":"組み立てたくないです","D":"組み立てました"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nói mình muốn làm gì.', _utf8mb4 0x0a, _utf8mb4'池の魚が集まっています。手にえさがあります。'), _utf8mb4'Bỏ ます của やります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"池の魚にえさをやりましょうか。","B":"池の魚にえさをやりたくないです。","C":"池の魚にえさをやりました。","D":"池の魚にえさをやりたいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Muốn treo trong phòng. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'A「次は何をしたいですか。」 B「（　）」'), _utf8mb4'Bỏ ます của 印刷します rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"写真を大きく印刷したいです。","B":"写真を大きく印刷しましょうか。","C":"写真を大きく印刷したくないです。","D":"写真を大きく印刷しました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Mèo đang ở cạnh hoa. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'猫の写真を（　）。'), _utf8mb4'Bỏ ます của 撮ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"撮りました","B":"撮りたくないです","C":"撮りたいです","D":"撮りましょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu mong muốn luyện tập.', _utf8mb4 0x0a, _utf8mb4'合唱の発表は来週。まだ曲に自信がありません。'), _utf8mb4'Bỏ ます của します rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"合唱の練習をしましょうか。","B":"合唱の練習をしました。","C":"合唱の練習をしたいです。","D":"合唱の練習をしたくないです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kệ sách đã đầy. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'A「この後はどうしたいですか。」 B「（　）」'), _utf8mb4'Bỏ ます của まとめます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"古い雑誌をまとめました。","B":"古い雑誌をまとめたくないです。","C":"古い雑誌をまとめましょうか。","D":"古い雑誌をまとめたいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Tiết sau sắp bắt đầu. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'黒板の字を（　）。'), _utf8mb4'Bỏ ます của 消します rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"消したいです","B":"消したくないです","C":"消しましょうか","D":"消しました"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Muốn kể lại kỷ niệm chuyến đi. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'絵はがきを（　）。'), _utf8mb4'Bỏ ます của 書きます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"書きましょうか","B":"書きたくないです","C":"書きました","D":"書きたいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã đến hạn trả sách. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'図書館の本を（　）。'), _utf8mb4'Bỏ ます của 返します rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"返しましょうか","B":"返したいです","C":"返しました","D":"返したくないです"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần thông báo cho lớp. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'ポスターを壁に（　）。'), _utf8mb4'Bỏ ます của 貼ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"貼りたいです","B":"貼りたくないです","C":"貼りましょうか","D":"貼りました"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'新しい靴を選びたいです。'), _utf8mb4'Bỏ ます của 選びます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"Tôi đề nghị làm giúp việc này.","B":"Tôi không muốn chọn đôi giày mới.","C":"Tôi muốn chọn đôi giày mới.","D":"Tôi đã chọn đôi giày mới."},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đội yêu thích sắp ra sân. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'サッカーの試合を（　）。'), _utf8mb4'Bỏ ます của 見ます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"見ましょうか","B":"見たくないです","C":"見ました","D":"見たいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần gửi thư. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'手紙に切手を（　）。'), _utf8mb4'Bỏ ます của 貼ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"貼りたくないです","B":"貼りましょうか","C":"貼りたいです","D":"貼りました"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Có sẵn giấy màu. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'紙で鳥を（　）。'), _utf8mb4'Bỏ ます của 折ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"折りました","B":"折りたいです","C":"折りましょうか","D":"折りたくないです"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Em gái chưa biết bơi. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'A「次は何をしたいですか。」 B「（　）」'), _utf8mb4'Bỏ ます của 教えます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"泳ぎ方を教えたいです。","B":"泳ぎ方を教えましょうか。","C":"泳ぎ方を教えたくないです。","D":"泳ぎ方を教えました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần kiểm tra âm thanh. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'ピアノの曲を（　）。'), _utf8mb4'Bỏ ます của 弾きます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"弾きましょうか","B":"弾きました","C":"弾きたくないです","D":"弾きたいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1004, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cà chua đã chín đỏ. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'畑のトマトを（　）。'), _utf8mb4'Bỏ ます của 取ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"取りましょうか","B":"取りたくないです","C":"取りました","D":"取りたいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chưa mở được cửa ô tô. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'A「この後はどうしたいですか。」 B「（　）」'), _utf8mb4'Bỏ ます của 探します rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"車のかぎを探しました。","B":"車のかぎを探しましょうか。","C":"車のかぎを探したいです。","D":"車のかぎを探したくないです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1014, _utf8mb4'EASY', CONCAT(_utf8mb4'Đã chọn mua chiếc áo này. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'シャツの代金を（　）。'), _utf8mb4'Bỏ ます của 払います rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"払いました","B":"払いましょうか","C":"払いたくないです","D":"払いたいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã quên bản đồ. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'駅までの道を（　）。'), _utf8mb4'Bỏ ます của 聞きます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"聞きたいです","B":"聞きました","C":"聞きたくないです","D":"聞きましょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 1024, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gió đã lặng. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'川でボートを（　）。'), _utf8mb4'Bỏ ます của こぎます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"こぎましょうか","B":"こぎたいです","C":"こぎました","D":"こぎたくないです"},"correctAnswer":"B"}'
    UNION ALL SELECT 1029, _utf8mb4'EASY', CONCAT(_utf8mb4'Trời đang đẹp. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'古い町を（　）。'), _utf8mb4'Bỏ ます của 歩きます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"歩きたくないです","B":"歩きたいです","C":"歩きました","D":"歩きましょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 1034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đây là bài tập môn khoa học. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'木の高さを（　）。'), _utf8mb4'Bỏ ます của 測ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"測りたくないです","B":"測りましょうか","C":"測りました","D":"測りたいです"},"correctAnswer":"D"}'
    UNION ALL SELECT 1039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã viết xong bài văn. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'先生に作文を（　）。'), _utf8mb4'Bỏ ます của 見せます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"見せたくないです","B":"見せましょうか","C":"見せたいです","D":"見せました"},"correctAnswer":"C"}'
    UNION ALL SELECT 1044, _utf8mb4'EASY', CONCAT(_utf8mb4'Có giấy rơi trên đường. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'公園のごみを（　）。'), _utf8mb4'Bỏ ます của 拾います rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"拾いたくないです","B":"拾いたいです","C":"拾いましょうか","D":"拾いました"},"correctAnswer":"B"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã ghi địa chỉ lên hộp. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'祖母に荷物を（　）。'), _utf8mb4'Bỏ ます của 送ります rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"送りたいです","B":"送りたくないです","C":"送りました","D":"送りましょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 2016, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'地元の料理を習いたいです。'), _utf8mb4'Bỏ ます của 習います rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"Tôi muốn học nấu món địa phương.","B":"Tôi đề nghị làm giúp việc này.","C":"Tôi không muốn học nấu món địa phương.","D":"Tôi đã học nấu món địa phương."},"correctAnswer":"A"}'
    UNION ALL SELECT 2033, _utf8mb4'EASY', CONCAT(_utf8mb4'Lốp xe bị thủng. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'自転車のタイヤを（　）。'), _utf8mb4'Bỏ ます của 直します rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"直しましょうか","B":"直しました","C":"直したいです","D":"直したくないです"},"correctAnswer":"C"}'
    UNION ALL SELECT 2050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kính đang bẩn. Nói mong muốn của mình.', _utf8mb4 0x0a, _utf8mb4'店の窓を（　）。'), _utf8mb4'Bỏ ます của 磨きます rồi thêm たいです để nêu hành động bản thân muốn làm.', _utf8mb4'{"options":{"A":"磨きました","B":"磨きましょうか","C":"磨きたくないです","D":"磨きたいです"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 16 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます bỏ ます + たいです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 5 / NGỮ PHÁP / Mẫu 17 (Địa điểm へ + Vます bỏ ます + に行きます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Đến sân vận động để xem trận bóng đá.', _utf8mb4 0x0a, _utf8mb4'競技場へサッカーの試合を（　）行きます。') AS content, _utf8mb4'Gốc 見 + に nêu mục đích của việc đến 競技場.' AS explanation, _utf8mb4'{"options":{"A":"見たいと","B":"見に","C":"見ながら","D":"見ましたが"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đến bưu điện để dán tem lên thư.', _utf8mb4 0x0a, _utf8mb4'郵便局へ手紙に切手を貼り（　）行きます。'), _utf8mb4'に sau gốc động từ 貼り nêu mục đích chuyến đi.', _utf8mb4'{"options":{"A":"まで","B":"から","C":"で","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'工作室へ紙で鳥を折りに行きます。'), _utf8mb4'Gốc 折り + に nêu mục đích của việc đến 工作室.', _utf8mb4'{"options":{"A":"Tôi đến phòng thủ công để gấp chim bằng giấy.","B":"Tôi đã gấp chim bằng giấy nhưng chưa đến phòng thủ công.","C":"Tôi chỉ muốn đến phòng thủ công chứ không làm gì.","D":"Sau khi gấp chim bằng giấy tôi rời phòng thủ công."},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Đến bể bơi để dạy cách bơi.', _utf8mb4 0x0a, _utf8mb4'プールへ泳ぎ方を教え（　）行きます。'), _utf8mb4'に sau gốc động từ 教え nêu mục đích chuyến đi.', _utf8mb4'{"options":{"A":"で","B":"まで","C":"から","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đến hội trường để chơi một bản nhạc piano.', _utf8mb4 0x0a, _utf8mb4'ホールへピアノの曲を（　）行きます。'), _utf8mb4'Gốc 弾き + に nêu mục đích của việc đến ホール.', _utf8mb4'{"options":{"A":"弾きましたが","B":"弾きたいと","C":"弾きに","D":"弾きながら"},"correctAnswer":"C"}'
