    UNION ALL SELECT 1050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đến phòng nhạc để tập hát hợp xướng.', _utf8mb4 0x0a, _utf8mb4'A「何をしに音楽室へ行きますか。」 B「（　）」'), _utf8mb4'Gốc し + に nêu mục đích của việc đến 音楽室.', _utf8mb4'{"options":{"A":"音楽室へ行かないで、家で合唱の練習をします。","B":"音楽室へ合唱の練習をしに行きます。","C":"音楽室へ行きましたが、合唱の練習をしませんでした。","D":"音楽室から帰って合唱の練習をします。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2017, _utf8mb4'EASY', CONCAT(_utf8mb4'Đến phòng để gom tạp chí cũ lại.', _utf8mb4 0x0a, _utf8mb4'部屋（　）古い雑誌をまとめに行きます。'), _utf8mb4'へ theo sau 部屋 để đánh dấu đích đến.', _utf8mb4'{"options":{"A":"の","B":"と","C":"へ","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 2034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đến lớp học để xóa chữ trên bảng.', _utf8mb4 0x0a, _utf8mb4'A「何をしに教室へ行きますか。」 B「（　）」'), _utf8mb4'Gốc 消し + に nêu mục đích của việc đến 教室.', _utf8mb4'{"options":{"A":"教室へ行きましたが、黒板の字を消しませんでした。","B":"教室から帰って黒板の字を消します。","C":"教室へ行かないで、家で黒板の字を消します。","D":"教室へ黒板の字を消しに行きます。"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 5
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 17 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm へ + Vます bỏ ます + に行きます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 1 (Vます → Vませんか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chưa mở được cửa ô tô. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「ええ、ぜひ一緒に。」') AS content, _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng tìm chìa khóa ô tô không.' AS explanation, _utf8mb4'{"options":{"A":"車のかぎを探しませんか。","B":"車のかぎを探したくないです。","C":"車のかぎを探しました。","D":"車のかぎを探したいです。"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Đã chọn mua chiếc áo này. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'この後、シャツの代金を（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng trả tiền áo sơ mi không.', _utf8mb4'{"options":{"A":"払いたいです","B":"払いませんでした","C":"払いませんよ","D":"払いませんか"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã quên bản đồ. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「ええ、ぜひ一緒に。」'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng hỏi đường ra ga không.', _utf8mb4'{"options":{"A":"駅までの道を聞きたいです。","B":"駅までの道を聞きたくないです。","C":"駅までの道を聞きました。","D":"駅までの道を聞きませんか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gió đã lặng. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'風が止みました。一緒に川でボートを（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng chèo thuyền trên sông không.', _utf8mb4'{"options":{"A":"こぎませんか","B":"こぎませんでした","C":"こぎませんよ","D":"こぎたいです"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Trời đang đẹp. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'一緒に古い町を歩きません（　）。'), _utf8mb4'か biến ません thành lời mời dưới dạng câu hỏi.', _utf8mb4'{"options":{"A":"が","B":"ね","C":"か","D":"よ"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đây là bài tập môn khoa học. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'木の高さを（　）。二人ならできます。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng đo chiều cao của cây không.', _utf8mb4'{"options":{"A":"測りたいです","B":"測りませんよ","C":"測りませんか","D":"測りませんでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã viết xong bài văn. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「ええ、ぜひ一緒に。」'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng cho thầy xem bài văn không.', _utf8mb4'{"options":{"A":"先生に作文を見せたくないです。","B":"先生に作文を見せませんか。","C":"先生に作文を見せたいです。","D":"先生に作文を見せました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Có giấy rơi trên đường. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'この後、公園のごみを（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng nhặt rác ở công viên không.', _utf8mb4'{"options":{"A":"拾いませんよ","B":"拾いませんか","C":"拾いたいです","D":"拾いませんでした"},"correctAnswer":"B"}'
