    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ngỏ lời mời người bên cạnh.', _utf8mb4 0x0a, _utf8mb4'公園で魚の世話をする人を探しています。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng cho cá trong hồ ăn không.', _utf8mb4'{"options":{"A":"池の魚にえさをやりたいです。","B":"池の魚にえさをやりたくないです。","C":"池の魚にえさをやりませんか。","D":"池の魚にえさをやりました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1006, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Muốn treo trong phòng. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'部屋に飾ります。一緒に写真を大きく（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng in ảnh khổ lớn không.', _utf8mb4'{"options":{"A":"印刷したいです","B":"印刷しませんでした","C":"印刷しませんよ","D":"印刷しませんか"},"correctAnswer":"D"}'
    UNION ALL SELECT 1011, _utf8mb4'EASY', CONCAT(_utf8mb4'Mèo đang ở cạnh hoa. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'この後、猫の写真を（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng chụp ảnh mèo không.', _utf8mb4'{"options":{"A":"撮りませんよ","B":"撮りませんでした","C":"撮りたいです","D":"撮りませんか"},"correctAnswer":"D"}'
    UNION ALL SELECT 1016, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn ý đúng với lời nói.', _utf8mb4 0x0a, _utf8mb4'合唱の練習をしませんか。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng tập hát hợp xướng không.', _utf8mb4'{"options":{"A":"Bạn có muốn cùng tập hát hợp xướng không?","B":"Tôi muốn tự tập hát hợp xướng.","C":"Tôi đã không tập hát hợp xướng.","D":"Tôi từ chối tập hát hợp xướng."},"correctAnswer":"A"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kệ sách đã đầy. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'本棚がいっぱいです。一緒に古い雑誌を（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng gom tạp chí cũ lại không.', _utf8mb4'{"options":{"A":"まとめたいです","B":"まとめませんか","C":"まとめませんでした","D":"まとめませんよ"},"correctAnswer":"B"}'
