    UNION ALL SELECT 1031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Rủ người cùng phòng viết thiệp.', _utf8mb4 0x0a, _utf8mb4'宿で絵はがきを二枚もらいました。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng viết bưu thiếp không.', _utf8mb4'{"options":{"A":"絵はがきを書きませんか。","B":"絵はがきを書きたいです。","C":"絵はがきを書きました。","D":"絵はがきを書きたくないです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã đến hạn trả sách. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'返す日です。一緒に図書館の本を（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng trả sách thư viện không.', _utf8mb4'{"options":{"A":"返したいです","B":"返しませんか","C":"返しませんよ","D":"返しませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 1041, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần thông báo cho lớp. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'一緒にポスターを壁に貼りません（　）。'), _utf8mb4'か biến ません thành lời mời dưới dạng câu hỏi.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"が","D":"か"},"correctAnswer":"D"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'新しい靴を選びませんか。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng chọn đôi giày mới không.', _utf8mb4'{"options":{"A":"Tôi đã không chọn đôi giày mới.","B":"Tôi từ chối chọn đôi giày mới.","C":"Bạn có muốn cùng chọn đôi giày mới không?","D":"Tôi muốn tự chọn đôi giày mới."},"correctAnswer":"C"}'
    UNION ALL SELECT 2001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đội yêu thích sắp ra sân. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「ええ、ぜひ一緒に。」'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng xem trận bóng đá không.', _utf8mb4'{"options":{"A":"サッカーの試合を見たいです。","B":"サッカーの試合を見ました。","C":"サッカーの試合を見ませんか。","D":"サッカーの試合を見たくないです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2016, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần gửi thư. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'この後、手紙に切手を（　）。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng dán tem lên thư không.', _utf8mb4'{"options":{"A":"貼りませんか","B":"貼りませんよ","C":"貼りたいです","D":"貼りませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 2031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mở lời mời.', _utf8mb4 0x0a, _utf8mb4'折り紙がたくさんあります。友達にも作ってほしいです。'), _utf8mb4'〜ませんか là lời mời để người nghe tự quyết định có cùng gấp chim bằng giấy không.', _utf8mb4'{"options":{"A":"紙で鳥を折りたいです。","B":"紙で鳥を折りませんか。","C":"紙で鳥を折りたくないです。","D":"紙で鳥を折りました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Em gái chưa biết bơi. Ngỏ lời mời.', _utf8mb4 0x0a, _utf8mb4'一緒に泳ぎ方を教えません（　）。'), _utf8mb4'か biến ません thành lời mời dưới dạng câu hỏi.', _utf8mb4'{"options":{"A":"ね","B":"か","C":"よ","D":"が"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます → Vませんか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 2 (Vます → Vましょう。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Tuần sau có buổi biểu diễn. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、合唱の練習を（　）。') AS content, _utf8mb4'〜ましょう rủ cả hai cùng tập hát hợp xướng, thường dùng khi đã đồng ý.' AS explanation, _utf8mb4'{"options":{"A":"しますか","B":"しました","C":"しましょう","D":"しませんでした"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kệ sách đã đầy. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次は古い雑誌を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng gom tạp chí cũ lại, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"まとめますか","B":"まとめませんでした","C":"まとめましょう","D":"まとめました"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tiết sau sắp bắt đầu. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'黒板の字を（　）。二人ならできます。'), _utf8mb4'〜ましょう rủ cả hai cùng xóa chữ trên bảng, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"消しました","B":"消しませんでした","C":"消しますか","D":"消しましょう"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Muốn kể lại kỷ niệm chuyến đi. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、絵はがきを（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng viết bưu thiếp, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"書きませんでした","B":"書きますか","C":"書きましょう","D":"書きました"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã đến hạn trả sách. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次は図書館の本を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng trả sách thư viện, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"返しませんでした","B":"返しました","C":"返しますか","D":"返しましょう"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần thông báo cho lớp. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'ポスターを壁に（　）。二人ならできます。'), _utf8mb4'〜ましょう rủ cả hai cùng dán áp phích lên tường, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"貼りませんでした","B":"貼りますか","C":"貼りました","D":"貼りましょう"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Đôi giày đang đi bị chật. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'友達と一緒（　）新しい靴を選びましょう。'), _utf8mb4'一緒に đứng trước hành động mà mình đề nghị cùng làm.', _utf8mb4'{"options":{"A":"に","B":"から","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đội yêu thích sắp ra sân. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次はサッカーの試合を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng xem trận bóng đá, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"見ましょう","B":"見ました","C":"見ませんでした","D":"見ますか"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần gửi thư. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'手紙に切手を（　）。二人ならできます。'), _utf8mb4'〜ましょう rủ cả hai cùng dán tem lên thư, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"貼りました","B":"貼りましょう","C":"貼りますか","D":"貼りませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'Có sẵn giấy màu. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、紙で鳥を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng gấp chim bằng giấy, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"折りますか","B":"折りました","C":"折りましょう","D":"折りませんでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Em gái chưa biết bơi. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'A「次は何をしましょうか。」 B「（　）」'), _utf8mb4'〜ましょう rủ cả hai cùng dạy cách bơi, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"泳ぎ方を教えましょう。","B":"泳ぎ方を教えました。","C":"泳ぎ方を教えたくないです。","D":"泳ぎ方を教えたいです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đề nghị cùng bắt đầu.', _utf8mb4 0x0a, _utf8mb4'音楽室を使えることになり、二人はピアノの前に座りました。'), _utf8mb4'〜ましょう rủ cả hai cùng chơi một bản nhạc piano, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"ピアノの曲を弾きましょう。","B":"ピアノの曲を弾きたいです。","C":"ピアノの曲を弾きました。","D":"ピアノの曲を弾きたくないです。"},"correctAnswer":"A"}'
