    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gió đã lặng. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次は川でボートを（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng chèo thuyền trên sông, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"こぎますか","B":"こぎました","C":"こぎませんでした","D":"こぎましょう"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'古い町を歩きましょう。'), _utf8mb4'〜ましょう rủ cả hai cùng đi bộ khám phá phố cổ, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"Tôi đã không đi bộ khám phá phố cổ.","B":"Chúng ta cùng đi bộ khám phá phố cổ nhé!","C":"Tôi đã đi bộ khám phá phố cổ.","D":"Tôi muốn tự đi bộ khám phá phố cổ."},"correctAnswer":"B"}'
