    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã viết xong bài văn. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次は先生に作文を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng cho thầy xem bài văn, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"見せました","B":"見せませんでした","C":"見せますか","D":"見せましょう"},"correctAnswer":"D"}'
    UNION ALL SELECT 1002, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'公園のごみを拾いましょう。'), _utf8mb4'〜ましょう rủ cả hai cùng nhặt rác ở công viên, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"Tôi đã nhặt rác ở công viên.","B":"Tôi muốn tự nhặt rác ở công viên.","C":"Chúng ta cùng nhặt rác ở công viên nhé!","D":"Tôi đã không nhặt rác ở công viên."},"correctAnswer":"C"}'
    UNION ALL SELECT 1007, _utf8mb4'EASY', CONCAT(_utf8mb4'Đã ghi địa chỉ lên hộp. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'みんな（　）一緒に祖母に荷物を送りましょう。'), _utf8mb4'と一緒に nêu người cùng tham gia lời đề nghị ましょう。', _utf8mb4'{"options":{"A":"を","B":"と","C":"から","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1012, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thích hương vị từng nếm khi du lịch. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次は地元の料理を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng học nấu món địa phương, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"習いますか","B":"習いましょう","C":"習いました","D":"習いませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đề xuất cùng sửa xe.', _utf8mb4 0x0a, _utf8mb4'タイヤに穴があります。二人の前に工具がそろいました。'), _utf8mb4'〜ましょう rủ cả hai cùng sửa lốp xe đạp, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"自転車のタイヤを直したいです。","B":"自転車のタイヤを直しました。","C":"自転車のタイヤを直しましょう。","D":"自転車のタイヤを直したくないです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1022, _utf8mb4'EASY', CONCAT(_utf8mb4'Kính đang bẩn. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'友達と一緒（　）店の窓を磨きましょう。'), _utf8mb4'一緒に đứng trước hành động mà mình đề nghị cùng làm.', _utf8mb4'{"options":{"A":"に","B":"を","C":"から","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đang có đợt quyên góp. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、次は古い服を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng mang quần áo cũ đến tặng, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"届けますか","B":"届けました","C":"届けませんでした","D":"届けましょう"},"correctAnswer":"D"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ngày đi du lịch đã gần. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'A「準備ができました。次はどうしましょうか。」 B「（　）」'), _utf8mb4'〜ましょう rủ cả hai cùng mua vé tàu, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"電車の切符を買いましょう。","B":"電車の切符を買いました。","C":"電車の切符を買いたくないです。","D":"電車の切符を買いたいです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1037, _utf8mb4'EASY', CONCAT(_utf8mb4'Chỉ có một bản giấy. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、会議の資料を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng sao tài liệu họp, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"コピーしますか","B":"コピーしました","C":"コピーしましょう","D":"コピーしませんでした"},"correctAnswer":"C"}'
    UNION ALL SELECT 1042, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đề nghị hai người cùng đi.', _utf8mb4 0x0a, _utf8mb4'留学生の飛行機が着きます。案内係が二人います。'), _utf8mb4'〜ましょう rủ cả hai cùng đón sinh viên quốc tế, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"留学生を迎えたくないです。","B":"留学生を迎えたいです。","C":"留学生を迎えました。","D":"留学生を迎えましょう。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bánh mì vừa ra lò. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'A「次は何をしましょうか。」 B「（　）」'), _utf8mb4'〜ましょう rủ cả hai cùng bán bánh mì tự làm, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"手作りのパンを売りたいです。","B":"手作りのパンを売りたくないです。","C":"手作りのパンを売りました。","D":"手作りのパンを売りましょう。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2002, _utf8mb4'EASY', CONCAT(_utf8mb4'Đã thấy một loài hoa lạ. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'よかったら、花の名前を（　）。'), _utf8mb4'〜ましょう rủ cả hai cùng tra tên loài hoa, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"調べましょう","B":"調べました","C":"調べますか","D":"調べませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 2017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thời gian có thay đổi. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'A「準備ができました。次はどうしましょうか。」 B「（　）」'), _utf8mb4'〜ましょう rủ cả hai cùng kiểm tra lịch thi đấu, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"試合の予定を確かめましょう。","B":"試合の予定を確かめたくないです。","C":"試合の予定を確かめました。","D":"試合の予定を確かめたいです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đã đủ các linh kiện. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'A「準備ができました。次はどうしましょうか。」 B「（　）」'), _utf8mb4'〜ましょう rủ cả hai cùng lắp kệ sách, thường dùng khi đã đồng ý.', _utf8mb4'{"options":{"A":"本棚を組み立てたいです。","B":"本棚を組み立てましょう。","C":"本棚を組み立てたくないです。","D":"本棚を組み立てました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2047, _utf8mb4'EASY', CONCAT(_utf8mb4'Cá đang tụ lại. Đề nghị cùng làm.', _utf8mb4 0x0a, _utf8mb4'みんな（　）一緒に池の魚にえさをやりましょう。'), _utf8mb4'と一緒に nêu người cùng tham gia lời đề nghị ましょう。', _utf8mb4'{"options":{"A":"へ","B":"を","C":"から","D":"と"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 2 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます → Vましょう。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 3 (Thời gian はちょっと……。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Dự họp ban cán sự. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'A「授業のあとに歴史の講座に行きませんか。」 B「（　）」') AS content, _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.' AS explanation, _utf8mb4'{"options":{"A":"授業のあとならぜひ行きます。","B":"すみません、授業のあとはちょっと……。","C":"授業のあとなら大丈夫です。","D":"授業のあとにしましょう。"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Có khách đến. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、お昼の十二時（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ お昼の十二時 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"を","B":"の","C":"へ","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Khéo từ chối.', _utf8mb4 0x0a, _utf8mb4'「夏祭りの日に会いませんか」その日は仕事です。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"すみません、夏祭りの日はちょっと……。","B":"夏祭りの日にしましょう。","C":"夏祭りの日なら大丈夫です。","D":"夏祭りの日ならぜひ行きます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đi công tác. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、来週の火曜日（　）ちょっと……。出張です。'), _utf8mb4'は nêu riêng khung giờ 来週の火曜日 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chuyển nhà. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、今月の末（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 今月の末 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"を","C":"は","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đang học. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、四時半（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 四時半 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"へ","C":"は","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'すみません、来月の十日はちょっと……。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"Đổi điểm hẹn.","B":"Từ chối khéo lời mời vào mùng mười tháng sau.","C":"Vui vẻ nhận lời vào mùng mười tháng sau.","D":"Hỏi thời gian bắt đầu."},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Từ chối nhẹ nhàng.', _utf8mb4 0x0a, _utf8mb4'来週末は大事な試合。友達から同じ日に誘われました。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"来週末ならぜひ行きます。","B":"すみません、来週末はちょっと……。","C":"来週末にしましょう。","D":"来週末なら大丈夫です。"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Có lớp tiếng Nhật. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、火曜日の夜（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 火曜日の夜 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"は","B":"へ","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đưa con đi học. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'A「明日の朝に健康相談会に行きませんか。」 B「（　）」'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"すみません、明日の朝はちょっと……。","B":"明日の朝なら大丈夫です。","C":"明日の朝にしましょう。","D":"明日の朝ならぜひ行きます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Phải làm ca tối. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'A「今夜にお話の会に行きませんか。」 B「（　）」'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"今夜なら大丈夫です。","B":"今夜ならぜひ行きます。","C":"すみません、今夜はちょっと……。","D":"今夜にしましょう。"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đón em trai. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、月曜の夕方（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 月曜の夕方 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"へ","B":"は","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'すみません、朝七時はちょっと……。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"Đổi điểm hẹn.","B":"Vui vẻ nhận lời vào bảy giờ sáng.","C":"Hỏi thời gian bắt đầu.","D":"Từ chối khéo lời mời vào bảy giờ sáng."},"correctAnswer":"D"}'
