    UNION ALL SELECT 1013, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chuẩn bị cho kỳ thi. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、明後日は（　） 試験の準備があります。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"ちょっと……。","B":"大丈夫です。","C":"楽しみです。","D":"ぜひ行きます。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1018, _utf8mb4'EASY', CONCAT(_utf8mb4'Có đợt tập huấn. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、春休み（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 春休み mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"を","B":"の","C":"は","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tập lái xe. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、木曜日の午後（　）ちょっと……。運転の練習です。'), _utf8mb4'は nêu riêng khung giờ 木曜日の午後 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"は","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gia đình đến thăm. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、日曜日（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 日曜日 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 1033, _utf8mb4'EASY', CONCAT(_utf8mb4'Đi khám răng. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、金曜日（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 金曜日 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Có buổi tập. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、水曜日（　）ちょっと……。練習があります。'), _utf8mb4'は nêu riêng khung giờ 水曜日 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"は","B":"の","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Có cuộc họp. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、午前中は（　） 会議があります。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"大丈夫です。","B":"楽しみです。","C":"ちょっと……。","D":"ぜひ行きます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1048, _utf8mb4'EASY', CONCAT(_utf8mb4'Họp mặt họ hàng. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、一月二日（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 一月二日 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"は","B":"の","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2003, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Làm ở thư viện. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、土曜日の午後（　）ちょっと……。図書館で働きます。'), _utf8mb4'は nêu riêng khung giờ 土曜日の午後 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"を","C":"へ","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 2018, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Từ chối bằng cách nói lửng.', _utf8mb4 0x0a, _utf8mb4'月曜は島へ渡ります。その日、町の食事会に誘われました。'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"今度の月曜日なら大丈夫です。","B":"すみません、今度の月曜日はちょっと……。","C":"今度の月曜日ならぜひ行きます。","D":"今度の月曜日にしましょう。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2033, _utf8mb4'EASY', CONCAT(_utf8mb4'Có bài thi. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'すみません、午後三時（　）ちょっと……。'), _utf8mb4'は nêu riêng khung giờ 午後三時 mà người được mời thấy bất tiện.', _utf8mb4'{"options":{"A":"の","B":"を","C":"は","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 2048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gặp thầy. Từ chối khéo.', _utf8mb4 0x0a, _utf8mb4'A「明日の昼にパン作りの会に行きませんか。」 B「（　）」'), _utf8mb4'Nói lửng はちょっと…… để báo rằng lịch hẹn không thuận tiện mà vẫn giữ phép lịch sự.', _utf8mb4'{"options":{"A":"明日の昼なら大丈夫です。","B":"すみません、明日の昼はちょっと……。","C":"明日の昼にしましょう。","D":"明日の昼ならぜひ行きます。"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 3 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Thời gian はちょっと……。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 4 (Địa điểm で Sự kiện があります。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Lịch sắp tới: trận judo tại võ đường.', _utf8mb4 0x0a, _utf8mb4'次の柔道の試合は道場（　）開かれます。') AS content, _utf8mb4'で đánh dấu nơi tổ chức 柔道の試合; sự kiện diễn ra ở 道場.' AS explanation, _utf8mb4'{"options":{"A":"を","B":"の","C":"へ","D":"で"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: buổi giới thiệu cách chăm sóc thú tại vườn thú.', _utf8mb4 0x0a, _utf8mb4'動物園で飼育の説明会（　）あります。'), _utf8mb4'が đánh dấu 飼育の説明会 là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"から","B":"まで","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: lễ tốt nghiệp tại hội trường trường cấp ba.', _utf8mb4 0x0a, _utf8mb4'次の卒業式は高校のホール（　）開かれます。'), _utf8mb4'で đánh dấu nơi tổ chức 卒業式; sự kiện diễn ra ở 高校のホール.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: triển lãm tác phẩm cát tại bờ biển.', _utf8mb4 0x0a, _utf8mb4'海岸で砂の作品展（　）あります。'), _utf8mb4'が đánh dấu 砂の作品展 là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"から","B":"まで","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: giải bơi tại bể bơi của trường.', _utf8mb4 0x0a, _utf8mb4'明日は学校のプールで水泳大会が（　）。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 水泳大会; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"ありました","B":"います","C":"あります","D":"ありません"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: buổi cùng đọc sách tại quán cà phê.', _utf8mb4 0x0a, _utf8mb4'カフェで読書会が（　）。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 読書会; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"います","B":"あります","C":"ありません","D":"ありました"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: buổi tìm hiểu các vì sao tại phòng khoa học.', _utf8mb4 0x0a, _utf8mb4'次の星の勉強会は理科室（　）開かれます。'), _utf8mb4'で đánh dấu nơi tổ chức 星の勉強会; sự kiện diễn ra ở 理科室.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"の","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: buổi dự giờ của phụ huynh tại trường tiểu học.', _utf8mb4 0x0a, _utf8mb4'明日は小学校で授業参観が（　）。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 授業参観; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"あります","B":"います","C":"ありました","D":"ありません"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thông báo một sự kiện sắp diễn ra.', _utf8mb4 0x0a, _utf8mb4'掲示板：町の会館・手話教室・来週開講。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 手話の教室; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"手話の教室の会場はまだ決まっていません。","B":"町の会館で手話の教室があります。","C":"町の会館での手話の教室は中止です。","D":"手話の教室は昨日終わりました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: chợ sáng tại quảng trường trước ga.', _utf8mb4 0x0a, _utf8mb4'A「どこで朝市がありますか。」 B「（　）」'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 朝市; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"駅前広場で朝市があります。","B":"駅前広場での朝市は中止です。","C":"朝市の会場はまだ決まっていません。","D":"朝市は昨日終わりました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: buổi làm bánh mì tại lớp nấu ăn.', _utf8mb4 0x0a, _utf8mb4'料理教室（　）パン作りの会があります。'), _utf8mb4'で đánh dấu nơi tổ chức パン作りの会; sự kiện diễn ra ở 料理教室.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Thông báo nơi tổ chức hòa nhạc ngoài trời.', _utf8mb4 0x0a, _utf8mb4'チラシには、公園のステージと出演者の写真があります。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 野外コンサート; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"公園で野外コンサートがあります。","B":"公園での野外コンサートは中止です。","C":"野外コンサートは昨日終わりました。","D":"野外コンサートの会場はまだ決まっていません。"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu địa điểm diễn ra giải bóng.', _utf8mb4 0x0a, _utf8mb4'対戦表：高校グラウンド集合。開会式は来月です。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra サッカー大会; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"高校のグラウンドでのサッカー大会は中止です。","B":"サッカー大会は昨日終わりました。","C":"高校のグラウンドでサッカー大会があります。","D":"サッカー大会の会場はまだ決まっていません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: buổi học lịch sử tại bảo tàng.', _utf8mb4 0x0a, _utf8mb4'博物館で歴史の講座（　）あります。'), _utf8mb4'が đánh dấu 歴史の講座 là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"が","B":"まで","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: hội chợ sách cũ tại tòa nhà nhà ga.', _utf8mb4 0x0a, _utf8mb4'A「どこで古本市がありますか。」 B「（　）」'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 古本市; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"古本市は昨日終わりました。","B":"古本市の会場はまだ決まっていません。","C":"駅ビルで古本市があります。","D":"駅ビルでの古本市は中止です。"},"correctAnswer":"C"}'
