    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: buổi kể chuyện tại thư viện.', _utf8mb4 0x0a, _utf8mb4'図書館でお話の会（　）あります。'), _utf8mb4'が đánh dấu お話の会 là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"まで","B":"が","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1024, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: buổi tập ghi-ta tại phòng nhạc.', _utf8mb4 0x0a, _utf8mb4'A「どこでギターの練習がありますか。」 B「（　）」'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra ギターの練習; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"ギターの練習の会場はまだ決まっていません。","B":"ギターの練習は昨日終わりました。","C":"音楽室でのギターの練習は中止です。","D":"音楽室でギターの練習があります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1029, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: tiệc chào đón tại nhà ăn đại học.', _utf8mb4 0x0a, _utf8mb4'大学の食堂で歓迎会（　）あります。'), _utf8mb4'が đánh dấu 歓迎会 là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"が","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 1034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: buổi biểu diễn piano tại nhà văn hóa.', _utf8mb4 0x0a, _utf8mb4'次のピアノの発表会は市民ホール（　）開かれます。'), _utf8mb4'で đánh dấu nơi tổ chức ピアノの発表会; sự kiện diễn ra ở 市民ホール.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: tiệc đầu năm tại nhà trọ.', _utf8mb4 0x0a, _utf8mb4'旅館で新年会（　）あります。'), _utf8mb4'が đánh dấu 新年会 là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"へ","B":"が","C":"まで","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1044, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: buổi học nhảy tại phòng tập.', _utf8mb4 0x0a, _utf8mb4'スタジオ（　）ダンスのレッスンがあります。'), _utf8mb4'で đánh dấu nơi tổ chức ダンスのレッスン; sự kiện diễn ra ở スタジオ.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"の","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'湖でボート大会があります。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra ボート大会; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"Sự kiện ở hồ đã kết thúc.","B":"Có người đang ở hồ.","C":"Sự kiện ở hồ đã bị hủy.","D":"Sắp có giải đua thuyền tại hồ."},"correctAnswer":"D"}'
    UNION ALL SELECT 2004, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: trận bóng chuyền tại nhà thi đấu.', _utf8mb4 0x0a, _utf8mb4'予定表によると、体育館でバレーの試合が（　）。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra バレーの試合; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"あります","B":"ありません","C":"ありました","D":"います"},"correctAnswer":"A"}'
    UNION ALL SELECT 2019, _utf8mb4'EASY', CONCAT(_utf8mb4'Lịch sắp tới: lễ hội dâu tại trang trại.', _utf8mb4 0x0a, _utf8mb4'農園でいちご祭り（　）あります。'), _utf8mb4'が đánh dấu いちご祭り là sự kiện được tổ chức ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"が","B":"まで","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lịch sắp tới: buổi phổ biến tin của thị trấn tại tòa thị chính.', _utf8mb4 0x0a, _utf8mb4'A「どこで町の説明会がありますか。」 B「（　）」'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 町の説明会; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"市役所での町の説明会は中止です。","B":"町の説明会は昨日終わりました。","C":"市役所で町の説明会があります。","D":"町の説明会の会場はまだ決まっていません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'幼稚園で人形劇があります。'), _utf8mb4'Địa điểm + で chỉ nơi diễn ra 人形劇; が nêu sự kiện sắp tổ chức.', _utf8mb4'{"options":{"A":"Sự kiện ở trường mẫu giáo đã kết thúc.","B":"Có người đang ở trường mẫu giáo.","C":"Sắp có buổi diễn rối tại trường mẫu giáo.","D":"Sự kiện ở trường mẫu giáo đã bị hủy."},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 4 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm で Sự kiện があります。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 5 (N が số + 枚 あります。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Viết thư về nhà: đếm 5 bưu thiếp có hình.', _utf8mb4 0x0a, _utf8mb4'絵はがき（　）5枚あります。') AS content, _utf8mb4'が nêu vật hiện có; 5枚 là số lượng bưu thiếp có hình.' AS explanation, _utf8mb4'{"options":{"A":"が","B":"で","C":"へ","D":"より"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đếm số danh thiếp đang có.', _utf8mb4 0x0a, _utf8mb4'名刺は一箱に六枚ずつ。机の上に箱が二つあります。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như danh thiếp; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"名刺が13枚あります。","B":"名刺が12枚あります。","C":"名刺は全部使いました。","D":"名刺があと12枚必要です。"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo số bản đồ còn lại.', _utf8mb4 0x0a, _utf8mb4'地図を五枚受け取り、一枚を先生に渡しました。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như bản đồ; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"地図が4枚あります。","B":"地図があと4枚必要です。","C":"地図は全部使いました。","D":"地図が5枚あります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Nộp bài văn: đếm 11 tờ giấy viết bản thảo.', _utf8mb4 0x0a, _utf8mb4'原稿用紙（　）11枚あります。'), _utf8mb4'が nêu vật hiện có; 11枚 là số lượng tờ giấy viết bản thảo.', _utf8mb4'{"options":{"A":"より","B":"で","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'シャツが3枚あります。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như áo sơ mi; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"Có 3 áo sơ mi.","B":"Chỉ còn một nửa số áo sơ mi đó.","C":"Đã dùng hết 3 áo sơ mi.","D":"Cần thêm 3 áo sơ mi."},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đón khách ở phòng chiếu: đếm 10 đệm ngồi.', _utf8mb4 0x0a, _utf8mb4'A「座布団は何枚ありますか。」 B「（　）」'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như đệm ngồi; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"座布団があと10枚必要です。","B":"座布団が10枚あります。","C":"座布団は全部使いました。","D":"座布団が11枚あります。"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', CONCAT(_utf8mb4'Chuẩn bị biểu diễn: đếm 2 mặt nạ.', _utf8mb4 0x0a, _utf8mb4'お面（　）2枚あります。'), _utf8mb4'が nêu vật hiện có; 2枚 là số lượng mặt nạ.', _utf8mb4'{"options":{"A":"で","B":"より","C":"が","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Khách xếp hàng ở cổng: đếm 9 vé vào cửa.', _utf8mb4 0x0a, _utf8mb4'箱の中に入場券（　）9枚入っています。'), _utf8mb4'が nêu vật hiện có; 9枚 là số lượng vé vào cửa.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"より","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đếm tiền lẻ: đếm 16 đồng 500 yên.', _utf8mb4 0x0a, _utf8mb4'五百円玉を数えました。五百円玉（　）16枚あります。'), _utf8mb4'が nêu vật hiện có; 16枚 là số lượng đồng 500 yên.', _utf8mb4'{"options":{"A":"より","B":"まで","C":"へ","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', CONCAT(_utf8mb4'Ở quầy bể bơi: đếm 8 khăn tắm.', _utf8mb4 0x0a, _utf8mb4'タオルが8（　）あります。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như khăn tắm; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"台","B":"冊","C":"本","D":"枚"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong giờ thủ công: đếm 15 tờ giấy gấp.', _utf8mb4 0x0a, _utf8mb4'A「折り紙は何枚ありますか。」 B「（　）」'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như tờ giấy gấp; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"折り紙は全部使いました。","B":"折り紙が16枚あります。","C":"折り紙があと15枚必要です。","D":"折り紙が15枚あります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dán địa chỉ: đếm 7 phong bì.', _utf8mb4 0x0a, _utf8mb4'封筒を数えました。封筒（　）7枚あります。'), _utf8mb4'が nêu vật hiện có; 7枚 là số lượng phong bì.', _utf8mb4'{"options":{"A":"より","B":"が","C":"へ","D":"まで"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', CONCAT(_utf8mb4'Làm bánh mì kẹp: đếm 14 lá xà lách.', _utf8mb4 0x0a, _utf8mb4'レタスの葉（　）14枚あります。'), _utf8mb4'が nêu vật hiện có; 14枚 là số lượng lá xà lách.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"が","D":"より"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'布が6枚あります。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như mảnh vải; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"Đã dùng hết 6 mảnh vải.","B":"Chỉ còn một nửa số mảnh vải đó.","C":"Có 6 mảnh vải.","D":"Cần thêm 6 mảnh vải."},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gói cơm nắm: đếm 13 lá rong biển.', _utf8mb4 0x0a, _utf8mb4'A「のりは何枚ありますか。」 B「（　）」'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như lá rong biển; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"のりは全部使いました。","B":"のりが14枚あります。","C":"のりがあと13枚必要です。","D":"のりが13枚あります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', CONCAT(_utf8mb4'Sắp va li: đếm 5 khăn tay.', _utf8mb4 0x0a, _utf8mb4'ハンカチが5（　）あります。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như khăn tay; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"枚","B":"本","C":"冊","D":"台"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gửi thư ra nước ngoài: đếm 12 tem.', _utf8mb4 0x0a, _utf8mb4'箱の中に切手（　）12枚入っています。'), _utf8mb4'が nêu vật hiện có; 12枚 là số lượng tem.', _utf8mb4'{"options":{"A":"へ","B":"より","C":"が","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ở bàn tiệc: đếm 4 khăn giấy ăn.', _utf8mb4 0x0a, _utf8mb4'紙ナプキンを数えました。紙ナプキン（　）4枚あります。'), _utf8mb4'が nêu vật hiện có; 4枚 là số lượng khăn giấy ăn.', _utf8mb4'{"options":{"A":"が","B":"まで","C":"より","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Sửa khung cửa: đếm 11 tấm kính.', _utf8mb4 0x0a, _utf8mb4'ガラス板（　）11枚あります。'), _utf8mb4'が nêu vật hiện có; 11枚 là số lượng tấm kính.', _utf8mb4'{"options":{"A":"より","B":"が","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm số giấy hiện có.', _utf8mb4 0x0a, _utf8mb4'机の上に答案用紙が一枚。先生が二枚足しました。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như tờ giấy trả lời; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"答案用紙があと3枚必要です。","B":"答案用紙が3枚あります。","C":"答案用紙が4枚あります。","D":"答案用紙は全部使いました。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm kê quầy thời trang: đếm 10 chân váy ngắn.', _utf8mb4 0x0a, _utf8mb4'短いスカートを数えました。短いスカート（　）10枚あります。'), _utf8mb4'が nêu vật hiện có; 10枚 là số lượng chân váy ngắn.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"が","D":"より"},"correctAnswer":"C"}'
    UNION ALL SELECT 1010, _utf8mb4'EASY', CONCAT(_utf8mb4'Tổ chức lễ cưới: đếm 2 thiệp mời.', _utf8mb4 0x0a, _utf8mb4'招待状（　）2枚あります。'), _utf8mb4'が nêu vật hiện có; 2枚 là số lượng thiệp mời.', _utf8mb4'{"options":{"A":"より","B":"が","C":"へ","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 1015, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chuẩn bị máy in: đếm 9 tờ giấy in.', _utf8mb4 0x0a, _utf8mb4'箱の中にコピー用紙（　）9枚入っています。'), _utf8mb4'が nêu vật hiện có; 9枚 là số lượng tờ giấy in.', _utf8mb4'{"options":{"A":"へ","B":"より","C":"まで","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1020, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chuẩn bị cho khách qua đêm: đếm 16 chăn.', _utf8mb4 0x0a, _utf8mb4'毛布は15枚ありました。一枚もらって、今は（　）です。'), _utf8mb4'一枚 thêm vào 15枚 thành 16枚; 枚 dùng cho chăn.', _utf8mb4'{"options":{"A":"15枚","B":"16枚","C":"16本","D":"17枚"},"correctAnswer":"B"}'
    UNION ALL SELECT 1025, _utf8mb4'EASY', CONCAT(_utf8mb4'Chuẩn bị bữa sáng: đếm 8 lát bánh mì.', _utf8mb4 0x0a, _utf8mb4'食パン（　）8枚あります。'), _utf8mb4'が nêu vật hiện có; 8枚 là số lượng lát bánh mì.', _utf8mb4'{"options":{"A":"で","B":"より","C":"へ","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1030, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đếm tổng số tấm ván mỏng.', _utf8mb4 0x0a, _utf8mb4'工作用の板は十枚と五枚の二束です。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như tấm ván mỏng; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"うすい板があと15枚必要です。","B":"うすい板が16枚あります。","C":"うすい板が15枚あります。","D":"うすい板は全部使いました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1035, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đăng ký thành viên: đếm 7 thẻ hội viên.', _utf8mb4 0x0a, _utf8mb4'A「会員カードは何枚ありますか。」 B「（　）」'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như thẻ hội viên; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"会員カードが7枚あります。","B":"会員カードは全部使いました。","C":"会員カードがあと7枚必要です。","D":"会員カードが8枚あります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1040, _utf8mb4'EASY', CONCAT(_utf8mb4'Ghi tên lên hộp: đếm 14 nhãn dán.', _utf8mb4 0x0a, _utf8mb4'ラベルが14（　）あります。'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như nhãn dán; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"枚","B":"本","C":"台","D":"冊"},"correctAnswer":"A"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ở quầy giặt: đếm 6 ga giường.', _utf8mb4 0x0a, _utf8mb4'A「シーツは何枚ありますか。」 B「（　）」'), _utf8mb4'枚（まい） đếm vật mỏng, phẳng như ga giường; số lượng đứng trước あります.', _utf8mb4'{"options":{"A":"シーツがあと6枚必要です。","B":"シーツは全部使いました。","C":"シーツが6枚あります。","D":"シーツが7枚あります。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Dọn bàn ăn: đếm 13 đĩa trắng.', _utf8mb4 0x0a, _utf8mb4'白い皿を数えました。白い皿（　）13枚あります。'), _utf8mb4'が nêu vật hiện có; 13枚 là số lượng đĩa trắng.', _utf8mb4'{"options":{"A":"へ","B":"が","C":"まで","D":"より"},"correctAnswer":"B"}'
    UNION ALL SELECT 2005, _utf8mb4'EASY', CONCAT(_utf8mb4'Chọn ảnh làm album: đếm 5 bức ảnh.', _utf8mb4 0x0a, _utf8mb4'写真（　）5枚あります。'), _utf8mb4'が nêu vật hiện có; 5枚 là số lượng bức ảnh.', _utf8mb4'{"options":{"A":"より","B":"へ","C":"で","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 2020, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trang trí hành lang: đếm 12 áp phích.', _utf8mb4 0x0a, _utf8mb4'箱の中にポスター（　）12枚入っています。'), _utf8mb4'が nêu vật hiện có; 12枚 là số lượng áp phích.', _utf8mb4'{"options":{"A":"が","B":"より","C":"まで","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2035, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trước khi lên tàu: đếm 4 vé xe.', _utf8mb4 0x0a, _utf8mb4'乗車券を数えました。乗車券（　）4枚あります。'), _utf8mb4'が nêu vật hiện có; 4枚 là số lượng vé xe.', _utf8mb4'{"options":{"A":"より","B":"へ","C":"が","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 2050, _utf8mb4'EASY', CONCAT(_utf8mb4'Thi vẽ ở trường: đếm 11 tờ giấy vẽ.', _utf8mb4 0x0a, _utf8mb4'画用紙（　）11枚あります。'), _utf8mb4'が nêu vật hiện có; 11枚 là số lượng tờ giấy vẽ.', _utf8mb4'{"options":{"A":"が","B":"より","C":"で","D":"へ"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 5 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N が số + 枚 あります。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 6 (N1 で N2 がいちばん Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Trong nhóm cây trong công viên, cây anh đào cao nhất.', _utf8mb4 0x0a, _utf8mb4'公園の木の中で桜の木（　）いちばん高いです。') AS content, _utf8mb4'が nêu đối tượng đứng đầu là 桜の木; いちばん cho biết mức cao nhất.' AS explanation, _utf8mb4'{"options":{"A":"へ","B":"から","C":"まで","D":"が"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm bàn trong lớp, bàn phía trước thấp nhất.', _utf8mb4 0x0a, _utf8mb4'A「この中で何がいちばん低いですか。」 B「（　）」'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 低い chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"後ろの机のほうが低いです。","B":"教室の机の中で前の机がいちばん低いです。","C":"前の机も後ろの机も同じくらい低いです。","D":"前の机と後ろの机と、どちらが低いですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm cửa tiệm trong phố, hiệu sách lâu đời nhất.', _utf8mb4 0x0a, _utf8mb4'町の店の中で本屋（　）いちばん古いです。'), _utf8mb4'が nêu đối tượng đứng đầu là 本屋; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"が","B":"から","C":"まで","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm ga chuyển tuyến, ga Đông tiện nhất.', _utf8mb4 0x0a, _utf8mb4'A「この中で何がいちばん便利ですか。」 B「（　）」'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 便利 chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"東駅も西駅も同じくらい便利です。","B":"東駅と西駅と、どちらが便利ですか。","C":"乗り換えの駅の中で東駅がいちばん便利です。","D":"西駅のほうが便利です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm khung giờ trực quầy, buổi sáng bận nhất.', _utf8mb4 0x0a, _utf8mb4'A「この中で何がいちばん忙しいですか。」 B「（　）」'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 忙しい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"受付の時間帯の中で午前がいちばん忙しいです。","B":"午前と夕方と、どちらが忙しいですか。","C":"午前も夕方も同じくらい忙しいです。","D":"夕方のほうが忙しいです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm giấy trong tiệm, giấy vẽ dày nhất.', _utf8mb4 0x0a, _utf8mb4'店の紙の中（　）絵の紙がいちばん厚いです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 店の紙.', _utf8mb4'{"options":{"A":"を","B":"から","C":"へ","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm tòa nhà trong thị trấn, thư viện mới nhất.', _utf8mb4 0x0a, _utf8mb4'町の建物の中で図書館（　）いちばん新しいです。'), _utf8mb4'が nêu đối tượng đứng đầu là 図書館; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"が","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm túi trong tiệm, túi nâu nhẹ nhất.', _utf8mb4 0x0a, _utf8mb4'A「この中で何がいちばん軽いですか。」 B「（　）」'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 軽い chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"茶色のかばんと白いかばんと、どちらが軽いですか。","B":"茶色のかばんも白いかばんも同じくらい軽いです。","C":"店のかばんの中で茶色のかばんがいちばん軽いです。","D":"白いかばんのほうが軽いです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm trận đấu tuần này, trận đấu hôm thứ Hai vui nhất.', _utf8mb4 0x0a, _utf8mb4'今週の試合の中で月曜の試合（　）いちばん楽しいです。'), _utf8mb4'が nêu đối tượng đứng đầu là 月曜の試合; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"まで","B":"から","C":"へ","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thích trượt tuyết nhất trong nhóm thể thao mùa đông.', _utf8mb4 0x0a, _utf8mb4'選ぶなら、冬のスポーツ（　）スキーがいちばん好きです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 冬のスポーツ.', _utf8mb4'{"options":{"A":"から","B":"を","C":"で","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'村の祭りの中で春祭りがいちばん有名です。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 有名 chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"lễ hội xuân chỉ hơi nổi tiếng.","B":"Trong nhóm lễ hội trong làng, lễ hội xuân đứng đầu về mức độ “nổi tiếng”.","C":"Người nói đang hỏi sự khác nhau.","D":"lễ hội xuân và lễ hội thu ngang nhau."},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm màu vẽ, màu vàng sáng nhất.', _utf8mb4 0x0a, _utf8mb4'絵の具の色の中（　）黄色がいちばん明るいです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 絵の具の色.', _utf8mb4'{"options":{"A":"を","B":"で","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhận xét mức cao nhất trong nhóm.', _utf8mb4 0x0a, _utf8mb4'学校行事の人気投票で、運動会が楽しさの一位でした。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 楽しい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"運動会も文化祭も同じくらい楽しいです。","B":"学校の行事の中で運動会がいちばん楽しいです。","C":"運動会と文化祭と、どちらが楽しいですか。","D":"文化祭のほうが楽しいです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm phương tiện đi học, xe đạp rẻ nhất.', _utf8mb4 0x0a, _utf8mb4'選ぶなら、通学の乗り物（　）自転車がいちばん安いです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 通学の乗り物.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"を","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm món buổi trưa, mì udon rẻ nhất.', _utf8mb4 0x0a, _utf8mb4'昼の料理の中でうどん（　）いちばん安いです。'), _utf8mb4'が nêu đối tượng đứng đầu là うどん; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"まで","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm tranh ở bảo tàng, tranh biển lớn nhất.', _utf8mb4 0x0a, _utf8mb4'A「この中で何がいちばん大きいですか。」 B「（　）」'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 大きい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"美術館の絵の中で海の絵がいちばん大きいです。","B":"海の絵も城の絵も同じくらい大きいです。","C":"海の絵と城の絵と、どちらが大きいですか。","D":"城の絵のほうが大きいです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm hành lý chuyến đi, lều nặng nhất.', _utf8mb4 0x0a, _utf8mb4'旅の荷物の中でテント（　）いちばん重いです。'), _utf8mb4'が nêu đối tượng đứng đầu là テント; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"が","B":"から","C":"まで","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm môn thi, toán khó nhất.', _utf8mb4 0x0a, _utf8mb4'試験の科目の中で数学が（　）難しいです。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 難しい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"同じくらい","B":"少し","C":"あまり","D":"いちばん"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'So sánh nhất theo khoảng cách.', _utf8mb4 0x0a, _utf8mb4'遠足の候補は三つ。湖だけ片道二時間、ほかは一時間以内です。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 遠い chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"湖と牧場と、どちらが遠いですか。","B":"湖も牧場も同じくらい遠いです。","C":"遠足の場所の中で湖がいちばん遠いです。","D":"牧場のほうが遠いです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thích mùa xuân nhất trong nhóm mùa đi du lịch.', _utf8mb4 0x0a, _utf8mb4'選ぶなら、旅行の季節（　）春がいちばん好きです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 旅行の季節.', _utf8mb4'{"options":{"A":"で","B":"へ","C":"を","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 1001, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm trái cây ở tiệm, dâu ngọt nhất.', _utf8mb4 0x0a, _utf8mb4'この店の果物の中でいちご（　）いちばん甘いです。'), _utf8mb4'が nêu đối tượng đứng đầu là いちご; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"まで","B":"が","C":"から","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1006, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm đường trong làng, đường ven sông rộng nhất.', _utf8mb4 0x0a, _utf8mb4'選ぶなら、村の道（　）川沿いの道がいちばん広いです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 村の道.', _utf8mb4'{"options":{"A":"で","B":"から","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1011, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm ga quanh đây, ga Nam gần nhất.', _utf8mb4 0x0a, _utf8mb4'近所の駅の中で南駅が（　）近いです。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 近い chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"同じくらい","B":"あまり","C":"少し","D":"いちばん"},"correctAnswer":"D"}'
    UNION ALL SELECT 1016, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm áo khoác trong tiệm, áo khoác xanh ấm nhất.', _utf8mb4 0x0a, _utf8mb4'店の上着の中（　）青い上着がいちばん暖かいです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 店の上着.', _utf8mb4'{"options":{"A":"を","B":"から","C":"で","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm các đường phố buổi sáng, phố trước ga náo nhiệt nhất.', _utf8mb4 0x0a, _utf8mb4'朝の道の中で駅前通り（　）いちばんにぎやかです。'), _utf8mb4'が nêu đối tượng đứng đầu là 駅前通り; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"まで","B":"が","C":"から","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1026, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nêu sở thích cao nhất trong nhóm.', _utf8mb4 0x0a, _utf8mb4'夏に飲む物を三つ選びました。私の一位は麦茶です。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 好き chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"麦茶とレモン水と、どちらが好きですか。","B":"麦茶もレモン水も同じくらい好きです。","C":"夏の飲み物の中で麦茶がいちばん好きです。","D":"レモン水のほうが好きです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1031, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm rau trong vườn, cải thảo to nhất.', _utf8mb4 0x0a, _utf8mb4'畑の野菜の中で白菜が（　）大きいです。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 大きい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"あまり","B":"同じくらい","C":"いちばん","D":"少し"},"correctAnswer":"C"}'
    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm cửa sổ trong nhà, cửa sổ nam nhỏ nhất.', _utf8mb4 0x0a, _utf8mb4'選ぶなら、家の窓（　）南の窓がいちばん小さいです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 家の窓.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"から","D":"で"},"correctAnswer":"D"}'
    UNION ALL SELECT 1041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm các phòng nhà trọ, phòng đông sáng nhất.', _utf8mb4 0x0a, _utf8mb4'旅館の部屋の中で東の部屋が（　）明るいです。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước 明るい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"いちばん","B":"同じくらい","C":"あまり","D":"少し"},"correctAnswer":"A"}'
    UNION ALL SELECT 1046, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm các câu trong sách, câu đầu ngắn nhất.', _utf8mb4 0x0a, _utf8mb4'教科書の文章の中（　）最初の文がいちばん短いです。'), _utf8mb4'で giới hạn phạm vi so sánh trong nhóm 教科書の文章.', _utf8mb4'{"options":{"A":"で","B":"を","C":"へ","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 2006, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trong nhóm công viên trong thị trấn, công viên Trung Tâm yên tĩnh nhất.', _utf8mb4 0x0a, _utf8mb4'町の公園の中で中央公園（　）いちばん静かです。'), _utf8mb4'が nêu đối tượng đứng đầu là 中央公園; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"から","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 2021, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn ý đúng với lời nói.', _utf8mb4 0x0a, _utf8mb4'給食のおかずの中で焼き魚がいちばんおいしいです。'), _utf8mb4'～の中で nêu phạm vi; いちばん trước おいしい chỉ mức cao nhất.', _utf8mb4'{"options":{"A":"cá nướng và trứng cuộn ngang nhau.","B":"Trong nhóm món trong suất ăn, cá nướng đứng đầu về mức độ “ngon”.","C":"cá nướng chỉ hơi ngon.","D":"Người nói đang hỏi sự khác nhau."},"correctAnswer":"B"}'
    UNION ALL SELECT 2036, _utf8mb4'EASY', CONCAT(_utf8mb4'Trong nhóm bài nhạc tập, bài hát ban mai dễ nhất.', _utf8mb4 0x0a, _utf8mb4'練習の曲の中で朝の歌（　）いちばん簡単です。'), _utf8mb4'が nêu đối tượng đứng đầu là 朝の歌; いちばん cho biết mức cao nhất.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"まで","D":"が"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 6 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 で N2 がいちばん Aです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 7 (N1 と N2 とどちらが Aですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Nhờ chọn giữa áo khoác xanh và áo khoác đỏ.', _utf8mb4 0x0a, _utf8mb4'青い上着と赤い上着を比べます。（　）が暖かいですか。') AS content, _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.' AS explanation, _utf8mb4'{"options":{"A":"だれ","B":"いくら","C":"どちら","D":"いつ"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa phố trước ga và đường ven biển.', _utf8mb4 0x0a, _utf8mb4'駅前通り（　）海岸通りと、どちらがにぎやかですか。'), _utf8mb4'と nối hai lựa chọn 駅前通り và 海岸通り trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"から","B":"を","C":"と","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa trà lúa mạch và nước chanh.', _utf8mb4 0x0a, _utf8mb4'麦茶とレモン水と、どちら（　）好きですか。'), _utf8mb4'が sau どちら đánh dấu đối tượng cần xác định trong phép so sánh hai bên.', _utf8mb4'{"options":{"A":"が","B":"まで","C":"へ","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa cải thảo và củ cải.', _utf8mb4 0x0a, _utf8mb4'白菜（　）大根と、どちらが大きいですか。'), _utf8mb4'と nối hai lựa chọn 白菜 và 大根 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"と","B":"から","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa cửa sổ nam và cửa sổ bắc.', _utf8mb4 0x0a, _utf8mb4'南の窓と北の窓（　）どちらが小さいですか。'), _utf8mb4'と nối hai lựa chọn 南の窓 và 北の窓 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"まで","B":"と","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa phòng đông và phòng tây.', _utf8mb4 0x0a, _utf8mb4'東の部屋（　）西の部屋と、どちらが明るいですか。'), _utf8mb4'と nối hai lựa chọn 東の部屋 và 西の部屋 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"を","B":"と","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa câu đầu và câu cuối.', _utf8mb4 0x0a, _utf8mb4'最初の文と最後の文と、どちら（　）短いですか。'), _utf8mb4'が sau どちら đánh dấu đối tượng cần xác định trong phép so sánh hai bên.', _utf8mb4'{"options":{"A":"まで","B":"が","C":"から","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa công viên Trung Tâm và công viên Nam.', _utf8mb4 0x0a, _utf8mb4'中央公園と南公園と、（　）が静かですか。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"いくら","B":"だれ","C":"どちら","D":"いつ"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa cá nướng và trứng cuộn.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「焼き魚のほうがおいしいです。」'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"焼き魚のほうがおいしいです。","B":"焼き魚も卵焼きもおいしいです。","C":"焼き魚と卵焼きと、どちらがおいしいですか。","D":"卵焼きのほうがおいしいです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa bài hát ban mai và bài hát ngôi sao.', _utf8mb4 0x0a, _utf8mb4'朝の歌（　）星の歌と、どちらが簡単ですか。'), _utf8mb4'と nối hai lựa chọn 朝の歌 và 星の歌 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"と","B":"から","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa bãi đông và bãi nam.', _utf8mb4 0x0a, _utf8mb4'東の浜と南の浜と、どちら（　）きれいですか。'), _utf8mb4'が sau どちら đánh dấu đối tượng cần xác định trong phép so sánh hai bên.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"まで","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ so sánh hai món.', _utf8mb4 0x0a, _utf8mb4'赤いスープと白いスープがあります。辛さはまだ知りません。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"赤いスープも白いスープも辛いです。","B":"白いスープのほうが辛いです。","C":"赤いスープのほうが辛いです。","D":"赤いスープと白いスープと、どちらが辛いですか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'はさみとものさしと、どちらが長いですか。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"Hỏi giữa kéo và thước, bên nào dài hơn.","B":"Nói kéo chắc chắn dài hơn.","C":"Hỏi số lượng của cả hai.","D":"Khẳng định cả hai đều dài."},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa cây anh đào và cây thông.', _utf8mb4 0x0a, _utf8mb4'桜の木（　）松の木と、どちらが高いですか。'), _utf8mb4'と nối hai lựa chọn 桜の木 và 松の木 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"と","B":"から","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'前の机と後ろの机と、どちらが低いですか。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"Nói bàn phía trước chắc chắn thấp hơn.","B":"Hỏi giữa bàn phía trước và bàn phía sau, bên nào thấp hơn.","C":"Khẳng định cả hai đều thấp.","D":"Hỏi số lượng của cả hai."},"correctAnswer":"B"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa hiệu sách và tiệm bánh.', _utf8mb4 0x0a, _utf8mb4'本屋（　）パン屋と、どちらが古いですか。'), _utf8mb4'と nối hai lựa chọn 本屋 và パン屋 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"を","B":"から","C":"へ","D":"と"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa ga Đông và ga Tây.', _utf8mb4 0x0a, _utf8mb4'東駅と西駅（　）どちらが便利ですか。'), _utf8mb4'と nối hai lựa chọn 東駅 và 西駅 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"を","D":"と"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa buổi sáng và chiều tối.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「午前のほうが忙しいです。」'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"夕方のほうが忙しいです。","B":"午前と夕方と、どちらが忙しいですか。","C":"午前のほうが忙しいです。","D":"午前も夕方も忙しいです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa giấy vẽ và giấy viết thư.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「絵の紙のほうが厚いです。」'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"絵の紙のほうが厚いです。","B":"絵の紙も手紙の紙も厚いです。","C":"手紙の紙のほうが厚いです。","D":"絵の紙と手紙の紙と、どちらが厚いですか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa thư viện và tòa thị chính.', _utf8mb4 0x0a, _utf8mb4'図書館（　）市役所と、どちらが新しいですか。'), _utf8mb4'と nối hai lựa chọn 図書館 và 市役所 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"を","B":"から","C":"と","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1002, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi chiếc nào nhẹ hơn.', _utf8mb4 0x0a, _utf8mb4'旅行用の茶色と白のかばんを手に取りました。重さはまだ不明です。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"茶色のかばんのほうが軽いです。","B":"茶色のかばんと白いかばんと、どちらが軽いですか。","C":"白いかばんのほうが軽いです。","D":"茶色のかばんも白いかばんも軽いです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa trận đấu hôm thứ Hai và trận đấu hôm thứ Sáu.', _utf8mb4 0x0a, _utf8mb4'月曜の試合（　）金曜の試合と、どちらが楽しいですか。'), _utf8mb4'と nối hai lựa chọn 月曜の試合 và 金曜の試合 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"を","D":"と"},"correctAnswer":"D"}'
    UNION ALL SELECT 1012, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa trượt tuyết và trượt băng.', _utf8mb4 0x0a, _utf8mb4'スキーとスケートと、（　）が好きですか。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"どちら","B":"いつ","C":"いくら","D":"だれ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa lễ hội xuân và lễ hội thu.', _utf8mb4 0x0a, _utf8mb4'春祭り（　）秋祭りと、どちらが有名ですか。'), _utf8mb4'と nối hai lựa chọn 春祭り và 秋祭り trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"へ","B":"と","C":"から","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 1022, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa màu vàng và màu xanh lá.', _utf8mb4 0x0a, _utf8mb4'黄色と緑（　）どちらが明るいですか。'), _utf8mb4'と nối hai lựa chọn 黄色 và 緑 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"と","B":"を","C":"へ","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 1027, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa hội thao và hội văn hóa.', _utf8mb4 0x0a, _utf8mb4'運動会（　）文化祭と、どちらが楽しいですか。'), _utf8mb4'と nối hai lựa chọn 運動会 và 文化祭 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"から","B":"を","C":"と","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa xe đạp và xe buýt.', _utf8mb4 0x0a, _utf8mb4'自転車とバスと、どちら（　）安いですか。'), _utf8mb4'が sau どちら đánh dấu đối tượng cần xác định trong phép so sánh hai bên.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"が","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 1037, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa mì udon và mì soba.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「うどんのほうが安いです。」'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"そばのほうが安いです。","B":"うどんのほうが安いです。","C":"うどんもそばも安いです。","D":"うどんとそばと、どちらが安いですか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1042, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa tranh biển và tranh lâu đài.', _utf8mb4 0x0a, _utf8mb4'海の絵と城の絵（　）どちらが大きいですか。'), _utf8mb4'と nối hai lựa chọn 海の絵 và 城の絵 trước câu hỏi どちらが.', _utf8mb4'{"options":{"A":"へ","B":"と","C":"を","D":"まで"},"correctAnswer":"B"}'
    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi để so sánh đúng hai vật.', _utf8mb4 0x0a, _utf8mb4'二人でテントと寝袋を運びます。重さを知りたいです。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"テントと寝袋と、どちらが重いですか。","B":"寝袋のほうが重いです。","C":"テントのほうが重いです。","D":"テントも寝袋も重いです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2007, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa toán và tiếng Anh.', _utf8mb4 0x0a, _utf8mb4'数学と英語と、どちら（　）難しいですか。'), _utf8mb4'が sau どちら đánh dấu đối tượng cần xác định trong phép so sánh hai bên.', _utf8mb4'{"options":{"A":"へ","B":"が","C":"から","D":"まで"},"correctAnswer":"B"}'
    UNION ALL SELECT 2022, _utf8mb4'EASY', CONCAT(_utf8mb4'Nhờ chọn giữa hồ và trang trại.', _utf8mb4 0x0a, _utf8mb4'湖と牧場と、（　）が遠いですか。'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"いくら","B":"だれ","C":"いつ","D":"どちら"},"correctAnswer":"D"}'
    UNION ALL SELECT 2037, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhờ chọn giữa mùa xuân và mùa thu.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「春のほうが好きです。」'), _utf8mb4'どちらが dùng để hỏi bên nào có đặc điểm được nêu khi so sánh hai lựa chọn.', _utf8mb4'{"options":{"A":"春も秋も好きです。","B":"秋のほうが好きです。","C":"春と秋と、どちらが好きですか。","D":"春のほうが好きです。"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 7 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 と N2 とどちらが Aですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 8 (N のほうが Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Chọn bên nổi tiếng hơn.', _utf8mb4 0x0a, _utf8mb4'春祭りには全国から人が来ます。秋祭りは村の人だけです。') AS content, _utf8mb4'N のほうが nêu bên trội hơn trong phép so sánh hai đối tượng; ở đây là 春祭り.' AS explanation, _utf8mb4'{"options":{"A":"春祭りのほうが有名です。","B":"秋祭りのほうが有名です。","C":"どちらが有名ですか。","D":"春祭りも秋祭りも同じくらい有名です。"},"correctAnswer":"A"}' AS answers
