    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chọn ý đúng với lời nói.', _utf8mb4 0x0a, _utf8mb4'最初の文と最後の文を比べます。最初の文のほうが短いです。'), _utf8mb4'N のほうが nêu bên trội hơn trong phép so sánh hai đối tượng; ở đây là 最初の文.', _utf8mb4'{"options":{"A":"Hai bên ngang nhau.","B":"Giữa câu đầu và câu cuối, tôi chọn câu đầu là bên ngắn hơn.","C":"Hỏi bên nào ngắn hơn.","D":"Chỉ câu cuối có đặc điểm này."},"correctAnswer":"B"}'
    UNION ALL SELECT 1003, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xét hai bên, công viên Trung Tâm yên tĩnh hơn.', _utf8mb4 0x0a, _utf8mb4'中央公園のほう（　）静かです。'), _utf8mb4'が đánh dấu bên trội hơn sau 中央公園のほう.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"を","D":"が"},"correctAnswer":"D"}'
