    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xét hai bên, ga Đông tiện hơn.', _utf8mb4 0x0a, _utf8mb4'東駅（　）ほうが便利です。'), _utf8mb4'の nối danh từ 東駅 với ほう để chỉ bên được chọn trong hai bên.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 2008, _utf8mb4'EASY', CONCAT(_utf8mb4'Xét hai bên, buổi sáng bận hơn.', _utf8mb4 0x0a, _utf8mb4'午前のほう（　）忙しいです。'), _utf8mb4'が đánh dấu bên trội hơn sau 午前のほう.', _utf8mb4'{"options":{"A":"が","B":"へ","C":"から","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 2023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xét hai bên, giấy vẽ dày hơn.', _utf8mb4 0x0a, _utf8mb4'絵の紙（　）ほうが厚いです。'), _utf8mb4'の nối danh từ 絵の紙 với ほう để chỉ bên được chọn trong hai bên.', _utf8mb4'{"options":{"A":"から","B":"を","C":"へ","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 2038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'図書館と市役所を比べます。図書館のほうが新しいです。'), _utf8mb4'N のほうが nêu bên trội hơn trong phép so sánh hai đối tượng; ở đây là 図書館.', _utf8mb4'{"options":{"A":"Hai bên ngang nhau.","B":"Chỉ tòa thị chính có đặc điểm này.","C":"Giữa thư viện và tòa thị chính, tôi chọn thư viện là bên mới hơn.","D":"Hỏi bên nào mới hơn."},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 8 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N のほうが Aです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 9 (どちらも Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Khen chung cả hai bãi biển.', _utf8mb4 0x0a, _utf8mb4'東の浜にも南の浜にも、ごみ一つありません。') AS content, _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm きれい.' AS explanation, _utf8mb4'{"options":{"A":"東の浜と南の浜ですか。どちらもきれいです。","B":"東の浜より南の浜のほうがきれいです。","C":"東の浜だけがきれいです。","D":"南の浜だけがきれいです。"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều cay: súp đỏ và súp trắng.', _utf8mb4 0x0a, _utf8mb4'赤いスープと白いスープは、（　）辛いです。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 辛い.', _utf8mb4'{"options":{"A":"赤いスープだけが","B":"どちらが","C":"白いスープのほうが","D":"どちらも"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều dài: kéo và thước.', _utf8mb4 0x0a, _utf8mb4'はさみですか、ものさしですか。私はどちら（　）長いと思います。'), _utf8mb4'も sau どちら cho biết cả はさみ và ものさし đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"も","C":"から","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều cao: cây anh đào và cây thông.', _utf8mb4 0x0a, _utf8mb4'桜の木と松の木は、どちら（　）高いです。'), _utf8mb4'も sau どちら cho biết cả 桜の木 và 松の木 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"を","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'前の机と後ろの机ですか。前の机と後ろの机ですか。どちらも低いです。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 低い.', _utf8mb4'{"options":{"A":"Hỏi nên chọn bên nào.","B":"Cả bàn phía trước và bàn phía sau đều thấp.","C":"bàn phía sau thấp hơn.","D":"Chỉ bàn phía trước có đặc điểm đó."},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều lâu đời: hiệu sách và tiệm bánh.', _utf8mb4 0x0a, _utf8mb4'本屋ですか、パン屋ですか。私はどちら（　）古いと思います。'), _utf8mb4'も sau どちら cho biết cả 本屋 và パン屋 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"も","C":"から","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều tiện: ga Đông và ga Tây.', _utf8mb4 0x0a, _utf8mb4'A「東駅と西駅と、どちらが便利ですか。」 B「（　）」'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 便利.', _utf8mb4'{"options":{"A":"東駅より西駅のほうが便利です。","B":"東駅だけが便利です。","C":"東駅と西駅ですか。どちらも便利です。","D":"西駅だけが便利です。"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều bận: buổi sáng và chiều tối.', _utf8mb4 0x0a, _utf8mb4'A「午前と夕方と、どちらが忙しいですか。」 B「（　）」'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 忙しい.', _utf8mb4'{"options":{"A":"夕方だけが忙しいです。","B":"午前だけが忙しいです。","C":"午前より夕方のほうが忙しいです。","D":"午前と夕方ですか。どちらも忙しいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều dày: giấy vẽ và giấy viết thư.', _utf8mb4 0x0a, _utf8mb4'絵の紙ですか、手紙の紙ですか。私はどちら（　）厚いと思います。'), _utf8mb4'も sau どちら cho biết cả 絵の紙 và 手紙の紙 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"から","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều mới: thư viện và tòa thị chính.', _utf8mb4 0x0a, _utf8mb4'図書館と市役所は、どちら（　）新しいです。'), _utf8mb4'も sau どちら cho biết cả 図書館 và 市役所 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"も","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều nhẹ: túi nâu và túi trắng.', _utf8mb4 0x0a, _utf8mb4'A「茶色のかばんと白いかばんと、どちらが軽いですか。」 B「（　）」'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 軽い.', _utf8mb4'{"options":{"A":"茶色のかばんと白いかばんですか。どちらも軽いです。","B":"茶色のかばんだけが軽いです。","C":"白いかばんだけが軽いです。","D":"茶色のかばんより白いかばんのほうが軽いです。"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều vui: trận đấu hôm thứ Hai và trận đấu hôm thứ Sáu.', _utf8mb4 0x0a, _utf8mb4'月曜の試合ですか、金曜の試合ですか。私はどちら（　）楽しいと思います。'), _utf8mb4'も sau どちら cho biết cả 月曜の試合 và 金曜の試合 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"も","C":"を","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thích cả trượt tuyết lẫn trượt băng.', _utf8mb4 0x0a, _utf8mb4'A「スキーとスケートと、どちらが好きですか。」 B「（　）」'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 好き.', _utf8mb4'{"options":{"A":"スケートだけが好きです。","B":"スキーよりスケートのほうが好きです。","C":"スキーだけが好きです。","D":"スキーとスケートですか。どちらも好きです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều nổi tiếng: lễ hội xuân và lễ hội thu.', _utf8mb4 0x0a, _utf8mb4'A「春祭りと秋祭りと、どちらが有名ですか。」 B「（　）」'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 有名.', _utf8mb4'{"options":{"A":"春祭りと秋祭りですか。どちらも有名です。","B":"春祭りだけが有名です。","C":"秋祭りだけが有名です。","D":"春祭りより秋祭りのほうが有名です。"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều sáng: màu vàng và màu xanh lá.', _utf8mb4 0x0a, _utf8mb4'黄色ですか、緑ですか。私はどちら（　）明るいと思います。'), _utf8mb4'も sau どちら cho biết cả 黄色 và 緑 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"を","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trả lời rằng cả hai đều vui.', _utf8mb4 0x0a, _utf8mb4'運動会でも文化祭でも、友達と心から楽しみました。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 楽しい.', _utf8mb4'{"options":{"A":"運動会より文化祭のほうが楽しいです。","B":"文化祭だけが楽しいです。","C":"運動会と文化祭ですか。どちらも楽しいです。","D":"運動会だけが楽しいです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều rẻ: xe đạp và xe buýt.', _utf8mb4 0x0a, _utf8mb4'自転車とバスは、（　）安いです。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 安い.', _utf8mb4'{"options":{"A":"自転車だけが","B":"どちらも","C":"バスのほうが","D":"どちらが"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều rẻ: mì udon và mì soba.', _utf8mb4 0x0a, _utf8mb4'うどんですか、そばですか。私はどちら（　）安いと思います。'), _utf8mb4'も sau どちら cho biết cả うどん và そば đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"も","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều lớn: tranh biển và tranh lâu đài.', _utf8mb4 0x0a, _utf8mb4'海の絵と城の絵は、どちら（　）大きいです。'), _utf8mb4'も sau どちら cho biết cả 海の絵 và 城の絵 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"も","B":"から","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều nặng: lều và túi ngủ.', _utf8mb4 0x0a, _utf8mb4'「テントと寝袋では？」「二つとも試しました。どちら（　）重いです。」'), _utf8mb4'も sau どちら cho biết cả テント và 寝袋 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"まで","C":"も","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 1004, _utf8mb4'EASY', CONCAT(_utf8mb4'Hai bên đều khó: toán và tiếng Anh.', _utf8mb4 0x0a, _utf8mb4'数学ですか、英語ですか。私はどちら（　）難しいと思います。'), _utf8mb4'も sau どちら cho biết cả 数学 và 英語 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"から","B":"も","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều xa: hồ và trang trại.', _utf8mb4 0x0a, _utf8mb4'湖と牧場は、（　）遠いです。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 遠い.', _utf8mb4'{"options":{"A":"どちらが","B":"湖だけが","C":"どちらも","D":"牧場のほうが"},"correctAnswer":"C"}'
    UNION ALL SELECT 1014, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thích cả mùa xuân lẫn mùa thu.', _utf8mb4 0x0a, _utf8mb4'「春と秋では？」「二つとも試しました。どちら（　）好きです。」'), _utf8mb4'も sau どちら cho biết cả 春 và 秋 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"まで","B":"から","C":"へ","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 1019, _utf8mb4'EASY', CONCAT(_utf8mb4'Hai bên đều ngọt: dâu và táo.', _utf8mb4 0x0a, _utf8mb4'いちごですか、りんごですか。私はどちら（　）甘いと思います。'), _utf8mb4'も sau どちら cho biết cả いちご và りんご đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"も","B":"から","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1024, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều rộng: đường ven sông và đường núi.', _utf8mb4 0x0a, _utf8mb4'川沿いの道と山道は、どちら（　）広いです。'), _utf8mb4'も sau どちら cho biết cả 川沿いの道 và 山道 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"を","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 1029, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều gần: ga Nam và ga Bắc.', _utf8mb4 0x0a, _utf8mb4'「南駅と北駅では？」「二つとも試しました。どちら（　）近いです。」'), _utf8mb4'も sau どちら cho biết cả 南駅 và 北駅 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"も","B":"まで","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1034, _utf8mb4'EASY', CONCAT(_utf8mb4'Hai bên đều ấm: áo khoác xanh và áo khoác đỏ.', _utf8mb4 0x0a, _utf8mb4'青い上着ですか、赤い上着ですか。私はどちら（　）暖かいと思います。'), _utf8mb4'も sau どちら cho biết cả 青い上着 và 赤い上着 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"から","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 1039, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hai bên đều náo nhiệt: phố trước ga và đường ven biển.', _utf8mb4 0x0a, _utf8mb4'駅前通りと海岸通りは、どちら（　）にぎやかです。'), _utf8mb4'も sau どちら cho biết cả 駅前通り và 海岸通り đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"を","B":"から","C":"も","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1044, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thích cả trà lúa mạch lẫn nước chanh.', _utf8mb4 0x0a, _utf8mb4'「麦茶とレモン水では？」「二つとも試しました。どちら（　）好きです。」'), _utf8mb4'も sau どちら cho biết cả 麦茶 và レモン水 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"まで","D":"も"},"correctAnswer":"D"}'
    UNION ALL SELECT 1049, _utf8mb4'EASY', CONCAT(_utf8mb4'Hai bên đều to: cải thảo và củ cải.', _utf8mb4 0x0a, _utf8mb4'白菜と大根は、（　）大きいです。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 大きい.', _utf8mb4'{"options":{"A":"どちらが","B":"どちらも","C":"白菜だけが","D":"大根のほうが"},"correctAnswer":"B"}'
    UNION ALL SELECT 2009, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'南の窓と北の窓ですか。南の窓と北の窓ですか。どちらも小さいです。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 小さい.', _utf8mb4'{"options":{"A":"Chỉ cửa sổ nam có đặc điểm đó.","B":"Cả cửa sổ nam và cửa sổ bắc đều nhỏ.","C":"Hỏi nên chọn bên nào.","D":"cửa sổ bắc nhỏ hơn."},"correctAnswer":"B"}'
    UNION ALL SELECT 2024, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhận xét chung cả hai phòng.', _utf8mb4 0x0a, _utf8mb4'東の部屋にも西の部屋にも日がよく入ります。'), _utf8mb4'どちらも khẳng định cả hai cùng có đặc điểm 明るい.', _utf8mb4'{"options":{"A":"東の部屋より西の部屋のほうが明るいです。","B":"西の部屋だけが明るいです。","C":"東の部屋と西の部屋ですか。どちらも明るいです。","D":"東の部屋だけが明るいです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2039, _utf8mb4'EASY', CONCAT(_utf8mb4'Hai bên đều ngắn: câu đầu và câu cuối.', _utf8mb4 0x0a, _utf8mb4'最初の文ですか、最後の文ですか。私はどちら（　）短いと思います。'), _utf8mb4'も sau どちら cho biết cả 最初の文 và 最後の文 đều có cùng đặc điểm.', _utf8mb4'{"options":{"A":"も","B":"へ","C":"から","D":"を"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 9 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'どちらも Aです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 10 (N1 は N2 より Aです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Dâu ngọt hơn táo.', _utf8mb4 0x0a, _utf8mb4'いちごとりんごを比べると、いちごはりんご（　）甘いです。') AS content, _utf8mb4'より đánh dấu mốc so sánh りんご; đối tượng có mức độ cao hơn là いちご.' AS explanation, _utf8mb4'{"options":{"A":"まで","B":"から","C":"より","D":"へ"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Đường ven sông rộng hơn đường núi.', _utf8mb4 0x0a, _utf8mb4'川沿いの道は山道（　）広いです。'), _utf8mb4'より đánh dấu mốc so sánh 山道; đối tượng có mức độ cao hơn là 川沿いの道.', _utf8mb4'{"options":{"A":"より","B":"へ","C":"まで","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Ga Nam gần hơn ga Bắc.', _utf8mb4 0x0a, _utf8mb4'南駅は北駅（　）近いです。'), _utf8mb4'より đánh dấu mốc so sánh 北駅; đối tượng có mức độ cao hơn là 南駅.', _utf8mb4'{"options":{"A":"まで","B":"から","C":"へ","D":"より"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Áo khoác xanh ấm hơn áo khoác đỏ.', _utf8mb4 0x0a, _utf8mb4'A「二つを比べると、どうですか。」 B「（　）」'), _utf8mb4'より đánh dấu mốc so sánh 赤い上着; đối tượng có mức độ cao hơn là 青い上着.', _utf8mb4'{"options":{"A":"どちらが暖かいですか。","B":"青い上着は赤い上着より暖かいです。","C":"青い上着と赤い上着は同じくらい暖かいです。","D":"赤い上着は青い上着より暖かいです。"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Phố trước ga náo nhiệt hơn đường ven biển.', _utf8mb4 0x0a, _utf8mb4'駅前通りは海岸通り（　）にぎやかです。'), _utf8mb4'より đánh dấu mốc so sánh 海岸通り; đối tượng có mức độ cao hơn là 駅前通り.', _utf8mb4'{"options":{"A":"だけ","B":"ほどは","C":"と同じくらい","D":"より"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Tôi thích trà lúa mạch hơn nước chanh.', _utf8mb4 0x0a, _utf8mb4'麦茶はレモン水（　）好きです。'), _utf8mb4'より đánh dấu mốc so sánh レモン水; đối tượng có mức độ cao hơn là 麦茶.', _utf8mb4'{"options":{"A":"まで","B":"から","C":"へ","D":"より"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'So kích thước, lấy củ cải làm mốc.', _utf8mb4 0x0a, _utf8mb4'白菜は大きい箱にしか入りません。大根は小さい箱に入ります。'), _utf8mb4'より đánh dấu mốc so sánh 大根; đối tượng có mức độ cao hơn là 白菜.', _utf8mb4'{"options":{"A":"大根は白菜より大きいです。","B":"白菜と大根は同じくらい大きいです。","C":"どちらが大きいですか。","D":"白菜は大根より大きいです。"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Cửa sổ nam nhỏ hơn cửa sổ bắc.', _utf8mb4 0x0a, _utf8mb4'南の窓は北の窓（　）小さいです。'), _utf8mb4'より đánh dấu mốc so sánh 北の窓; đối tượng có mức độ cao hơn là 南の窓.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"より","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Phòng đông sáng hơn phòng tây.', _utf8mb4 0x0a, _utf8mb4'東の部屋は西の部屋（　）明るいです。'), _utf8mb4'より đánh dấu mốc so sánh 西の部屋; đối tượng có mức độ cao hơn là 東の部屋.', _utf8mb4'{"options":{"A":"だけ","B":"より","C":"と同じくらい","D":"ほどは"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu đầu ngắn hơn câu cuối.', _utf8mb4 0x0a, _utf8mb4'A「二つを比べると、どうですか。」 B「（　）」'), _utf8mb4'より đánh dấu mốc so sánh 最後の文; đối tượng có mức độ cao hơn là 最初の文.', _utf8mb4'{"options":{"A":"最初の文と最後の文は同じくらい短いです。","B":"最初の文は最後の文より短いです。","C":"最後の文は最初の文より短いです。","D":"どちらが短いですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Công viên Trung Tâm yên tĩnh hơn công viên Nam.', _utf8mb4 0x0a, _utf8mb4'中央公園は南公園（　）静かです。'), _utf8mb4'より đánh dấu mốc so sánh 南公園; đối tượng có mức độ cao hơn là 中央公園.', _utf8mb4'{"options":{"A":"へ","B":"より","C":"から","D":"まで"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cá nướng ngon hơn trứng cuộn.', _utf8mb4 0x0a, _utf8mb4'焼き魚は卵焼き（　）おいしいです。'), _utf8mb4'より đánh dấu mốc so sánh 卵焼き; đối tượng có mức độ cao hơn là 焼き魚.', _utf8mb4'{"options":{"A":"へ","B":"まで","C":"より","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Bài hát ban mai dễ hơn bài hát ngôi sao.', _utf8mb4 0x0a, _utf8mb4'朝の歌と星の歌を比べると、朝の歌は星の歌（　）簡単です。'), _utf8mb4'より đánh dấu mốc so sánh 星の歌; đối tượng có mức độ cao hơn là 朝の歌.', _utf8mb4'{"options":{"A":"より","B":"から","C":"へ","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', CONCAT(_utf8mb4'Bãi đông đẹp hơn bãi nam.', _utf8mb4 0x0a, _utf8mb4'東の浜は南の浜（　）きれいです。'), _utf8mb4'より đánh dấu mốc so sánh 南の浜; đối tượng có mức độ cao hơn là 東の浜.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"まで","D":"より"},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Súp đỏ cay hơn súp trắng.', _utf8mb4 0x0a, _utf8mb4'赤いスープは白いスープ（　）辛いです。'), _utf8mb4'より đánh dấu mốc so sánh 白いスープ; đối tượng có mức độ cao hơn là 赤いスープ.', _utf8mb4'{"options":{"A":"まで","B":"へ","C":"より","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kéo dài hơn thước.', _utf8mb4 0x0a, _utf8mb4'はさみとものさしを比べると、はさみはものさし（　）長いです。'), _utf8mb4'より đánh dấu mốc so sánh ものさし; đối tượng có mức độ cao hơn là はさみ.', _utf8mb4'{"options":{"A":"へ","B":"まで","C":"より","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Cây anh đào cao hơn cây thông.', _utf8mb4 0x0a, _utf8mb4'桜の木は松の木（　）高いです。'), _utf8mb4'より đánh dấu mốc so sánh 松の木; đối tượng có mức độ cao hơn là 桜の木.', _utf8mb4'{"options":{"A":"より","B":"と同じくらい","C":"だけ","D":"ほどは"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nói bàn nào thấp hơn.', _utf8mb4 0x0a, _utf8mb4'前の机は高さ六十センチ。後ろの机は七十センチです。'), _utf8mb4'より đánh dấu mốc so sánh 後ろの机; đối tượng có mức độ cao hơn là 前の机.', _utf8mb4'{"options":{"A":"前の机と後ろの机は同じくらい低いです。","B":"前の机は後ろの机より低いです。","C":"後ろの机は前の机より低いです。","D":"どちらが低いですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'本屋はパン屋より古いです。'), _utf8mb4'より đánh dấu mốc so sánh パン屋; đối tượng có mức độ cao hơn là 本屋.', _utf8mb4'{"options":{"A":"Hiệu sách lâu đời hơn tiệm bánh.","B":"Hai bên ngang nhau.","C":"tiệm bánh lâu đời hơn hiệu sách.","D":"Chưa xác định được bên nào lâu đời hơn."},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Ga Đông tiện hơn ga Tây.', _utf8mb4 0x0a, _utf8mb4'東駅は西駅（　）便利です。'), _utf8mb4'より đánh dấu mốc so sánh 西駅; đối tượng có mức độ cao hơn là 東駅.', _utf8mb4'{"options":{"A":"より","B":"まで","C":"から","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1005, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Buổi sáng bận hơn chiều tối.', _utf8mb4 0x0a, _utf8mb4'午前は夕方（　）忙しいです。'), _utf8mb4'より đánh dấu mốc so sánh 夕方; đối tượng có mức độ cao hơn là 午前.', _utf8mb4'{"options":{"A":"より","B":"から","C":"まで","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1010, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Giấy vẽ dày hơn giấy viết thư.', _utf8mb4 0x0a, _utf8mb4'絵の紙と手紙の紙を比べると、絵の紙は手紙の紙（　）厚いです。'), _utf8mb4'より đánh dấu mốc so sánh 手紙の紙; đối tượng có mức độ cao hơn là 絵の紙.', _utf8mb4'{"options":{"A":"から","B":"へ","C":"まで","D":"より"},"correctAnswer":"D"}'
    UNION ALL SELECT 1015, _utf8mb4'EASY', CONCAT(_utf8mb4'Thư viện mới hơn tòa thị chính.', _utf8mb4 0x0a, _utf8mb4'図書館は市役所（　）新しいです。'), _utf8mb4'より đánh dấu mốc so sánh 市役所; đối tượng có mức độ cao hơn là 図書館.', _utf8mb4'{"options":{"A":"へ","B":"より","C":"まで","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1020, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Túi nâu nhẹ hơn túi trắng.', _utf8mb4 0x0a, _utf8mb4'A「二つを比べると、どうですか。」 B「（　）」'), _utf8mb4'より đánh dấu mốc so sánh 白いかばん; đối tượng có mức độ cao hơn là 茶色のかばん.', _utf8mb4'{"options":{"A":"茶色のかばんは白いかばんより軽いです。","B":"茶色のかばんと白いかばんは同じくらい軽いです。","C":"白いかばんは茶色のかばんより軽いです。","D":"どちらが軽いですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Trận đấu hôm thứ Hai vui hơn trận đấu hôm thứ Sáu.', _utf8mb4 0x0a, _utf8mb4'A「二つを比べると、どうですか。」 B「（　）」'), _utf8mb4'より đánh dấu mốc so sánh 金曜の試合; đối tượng có mức độ cao hơn là 月曜の試合.', _utf8mb4'{"options":{"A":"どちらが楽しいですか。","B":"月曜の試合と金曜の試合は同じくらい楽しいです。","C":"月曜の試合は金曜の試合より楽しいです。","D":"金曜の試合は月曜の試合より楽しいです。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1030, _utf8mb4'EASY', CONCAT(_utf8mb4'Tôi thích trượt tuyết hơn trượt băng.', _utf8mb4 0x0a, _utf8mb4'スキーはスケート（　）好きです。'), _utf8mb4'より đánh dấu mốc so sánh スケート; đối tượng có mức độ cao hơn là スキー.', _utf8mb4'{"options":{"A":"まで","B":"より","C":"へ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1035, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Lễ hội xuân nổi tiếng hơn lễ hội thu.', _utf8mb4 0x0a, _utf8mb4'A「二つを比べると、どうですか。」 B「（　）」'), _utf8mb4'より đánh dấu mốc so sánh 秋祭り; đối tượng có mức độ cao hơn là 春祭り.', _utf8mb4'{"options":{"A":"秋祭りは春祭りより有名です。","B":"春祭りと秋祭りは同じくらい有名です。","C":"どちらが有名ですか。","D":"春祭りは秋祭りより有名です。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Màu vàng sáng hơn màu xanh lá.', _utf8mb4 0x0a, _utf8mb4'黄色は緑（　）明るいです。'), _utf8mb4'より đánh dấu mốc so sánh 緑; đối tượng có mức độ cao hơn là 黄色.', _utf8mb4'{"options":{"A":"ほどは","B":"だけ","C":"より","D":"と同じくらい"},"correctAnswer":"C"}'
    UNION ALL SELECT 1045, _utf8mb4'EASY', CONCAT(_utf8mb4'Hội thao vui hơn hội văn hóa.', _utf8mb4 0x0a, _utf8mb4'運動会は文化祭（　）楽しいです。'), _utf8mb4'より đánh dấu mốc so sánh 文化祭; đối tượng có mức độ cao hơn là 運動会.', _utf8mb4'{"options":{"A":"へ","B":"まで","C":"から","D":"より"},"correctAnswer":"D"}'
    UNION ALL SELECT 1050, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xe đạp rẻ hơn xe buýt.', _utf8mb4 0x0a, _utf8mb4'自転車はバス（　）安いです。'), _utf8mb4'より đánh dấu mốc so sánh バス; đối tượng có mức độ cao hơn là 自転車.', _utf8mb4'{"options":{"A":"へ","B":"から","C":"より","D":"まで"},"correctAnswer":"C"}'
    UNION ALL SELECT 2010, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'うどんはそばより安いです。'), _utf8mb4'より đánh dấu mốc so sánh そば; đối tượng có mức độ cao hơn là うどん.', _utf8mb4'{"options":{"A":"mì soba rẻ hơn mì udon.","B":"Mì udon rẻ hơn mì soba.","C":"Chưa xác định được bên nào rẻ hơn.","D":"Hai bên ngang nhau."},"correctAnswer":"B"}'
    UNION ALL SELECT 2025, _utf8mb4'EASY', CONCAT(_utf8mb4'Tranh biển lớn hơn tranh lâu đài.', _utf8mb4 0x0a, _utf8mb4'海の絵は城の絵（　）大きいです。'), _utf8mb4'より đánh dấu mốc so sánh 城の絵; đối tượng có mức độ cao hơn là 海の絵.', _utf8mb4'{"options":{"A":"より","B":"から","C":"へ","D":"まで"},"correctAnswer":"A"}'
    UNION ALL SELECT 2040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'So sánh bằng より.', _utf8mb4 0x0a, _utf8mb4'テントは五キロ、寝袋は一キロでした。'), _utf8mb4'より đánh dấu mốc so sánh 寝袋; đối tượng có mức độ cao hơn là テント.', _utf8mb4'{"options":{"A":"テントと寝袋は同じくらい重いです。","B":"テントは寝袋より重いです。","C":"どちらが重いですか。","D":"寝袋はテントより重いです。"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 2
                AND l.display_order = 10 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 より Aです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 11 (もう Vましたか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, CONCAT(_utf8mb4'Kiểm tra việc sao tài liệu họp đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう会議の資料を（　）か。') AS content, _utf8mb4'もう + động từ quá khứ + か kiểm tra việc sao tài liệu họp đã hoàn tất chưa.' AS explanation, _utf8mb4'{"options":{"A":"コピーしません","B":"コピーしました","C":"コピーしましょう","D":"コピーしたいです"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc đón sinh viên quốc tế đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう留学生を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc đón sinh viên quốc tế đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"迎えましょう","B":"迎えません","C":"迎えました","D":"迎えたいです"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc bán bánh mì tự làm đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、昨日手作りのパンを売りました。」'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc bán bánh mì tự làm đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"一緒に手作りのパンを売りましょう。","B":"手作りのパンを売りませんか。","C":"もう手作りのパンを売りましたか。","D":"手作りのパンを売りたいですか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', CONCAT(_utf8mb4'Kiểm tra việc tra tên loài hoa đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう花の名前を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc tra tên loài hoa đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"調べたいです","B":"調べません","C":"調べましょう","D":"調べました"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'もう試合の予定を確かめましたか。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc kiểm tra lịch thi đấu đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"Đề nghị cùng kiểm tra lịch thi đấu.","B":"Hỏi người nghe muốn làm gì.","C":"Xác nhận một việc không được làm.","D":"Hỏi xem đối phương đã kiểm tra lịch thi đấu chưa."},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi tiến độ lắp ráp.', _utf8mb4 0x0a, _utf8mb4'部品を渡した後、棚ができたか知りたくなりました。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc lắp kệ sách đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"本棚を組み立てたいですか。","B":"もう本棚を組み立てましたか。","C":"本棚を組み立てませんか。","D":"一緒に本棚を組み立てましょう。"},"correctAnswer":"B"}'
