    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc dán áp phích lên tường đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もうポスターを壁に（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc dán áp phích lên tường đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"貼りたいです","B":"貼りました","C":"貼りません","D":"貼りましょう"},"correctAnswer":"B"}'
