    UNION ALL SELECT 19, _utf8mb4'EASY', CONCAT(_utf8mb4'Kiểm tra việc gấp chim bằng giấy đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう紙で鳥を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc gấp chim bằng giấy đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"折りました","B":"折りません","C":"折りたいです","D":"折りましょう"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc dạy cách bơi đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、昨日泳ぎ方を教えました。」'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc dạy cách bơi đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"一緒に泳ぎ方を教えましょう。","B":"泳ぎ方を教えたいですか。","C":"もう泳ぎ方を教えましたか。","D":"泳ぎ方を教えませんか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc chơi một bản nhạc piano đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もうピアノの曲を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc chơi một bản nhạc piano đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"弾きたいです","B":"弾きましょう","C":"弾きません","D":"弾きました"},"correctAnswer":"D"}'
    UNION ALL SELECT 1006, _utf8mb4'EASY', CONCAT(_utf8mb4'Kiểm tra việc hái cà chua trong vườn đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう畑のトマトを（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc hái cà chua trong vườn đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"取りました","B":"取りたいです","C":"取りません","D":"取りましょう"},"correctAnswer":"A"}'
    UNION ALL SELECT 1011, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc tìm chìa khóa ô tô đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう車のかぎを（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc tìm chìa khóa ô tô đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"探したいです","B":"探しません","C":"探しましょう","D":"探しました"},"correctAnswer":"D"}'
    UNION ALL SELECT 1016, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc trả tiền áo sơ mi đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もうシャツの代金を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc trả tiền áo sơ mi đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"払いましょう","B":"払いました","C":"払いません","D":"払いたいです"},"correctAnswer":"B"}'
    UNION ALL SELECT 1021, _utf8mb4'EASY', CONCAT(_utf8mb4'Kiểm tra việc hỏi đường ra ga đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう駅までの道を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc hỏi đường ra ga đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"聞きました","B":"聞きません","C":"聞きたいです","D":"聞きましょう"},"correctAnswer":"A"}'
    UNION ALL SELECT 1026, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc chèo thuyền trên sông đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう川でボートを（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc chèo thuyền trên sông đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"こぎましょう","B":"こぎたいです","C":"こぎました","D":"こぎません"},"correctAnswer":"C"}'
    UNION ALL SELECT 1031, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hỏi hoạt động đã hoàn thành chưa.', _utf8mb4 0x0a, _utf8mb4'旅程には旧市街の散歩があります。客が戻ってきました。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc đi bộ khám phá phố cổ đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"古い町を歩きたいですか。","B":"古い町を歩きませんか。","C":"もう古い町を歩きましたか。","D":"一緒に古い町を歩きましょう。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1036, _utf8mb4'EASY', CONCAT(_utf8mb4'Kiểm tra việc đo chiều cao của cây đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう木の高さを（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc đo chiều cao của cây đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"測りたいです","B":"測りました","C":"測りません","D":"測りましょう"},"correctAnswer":"B"}'
    UNION ALL SELECT 1041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc cho thầy xem bài văn đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう先生に作文を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc cho thầy xem bài văn đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"見せません","B":"見せましょう","C":"見せました","D":"見せたいです"},"correctAnswer":"C"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc nhặt rác ở công viên đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、昨日公園のごみを拾いました。」'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc nhặt rác ở công viên đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"一緒に公園のごみを拾いましょう。","B":"もう公園のごみを拾いましたか。","C":"公園のごみを拾いたいですか。","D":"公園のごみを拾いませんか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2011, _utf8mb4'EASY', CONCAT(_utf8mb4'Kiểm tra việc gửi bưu kiện cho bà đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう祖母に荷物を（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc gửi bưu kiện cho bà đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"送りましょう","B":"送りません","C":"送りたいです","D":"送りました"},"correctAnswer":"D"}'
    UNION ALL SELECT 2026, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc học nấu món địa phương đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、昨日地元の料理を習いました。」'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc học nấu món địa phương đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"地元の料理を習いませんか。","B":"地元の料理を習いたいですか。","C":"一緒に地元の料理を習いましょう。","D":"もう地元の料理を習いましたか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2041, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra việc sửa lốp xe đạp đã xong chưa.', _utf8mb4 0x0a, _utf8mb4'もう自転車のタイヤを（　）か。'), _utf8mb4'もう + động từ quá khứ + か kiểm tra việc sửa lốp xe đạp đã hoàn tất chưa.', _utf8mb4'{"options":{"A":"直しました","B":"直したいです","C":"直しません","D":"直しましょう"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 11 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'もう Vましたか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 12 (いいえ、まだです。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Việc trả tiền áo sơ mi vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「もうシャツの代金を払いましたか」「いいえ、（　）。」') AS content, _utf8mb4'まだです rút gọn câu phủ định: việc trả tiền áo sơ mi chưa hoàn thành tính đến lúc nói.' AS explanation, _utf8mb4'{"options":{"A":"まだです","B":"昨日のことです","C":"毎日です","D":"もう終わりました"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Vẫn định hỏi đường ra ga nhưng chưa làm.', _utf8mb4 0x0a, _utf8mb4'A「もう駅までの道を聞きましたか。」 B「（　）」'), _utf8mb4'まだです rút gọn câu phủ định: việc hỏi đường ra ga chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"いいえ、まだです。","B":"いいえ、明日もしません。","C":"はい、もう終わりました。","D":"はい、昨日しました。"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', CONCAT(_utf8mb4'Việc chèo thuyền trên sông vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「もう川でボートをこぎましたか」「いいえ、（　）。これからします。」'), _utf8mb4'まだです rút gọn câu phủ định: việc chèo thuyền trên sông chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"終わりました","B":"まだです","C":"昨日しました","D":"すぐでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Việc đi bộ khám phá phố cổ vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「もう古い町を歩きましたか」「いいえ、（　）。」'), _utf8mb4'まだです rút gọn câu phủ định: việc đi bộ khám phá phố cổ chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"毎日です","B":"もう終わりました","C":"昨日のことです","D":"まだです"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Việc đo chiều cao của cây vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「木の高さを測りましたか」「いいえ、（　）です。これからです。」'), _utf8mb4'まだです rút gọn câu phủ định: việc đo chiều cao của cây chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"もう","B":"いつも","C":"まだ","D":"ときどき"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Việc cho thầy xem bài văn vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「もう先生に作文を見せましたか」「いいえ、（　）。これからします。」'), _utf8mb4'まだです rút gọn câu phủ định: việc cho thầy xem bài văn chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"すぐでした","B":"昨日しました","C":"まだです","D":"終わりました"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Việc nhặt rác ở công viên vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「もう公園のごみを拾いましたか」「いいえ、（　）。」'), _utf8mb4'まだです rút gọn câu phủ định: việc nhặt rác ở công viên chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"昨日のことです","B":"もう終わりました","C":"まだです","D":"毎日です"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Việc gửi bưu kiện cho bà vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「祖母に荷物を送りましたか」「いいえ、（　）です。これからです。」'), _utf8mb4'まだです rút gọn câu phủ định: việc gửi bưu kiện cho bà chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"いつも","B":"ときどき","C":"まだ","D":"もう"},"correctAnswer":"C"}'
