    UNION ALL SELECT 2027, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo việc chưa thực hiện.', _utf8mb4 0x0a, _utf8mb4'折り紙は机の上にあります。これから鳥を折ります。'), _utf8mb4'まだです rút gọn câu phủ định: việc gấp chim bằng giấy chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"はい、もう終わりました。","B":"いいえ、まだです。","C":"はい、昨日しました。","D":"いいえ、明日もしません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2042, _utf8mb4'EASY', CONCAT(_utf8mb4'Việc dạy cách bơi vẫn chưa xong.', _utf8mb4 0x0a, _utf8mb4'「もう泳ぎ方を教えましたか」「いいえ、（　）。これからします。」'), _utf8mb4'まだです rút gọn câu phủ định: việc dạy cách bơi chưa hoàn thành tính đến lúc nói.', _utf8mb4'{"options":{"A":"昨日しました","B":"終わりました","C":"まだです","D":"すぐでした"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'いいえ、まだです。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 13 (S + よ。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'明日は休みだと思っている友達に知らせます。「授業はあります（　）。」') AS content, _utf8mb4'Bạn học tưởng được nghỉ; よ báo lại lịch học mà bạn ấy chưa biết.' AS explanation, _utf8mb4'{"options":{"A":"から","B":"よ","C":"か","D":"ね"},"correctAnswer":"B"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：この席、空いていますか。B：すみません、そこは予約席です（　）。'), _utf8mb4'よ báo cho khách biết ghế đã được đặt trước.', _utf8mb4'{"options":{"A":"よ","B":"か","C":"から","D":"ね"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin: số mặt nạ là ba.', _utf8mb4 0x0a, _utf8mb4'A「初めて聞きました。教えてください。」 B「（　）」'), _utf8mb4'よ báo thông tin mới cho người nghe: お面は三枚です。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"お面は三枚ですよ。","C":"お面は三枚ですね。","D":"お面は三枚ですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：駅まで歩かないといけませんか。B：いいえ、ここからバスが出ます（　）。'), _utf8mb4'よ giới thiệu tuyến xe mà người hỏi chưa biết.', _utf8mb4'{"options":{"A":"ね","B":"か","C":"から","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'初めて来た学生に知らせます。「この図書館は日曜も開いています（　）。」'), _utf8mb4'よ dùng khi chủ động cho người mới biết lịch mở cửa.', _utf8mb4'{"options":{"A":"か","B":"から","C":"ね","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'友達が財布を忘れて帰りそうです。「机の上に財布があります（　）。」'), _utf8mb4'Người nghe chưa nhận ra ví để quên, nên người nói báo bằng よ.', _utf8mb4'{"options":{"A":"か","B":"から","C":"ね","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin: sự kiện buổi diễn rối diễn ra ở trường mẫu giáo.', _utf8mb4 0x0a, _utf8mb4'A「その件はまだ知りません。」 B「（　）」'), _utf8mb4'よ báo thông tin mới cho người nghe: 幼稚園で人形劇があります。', _utf8mb4'{"options":{"A":"幼稚園で人形劇がありますね。","B":"そのことはまだわかりません。","C":"幼稚園で人形劇がありますよ。","D":"幼稚園で人形劇がありますか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：すみません、出口は二階ですか。B：いいえ、一階です（　）。'), _utf8mb4'よ kết thúc lời đính chính của người biết rõ lối ra.', _utf8mb4'{"options":{"A":"ね","B":"よ","C":"から","D":"か"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'道を知らない旅行者に教えます。「橋を渡ると、右に駅があります（　）。」'), _utf8mb4'よ hướng thông tin chỉ đường tới người nghe chưa biết đường.', _utf8mb4'{"options":{"A":"ね","B":"から","C":"か","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：お金を用意します。B：今日は入場無料です（　）。'), _utf8mb4'よ cho người đang chuẩn bị tiền biết hôm nay được vào miễn phí.', _utf8mb4'{"options":{"A":"か","B":"から","C":"ね","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：もう映画が始まりますか。B：まだ十分あります（　）。'), _utf8mb4'Người B biết giờ chiếu và dùng よ để báo còn mười phút.', _utf8mb4'{"options":{"A":"か","B":"よ","C":"ね","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'暑いお茶を飲もうとする子に注意します。「とても熱いです（　）。」'), _utf8mb4'よ thu hút sự chú ý của người nghe vào điều cần cẩn thận.', _utf8mb4'{"options":{"A":"か","B":"から","C":"よ","D":"ね"},"correctAnswer":"C"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Chủ động báo địa điểm cho khách.', _utf8mb4 0x0a, _utf8mb4'旅行者は砂の作品展の場所を知りません。'), _utf8mb4'よ báo thông tin mới cho người nghe: 海岸で砂の作品展があります。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"海岸で砂の作品展がありますよ。","C":"海岸で砂の作品展がありますね。","D":"海岸で砂の作品展がありますか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：このペン、使ってもいいですか。B：それはインクが出ません（　）。'), _utf8mb4'よ báo cho người sắp dùng bút biết bút hết mực.', _utf8mb4'{"options":{"A":"ね","B":"か","C":"よ","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'ガラス板は三枚ですよ。'), _utf8mb4'よ báo thông tin mới cho người nghe: ガラス板は三枚です。', _utf8mb4'{"options":{"A":"Báo cho người nghe biết số tấm kính là ba.","B":"Nêu một khả năng và tỏ ý nghi ngờ.","C":"Không biết câu trả lời nên đặt một câu hỏi mới.","D":"Muốn nghe xác nhận về thông tin cả hai đã biết."},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：犬は外ですか。B：いいえ、さっき家の中に入りました（　）。'), _utf8mb4'Người nói đã thấy chó đi vào và dùng よ để báo cho người hỏi.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"から","D":"か"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'雨に気づかず外に出る人に声をかけます。「雨が降っています（　）。」'), _utf8mb4'よ dùng để nhắc người chưa nhận thấy trời đang mưa.', _utf8mb4'{"options":{"A":"から","B":"ね","C":"よ","D":"か"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：昼の切符は売り切れですか。B：窓口にはまだあります（　）。'), _utf8mb4'よ báo vé ở quầy vẫn còn, giúp người nghe biết có thể mua.', _utf8mb4'{"options":{"A":"よ","B":"から","C":"か","D":"ね"},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin: sự kiện chợ sáng diễn ra ở quảng trường trước ga.', _utf8mb4 0x0a, _utf8mb4'A「その件はまだ知りません。」 B「（　）」'), _utf8mb4'よ báo thông tin mới cho người nghe: 駅前広場で朝市があります。', _utf8mb4'{"options":{"A":"駅前広場で朝市がありますか。","B":"駅前広場で朝市がありますね。","C":"駅前広場で朝市がありますよ。","D":"そのことはまだわかりません。"},"correctAnswer":"C"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo tin mới cho người chưa biết.', _utf8mb4 0x0a, _utf8mb4'集合は明日の昼（　）。'), _utf8mb4'よ báo thông tin mới cho người nghe: 集合は明日の昼です。', _utf8mb4'{"options":{"A":"ですよ","B":"でしたか","C":"ですね","D":"でしょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 1003, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin mới cho người chưa biết.', _utf8mb4 0x0a, _utf8mb4'食パンは三枚（　）。'), _utf8mb4'よ báo thông tin mới cho người nghe: 食パンは三枚です。', _utf8mb4'{"options":{"A":"でしたか","B":"ですよ","C":"ですね","D":"でしょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 1008, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin hữu ích về địa điểm.', _utf8mb4 0x0a, _utf8mb4'初めて来た選手は、高校のグラウンドが遠いと思っています。'), _utf8mb4'よ báo thông tin mới cho người nghe: 高校のグラウンドは駅の近くです。', _utf8mb4'{"options":{"A":"高校のグラウンドは駅の近くですか。","B":"高校のグラウンドは駅の近くですよ。","C":"そのことはまだわかりません。","D":"高校のグラウンドは駅の近くですね。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1013, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：この字は「土」ですか。B：いいえ、上の線が長いので「士」です（　）。」'), _utf8mb4'よ đưa thông tin đính chính về chữ mà người học đọc nhầm.', _utf8mb4'{"options":{"A":"から","B":"か","C":"よ","D":"ね"},"correctAnswer":"C"}'
    UNION ALL SELECT 1018, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin: đàn ghi-ta ở tại quầy tiếp tân.', _utf8mb4 0x0a, _utf8mb4'A「初めて聞きました。教えてください。」 B「（　）」'), _utf8mb4'よ báo thông tin mới cho người nghe: ギターは受付にあります。', _utf8mb4'{"options":{"A":"ギターは受付にありますよ。","B":"ギターは受付にありますか。","C":"そのことはまだわかりません。","D":"ギターは受付にありますね。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'劇場で歌のコンテストがありますよ。'), _utf8mb4'よ báo thông tin mới cho người nghe: 劇場で歌のコンテストがあります。', _utf8mb4'{"options":{"A":"Muốn nghe xác nhận về thông tin cả hai đã biết.","B":"Nêu một khả năng và tỏ ý nghi ngờ.","C":"Không biết câu trả lời nên đặt một câu hỏi mới.","D":"Báo cho người nghe biết sự kiện cuộc thi hát diễn ra ở nhà hát."},"correctAnswer":"D"}'
    UNION ALL SELECT 1028, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo tin mới cho người chưa biết.', _utf8mb4 0x0a, _utf8mb4'集合は来週の火曜日（　）。'), _utf8mb4'よ báo thông tin mới cho người nghe: 集合は来週の火曜日です。', _utf8mb4'{"options":{"A":"ですよ","B":"でしたか","C":"でしょうか","D":"ですね"},"correctAnswer":"A"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：コピーは有料ですか。B：学生証を使うと一枚目は無料です（　）。'), _utf8mb4'よ thông báo điều kiện miễn phí cho người đang hỏi.', _utf8mb4'{"options":{"A":"ね","B":"から","C":"か","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin để khách cân nhắc.', _utf8mb4 0x0a, _utf8mb4'初めて来るお客さんが会議室までタクシーを呼ぼうとしています。'), _utf8mb4'よ báo thông tin mới cho người nghe: 会社の会議室は駅の近くです。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"会社の会議室は駅の近くですね。","C":"会社の会議室は駅の近くですよ。","D":"会社の会議室は駅の近くですか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1043, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo tin mới cho người chưa biết.', _utf8mb4 0x0a, _utf8mb4'夏祭りは明日（　）。'), _utf8mb4'よ báo thông tin mới cho người nghe: 夏祭りは明日です。', _utf8mb4'{"options":{"A":"ですよ","B":"でしたか","C":"ですね","D":"でしょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'隣の人が時刻を間違えています。「次の電車は九時半です（　）。」'), _utf8mb4'Người nói dùng よ để sửa thông tin giờ tàu cho người bên cạnh.', _utf8mb4'{"options":{"A":"から","B":"か","C":"よ","D":"ね"},"correctAnswer":"C"}'
    UNION ALL SELECT 2013, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo tin: sự kiện liên hoan phim diễn ra ở rạp chiếu phim.', _utf8mb4 0x0a, _utf8mb4'A「その件はまだ知りません。」 B「（　）」'), _utf8mb4'よ báo thông tin mới cho người nghe: 映画館で映画祭があります。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"映画館で映画祭がありますね。","C":"映画館で映画祭がありますか。","D":"映画館で映画祭がありますよ。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2028, _utf8mb4'EASY', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：これは去年の地図ですか。B：ええ。新しい地図は受付にあります（　）。'), _utf8mb4'よ cung cấp thông tin mới về nơi có bản đồ.', _utf8mb4'{"options":{"A":"から","B":"か","C":"ね","D":"よ"},"correctAnswer":"D"}'
    UNION ALL SELECT 2043, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Báo thông tin mới cho người nghe.', _utf8mb4 0x0a, _utf8mb4'A：先生はまだ教室ですか。B：もう職員室に戻りました（　）。'), _utf8mb4'よ báo việc giáo viên đã về phòng cho người chưa biết.', _utf8mb4'{"options":{"A":"から","B":"よ","C":"か","D":"ね"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 13 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S + よ。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 14 (N はどうですか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Cần chọn giờ cho hội chợ sách cũ. Gợi ý mười hai giờ trưa.', _utf8mb4 0x0a, _utf8mb4'A「いつ古本市をしましょうか。」 B「（　）」') AS content, _utf8mb4'N はどうですか đưa お昼の十二時 ra làm phương án để người nghe cân nhắc.' AS explanation, _utf8mb4'{"options":{"A":"お昼の十二時はどうですか。","B":"古本市は昨日でしたか。","C":"古本市はどうでしたか。","D":"古本市の予定は変わりましたか。"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức cuộc thi hát. Gợi ý nhà hát.', _utf8mb4 0x0a, _utf8mb4'劇場（　）どうですか。'), _utf8mb4'は nêu 劇場 làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"へ","B":"は","C":"を","D":"の"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Gợi ý lịch tuần tới.', _utf8mb4 0x0a, _utf8mb4'花火大会の日がまだ決まりません。火曜は全員が空いています。'), _utf8mb4'N はどうですか đưa 来週の火曜日 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"花火大会の予定は変わりましたか。","B":"花火大会は昨日でしたか。","C":"花火大会はどうでしたか。","D":"来週の火曜日はどうですか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức triển lãm ảnh. Gợi ý bảo tàng mỹ thuật.', _utf8mb4 0x0a, _utf8mb4'A「どこで写真展をしましょうか。」 B「（　）」'), _utf8mb4'N はどうですか đưa 美術館 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"写真展の予定は変わりましたか。","B":"美術館はどうですか。","C":"写真展は昨日でしたか。","D":"写真展はどうでしたか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đưa ra phương án.', _utf8mb4 0x0a, _utf8mb4'ピアノ発表会の開始時刻を相談中。四時半なら講師が来られます。'), _utf8mb4'N はどうですか đưa 四時半 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"打ち合わせの予定は変わりましたか。","B":"四時半はどうですか。","C":"打ち合わせは昨日でしたか。","D":"打ち合わせはどうでしたか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Đề xuất địa điểm.', _utf8mb4 0x0a, _utf8mb4'夏祭りの場所は未定。商店街から会場を使っていいと連絡が来ました。'), _utf8mb4'N はどうですか đưa 商店街 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"夏祭りの予定は変わりましたか。","B":"夏祭りは昨日でしたか。","C":"商店街はどうですか。","D":"夏祭りはどうでしたか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn giờ cho tiệc trà. Gợi ý cuối tuần tới.', _utf8mb4 0x0a, _utf8mb4'来週末は（　）。'), _utf8mb4'N はどうですか đưa 来週末 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"いつでしたか","B":"どうですか","C":"どこでしたか","D":"どうでしたか"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức liên hoan phim. Gợi ý rạp chiếu phim.', _utf8mb4 0x0a, _utf8mb4'A「どこで映画祭をしましょうか。」 B「（　）」'), _utf8mb4'N はどうですか đưa 映画館 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"映画祭の予定は変わりましたか。","B":"映画館はどうですか。","C":"映画祭は昨日でしたか。","D":"映画祭はどうでしたか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn giờ cho buổi tư vấn sức khỏe. Gợi ý sáng mai.', _utf8mb4 0x0a, _utf8mb4'明日の朝（　）どうですか。'), _utf8mb4'は nêu 明日の朝 làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"は","B":"を","C":"へ","D":"の"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức buổi kể chuyện. Gợi ý thư viện.', _utf8mb4 0x0a, _utf8mb4'図書館は（　）。'), _utf8mb4'N はどうですか đưa 図書館 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どうでしたか","B":"どこでしたか","C":"いつでしたか","D":"どうですか"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn giờ cho buổi tập ghi-ta. Gợi ý chiều thứ hai.', _utf8mb4 0x0a, _utf8mb4'月曜の夕方（　）どうですか。'), _utf8mb4'は nêu 月曜の夕方 làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"は","B":"を","C":"の","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức tiệc chào đón. Gợi ý nhà ăn đại học.', _utf8mb4 0x0a, _utf8mb4'大学の食堂は（　）。'), _utf8mb4'N はどうですか đưa 大学の食堂 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どこでしたか","B":"いつでしたか","C":"どうでしたか","D":"どうですか"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn giờ cho buổi biểu diễn piano. Gợi ý một giờ chiều.', _utf8mb4 0x0a, _utf8mb4'午後一時は（　）。'), _utf8mb4'N はどうですか đưa 午後一時 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どこでしたか","B":"どうでしたか","C":"いつでしたか","D":"どうですか"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức tiệc đầu năm. Gợi ý nhà trọ.', _utf8mb4 0x0a, _utf8mb4'旅館は（　）。'), _utf8mb4'N はどうですか đưa 旅館 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どうでしたか","B":"どこでしたか","C":"どうですか","D":"いつでしたか"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn giờ cho buổi học nhảy. Gợi ý sáu giờ tối.', _utf8mb4 0x0a, _utf8mb4'夕方六時は（　）。'), _utf8mb4'N はどうですか đưa 夕方六時 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"いつでしたか","B":"どうでしたか","C":"どうですか","D":"どこでしたか"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức giải đua thuyền. Gợi ý hồ.', _utf8mb4 0x0a, _utf8mb4'湖は（　）。'), _utf8mb4'N はどうですか đưa 湖 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どうですか","B":"どこでしたか","C":"いつでしたか","D":"どうでしたか"},"correctAnswer":"A"}'
