    UNION ALL SELECT 1034, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'水泳大会の予定を決めています。水曜日はどうですか。'), _utf8mb4'N はどうですか đưa 水曜日 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"Hỏi lại ngày đã diễn ra sự kiện.","B":"Đề xuất thứ tư làm thời điểm cho giải bơi.","C":"Hỏi địa điểm cũ của sự kiện.","D":"Hỏi cảm nhận sau sự kiện."},"correctAnswer":"B"}'
    UNION ALL SELECT 1039, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần chọn nơi tổ chức buổi cùng đọc sách. Gợi ý quán cà phê.', _utf8mb4 0x0a, _utf8mb4'カフェは（　）。'), _utf8mb4'N はどうですか đưa カフェ ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どこでしたか","B":"どうでしたか","C":"どうですか","D":"いつでしたか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1044, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn giờ cho buổi tìm hiểu các vì sao. Gợi ý mùng hai tháng một.', _utf8mb4 0x0a, _utf8mb4'一月二日（　）どうですか。'), _utf8mb4'は nêu 一月二日 làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"は","B":"を","C":"の","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức buổi dự giờ của phụ huynh. Gợi ý trường tiểu học.', _utf8mb4 0x0a, _utf8mb4'A「どこで授業参観をしましょうか。」 B「（　）」'), _utf8mb4'N はどうですか đưa 小学校 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"授業参観はどうでしたか。","B":"小学校はどうですか。","C":"授業参観は昨日でしたか。","D":"授業参観の予定は変わりましたか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 2014, _utf8mb4'EASY', CONCAT(_utf8mb4'Cần chọn giờ cho lớp ngôn ngữ ký hiệu. Gợi ý thứ hai tới.', _utf8mb4 0x0a, _utf8mb4'今度の月曜日は（　）。'), _utf8mb4'N はどうですか đưa 今度の月曜日 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"いつでしたか","B":"どこでしたか","C":"どうでしたか","D":"どうですか"},"correctAnswer":"D"}'
    UNION ALL SELECT 2029, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Cần chọn nơi tổ chức chợ sáng. Gợi ý quảng trường trước ga.', _utf8mb4 0x0a, _utf8mb4'駅前広場は（　）。'), _utf8mb4'N はどうですか đưa 駅前広場 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"どうですか","B":"どうでしたか","C":"いつでしたか","D":"どこでしたか"},"correctAnswer":"A"}'
    UNION ALL SELECT 2044, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Người nói muốn cho biết điều gì?', _utf8mb4 0x0a, _utf8mb4'パン作りの会の予定を決めています。明日の昼はどうですか。'), _utf8mb4'N はどうですか đưa 明日の昼 ra làm phương án để người nghe cân nhắc.', _utf8mb4'{"options":{"A":"Đề xuất trưa mai làm thời điểm cho buổi làm bánh mì.","B":"Hỏi cảm nhận sau sự kiện.","C":"Hỏi lại ngày đã diễn ra sự kiện.","D":"Hỏi địa điểm cũ của sự kiện."},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 14 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N はどうですか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 6 / NGỮ PHÁP / Mẫu 15 (S + ね。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人で同じカレンダーを見ています。「遠足は来週の金曜です（　）。」') AS content, _utf8mb4'ね mời người cùng xem lịch xác nhận ngày đi chơi.' AS explanation, _utf8mb4'{"options":{"A":"から","B":"か","C":"ね","D":"よ"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：ずいぶん歩きました。B：ええ。そろそろ休みたいです（　）。'), _utf8mb4'ね tìm sự đồng tình sau khi cả hai cùng đi bộ một quãng dài.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"から","D":"か"},"correctAnswer":"B"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'湯を一口ずつ飲んだ二人。「このお茶、少し熱いです（　）。」'), _utf8mb4'ね chia sẻ cảm nhận mà cả hai vừa có khi uống trà.', _utf8mb4'{"options":{"A":"か","B":"から","C":"ね","D":"よ"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：この字は「春」です。B：上は三本の線です（　）。」'), _utf8mb4'ね kiểm tra lại chi tiết chữ mà hai người đang nhìn.', _utf8mb4'{"options":{"A":"ね","B":"よ","C":"から","D":"か"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、読書会は明日です。」'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 読書会は明日です。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"読書会は明日ですか。","C":"読書会は明日ですよ。","D":"読書会は明日ですね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人で窓の外を見て「きれいな雪です（　）。」'), _utf8mb4'ね mời người cùng ngắm cảnh đồng tình.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"から","D":"か"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'待ち合わせをもう一度確認します。「駅の東口に九時です（　）。」'), _utf8mb4'ね dùng khi nhắc lại điểm hẹn để đối phương xác nhận.', _utf8mb4'{"options":{"A":"か","B":"から","C":"よ","D":"ね"},"correctAnswer":"D"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để người kia xác nhận.', _utf8mb4 0x0a, _utf8mb4'係の人が「今度の月曜に集合」と言いました。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 集合は今度の月曜日です。', _utf8mb4'{"options":{"A":"集合は今度の月曜日ですか。","B":"集合は今度の月曜日ですよ。","C":"そのことはまだわかりません。","D":"集合は今度の月曜日ですね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、コピー用紙は三枚です。」'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với コピー用紙は三枚です。', _utf8mb4'{"options":{"A":"コピー用紙は三枚ですよ。","B":"コピー用紙は三枚ですね。","C":"そのことはまだわかりません。","D":"コピー用紙は三枚ですか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：切符は一人五百円です。B：二人で千円です（　）。'), _utf8mb4'ね xác nhận số tiền vừa tính từ giá hai người đã biết.', _utf8mb4'{"options":{"A":"か","B":"よ","C":"から","D":"ね"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Câu này diễn đạt ý nào?', _utf8mb4 0x0a, _utf8mb4'野外コンサートは明日ですね。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 野外コンサートは明日です。', _utf8mb4'{"options":{"A":"Xác nhận với người nghe rằng hòa nhạc ngoài trời diễn ra ngày mai.","B":"Nêu một khả năng và tỏ ý nghi ngờ.","C":"Không biết câu trả lời nên đặt một câu hỏi mới.","D":"Báo một tin mới mà người nghe chưa biết."},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'テントは受付に（　）。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với テントは受付にあります。', _utf8mb4'{"options":{"A":"ありますね","B":"ありますよ","C":"ありましたか","D":"ありますか"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Kiểm tra lại cách hiểu chung.', _utf8mb4 0x0a, _utf8mb4'博物館と書いた歴史講座の案内を二人で読んでいます。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 博物館で歴史の講座があります。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"博物館で歴史の講座がありますか。","C":"博物館で歴史の講座がありますね。","D":"博物館で歴史の講座がありますよ。"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、集合はお昼の十二時です。」'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 集合はお昼の十二時です。', _utf8mb4'{"options":{"A":"集合はお昼の十二時ですよ。","B":"集合はお昼の十二時ですね。","C":"集合はお昼の十二時ですか。","D":"そのことはまだわかりません。"},"correctAnswer":"B"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'友達も同じ宿題を読みました。「最後の問題は難しいです（　）。」'), _utf8mb4'ね gợi sự đồng tình từ người cũng đã làm bài.', _utf8mb4'{"options":{"A":"ね","B":"よ","C":"から","D":"か"},"correctAnswer":"A"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、川のそばに駅があります。」'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 川のそばに駅があります。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"川のそばに駅がありますよ。","C":"川のそばに駅がありますか。","D":"川のそばに駅がありますね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：次は京都です。B：では、次の駅で降ります（　）。'), _utf8mb4'Người nghe dùng ね xác nhận lại ga cần xuống.', _utf8mb4'{"options":{"A":"から","B":"ね","C":"よ","D":"か"},"correctAnswer":"B"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'温かい毛布は受付に（　）。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 温かい毛布は受付にあります。', _utf8mb4'{"options":{"A":"ありましたか","B":"ありますよ","C":"ありますね","D":"ありますか"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人で地図を開いて確かめます。「ホテルは川の向こうです（　）。」'), _utf8mb4'ね mời người cùng xem bản đồ xác nhận vị trí.', _utf8mb4'{"options":{"A":"ね","B":"から","C":"よ","D":"か"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'集合は来週末（　）。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 集合は来週末です。', _utf8mb4'{"options":{"A":"ですよ","B":"でしたか","C":"ですね","D":"でしょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1005, _utf8mb4'EASY', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'同じ曲を聞き終えた二人。「いい歌でした（　）。」'), _utf8mb4'ね chia sẻ ấn tượng với người vừa nghe cùng mình.', _utf8mb4'{"options":{"A":"から","B":"よ","C":"ね","D":"か"},"correctAnswer":"C"}'
    UNION ALL SELECT 1010, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Hiểu câu sau thế nào?', _utf8mb4 0x0a, _utf8mb4'病院は駅の近くですね。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 病院は駅の近くです。', _utf8mb4'{"options":{"A":"Không biết câu trả lời nên đặt một câu hỏi mới.","B":"Báo một tin mới mà người nghe chưa biết.","C":"Nêu một khả năng và tỏ ý nghi ngờ.","D":"Xác nhận với người nghe rằng bệnh viện ở gần ga."},"correctAnswer":"D"}'
    UNION ALL SELECT 1015, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'お話の会は明日（　）。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với お話の会は明日です。', _utf8mb4'{"options":{"A":"ですよ","B":"でしたか","C":"ですね","D":"でしょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1020, _utf8mb4'EASY', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：受付は五時までです。B：今日はもう終わりです（　）。'), _utf8mb4'ね dùng để kiểm tra lại kết luận dựa trên giờ vừa nghe.', _utf8mb4'{"options":{"A":"ね","B":"から","C":"か","D":"よ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Nhắc lại để hai bên xác nhận.', _utf8mb4 0x0a, _utf8mb4'A「（　）」 B「はい、大学の食堂で歓迎会があります。」'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 大学の食堂で歓迎会があります。', _utf8mb4'{"options":{"A":"そのことはまだわかりません。","B":"大学の食堂で歓迎会がありますか。","C":"大学の食堂で歓迎会がありますよ。","D":"大学の食堂で歓迎会がありますね。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1030, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'帰り道で一緒に空を見上げます。「今日は月が丸いです（　）。」'), _utf8mb4'ね chia sẻ nhận xét về cảnh mà cả hai cùng thấy.', _utf8mb4'{"options":{"A":"よ","B":"ね","C":"か","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1035, _utf8mb4'EASY', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：明日はお弁当を持ってきてください。B：飲み物も自分で持ってきます（　）。'), _utf8mb4'ね yêu cầu xác nhận lại phần chuẩn bị đồ uống.', _utf8mb4'{"options":{"A":"ね","B":"から","C":"か","D":"よ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'買い物のメモを読み合わせます。「卵はひと箱です（　）。」'), _utf8mb4'ね mời người cùng đọc danh sách xác nhận số lượng.', _utf8mb4'{"options":{"A":"ね","B":"か","C":"よ","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人で空になった棚を見ます。「もうパンはありません（　）。」'), _utf8mb4'ね tìm sự đồng tình về tình trạng cả hai đều thấy.', _utf8mb4'{"options":{"A":"か","B":"ね","C":"よ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 1050, _utf8mb4'EASY', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'A：集合は十時から九時に変わりました。B：前より一時間早いです（　）。'), _utf8mb4'ね dùng khi kiểm tra lại cách hiểu về giờ hẹn mới.', _utf8mb4'{"options":{"A":"か","B":"よ","C":"から","D":"ね"},"correctAnswer":"D"}'
    UNION ALL SELECT 2015, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Xác nhận lại địa điểm.', _utf8mb4 0x0a, _utf8mb4'案内には「農園、いちご祭り」とあります。友達も同じ紙を見ています。'), _utf8mb4'ね mời người nghe xác nhận hoặc đồng tình với 農園でいちご祭りがあります。', _utf8mb4'{"options":{"A":"農園でいちご祭りがありますか。","B":"そのことはまだわかりません。","C":"農園でいちご祭りがありますね。","D":"農園でいちご祭りがありますよ。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2030, _utf8mb4'MEDIUM', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'二人で映画館から出ました。「最後の場面はおもしろかったです（　）。」'), _utf8mb4'ね chia sẻ ấn tượng và chờ người đã xem cùng đồng tình.', _utf8mb4'{"options":{"A":"か","B":"ね","C":"よ","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 2045, _utf8mb4'EASY', CONCAT(_utf8mb4'Mời người nghe xác nhận hoặc đồng tình.', _utf8mb4 0x0a, _utf8mb4'机を並べながら場所を確かめます。「先生の席はここです（　）。」'), _utf8mb4'ね mời người cùng sắp chỗ xác nhận vị trí bàn.', _utf8mb4'{"options":{"A":"から","B":"ね","C":"か","D":"よ"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 6
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 15 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'S + ね。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 1 (Địa điểm に N がいます。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'静かな廊下（　）学生が一人います。' AS content, _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.' AS explanation, _utf8mb4'{"options":{"A":"を","B":"で","C":"に","D":"から"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', _utf8mb4'教室（　）先生がいます。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"から","B":"を","C":"で","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng khi giới thiệu người ở ga.', _utf8mb4'Mẫu địa điểm に + người がいます giới thiệu sinh viên ở ga.', _utf8mb4'{"options":{"A":"駅前に学生がいます。","B":"駅前に学生があります。","C":"駅前に学生をいます。","D":"駅前に学生にあります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'先生のうしろにはだれ（　）いますか。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"が","B":"を","C":"で","D":"に"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', _utf8mb4'箱の中に子ねこが（　）。鳴き声がします。', _utf8mb4'Dùng います để nói có một con vật đang sống ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"います","B":"ですか","C":"いましたか","D":"あります"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'だれも来ないと思いましたが、玄関（　）お客さんがいます。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"を","B":"に","C":"から","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'今、橋の下に魚が（　）。— はい、三匹見えます。', _utf8mb4'Để hỏi có con vật ở đó hay không, dùng いますか.', _utf8mb4'{"options":{"A":"ありました","B":"いますか","C":"いましたね","D":"あります"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', _utf8mb4'門の前に白い犬（　）います。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"に","B":"が","C":"で","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'運動場に人がいます。あ、妹（　）います。', _utf8mb4'も bổ sung một người cũng có mặt, sau người đã nhắc.', _utf8mb4'{"options":{"A":"を","B":"で","C":"も","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'A：だれか来ましたか。B：はい、入口に（　）。', _utf8mb4'Giới thiệu người mới xuất hiện bằng 人がいます.', _utf8mb4'{"options":{"A":"お客さんがいます","B":"お客さんをいます","C":"お客さんがです","D":"お客さんがあります"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', _utf8mb4'棚の下（　）ねこがいます。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"で","B":"から","C":"を","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'犬は公園にいます。ねこも公園（　）います。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"で","B":"に","C":"から","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'この島には、どんな動物（　）いますか。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', _utf8mb4'池の中に魚（　）います。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'A：池に何がいますか。B：ほら、水の中に（　）。', _utf8mb4'Sau địa điểm に, dùng がいます với con vật nhìn thấy.', _utf8mb4'{"options":{"A":"魚をいます","B":"魚にあります","C":"魚がいます","D":"魚がします"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'ベンチの下を見て。そこ（　）小さな犬がいます。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"から","B":"を","C":"に","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', _utf8mb4'小さな子はどこですか。庭（　）いますよ。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"に","B":"から","C":"で","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng khi chỉ hai con chim.', _utf8mb4'Địa điểm tồn tại đi với に. 二羽 đếm chim.', _utf8mb4'{"options":{"A":"屋根の上を鳥が二羽います。","B":"屋根の上が鳥が二羽います。","C":"屋根の上を鳥に二羽います。","D":"屋根の上に鳥が二羽います。"},"correctAnswer":"D"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng khi hỏi ai có mặt.', _utf8mb4'Dùng だれがいますか để hỏi ai đang có mặt ở sảnh.', _utf8mb4'{"options":{"A":"ロビーにだれがありますか。","B":"ロビーにだれがいますか。","C":"ロビーにだれをありますか。","D":"ロビーにだれをいますか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', _utf8mb4'窓のそばにだれ（　）いますか。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"を","B":"で","C":"が","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 1001, _utf8mb4'MEDIUM', _utf8mb4'「庭にうさぎがいます。」が đánh dấu gì?', _utf8mb4'が chỉ con vật được giới thiệu là có mặt trong vườn.', _utf8mb4'{"options":{"A":"Nơi diễn ra hoạt động","B":"Điểm đến","C":"Con vật đang hiện diện","D":"Công cụ"},"correctAnswer":"C"}'
    UNION ALL SELECT 1006, _utf8mb4'MEDIUM', _utf8mb4'一階に先生がいます。二階に（　）先生がいます。', _utf8mb4'も bổ sung một người cũng có mặt, sau người đã nhắc.', _utf8mb4'{"options":{"A":"から","B":"で","C":"も","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 1011, _utf8mb4'EASY', _utf8mb4'鳥の声ですね。木の上（　）小鳥がいます。', _utf8mb4'に đánh dấu vị trí nơi người hay con vật hiện diện trước います.', _utf8mb4'{"options":{"A":"に","B":"で","C":"を","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 1016, _utf8mb4'MEDIUM', _utf8mb4'「川に魚がいます。」に cho biết điều gì?', _utf8mb4'Với います, に cho biết nơi tìm thấy con vật.', _utf8mb4'{"options":{"A":"Hướng cá bơi tới","B":"Số lượng cá","C":"Thời gian cá đến","D":"Nơi cá đang sống"},"correctAnswer":"D"}'
    UNION ALL SELECT 1021, _utf8mb4'MEDIUM', _utf8mb4'庭には一匹だけ？　いいえ、親ねこ（　）子ねこがいます。', _utf8mb4'と nối hai con vật cùng có mặt trước động từ います.', _utf8mb4'{"options":{"A":"から","B":"と","C":"で","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1026, _utf8mb4'EASY', _utf8mb4'絵を見てください。馬（　）二頭います。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"が","B":"を","C":"で","D":"に"},"correctAnswer":"A"}'
    UNION ALL SELECT 1031, _utf8mb4'MEDIUM', _utf8mb4'A：だれが体育館にいますか。B：（　）。ボールを持っていますよ。', _utf8mb4'Khi trả lời だれが, dùng が trước います để xác định người.', _utf8mb4'{"options":{"A":"兄があります","B":"兄がいます","C":"兄でいます","D":"兄をいます"},"correctAnswer":"B"}'
    UNION ALL SELECT 1036, _utf8mb4'MEDIUM', _utf8mb4'部屋に母がいます。台所に（　）だれがいますか。', _utf8mb4'には nêu địa điểm thứ hai để đối chiếu với căn phòng đã nói.', _utf8mb4'{"options":{"A":"へ","B":"の","C":"を","D":"は"},"correctAnswer":"D"}'
    UNION ALL SELECT 1041, _utf8mb4'EASY', _utf8mb4'写真に写っている動物を紹介します。「木の枝に鳥が二羽（　）。」', _utf8mb4'Dùng います để nói có một con vật đang sống ở địa điểm đã nêu.', _utf8mb4'{"options":{"A":"ですか","B":"あります","C":"いましたか","D":"います"},"correctAnswer":"D"}'
    UNION ALL SELECT 1046, _utf8mb4'MEDIUM', _utf8mb4'A：妹さんが見えませんね。B：あ、あそこ！ 木の下に（　）。', _utf8mb4'います diễn tả người đang ở chỗ vừa chỉ.', _utf8mb4'{"options":{"A":"妹があります","B":"妹がいます","C":"妹にいます","D":"妹をあります"},"correctAnswer":"B"}'
    UNION ALL SELECT 2001, _utf8mb4'MEDIUM', _utf8mb4'A：庭にねこは一匹だけですか。B：いいえ、もう一匹（　）。', _utf8mb4'もう一匹 bổ sung một con vật nên vị ngữ là います.', _utf8mb4'{"options":{"A":"あります","B":"います","C":"ですか","D":"します"},"correctAnswer":"B"}'
    UNION ALL SELECT 2016, _utf8mb4'EASY', _utf8mb4'昨日は休みでしたが、教室に先生が（　）。先生に挨拶して帰りました。', _utf8mb4'昨日 đặt việc có mặt ở quá khứ. Với người, dùng いました.', _utf8mb4'{"options":{"A":"ありました","B":"いませんでした","C":"いました","D":"あります"},"correctAnswer":"C"}'
    UNION ALL SELECT 2031, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng khi kể lại chuyện hôm qua.', _utf8mb4'Với người và mốc 昨日, dùng dạng quá khứ khẳng định いました.', _utf8mb4'{"options":{"A":"昨日、広場に子どもがありました。","B":"昨日、広場に子どもがありますか。","C":"昨日、広場に子どもがいました。","D":"昨日、広場に子どもがいますか。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2046, _utf8mb4'MEDIUM', _utf8mb4'バスの中に人はいますか。はい、子ども（　）二人います。', _utf8mb4'が đánh dấu người hoặc con vật được giới thiệu là có mặt ở đó.', _utf8mb4'{"options":{"A":"が","B":"で","C":"を","D":"に"},"correctAnswer":"A"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 1 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Địa điểm に N がいます。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 2 (N は địa điểm にあります／います。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, _utf8mb4'田中さんはどこにいますか。今、駅（　）います。' AS content, _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.' AS explanation, _utf8mb4'{"options":{"A":"に","B":"で","C":"から","D":"を"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'赤い箱は左、青い箱（　）右にあります。', _utf8mb4'は nêu chủ đề thứ hai để đối chiếu vị trí với chủ đề thứ nhất.', _utf8mb4'{"options":{"A":"を","B":"へ","C":"は","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'入口の地図は階段（　）前にあります。', _utf8mb4'の nối vật làm mốc với danh từ vị trí như 上・中・横・前.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'EASY', _utf8mb4'かぎはかばんの中（　）あります。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"から","B":"に","C":"で","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để báo vị trí của một người.', _utf8mb4'Nêu vị trí của anh trai bằng địa điểm にいます.', _utf8mb4'{"options":{"A":"兄は今、駅をあります。","B":"兄は今、駅にあります。","C":"兄は今、駅にいます。","D":"兄は今、駅をいます。"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'A：すみません、私の傘はどこですか。B：入口の横に（　）。', _utf8mb4'Đã biết vật cần tìm là ô. trả lời địa điểm bằng にあります.', _utf8mb4'{"options":{"A":"帰ります","B":"あります","C":"います","D":"来ます"},"correctAnswer":"B"}'
    UNION ALL SELECT 7, _utf8mb4'EASY', _utf8mb4'母は台所、父（　）庭にいます。', _utf8mb4'は nêu chủ đề thứ hai để đối chiếu vị trí với chủ đề thứ nhất.', _utf8mb4'{"options":{"A":"で","B":"は","C":"を","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'今、犬は外ですか。いいえ、家の中（　）います。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"を","B":"に","C":"で","D":"から"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'ピアノは教室にあります。ギター（　）そこにあります。', _utf8mb4'も cho biết chủ thể thứ hai cũng ở nơi vừa nhắc.', _utf8mb4'{"options":{"A":"も","B":"で","C":"から","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 10, _utf8mb4'EASY', _utf8mb4'本は二階の棚（　）ありますよ。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"から","B":"を","C":"で","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'ねこを見ませんでしたか。さっき、車の下（　）いました。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"から","B":"で","C":"を","D":"に"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'A：山田さんは会社ですか。B：いいえ、今は家に（　）。', _utf8mb4'Đang nói về vị trí của một người nên dùng います.', _utf8mb4'{"options":{"A":"します","B":"あります","C":"行きましたか","D":"います"},"correctAnswer":"D"}'
    UNION ALL SELECT 13, _utf8mb4'EASY', _utf8mb4'傘はどこですか。机（　）横にあります。', _utf8mb4'の nối vật làm mốc với danh từ vị trí như 上・中・横・前.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'コートはどこ？　いす（　）上にあります。', _utf8mb4'の nối vật làm mốc với danh từ vị trí như 上・中・横・前.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'A：どの階にコピー機がありますか。B：コピー機は（　）。', _utf8mb4'Lấy máy làm chủ đề và dùng 階にあります để nêu tầng.', _utf8mb4'{"options":{"A":"二階をあります","B":"二階でいます","C":"二階からいます","D":"二階にあります"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'EASY', _utf8mb4'消しゴムはどこに（　）。— ペンケースの中です。', _utf8mb4'Vật đã biết làm chủ đề. どこにありますか hỏi vị trí của vật.', _utf8mb4'{"options":{"A":"しましたか","B":"いますか","C":"行きましたか","D":"ありますか"},"correctAnswer":"D"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'A：ねこはどこにいましたか。B：朝は（　）。今は分かりません。', _utf8mb4'Câu hỏi quá khứ về con vật cần にいました.', _utf8mb4'{"options":{"A":"庭をいました","B":"庭にありました","C":"庭にいました","D":"庭にいませんか"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'手紙は引き出しですが、切手（　）箱にあります。', _utf8mb4'は nêu chủ đề thứ hai để đối chiếu vị trí với chủ đề thứ nhất.', _utf8mb4'{"options":{"A":"で","B":"を","C":"は","D":"へ"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'EASY', _utf8mb4'ねこは今、いすの下に（　）。寝ています。', _utf8mb4'Đã nêu con mèo làm chủ đề. dùng います khi nói nó đang ở đâu.', _utf8mb4'{"options":{"A":"います","B":"あります","C":"いません","D":"します"},"correctAnswer":"A"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'先生の本は事務室、学生の本は図書室（　）あります。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"を","B":"に","C":"から","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 1002, _utf8mb4'MEDIUM', _utf8mb4'A：ノートはかばんの中ですか。B：いいえ、（　）。机を見てください。', _utf8mb4'Đổi địa điểm của vật bằng 机の上にあります.', _utf8mb4'{"options":{"A":"机の上がします","B":"机の上をいます","C":"机の上にあります","D":"机の上にいます"},"correctAnswer":"C"}'
    UNION ALL SELECT 1007, _utf8mb4'EASY', _utf8mb4'自転車は昨日、門の横に（　）。今は別の所です。', _utf8mb4'Với xe đạp ở một vị trí trong quá khứ, dùng ありました.', _utf8mb4'{"options":{"A":"ありました","B":"います","C":"いました","D":"ではありません"},"correctAnswer":"A"}'
    UNION ALL SELECT 1012, _utf8mb4'MEDIUM', _utf8mb4'財布はリュック（　）中にあります。チャックを開けてみてください。', _utf8mb4'の nối vật làm mốc với danh từ vị trí như 上・中・横・前.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"の","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 1017, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để tìm đồ vật.', _utf8mb4'Với kính, câu hỏi vị trí là どこにありますか.', _utf8mb4'{"options":{"A":"めがねはどこをいますか。","B":"めがねはどこへ行きますか。","C":"めがねはどこにいますか。","D":"めがねはどこにありますか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1022, _utf8mb4'EASY', _utf8mb4'弟はさっきまで部屋に（　）。今は出かけています。', _utf8mb4'さっきまで cho thấy người đó đã ở đấy, nên dùng いました.', _utf8mb4'{"options":{"A":"ありました","B":"いました","C":"あります","D":"いませんでした"},"correctAnswer":"B"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', _utf8mb4'「本は机にあります。」は đưa thông tin nào lên làm chủ đề?', _utf8mb4'Đã xác định cuốn sách. phần sau cung cấp vị trí của nó.', _utf8mb4'{"options":{"A":"Cuốn sách đang được tìm","B":"Chiếc bàn mới xuất hiện","C":"Người đặt sách","D":"Giờ đặt sách"},"correctAnswer":"A"}'
    UNION ALL SELECT 1032, _utf8mb4'MEDIUM', _utf8mb4'この町の学校は川の東（　）あります。地図で確かめてください。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"を","B":"で","C":"に","D":"から"},"correctAnswer":"C"}'
    UNION ALL SELECT 1037, _utf8mb4'EASY', _utf8mb4'「けしゴムは？」一つはここ（　）あります。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"を","B":"に","C":"から","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 1042, _utf8mb4'MEDIUM', _utf8mb4'鍵も携帯も探しています。鍵は棚、携帯（　）机にあります。', _utf8mb4'は nêu chủ đề thứ hai để đối chiếu vị trí với chủ đề thứ nhất.', _utf8mb4'{"options":{"A":"を","B":"は","C":"で","D":"へ"},"correctAnswer":"B"}'
    UNION ALL SELECT 1047, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để nói về cuốn từ điển.', _utf8mb4'Dùng 本棚にあります khi cuốn từ điển là vật được định vị.', _utf8mb4'{"options":{"A":"辞書は本棚をいます。","B":"辞書は本棚がいます。","C":"辞書は本棚にいます。","D":"辞書は本棚にあります。"},"correctAnswer":"D"}'
    UNION ALL SELECT 2002, _utf8mb4'EASY', _utf8mb4'父は中にいます。弟（　）中にいますよ。', _utf8mb4'も cho biết chủ thể thứ hai cũng ở nơi vừa nhắc.', _utf8mb4'{"options":{"A":"も","B":"を","C":"で","D":"から"},"correctAnswer":"A"}'
    UNION ALL SELECT 2017, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để chỉ vị trí con chó.', _utf8mb4'犬 là chủ đề. vị trí 外 theo sau bởi にいます.', _utf8mb4'{"options":{"A":"うちの犬は外にいます。","B":"うちの犬は外をいます。","C":"うちの犬を外にいます。","D":"うちの犬は外にあります。"},"correctAnswer":"A"}'
    UNION ALL SELECT 2032, _utf8mb4'MEDIUM', _utf8mb4'「弟は公園にいます。」Vì sao chọn います?', _utf8mb4'Chủ thể là em trai, nên dùng います để nêu vị trí.', _utf8mb4'{"options":{"A":"Công viên là nơi rộng","B":"Sự việc ở quá khứ","C":"Em trai đang di chuyển","D":"Chủ thể là người"},"correctAnswer":"D"}'
    UNION ALL SELECT 2047, _utf8mb4'EASY', _utf8mb4'あの先生はいつも窓側の席（　）います。', _utf8mb4'Địa điểm sau chủ đề đã biết đi với に trước あります hoặc います.', _utf8mb4'{"options":{"A":"で","B":"を","C":"から","D":"に"},"correctAnswer":"D"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 2 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N は địa điểm にあります／います。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 3 (N1 は N2 の + vị trí + にあります／います。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
