    UNION ALL SELECT 1028, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng khi nói về khoảng giữa hai nhà.', _utf8mb4'Dùng 二つの家の間に + あります cho vị trí của cây.', _utf8mb4'{"options":{"A":"木は二つの家の間にいます。","B":"木は二つの家を間にあります。","C":"木は二つの家の間にあります。","D":"木は二つの家に間のあります。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1033, _utf8mb4'EASY', _utf8mb4'交番は駅（　）となりにあります。', _utf8mb4'Dùng の để nối vật làm mốc với từ chỉ vị trí tương đối.', _utf8mb4'{"options":{"A":"へ","B":"を","C":"で","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', _utf8mb4'玄関の外（　）自転車があります。中には置いていません。', _utf8mb4'Sau cụm chỉ vị trí, に đánh dấu nơi vật hoặc người hiện diện.', _utf8mb4'{"options":{"A":"に","B":"から","C":"で","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1043, _utf8mb4'MEDIUM', _utf8mb4'駅を出たら右を見てください。銀行（　）向こうに病院があります。', _utf8mb4'Dùng の để nối vật làm mốc với từ chỉ vị trí tương đối.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"を","D":"の"},"correctAnswer":"D"}'
    UNION ALL SELECT 1048, _utf8mb4'EASY', _utf8mb4'箱の中（　）何がありますか。', _utf8mb4'Sau cụm chỉ vị trí, に đánh dấu nơi vật hoặc người hiện diện.', _utf8mb4'{"options":{"A":"から","B":"に","C":"を","D":"で"},"correctAnswer":"B"}'
    UNION ALL SELECT 2003, _utf8mb4'MEDIUM', _utf8mb4'「机の下に本があります。」下 được nối với 机 bằng の vì sao?', _utf8mb4'下 hoạt động như danh từ vị trí, cần の sau vật làm mốc.', _utf8mb4'{"options":{"A":"Để nói sách thuộc sở hữu của ai","B":"Để xác định phía dưới của vật nào","C":"Để đánh dấu nơi đọc","D":"Để đếm sách"},"correctAnswer":"B"}'
    UNION ALL SELECT 2018, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng khi chỉ vị trí phía trước.', _utf8mb4'の前 liên kết phía trước với cánh cổng làm mốc.', _utf8mb4'{"options":{"A":"私の自転車は門の前をあります。","B":"私の自転車は門を前にあります。","C":"私の自転車は門の前にあります。","D":"私の自転車は門が前にあります。"},"correctAnswer":"C"}'
    UNION ALL SELECT 2033, _utf8mb4'EASY', _utf8mb4'本屋は銀行と郵便局（　）間にあります。', _utf8mb4'Dùng の để nối vật làm mốc với từ chỉ vị trí tương đối.', _utf8mb4'{"options":{"A":"の","B":"で","C":"を","D":"へ"},"correctAnswer":"A"}'
    UNION ALL SELECT 2048, _utf8mb4'MEDIUM', _utf8mb4'A：二人はどんな順番で立っていますか。B：先に先生、そのすぐ後ろに（　）。', _utf8mb4'Dùng 人がいます sau cụm vị trí để giới thiệu người đứng phía sau.', _utf8mb4'{"options":{"A":"学生があります","B":"学生がいます","C":"学生をいます","D":"学生にあります"},"correctAnswer":"B"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 1
                AND l.display_order = 3 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'N1 は N2 の + vị trí + にあります／います。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 4 (だれもいません。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
