                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 12 (Vています。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'A：今、教室で何をしていますか。B：（　）。まだ作文は終わっていません。' AS content, _utf8mb4'何をしていますか hỏi việc đang làm. 書いています đáp đúng thời điểm.' AS explanation, _utf8mb4'{"options":{"A":"作文を書きませんでした","B":"作文を書きましょうか","C":"作文を書いています","D":"作文を書いてください"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'今、店長はお客さんを（　）います。何人いるでしょうか。', _utf8mb4'数える thuộc nhóm 2. 数えている diễn tả việc đếm đang xảy ra.', _utf8mb4'{"options":{"A":"数えて","B":"数えって","C":"数えた","D":"数えるて"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'EASY', _utf8mb4'窓から見えます。今、子どもがプールで（　）。', _utf8mb4'泳ぐ đổi ぐ thành いで trước います.', _utf8mb4'{"options":{"A":"泳いで","B":"泳ぎて","C":"泳いて","D":"泳ぎ"},"correctAnswer":"A"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'生放送です。駅員がドアを（　）います。手を入れないで。', _utf8mb4'閉める bỏ る trước て. 閉めています chỉ thao tác đang tiến hành.', _utf8mb4'{"options":{"A":"閉めって","B":"閉めるて","C":"閉めた","D":"閉めて"},"correctAnswer":"D"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'A：赤ちゃんは今どうしていますか。B：（　）。起こさないでください。', _utf8mb4'Lời dặn đừng đánh thức cho biết em bé đang ngủ. 寝る → 寝ています.', _utf8mb4'{"options":{"A":"寝ましょうか","B":"寝てください","C":"寝ませんでした","D":"寝ています"},"correctAnswer":"D"}'
    UNION ALL SELECT 6, _utf8mb4'EASY', _utf8mb4'今、私は台所です。夕食を（　）いるので、電話はあとで。', _utf8mb4'作る là động từ nhóm 1, dùng 作って trước いる.', _utf8mb4'{"options":{"A":"作るて","B":"作りて","C":"作った","D":"作って"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'A：今、手が離せません。B：何をしているんですか。A：（　）。包丁を使っています。', _utf8mb4'切る dùng 切って＋います để tả thao tác đang làm với dao.', _utf8mb4'{"options":{"A":"野菜を切っています","B":"野菜を切ってください","C":"野菜を切りましょう","D":"野菜を切りませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'A：ミンさんは今、練習中です。B：何の練習ですか。A：（　）。音が聞こえますね。', _utf8mb4'あの音 và 今 xác định động tác đang xảy ra. 弾く nối いています.', _utf8mb4'{"options":{"A":"ギターを弾いてください","B":"ギターを弾いています","C":"ギターは弾きませんでした","D":"ギターを弾きましょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 9, _utf8mb4'EASY', _utf8mb4'あの音は何ですか。兄がピアノを（　）います。', _utf8mb4'弾く đổi く thành いて. ています diễn tả hành động đang nghe thấy.', _utf8mb4'{"options":{"A":"弾って","B":"弾くて","C":"弾いて","D":"弾きて"},"correctAnswer":"C"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'今、自転車のタイヤを（　）います。まだ乗れません。', _utf8mb4'直す đổi す thành して để diễn tả đang sửa một vật.', _utf8mb4'{"options":{"A":"直すて","B":"直ってて","C":"直した","D":"直して"},"correctAnswer":"D"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'聞いて。外では強い雨が（　）います。', _utf8mb4'降る là động từ nhóm 1. 降っている chỉ hiện tượng đang diễn ra.', _utf8mb4'{"options":{"A":"降って","B":"降んで","C":"降りて","D":"降るて"},"correctAnswer":"A"}'
    UNION ALL SELECT 12, _utf8mb4'EASY', _utf8mb4'今、駅前です。タクシーを（　）います。まだ来ません。', _utf8mb4'待つ đổi つ thành って trước います để diễn tả đang chờ.', _utf8mb4'{"options":{"A":"待って","B":"待ちて","C":"待んで","D":"待つて"},"correctAnswer":"A"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'カメラを見てください。今、赤ちゃんがミルクを（　）。', _utf8mb4'飲んでいます thuật lại việc đang quan sát, dùng thể て của 飲む.', _utf8mb4'{"options":{"A":"飲みましょうか","B":"飲んでください","C":"飲んでいます","D":"飲みたいですか"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để thuật lại điều đang thấy ở sân trường.', _utf8mb4'遊ぶ đổi thành 遊んで rồi nối います để mô tả cảnh đang thấy.', _utf8mb4'{"options":{"A":"今、子どもが校庭で遊んでください。","B":"今、子どもが校庭で遊びています。","C":"今、子どもが校庭で遊んでいます。","D":"今、子どもが校庭で遊ぶています。"},"correctAnswer":"C"}'
    UNION ALL SELECT 15, _utf8mb4'EASY', _utf8mb4'先生は今、教室で学生と（　）います。', _utf8mb4'話す đổi す thành して. ています chỉ việc đang diễn ra.', _utf8mb4'{"options":{"A":"話って","B":"話すて","C":"話し","D":"話して"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'Bạn nhìn qua cửa sổ và nói「子どもが走っています」。Câu này mô tả điều gì?', _utf8mb4'Trong cảnh trước mắt, Vています cho biết hành động đang tiếp diễn.', _utf8mb4'{"options":{"A":"Hãy bảo trẻ chạy","B":"Trẻ đang chạy ngay lúc nói","C":"Người nói rủ trẻ cùng chạy","D":"Trẻ muốn chạy"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'静かに。今はテストの時間です。みんな問題を（　）。', _utf8mb4'解く đổi く thành いて. います diễn tả việc cả lớp đang làm.', _utf8mb4'{"options":{"A":"解きましょうか","B":"解きましょう","C":"解いています","D":"解いてください"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'EASY', _utf8mb4'中継です。選手が橋の上を（　）います。', _utf8mb4'走る thuộc nhóm 1, dùng 走って trước います.', _utf8mb4'{"options":{"A":"走んで","B":"走って","C":"走りて","D":"走るて"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'今、コピーの音がします。事務の人が資料を（　）。', _utf8mb4'する có thể て là して. しています mô tả công việc đang nghe thấy.', _utf8mb4'{"options":{"A":"コピーをしてからです","B":"コピーしています","C":"コピーしてください","D":"コピーしましょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để giải thích mình đang học ở thư viện.', _utf8mb4'勉強する dùng して trước います để nói về việc đang làm.', _utf8mb4'{"options":{"A":"今、図書館で日本語を勉強しますています。","B":"今、図書館で日本語を勉強しています。","C":"今、図書館で日本語を勉強してください。","D":"今、図書館で日本語を勉強するいます。"},"correctAnswer":"B"}'
    UNION ALL SELECT 1002, _utf8mb4'EASY', _utf8mb4'少し待ってください。今、メールを（　）いるところです。', _utf8mb4'書く đổi く thành いて. 書いている chỉ việc viết đang tiếp diễn.', _utf8mb4'{"options":{"A":"書いた","B":"書きて","C":"書って","D":"書いて"},"correctAnswer":"D"}'
    UNION ALL SELECT 1007, _utf8mb4'MEDIUM', _utf8mb4'窓の外を見て。白い船が川を（　）。乗っている人が見えます。', _utf8mb4'渡る dùng 渡って trước います để tả cảnh trước mắt.', _utf8mb4'{"options":{"A":"渡っています","B":"渡るています","C":"渡りましょうか","D":"渡ってください"},"correctAnswer":"A"}'
    UNION ALL SELECT 1012, _utf8mb4'MEDIUM', _utf8mb4'Trong cuộc gọi,「今、何をしていますか」hỏi điều gì?', _utf8mb4'今 kết hợp Vていますか để hỏi hành động của người nghe vào lúc nói.', _utf8mb4'{"options":{"A":"Hôm qua người nghe đã làm gì","B":"Người nghe muốn nhờ việc gì","C":"Người nghe đang làm gì lúc này","D":"Người nói nên giúp làm gì"},"correctAnswer":"C"}'
    UNION ALL SELECT 1017, _utf8mb4'EASY', _utf8mb4'庭を見て。弟がボールで（　）いるよ。', _utf8mb4'遊ぶ đổi ぶ thành んで trước いる.', _utf8mb4'{"options":{"A":"遊って","B":"遊んだ","C":"遊びて","D":"遊んで"},"correctAnswer":"D"}'
    UNION ALL SELECT 1022, _utf8mb4'MEDIUM', _utf8mb4'電話に出られません。今、車を（　）からです。', _utf8mb4'運転しています nêu việc đang làm, cũng là lý do chưa thể nghe máy.', _utf8mb4'{"options":{"A":"運転してください","B":"運転しています","C":"運転しましょうか","D":"運転するています"},"correctAnswer":"B"}'
    UNION ALL SELECT 1027, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để hỏi bạn đang xem gì lúc này.', _utf8mb4'Hỏi hành động đang diễn ra bằng Vていますか. 見る có thể て là 見て.', _utf8mb4'{"options":{"A":"今、何を見ていますか。","B":"今、何を見てください。","C":"今、何を見るていますか。","D":"今、何を見ますていますか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1032, _utf8mb4'EASY', _utf8mb4'昼休みです。二人は食堂でパンを（　）います。', _utf8mb4'食べる thuộc nhóm 2, bỏ る rồi thêm て để nối với います.', _utf8mb4'{"options":{"A":"食べた","B":"食べって","C":"食べるて","D":"食べて"},"correctAnswer":"D"}'
    UNION ALL SELECT 1037, _utf8mb4'MEDIUM', _utf8mb4'A：もう電車に乗りましたか。B：いいえ、ホームで（　）。まだ来ません。', _utf8mb4'まだ来ません cho biết việc chờ vẫn tiếp diễn. 待つ dùng 待っています.', _utf8mb4'{"options":{"A":"待つています","B":"待ってください","C":"待っています","D":"待ちましょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1042, _utf8mb4'MEDIUM', _utf8mb4'今、そちらでは何を（　）。こちらは雪の写真を撮っています。', _utf8mb4'何をしていますか hỏi hành động đang diễn ra ở đầu dây bên kia.', _utf8mb4'{"options":{"A":"したですか","B":"していますか","C":"してください","D":"しましょう"},"correctAnswer":"B"}'
    UNION ALL SELECT 1047, _utf8mb4'EASY', _utf8mb4'今、放送室です。学生が日本語の文を（　）います。', _utf8mb4'読む đổi む thành んで. 読んでいます là đang đọc.', _utf8mb4'{"options":{"A":"読んで","B":"読むて","C":"読みて","D":"読って"},"correctAnswer":"A"}'
    UNION ALL SELECT 2012, _utf8mb4'MEDIUM', _utf8mb4'映画はまだ終わっていません。家族は今も映画を（　）。', _utf8mb4'見る dùng 見て trước います. 今も cho biết việc xem còn tiếp diễn.', _utf8mb4'{"options":{"A":"見ましょうか","B":"見るています","C":"見ています","D":"見てください"},"correctAnswer":"C"}'
    UNION ALL SELECT 2027, _utf8mb4'MEDIUM', _utf8mb4'今、母はまだ買い物中です。レジで代金を（　）。', _utf8mb4'払う đổi う thành って. います tả việc đang trả tiền.', _utf8mb4'{"options":{"A":"払うています","B":"払っています","C":"払ってください","D":"払いましょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 2042, _utf8mb4'EASY', _utf8mb4'今テレビを見ると、歌手が歌を（　）います。', _utf8mb4'歌う kết thúc bằng う nên dùng って trước います.', _utf8mb4'{"options":{"A":"歌いて","B":"歌った","C":"歌って","D":"歌うて"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 12 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vています。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 13 (Vます → Vましょうか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'A：すみません、両手がいっぱいです。B：では、私がドアを（　）。A：お願いします。' AS content, _utf8mb4'お願いします nhận lời giúp. người B là người mở cửa nên dùng ましょうか.' AS explanation, _utf8mb4'{"options":{"A":"開けましょうか","B":"開けてください","C":"開けていますか","D":"開けたいですか"},"correctAnswer":"A"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'EASY', _utf8mb4'荷物がとても重そうですね。私が（　）。', _utf8mb4'持つ bỏ ます ở 持ちます rồi thêm ましょうか để đề nghị mang giúp.', _utf8mb4'{"options":{"A":"持ちましょうか","B":"持つましょうか","C":"持ってください","D":"持ちませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'本が棚の上ですね。私なら届きます。私が（　）。', _utf8mb4'取る đổi thành 取り trước ましょうか khi đề nghị lấy hộ.', _utf8mb4'{"options":{"A":"取っていますか","B":"取ってください","C":"取りましょうか","D":"取るましょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'A：住所の漢字が難しいです。B：私が代わりに（　）。A：ありがとう。', _utf8mb4'私が代わりに xác định người viết hộ. lời đề nghị dùng 書きましょうか.', _utf8mb4'{"options":{"A":"書いてください","B":"書くですか","C":"書きましょうか","D":"書いていますか"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'EASY', _utf8mb4'写真を撮る人がいませんね。私が皆さんの写真を（　）。', _utf8mb4'撮りましょうか là lời người nói đề nghị chụp cho cả nhóm.', _utf8mb4'{"options":{"A":"撮るましょうか","B":"撮りましょうか","C":"撮ってください","D":"撮りたいですか"},"correctAnswer":"B"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'言葉が分かりませんか。私が辞書で（　）。', _utf8mb4'調べましょうか là lời đề nghị tra cứu giúp người nghe.', _utf8mb4'{"options":{"A":"調べましょうか","B":"調べるましょうか","C":"調べてください","D":"調べていますか"},"correctAnswer":"A"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'A：財布をなくしました。B：私も一緒に（　）。A：ええ、助かります。', _utf8mb4'助かります đáp lại lời ngỏ ý cùng tìm. 探す dùng 探しましょうか.', _utf8mb4'{"options":{"A":"探しましょうか","B":"探してください","C":"探していますか","D":"探しませんでした"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'EASY', _utf8mb4'暑そうですね。窓は私のすぐ横です。私が（　）。', _utf8mb4'開ける dùng 開けましょうか khi người nói đề nghị ra tay giúp.', _utf8mb4'{"options":{"A":"開けてください","B":"開けるましょうか","C":"開けていますか","D":"開けましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để đề nghị mang giúp va li cho khách.', _utf8mb4'私が và thân 持ち＋ましょうか thể hiện người nói ngỏ ý làm hộ.', _utf8mb4'{"options":{"A":"重そうですね。私が持ってください。","B":"重そうですね。私が持ちましょうか。","C":"重そうですね。私が持ちますか。","D":"重そうですね。私が持つましょうか。"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để đề nghị đặt chỗ giúp bạn.', _utf8mb4'予約する dùng しましょうか khi người nói hỏi có cần mình giúp không.', _utf8mb4'{"options":{"A":"私が席を予約しましょうか。","B":"私が席を予約するましょうか。","C":"私が席を予約してください。","D":"私が席を予約していますか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'EASY', _utf8mb4'黒板の字が小さいですね。私が大きく（　）。', _utf8mb4'書き là thân ます. 私が chỉ người nói sẽ viết giúp.', _utf8mb4'{"options":{"A":"書くましょうか","B":"書いていますか","C":"書きましょうか","D":"書いてください"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'寒そうですね。入り口にいる私がドアを（　）。', _utf8mb4'閉めましょうか hỏi xem người nghe có muốn mình đóng cửa giúp.', _utf8mb4'{"options":{"A":"閉めてください","B":"閉めましょうか","C":"閉めていますか","D":"閉めるましょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'コピーが要りますね。私が会議の資料を（　）。', _utf8mb4'Với コピーする, lời đề nghị dùng しましょうか sau コピー.', _utf8mb4'{"options":{"A":"コピーするましょうか","B":"コピーしてください","C":"コピーしましょうか","D":"コピーしていますか"},"correctAnswer":"C"}'
    UNION ALL SELECT 14, _utf8mb4'EASY', _utf8mb4'駅までの道が分かりませんか。私が地図を（　）。', _utf8mb4'Thân 描き nối ましょうか để đề nghị vẽ bản đồ cho người nghe.', _utf8mb4'{"options":{"A":"描いてください","B":"描くましょうか","C":"描いていますか","D":"描きましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'道に迷ったんですか。交番まで私が案内（　）。', _utf8mb4'案内する dùng しましょうか để người nói đề nghị dẫn đường.', _utf8mb4'{"options":{"A":"してください","B":"するましょうか","C":"していますか","D":"しましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'傘がないんですね。私の予備の傘を貸し（　）。', _utf8mb4'Sau thân 貸し, ましょうか biến lời nói thành đề nghị cho mượn.', _utf8mb4'{"options":{"A":"るでしょうか","B":"ましょうか","C":"ていますか","D":"てください"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'EASY', _utf8mb4'お客さんが来ましたね。私がお茶を（　）。', _utf8mb4'入れましょうか hỏi người nghe có muốn mình pha trà giúp hay không.', _utf8mb4'{"options":{"A":"入れるましょうか","B":"入れたいですか","C":"入れましょうか","D":"入れてください"},"correctAnswer":"C"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Khách cầm nhiều đồ. Nhân viên nói「私が持ちましょうか」。Ai sẽ cầm nếu khách đồng ý?', _utf8mb4'私が chỉ nhân viên. ましょうか là lời đề nghị làm giúp.', _utf8mb4'{"options":{"A":"Khách phải cầm giúp nhân viên","B":"Nhân viên sẽ cầm hộ khách","C":"Cả hai đã cầm xong","D":"Nhân viên hỏi khách đã cầm chưa"},"correctAnswer":"B"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'ひとりでは難しいですね。私がひもを結び（　）。', _utf8mb4'Thân 結び nối trực tiếp với ましょうか khi đề nghị buộc hộ.', _utf8mb4'{"options":{"A":"ていますか","B":"るですか","C":"てください","D":"ましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'EASY', _utf8mb4'お皿がたくさんありますね。私が（　）。', _utf8mb4'洗う có thân ます là 洗い. ましょうか diễn đạt ý đề nghị giúp.', _utf8mb4'{"options":{"A":"洗うましょうか","B":"洗ってください","C":"洗っていますか","D":"洗いましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 1003, _utf8mb4'MEDIUM', _utf8mb4'ごみがいっぱいですね。私が外に出し（　）。', _utf8mb4'出し là thân ます. thêm ましょうか để hỏi xem mình có thể giúp không.', _utf8mb4'{"options":{"A":"るでしょうか","B":"ていますか","C":"ってください","D":"ましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 1008, _utf8mb4'MEDIUM', _utf8mb4'A：この箱、一人では持てません。B：私がそちらを（　）。A：お願いします。', _utf8mb4'B nhận một bên hộ A. 持ちましょうか là lời đề nghị của B.', _utf8mb4'{"options":{"A":"持ちましょうか","B":"持ってください","C":"持っていますか","D":"持ちたいですか"},"correctAnswer":"A"}'
    UNION ALL SELECT 1013, _utf8mb4'EASY', _utf8mb4'字がよく見えませんか。私が手紙を（　）。', _utf8mb4'読みましょうか đề nghị người nói đọc thư cho người nghe.', _utf8mb4'{"options":{"A":"読んでいますか","B":"読みましょうか","C":"読むましょうか","D":"読んでください"},"correctAnswer":"B"}'
    UNION ALL SELECT 1018, _utf8mb4'MEDIUM', _utf8mb4'荷物はまだ駅ですね。私が車で取りに行き（　）。', _utf8mb4'行きましょうか đề nghị chính người nói đi lấy.', _utf8mb4'{"options":{"A":"るですか","B":"ていますか","C":"ましょうか","D":"てください"},"correctAnswer":"C"}'
    UNION ALL SELECT 1023, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để đề nghị đón người nghe bằng xe.', _utf8mb4'迎えに行きましょうか là lời đề nghị của người sẽ đi đón.', _utf8mb4'{"options":{"A":"私が車で駅まで迎えに行きましょうか。","B":"私が車で駅まで迎えに行くましょうか。","C":"私が車で駅まで迎えに行ってください。","D":"私が車で駅まで迎えに行きたいですか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 1028, _utf8mb4'EASY', _utf8mb4'バスはもうありませんね。私がタクシーを（　）。', _utf8mb4'呼び cộng ましょうか cho biết người nói sẵn sàng gọi xe giúp.', _utf8mb4'{"options":{"A":"呼ぶましょうか","B":"呼びましょうか","C":"呼んでください","D":"呼んでいますか"},"correctAnswer":"B"}'
    UNION ALL SELECT 1033, _utf8mb4'MEDIUM', _utf8mb4'会議まで時間がありませんね。私が店に電話（　）。', _utf8mb4'電話する → 電話しましょうか là đề nghị gọi điện hộ.', _utf8mb4'{"options":{"A":"していますか","B":"するましょうか","C":"してください","D":"しましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 1038, _utf8mb4'MEDIUM', _utf8mb4'荷物が重そうですね。私がその辞書を持って（　）。— はい、お願いします。', _utf8mb4'帰りましょうか đề nghị người nói mang đồ về giúp đối phương.', _utf8mb4'{"options":{"A":"帰ってください","B":"帰っていますか","C":"帰りましょうか","D":"帰るましょうか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1043, _utf8mb4'EASY', _utf8mb4'机が邪魔ですね。私が廊下へ（　）。', _utf8mb4'運ぶ dùng thân 運び trước ましょうか để ngỏ ý chuyển bàn giúp.', _utf8mb4'{"options":{"A":"運んでいますか","B":"運びましょうか","C":"運ぶましょうか","D":"運んでください"},"correctAnswer":"B"}'
    UNION ALL SELECT 1048, _utf8mb4'MEDIUM', _utf8mb4'漢字が読めないんですか。私が横にひらがなを（　）。', _utf8mb4'私が chỉ người sẽ viết. ましょうか ngỏ ý giúp người nghe.', _utf8mb4'{"options":{"A":"書いてください","B":"書いていますか","C":"書くましょうか","D":"書きましょうか"},"correctAnswer":"D"}'
    UNION ALL SELECT 2013, _utf8mb4'MEDIUM', _utf8mb4'「窓を開けてください」と「私が窓を開けましょうか」khác nhau ở điểm nào?', _utf8mb4'てください nhờ người nghe. 私が…ましょうか đề nghị tự mình làm.', _utf8mb4'{"options":{"A":"Cả hai đều ra lệnh mở","B":"Câu đầu nhờ mở, câu sau ngỏ ý mở hộ","C":"Câu sau hỏi cửa có đang mở không","D":"Câu đầu kể việc đã làm"},"correctAnswer":"B"}'
    UNION ALL SELECT 2028, _utf8mb4'EASY', _utf8mb4'一人で準備するのは大変ですね。私も（　）。', _utf8mb4'私も và ましょうか cho thấy người nói tự ngỏ ý phụ giúp.', _utf8mb4'{"options":{"A":"手伝いましょうか","B":"手伝ってください","C":"手伝っていますか","D":"手伝うましょうか"},"correctAnswer":"A"}'
    UNION ALL SELECT 2043, _utf8mb4'MEDIUM', _utf8mb4'A：部屋が少し暗いですね。B：私が電気を（　）。A：ええ、お願いします。', _utf8mb4'私が và lời chấp nhận cho thấy B đề nghị bật đèn cho A.', _utf8mb4'{"options":{"A":"つけたいですか","B":"つけてください","C":"つけましょうか","D":"つけていますか"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 13 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'Vます → Vましょうか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 14 (だれが Vましたか。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'お昼に電話がありましたね。だれ（　）電話しましたか。— 母が電話しました。' AS content, _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.' AS explanation, _utf8mb4'{"options":{"A":"に","B":"を","C":"が","D":"で"},"correctAnswer":"C"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'だれが窓を開けましたか。— 私（　）開けました。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'昨日の朝、受付に（　）。— 配達の人が来ました。', _utf8mb4'来る là hành động do người đến thực hiện. hỏi chủ thể quá khứ bằng だれが来ましたか.', _utf8mb4'{"options":{"A":"なにを来ましたか","B":"だれが来ましたか","C":"だれを来ましたか","D":"だれに来ますか"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'きのうの試合で、だれ（　）勝ちましたか。— リンさんが勝ちました。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"を","B":"に","C":"が","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'「だれが先生を呼びましたか」「弟（　）呼びました。」', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"が","B":"を","C":"で","D":"に"},"correctAnswer":"A"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'このケーキを作った人に会いたいです。だれ（　）作りましたか。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"に","C":"が","D":"を"},"correctAnswer":"C"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'「だれが先に駅に着きましたか」「父（　）着きました。」', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"を","B":"が","C":"で","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'「だれが田中さんを呼びましたか。」Người hỏi muốn xác định ai?', _utf8mb4'だれが hỏi người gọi. 田中さんを là người được gọi.', _utf8mb4'{"options":{"A":"Người đã gọi Tanaka","B":"Người nhận quà của Tanaka","C":"Người mà Tanaka gọi","D":"Người đang nói với Tanaka"},"correctAnswer":"A"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'「先生がだれを呼びましたか」と「だれが先生を呼びましたか」khác nhau ở đâu?', _utf8mb4'を gắn với người được gọi, còn が gắn với người thực hiện hành động.', _utf8mb4'{"options":{"A":"Chỉ câu sau hỏi một địa điểm","B":"Câu đầu hỏi người được gọi, câu sau hỏi người gọi","C":"Cả hai hỏi người được gọi","D":"Cả hai hỏi giờ gọi"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'黒板のこの漢字は、だれ（　）書きましたか。— 私が書きました。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"を","B":"で","C":"が","D":"に"},"correctAnswer":"C"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'A：きのう、だれが教室に残りましたか。B：（　）。私は先に帰りました。', _utf8mb4'Tên người trả lời cho だれが đi với が. 残る dùng quá khứ 残りました.', _utf8mb4'{"options":{"A":"リンさんと残りますか","B":"リンさんを残りました","C":"リンさんに残りました","D":"リンさんが残りました"},"correctAnswer":"D"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'A：プレゼントを買った人を教えて。B：（　）。父はカードを書きました。', _utf8mb4'B xác định người đã mua, nên người đó nhận が, động từ dùng ました.', _utf8mb4'{"options":{"A":"母が買いますか","B":"母に買いました","C":"母が買いました","D":"母を買いました"},"correctAnswer":"C"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'だれが鍵を拾いましたか。— 掃除の人（　）拾いました。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"が","C":"を","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'きのうの発表で、だれが（　）。— 木村さんが英語で話しました。', _utf8mb4'Hỏi ai đã trình bày hôm qua nên dùng だれが với động từ quá khứ ましたか.', _utf8mb4'{"options":{"A":"英語で話しましたか","B":"英語を話してください","C":"英語で話しましょうか","D":"英語で話していますか"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'作った人の名前が知りたいです。このいすは、だれ（　）作りましたか。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'朝、玄関で音がしましたね。だれ（　）入りましたか。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"が","B":"を","C":"に","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'「会議を始めたのはだれですか」「部長（　）始めました。」', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"を","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để hỏi ai đã xóa chữ trên bảng.', _utf8mb4'だれが hỏi người đã làm. 消しましたか giữ thời quá khứ.', _utf8mb4'{"options":{"A":"黒板の字はだれが消しましたか。","B":"黒板の字はだれに消しませんか。","C":"黒板の字はだれを消しましたか。","D":"黒板の字はだれで消しますか。"},"correctAnswer":"A"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'A：この赤い線、（　）。B：私が引きました。すみません。', _utf8mb4'私が引きました đáp lại câu hỏi ai đã kẻ, dùng だれが và quá khứ.', _utf8mb4'{"options":{"A":"どこで引きますか","B":"だれが引きましたか","C":"だれを引きましたか","D":"いつ引きましょうか"},"correctAnswer":"B"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để xác định ai đã trả tiền ở quầy.', _utf8mb4'Hỏi người trả tiền hôm qua bằng だれが và động từ quá khứ.', _utf8mb4'{"options":{"A":"きのう、レジでだれが払いましょう。","B":"きのう、レジでだれを払いましたか。","C":"きのう、レジでだれで払いましたか。","D":"きのう、レジでだれが払いましたか。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1004, _utf8mb4'MEDIUM', _utf8mb4'「本を返した人はだれですか」「私（　）返しました。」', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"が","C":"を","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1009, _utf8mb4'EASY', _utf8mb4'先生に聞きます。「きのう、（　）教室の掃除をしましたか。」「三班の学生です。」', _utf8mb4'Đáp án nêu người đã dọn. だれが hỏi chủ thể của hành động quá khứ.', _utf8mb4'{"options":{"A":"なにを","B":"どこで","C":"だれを","D":"だれが"},"correctAnswer":"D"}'
    UNION ALL SELECT 1014, _utf8mb4'MEDIUM', _utf8mb4'A：きのう先生にノートを渡したのは（　）。B：ハイさんが渡しました。', _utf8mb4'のはだれですか hỏi danh tính người đã làm. B trả lời bằng ハイさんが.', _utf8mb4'{"options":{"A":"いくらですか","B":"どこですか","C":"だれですか","D":"いつですか"},"correctAnswer":"C"}'
    UNION ALL SELECT 1019, _utf8mb4'MEDIUM', _utf8mb4'みんな一緒に走りました。一番早くゴールしたのは？　— アンさん（　）一番でした。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"が","B":"を","C":"で","D":"に"},"correctAnswer":"A"}'
    UNION ALL SELECT 1024, _utf8mb4'EASY', _utf8mb4'だれ（　）この絵を描きましたか。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"を","B":"で","C":"に","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 1029, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để trả lời câu hỏi「だれが教えましたか」.', _utf8mb4'が đánh dấu 姉 là người đã dạy, tương ứng với だれが.', _utf8mb4'{"options":{"A":"その歌は姉を教えました。","B":"その歌は姉が教えますか。","C":"その歌は姉で教えました。","D":"その歌は姉が教えました。"},"correctAnswer":"D"}'
    UNION ALL SELECT 1034, _utf8mb4'MEDIUM', _utf8mb4'この手紙は先生に届きました。書いたのはだれですか。— クラスの代表（　）書きました。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"が","B":"に","C":"で","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 1039, _utf8mb4'EASY', _utf8mb4'「だれが来ましたか」「山田さん（　）来ました。」', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"が","B":"を","C":"で","D":"に"},"correctAnswer":"A"}'
    UNION ALL SELECT 1044, _utf8mb4'MEDIUM', _utf8mb4'きのう、だれ（　）欠席しましたか。名簿に印をつけます。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"に","B":"を","C":"が","D":"で"},"correctAnswer":"C"}'
    UNION ALL SELECT 1049, _utf8mb4'MEDIUM', _utf8mb4'「だれがこの箱を置きましたか。」「（　）。私ではありません。」', _utf8mb4'Trả lời だれが bằng người thực hiện với が và động từ ở quá khứ.', _utf8mb4'{"options":{"A":"兄を置きました","B":"兄が置きました","C":"兄に置きました","D":"兄が置きますか"},"correctAnswer":"B"}'
    UNION ALL SELECT 2014, _utf8mb4'EASY', _utf8mb4'「あのピアノは、だれ（　）弾きましたか。」「妹です。」', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"に","B":"が","C":"で","D":"を"},"correctAnswer":"B"}'
    UNION ALL SELECT 2029, _utf8mb4'MEDIUM', _utf8mb4'係の人を確認します。この写真は、だれ（　）撮りましたか。', _utf8mb4'が đánh dấu người thực hiện cần xác định trong câu hỏi hoặc câu trả lời về だれ.', _utf8mb4'{"options":{"A":"で","B":"に","C":"を","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 2044, _utf8mb4'MEDIUM', _utf8mb4'A：ドアの前に花がありました。あの花は（　）。B：隣の人が置きましたよ。', _utf8mb4'Câu đáp nêu người đặt hoa. だれが hỏi tác nhân của 置きました.', _utf8mb4'{"options":{"A":"どこに置きましょうか","B":"いつ置きましたか","C":"だれが置きましたか","D":"だれを置きましたか"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 14 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'だれが Vましたか。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- JPD123 / Chương 7 / NGỮ PHÁP / Mẫu 15 (まだあります／もうありません。)
INSERT INTO question (skill, question_type, lesson_id, grammar_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'GRAMMAR', 'MCQ', l.id, g.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'MEDIUM' AS difficulty, _utf8mb4'Chọn câu đúng để báo bưu thiếp vẫn còn sau khi đã bán một ít.' AS content, _utf8mb4'十枚残っています cho biết vẫn còn. まだ đi với あります.' AS explanation, _utf8mb4'{"options":{"A":"はがきは十枚残っています。まだありません。","B":"はがきは十枚残っています。もうなくなりました。","C":"はがきは十枚残っています。もうありません。","D":"はがきは十枚残っています。まだあります。"},"correctAnswer":"D"}' AS answers
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'さっき最後の一つを食べました。箱の中にお菓子は（　）。', _utf8mb4'Ngay cả cái cuối cũng hết. もうありません diễn tả hiện nay không còn.', _utf8mb4'{"options":{"A":"もうあります","B":"まだあります","C":"もうありません","D":"まだ残っています"},"correctAnswer":"C"}'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'チーズは全部使いました。冷蔵庫にチーズは（　）。', _utf8mb4'全部使いました nghĩa là đã dùng hết nên chọn もうありません.', _utf8mb4'{"options":{"A":"まだあります","B":"もうありません","C":"まだ残っています","D":"もうあります"},"correctAnswer":"B"}'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'消しゴムは一つしか使っていません。机に二つ（　）。', _utf8mb4'Hai cục còn trên bàn, vì vậy dùng まだ với động từ tồn tại khẳng định.', _utf8mb4'{"options":{"A":"まだあります","B":"もうありません","C":"まだありません","D":"もうなくなりました"},"correctAnswer":"A"}'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'白い紙は使い切りました。白い紙は（　）。青い紙を使いましょう。', _utf8mb4'使い切りました xác định giấy trắng đã hết. もう đi cùng ありません.', _utf8mb4'{"options":{"A":"まだあります","B":"まだ残っています","C":"もうありません","D":"もうあります"},"correctAnswer":"C"}'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'A：このサイズは全部売れましたか。B：いいえ、奥に一着（　）。お持ちします。', _utf8mb4'一着 và lời đi lấy xác nhận vẫn còn một chiếc. dùng まだあります.', _utf8mb4'{"options":{"A":"まだありません","B":"もうありません","C":"もうなくなりました","D":"まだあります"},"correctAnswer":"D"}'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'店員「昨日までありましたが、もうありません。」Tình trạng hàng đã đổi thế nào?', _utf8mb4'もう kết hợp ありません cho biết trước kia có nhưng hiện đã hết.', _utf8mb4'{"options":{"A":"Trước có, hiện đã hết","B":"Chưa từng có","C":"Vẫn còn như hôm qua","D":"Trước hết, nay đã có"},"correctAnswer":"A"}'
    UNION ALL SELECT 8, _utf8mb4'MEDIUM', _utf8mb4'今月の休みはあと一日です。今月は休みが（　）。', _utf8mb4'あと一日 cho biết vẫn còn một ngày nghỉ. dùng まだあります.', _utf8mb4'{"options":{"A":"もう終わりました","B":"まだありません","C":"もうありません","D":"まだあります"},"correctAnswer":"D"}'
    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'Hai bạn hỏi còn vé không. Người bán đáp「まだあります」。Câu này cho biết điều gì?', _utf8mb4'まだ nối với あります khẳng định vé vẫn còn ở thời điểm hỏi.', _utf8mb4'{"options":{"A":"Vé chưa từng được bán","B":"Hiện vẫn còn vé","C":"Vé vừa bán hết","D":"Chỉ ngày mai mới có vé"},"correctAnswer":"B"}'
    UNION ALL SELECT 10, _utf8mb4'MEDIUM', _utf8mb4'店員「これが最後の一個でした。店にも倉庫にも（　）。」', _utf8mb4'最後の一個 và hai địa điểm đều hết đòi hỏi もうありません.', _utf8mb4'{"options":{"A":"もうありません","B":"もうあります","C":"まだ残っています","D":"まだあります"},"correctAnswer":"A"}'
    UNION ALL SELECT 11, _utf8mb4'MEDIUM', _utf8mb4'コップを全部洗いました。洗うコップは（　）。', _utf8mb4'Đã rửa hết nên không còn cốc cần rửa. dùng もうありません.', _utf8mb4'{"options":{"A":"まだあります","B":"まだ残っています","C":"もうありません","D":"もうあります"},"correctAnswer":"C"}'
    UNION ALL SELECT 12, _utf8mb4'MEDIUM', _utf8mb4'A：牛乳を入れましょうか。B：さっき全部使ったので、（　）。', _utf8mb4'全部使った cho biết sữa đã hết. もう với phủ định chỉ không còn nữa.', _utf8mb4'{"options":{"A":"もうあります","B":"もうありません","C":"まだあります","D":"まだ残っています"},"correctAnswer":"B"}'
    UNION ALL SELECT 13, _utf8mb4'MEDIUM', _utf8mb4'冷蔵庫を全部見ました。朝買った卵が二つ残っています。卵は（　）。', _utf8mb4'残っています xác nhận trứng vẫn còn, dùng まだ＋khẳng định.', _utf8mb4'{"options":{"A":"まだあります","B":"まだありません","C":"もうありません","D":"もうなくなりました"},"correctAnswer":"A"}'
    UNION ALL SELECT 14, _utf8mb4'MEDIUM', _utf8mb4'借りた本を全部返しました。私の手元には借りた本が（　）。', _utf8mb4'Đã trả tất cả nên hiện không còn sách mượn. もう đi với phủ định.', _utf8mb4'{"options":{"A":"もうありません","B":"まだ残っています","C":"もうあります","D":"まだあります"},"correctAnswer":"A"}'
    UNION ALL SELECT 15, _utf8mb4'MEDIUM', _utf8mb4'出発まであと十分。急がなくても時間は（　）。', _utf8mb4'あと十分 báo vẫn còn thời gian. まだあります diễn tả sự tiếp tục.', _utf8mb4'{"options":{"A":"もうありません","B":"まだありません","C":"まだあります","D":"もうなくなりました"},"correctAnswer":"C"}'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'棚は空です。昨日ここにあったかばんは（　）。', _utf8mb4'Kệ hiện trống sau khi từng có túi. もうありません diễn tả sự thay đổi.', _utf8mb4'{"options":{"A":"まだ残っています","B":"もうありません","C":"もうあります","D":"まだあります"},"correctAnswer":"B"}'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'A：今日はもう宿題がありませんか。B：いいえ、漢字の練習が（　）。', _utf8mb4'いいえ phủ định nhận xét đã hết bài. học viên vẫn còn bài kanji.', _utf8mb4'{"options":{"A":"もう終わりました","B":"まだありません","C":"もうありません","D":"まだあります"},"correctAnswer":"D"}'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'新しい箱を開ける前に見てください。古い箱に電池が（　）あります。二本です。', _utf8mb4'Hai viên hiện vẫn còn trong hộp cũ, nên dùng まだ với あります.', _utf8mb4'{"options":{"A":"もうすぐ","B":"まだに","C":"まだ","D":"まもなく"},"correctAnswer":"C"}'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để báo đã hết bánh sau khi bán chiếc cuối.', _utf8mb4'Khi số lượng từ có chuyển thành hết, dùng もうありません.', _utf8mb4'{"options":{"A":"最後のケーキも売れました。まだ残っています。","B":"最後のケーキも売れました。まだあります。","C":"最後のケーキも売れました。もうあります。","D":"最後のケーキも売れました。もうありません。"},"correctAnswer":"D"}'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'机の上は空です。さっきあった新聞は（　）ありません。全部片付けました。', _utf8mb4'Trước có báo, hiện đã dọn hết. もう＋phủ định có nghĩa không còn nữa.', _utf8mb4'{"options":{"A":"まだ","B":"もう","C":"そろそろ","D":"これから"},"correctAnswer":"B"}'
    UNION ALL SELECT 1005, _utf8mb4'EASY', _utf8mb4'全部売れました。在庫（　）もうありません。', _utf8mb4'は nêu mặt hàng để nói còn hay hết. ở đây まだ／もう cho biết tình trạng.', _utf8mb4'{"options":{"A":"は","B":"を","C":"に","D":"で"},"correctAnswer":"A"}'
    UNION ALL SELECT 1010, _utf8mb4'MEDIUM', _utf8mb4'パンは売り切れですが、おにぎり（　）まだあります。', _utf8mb4'は nêu mặt hàng để nói còn hay hết. ở đây まだ／もう cho biết tình trạng.', _utf8mb4'{"options":{"A":"で","B":"は","C":"を","D":"に"},"correctAnswer":"B"}'
    UNION ALL SELECT 1015, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu đúng để báo vẫn còn hai phòng trống.', _utf8mb4'Còn phòng trống ở hiện tại, nên dùng まだあります.', _utf8mb4'{"options":{"A":"部屋は二つ空いています。空きはもうありません。","B":"部屋は二つ空いています。空きはまだありません。","C":"部屋は二つ空いています。空きはまだあります。","D":"部屋は二つ空いています。空きはもうなくなりました。"},"correctAnswer":"C"}'
    UNION ALL SELECT 1020, _utf8mb4'EASY', _utf8mb4'切符は十枚のうち八枚売れました。あと二枚（　）。', _utf8mb4'Còn hai vé, dùng まだ với thể khẳng định あります.', _utf8mb4'{"options":{"A":"もうありませんでした","B":"まだありません","C":"もうありません","D":"まだあります"},"correctAnswer":"D"}'
    UNION ALL SELECT 1025, _utf8mb4'MEDIUM', _utf8mb4'A：昨日はパンがありましたね。今日も買えますか。B：売り切れです。（　）。', _utf8mb4'売り切れ xác nhận đã bán hết, trả lời bằng もうありません.', _utf8mb4'{"options":{"A":"まだ残っています","B":"もうありません","C":"まだあります","D":"もうあります"},"correctAnswer":"B"}'
    UNION ALL SELECT 1030, _utf8mb4'MEDIUM', _utf8mb4'きょうは月曜で、休みは水曜までです。休みは（　）あります。あと二日です。', _utf8mb4'Hai ngày nghỉ còn lại là tình trạng tiếp diễn, biểu thị bằng まだあります.', _utf8mb4'{"options":{"A":"まで","B":"もうすぐ","C":"から","D":"まだ"},"correctAnswer":"D"}'
    UNION ALL SELECT 1035, _utf8mb4'EASY', _utf8mb4'水は全部飲みました。びんの中には（　）。', _utf8mb4'全部飲みました cho biết nước đã hết. dùng もう＋phủ định.', _utf8mb4'{"options":{"A":"まだあります","B":"もうありません","C":"まだありました","D":"もうあります"},"correctAnswer":"B"}'
    UNION ALL SELECT 1040, _utf8mb4'MEDIUM', _utf8mb4'A：缶ジュースはこれで最後ですか。B：いいえ。冷蔵庫に二本（　）。', _utf8mb4'いいえ và hai lon trong tủ cho biết nước vẫn còn.', _utf8mb4'{"options":{"A":"まだありません","B":"もうなくなりました","C":"まだあります","D":"もうありません"},"correctAnswer":"C"}'
    UNION ALL SELECT 1045, _utf8mb4'MEDIUM', _utf8mb4'出発前には席がありましたが、今は満席です。空いている席は（　）ありません。', _utf8mb4'Từ còn chỗ sang hết chỗ, dùng もうありません để nói không còn nữa.', _utf8mb4'{"options":{"A":"もう","B":"もうすぐ","C":"そろそろ","D":"まだ"},"correctAnswer":"A"}'
    UNION ALL SELECT 1050, _utf8mb4'EASY', _utf8mb4'売り場に赤い花が三本残っています。赤い花は（　）。', _utf8mb4'残っています cho biết hoa vẫn còn. まだ＋あります phù hợp.', _utf8mb4'{"options":{"A":"まだあります","B":"もうありません","C":"まだありません","D":"もうなくなりました"},"correctAnswer":"A"}'
    UNION ALL SELECT 2015, _utf8mb4'MEDIUM', _utf8mb4'「何がまだありますか。」「入り口の箱にタオル（　）まだあります。」', _utf8mb4'が đánh dấu thứ còn lại khi trả lời câu hỏi 何がまだありますか.', _utf8mb4'{"options":{"A":"へ","B":"で","C":"を","D":"が"},"correctAnswer":"D"}'
    UNION ALL SELECT 2030, _utf8mb4'MEDIUM', _utf8mb4'二階にいすがまだあります。一階に（　）まだあります。', _utf8mb4'も thêm một trường hợp có cùng tình trạng còn hoặc hết như trường hợp vừa nêu.', _utf8mb4'{"options":{"A":"も","B":"から","C":"へ","D":"を"},"correctAnswer":"A"}'
    UNION ALL SELECT 2045, _utf8mb4'EASY', _utf8mb4'紙がもうありません。封筒（　）もうありません。', _utf8mb4'も thêm một trường hợp có cùng tình trạng còn hoặc hết như trường hợp vừa nêu.', _utf8mb4'{"options":{"A":"を","B":"から","C":"も","D":"へ"},"correctAnswer":"C"}'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'GRAMMAR' AND l.lesson_no = 3
                AND l.display_order = 15 AND l.status = 'PUBLISHED'
JOIN grammar AS g ON g.lesson_id = l.id AND g.status = 'PUBLISHED'
                 AND CAST(g.structure_name AS BINARY) = CAST(_utf8mb4'まだあります／もうありません。' AS BINARY)
LEFT JOIN question AS existing ON existing.skill = 'GRAMMAR'
                              AND existing.grammar_id = g.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
ORDER BY s.display_order;

-- KANJI — dữ liệu câu hỏi theo bài.

-- JPD113 / Chương 1 / KANJI / Bài 1 / Nhóm 1
INSERT INTO question (skill, question_type, lesson_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'KANJI', 'MCQ', l.id, s.content, s.explanation,
       CAST(s.answers AS JSON),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, _utf8mb4'「私」 (tôi) được đọc như thế nào bằng hiragana?' AS content, _utf8mb4'私 (わたし) nghĩa là “tôi”.' AS explanation, _utf8mb4'{"options":["にほんじん","わたし","わたしのほん","しりつだいがく"],"correctAnswer":"わたし"}' AS answers, _utf8mb4'私' AS source_kanji
    UNION ALL SELECT 2, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「わたしのほん」 với nghĩa “sách của tôi”.', _utf8mb4'私の本 (わたしのほん) nghĩa là “sách của tôi”.', _utf8mb4'{"options":["私の学校","外国人","私の本","私立"],"correctAnswer":"私の本"}', _utf8mb4'本'
    UNION ALL SELECT 3, _utf8mb4'EASY', _utf8mb4'「私立」 có nghĩa gì trong tiếng Việt?', _utf8mb4'私立 (しりつ) nghĩa là “tư thục”.', _utf8mb4'{"options":["đại học tư thục","lữ khách","người Việt","tư thục"],"correctAnswer":"tư thục"}', _utf8mb4'私'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'Điền chữ Hán vào ô □ trong 「私立大□」 để được từ đọc là 「しりつだいがく」 (đại học tư thục).', _utf8mb4'私立大学 (しりつだいがく) nghĩa là “đại học tư thục”.', _utf8mb4'{"options":["学","生","校","日"],"correctAnswer":"学"}', _utf8mb4'学'
    UNION ALL SELECT 5, _utf8mb4'HARD', _utf8mb4'Chọn cách đọc lần lượt của 「私の学校」 và 「学校」.', _utf8mb4'私の学校 (わたしのがっこう) nghĩa là “trường của tôi”. 学校 (がっこう) nghĩa là “trường học”.', _utf8mb4'{"options":["がっこう ／ わたしのがっこう","わたしのがっこう ／ がっこう","わたしのがっこう ／ たびびと","にほんじん ／ がっこう"],"correctAnswer":"わたしのがっこう ／ がっこう"}', _utf8mb4'校'
    UNION ALL SELECT 6, _utf8mb4'HARD', _utf8mb4'Hai từ nào lần lượt mang nghĩa “lữ khách” và “đại học”?', _utf8mb4'旅人 (たびびと) nghĩa là “lữ khách”. 大学 (だいがく) nghĩa là “đại học”.', _utf8mb4'{"options":["外国人 ／ 大学","大学 ／ 旅人","旅人 ／ 大学","旅人 ／ 人口"],"correctAnswer":"旅人 ／ 大学"}', _utf8mb4'人'
