    UNION ALL SELECT 4, _utf8mb4'EASY', _utf8mb4'「来客」 có nghĩa gì trong tiếng Việt?', _utf8mb4'来客 (らいきゃく) nghĩa là “khách đến thăm”.', _utf8mb4'{"options":["khách đến thăm","việc về nước","việc trở về nhà","địa điểm tổ chức sự kiện"],"correctAnswer":"khách đến thăm"}', _utf8mb4'来'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'Điền chữ Hán vào ô □ trong 「□国」 để được từ đọc là 「きこく」 (việc về nước).', _utf8mb4'帰国 (きこく) nghĩa là “việc về nước”.', _utf8mb4'{"options":["聞","帰","会","社"],"correctAnswer":"帰"}', _utf8mb4'帰'
