    UNION ALL SELECT 9, _utf8mb4'MEDIUM', _utf8mb4'Chọn cách viết của 「かいしゃ」 với nghĩa “công ty”.', _utf8mb4'会社 (かいしゃ) nghĩa là “công ty”.', _utf8mb4'{"options":["本社","会社","会話","飲み会"],"correctAnswer":"会社"}', _utf8mb4'会'
