    UNION ALL SELECT 1054, _utf8mb4'EASY', _utf8mb4'「焼き肉」 (thịt nướng) được đọc như thế nào bằng hiragana?', _utf8mb4'焼き肉 (やきにく) nghĩa là “thịt nướng”.', _utf8mb4'{"options":["にくや","きんにく","ゆうりょう","やきにく"],"correctAnswer":"やきにく"}', _utf8mb4'肉'
