    UNION ALL SELECT 2046, _utf8mb4'EASY', _utf8mb4'「小学生」 có nghĩa gì trong tiếng Việt?', _utf8mb4'小学生 (しょうがくせい) nghĩa là “học sinh tiểu học”.', _utf8mb4'{"options":["giọng nói nhỏ","chim nhỏ","thịt gà","học sinh tiểu học"],"correctAnswer":"học sinh tiểu học"}', _utf8mb4'小'
    UNION ALL SELECT 2047, _utf8mb4'MEDIUM', _utf8mb4'Điền chữ Hán vào ô □ trong 「□声」 để được từ đọc là 「こごえ」 (giọng nói nhỏ).', _utf8mb4'小声 (こごえ) nghĩa là “giọng nói nhỏ”.', _utf8mb4'{"options":["小","肉","料","理"],"correctAnswer":"小"}', _utf8mb4'小'
    UNION ALL SELECT 2048, _utf8mb4'HARD', _utf8mb4'Chọn cách đọc lần lượt của 「小雨」 và 「入場料」.', _utf8mb4'小雨 (こさめ) nghĩa là “mưa nhỏ”. 入場料 (にゅうじょうりょう) nghĩa là “phí vào cửa”.', _utf8mb4'{"options":["にゅうじょうりょう ／ こさめ","こさめ ／ にゅうじょうりょう","こさめ ／ ことり","ぎゅうにく ／ にゅうじょうりょう"],"correctAnswer":"こさめ ／ にゅうじょうりょう"}', _utf8mb4'小'
    UNION ALL SELECT 2049, _utf8mb4'HARD', _utf8mb4'Hai từ nào lần lượt mang nghĩa “chim nhỏ” và “miễn phí”?', _utf8mb4'小鳥 (ことり) nghĩa là “chim nhỏ”. 無料 (むりょう) nghĩa là “miễn phí”.', _utf8mb4'{"options":["豚肉 ／ 無料","無料 ／ 小鳥","小鳥 ／ 無料","小鳥 ／ 小説"],"correctAnswer":"小鳥 ／ 無料"}', _utf8mb4'小'
    UNION ALL SELECT 2050, _utf8mb4'EASY', _utf8mb4'「小説」 (tiểu thuyết) được đọc như thế nào bằng hiragana?', _utf8mb4'小説 (しょうせつ) nghĩa là “tiểu thuyết”.', _utf8mb4'{"options":["ぎゅうにく","とりにく","きんにく","しょうせつ"],"correctAnswer":"しょうせつ"}', _utf8mb4'小'
) AS s
JOIN course AS c ON c.code = _utf8mb4'JPD123' COLLATE utf8mb4_unicode_ci
JOIN chapter AS ch ON ch.course_id = c.id AND ch.chapter_no = 7
JOIN lesson AS l ON l.chapter_id = ch.id AND l.skill_type = 'KANJI' AND l.lesson_no = 1
LEFT JOIN question AS existing ON existing.skill = 'KANJI'
                              AND existing.lesson_id = l.id
                              AND existing.display_order = s.display_order
                              AND existing.is_exercise_question = (s.display_order < 1000)
WHERE existing.id IS NULL
  AND EXISTS (SELECT 1 FROM kanji AS k WHERE k.lesson_id = l.id
              AND CAST(k.character_text AS BINARY) = CAST(s.source_kanji AS BINARY))
ORDER BY s.display_order;

-- TỪ VỰNG — dữ liệu câu hỏi theo bài.

-- JPD113 / Chương 1 / TỪ VỰNG / Bài 1 / Nhóm 1
INSERT INTO question (skill, question_type, lesson_id, content, explanation, answer_data,
                      difficulty, is_exercise_question, display_order, status)
SELECT 'VOCABULARY', 'MCQ', l.id, s.content, s.explanation,
       JSON_SET(s.answers, '$.sourceVocabularyId', v.id),
       s.difficulty, s.display_order < 1000, s.display_order, 'ACTIVE'
FROM (
    SELECT 1 AS display_order, _utf8mb4'EASY' AS difficulty, _utf8mb4'Từ 「ベトナム」 có nghĩa là gì?' AS content, _utf8mb4'「ベトナム」 nghĩa là “Việt Nam”. ハノイはベトナムの首都です。 — Hà Nội là thủ đô của Việt Nam.' AS explanation, _utf8mb4'{"options":["Thái Lan","Trung Quốc","Việt Nam","Hàn Quốc"],"correctAnswer":"Việt Nam"}' AS answers, _utf8mb4'ベトナム' AS source_word
    UNION ALL SELECT 2, _utf8mb4'EASY', _utf8mb4'Từ nào trong bài có nghĩa là “Nhật Bản”?', _utf8mb4'「にほん」 nghĩa là “Nhật Bản”. 富士山はにほんにあります。 — Núi Phú Sĩ nằm ở Nhật Bản.', _utf8mb4'{"options":["にほん","タイ","ちゅうごく","ロシア"],"correctAnswer":"にほん"}', _utf8mb4'にほん'
    UNION ALL SELECT 3, _utf8mb4'MEDIUM', _utf8mb4'Điền từ thích hợp vào câu 「ニューヨークは＿にあります。」 theo nghĩa “New York nằm ở Mỹ.”', _utf8mb4'「アメリカ」 nghĩa là “Mỹ”. ニューヨークはアメリカにあります。 — New York nằm ở Mỹ.', _utf8mb4'{"options":["ロシア","ベトナム","アメリカ","ちゅうごく"],"correctAnswer":"アメリカ"}', _utf8mb4'アメリカ'
    UNION ALL SELECT 4, _utf8mb4'MEDIUM', _utf8mb4'Câu 「ローマはイタリアの首都です。」 có nghĩa là gì?', _utf8mb4'「イタリア」 nghĩa là “Ý”. ローマはイタリアの首都です。 — Roma là thủ đô của Ý.', _utf8mb4'{"options":["Roma là thủ đô của Ý.","Moskva là thủ đô của Nga.","Hà Nội là thủ đô của Việt Nam.","Núi Phú Sĩ nằm ở Nhật Bản."],"correctAnswer":"Roma là thủ đô của Ý."}', _utf8mb4'イタリア'
    UNION ALL SELECT 5, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu tiếng Nhật diễn đạt đúng ý “Tôi sang Úc để xem gấu koala.”', _utf8mb4'「オーストラリア」 nghĩa là “Úc”. コアラを見にオーストラリアへ行きます。 — Tôi sang Úc để xem gấu koala.', _utf8mb4'{"options":["ハノイはベトナムの首都です。","富士山はにほんにあります。","ニューヨークはアメリカにあります。","コアラを見にオーストラリアへ行きます。"],"correctAnswer":"コアラを見にオーストラリアへ行きます。"}', _utf8mb4'オーストラリア'
    UNION ALL SELECT 6, _utf8mb4'MEDIUM', _utf8mb4'Hai từ 「かんこく」 và 「タイ」 lần lượt có nghĩa là gì?', _utf8mb4'① 「かんこく」: Hàn Quốc. ② 「タイ」: Thái Lan.', _utf8mb4'{"options":["Thái Lan / Hàn Quốc","Hàn Quốc / Thái Lan","Nhật Bản / Thái Lan","Hàn Quốc / Mỹ"],"correctAnswer":"Hàn Quốc / Thái Lan"}', _utf8mb4'かんこく'
    UNION ALL SELECT 7, _utf8mb4'MEDIUM', _utf8mb4'Chọn hai từ tiếng Nhật lần lượt tương ứng với “Thái Lan” và “Trung Quốc”.', _utf8mb4'① 「タイ」: Thái Lan. ② 「ちゅうごく」: Trung Quốc.', _utf8mb4'{"options":["アメリカ / ちゅうごく","タイ / イタリア","ちゅうごく / タイ","タイ / ちゅうごく"],"correctAnswer":"タイ / ちゅうごく"}', _utf8mb4'タイ'
    UNION ALL SELECT 8, _utf8mb4'HARD', _utf8mb4'Giải nghĩa hai từ trong ngoặc vuông theo thứ tự. ① ペキンは［ちゅうごく］の首都です。 ② ハノイは［ベトナム］の首都です。', _utf8mb4'① 「ちゅうごく」: Trung Quốc. ② 「ベトナム」: Việt Nam.', _utf8mb4'{"options":["Việt Nam / Trung Quốc","Trung Quốc / Việt Nam","Ý / Việt Nam","Trung Quốc / Úc"],"correctAnswer":"Trung Quốc / Việt Nam"}', _utf8mb4'ちゅうごく'
    UNION ALL SELECT 9, _utf8mb4'HARD', _utf8mb4'Điền hai từ theo đúng thứ tự. ① モスクワは＿の首都です。 (Moskva là thủ đô của Nga.) ② 富士山は＿にあります。 (Núi Phú Sĩ nằm ở Nhật Bản.)', _utf8mb4'① 「ロシア」: Nga. ② 「にほん」: Nhật Bản.', _utf8mb4'{"options":["ロシア / にほん","オーストラリア / にほん","ロシア / かんこく","にほん / ロシア"],"correctAnswer":"ロシア / にほん"}', _utf8mb4'ロシア'
    UNION ALL SELECT 10, _utf8mb4'HARD', _utf8mb4'Giải nghĩa hai từ trong ngoặc vuông theo thứ tự. ① 妹は四月から［こうこう］に通います。 ② この図書館は［がくせい］なら無料で使えます。', _utf8mb4'① 「こうこう」: trường trung học phổ thông. ② 「がくせい」: học sinh, sinh viên.', _utf8mb4'{"options":["trường trung học phổ thông / nhân viên ngân hàng","học sinh, sinh viên / trường trung học phổ thông","trường trung học phổ thông / học sinh, sinh viên","nhân viên công ty / học sinh, sinh viên"],"correctAnswer":"trường trung học phổ thông / học sinh, sinh viên"}', _utf8mb4'こうこう'
    UNION ALL SELECT 11, _utf8mb4'HARD', _utf8mb4'Điền hai từ theo đúng thứ tự. ① 兄は＿でけいざいを勉強しています。 (Anh trai tôi học kinh tế ở trường đại học.) ② わからないところを＿に質問しました。 (Tôi hỏi thầy giáo phần mình chưa hiểu.)', _utf8mb4'① 「だいがく」: trường đại học. ② 「せんせい」: giáo viên.', _utf8mb4'{"options":["だいがく / せんせい","ぎんこういん / せんせい","だいがく / いしゃ","せんせい / だいがく"],"correctAnswer":"だいがく / せんせい"}', _utf8mb4'だいがく'
    UNION ALL SELECT 12, _utf8mb4'HARD', _utf8mb4'Chọn bản dịch đúng cho cả hai câu. ① 来月から東京のにほんごがっこうで日本語を勉強します。 ② 父はぎんこういんで、毎日銀行の窓口で働いています。', _utf8mb4'① 「にほんごがっこう」: trường tiếng Nhật. ② 「ぎんこういん」: nhân viên ngân hàng.', _utf8mb4'{"options":["Từ tháng sau tôi học tiếng Nhật ở một trường tiếng Nhật tại Tokyo. / Sở thích của tôi là sưu tầm tem.","Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch. / Từ tháng sau tôi học tiếng Nhật ở một trường tiếng Nhật tại Tokyo.","Từ tháng sau tôi học tiếng Nhật ở một trường tiếng Nhật tại Tokyo. / Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch.","Vì sốt cao nên tôi đã đi khám bác sĩ. / Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch."],"correctAnswer":"Từ tháng sau tôi học tiếng Nhật ở một trường tiếng Nhật tại Tokyo. / Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch."}', _utf8mb4'にほんごがっこう'
    UNION ALL SELECT 13, _utf8mb4'HARD', _utf8mb4'Chọn hai câu tiếng Nhật phù hợp theo thứ tự. ① Sinh viên được sử dụng thư viện này miễn phí. ② Vì sốt cao nên tôi đã đi khám bác sĩ.', _utf8mb4'① 「がくせい」: học sinh, sinh viên. ② 「いしゃ」: bác sĩ.', _utf8mb4'{"options":["熱が高いので、いしゃに診てもらいました。 / この図書館はがくせいなら無料で使えます。","この図書館はがくせいなら無料で使えます。 / 熱が高いので、いしゃに診てもらいました。","私のしゅみは切手を集めることです。 / 熱が高いので、いしゃに診てもらいました。","この図書館はがくせいなら無料で使えます。 / 放課後、友達と運動場でサッカーをします。"],"correctAnswer":"この図書館はがくせいなら無料で使えます。 / 熱が高いので、いしゃに診てもらいました。"}', _utf8mb4'がくせい'
    UNION ALL SELECT 14, _utf8mb4'EASY', _utf8mb4'Từ 「せんせい」 có nghĩa là gì?', _utf8mb4'「せんせい」 nghĩa là “giáo viên”. わからないところをせんせいに質問しました。 — Tôi hỏi thầy giáo phần mình chưa hiểu.', _utf8mb4'{"options":["bóng đá","quần vợt","bơi lội","giáo viên"],"correctAnswer":"giáo viên"}', _utf8mb4'せんせい'
    UNION ALL SELECT 15, _utf8mb4'EASY', _utf8mb4'Từ nào trong bài có nghĩa là “giáo viên, nhà giáo”?', _utf8mb4'「きょうし」 nghĩa là “giáo viên, nhà giáo”. 母の職業は高校のきょうしです。 — Mẹ tôi làm nghề giáo viên trung học phổ thông.', _utf8mb4'{"options":["すいえい","きょうし","サッカー","テニス"],"correctAnswer":"きょうし"}', _utf8mb4'きょうし'
    UNION ALL SELECT 16, _utf8mb4'MEDIUM', _utf8mb4'Điền từ thích hợp vào câu 「兄は商社で働く＿です。」 theo nghĩa “Anh trai tôi là nhân viên của một công ty thương mại.”', _utf8mb4'「かいしゃいん」 nghĩa là “nhân viên công ty”. 兄は商社で働くかいしゃいんです。 — Anh trai tôi là nhân viên của một công ty thương mại.', _utf8mb4'{"options":["テニス","すいえい","えいが","かいしゃいん"],"correctAnswer":"かいしゃいん"}', _utf8mb4'かいしゃいん'
    UNION ALL SELECT 17, _utf8mb4'MEDIUM', _utf8mb4'Câu 「父はぎんこういんで、毎日銀行の窓口で働いています。」 có nghĩa là gì?', _utf8mb4'「ぎんこういん」 nghĩa là “nhân viên ngân hàng”. 父はぎんこういんで、毎日銀行の窓口で働いています。 — Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch.', _utf8mb4'{"options":["Hôm qua tôi xem một bộ phim cùng bạn.","Tôi hay nghe nhạc trên tàu.","Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch.","Kỳ nghỉ hè tôi học bơi ở bể bơi."],"correctAnswer":"Bố tôi là nhân viên ngân hàng, hằng ngày làm việc ở quầy giao dịch."}', _utf8mb4'ぎんこういん'
    UNION ALL SELECT 18, _utf8mb4'MEDIUM', _utf8mb4'Chọn câu tiếng Nhật diễn đạt đúng ý “Vì sốt cao nên tôi đã đi khám bác sĩ.”', _utf8mb4'「いしゃ」 nghĩa là “bác sĩ”. 熱が高いので、いしゃに診てもらいました。 — Vì sốt cao nên tôi đã đi khám bác sĩ.', _utf8mb4'{"options":["熱が高いので、いしゃに診てもらいました。","きのう友達とえいがを一本見ました。","電車の中でよくおんがくを聞きます。","休みに家族と京都へりょこうに行きます。"],"correctAnswer":"熱が高いので、いしゃに診てもらいました。"}', _utf8mb4'いしゃ'
    UNION ALL SELECT 19, _utf8mb4'MEDIUM', _utf8mb4'Hai từ 「しゅみ」 và 「サッカー」 lần lượt có nghĩa là gì?', _utf8mb4'① 「しゅみ」: sở thích. ② 「サッカー」: bóng đá.', _utf8mb4'{"options":["sở thích / du lịch","bóng đá / sở thích","sở thích / bóng đá","âm nhạc / bóng đá"],"correctAnswer":"sở thích / bóng đá"}', _utf8mb4'しゅみ'
    UNION ALL SELECT 20, _utf8mb4'MEDIUM', _utf8mb4'Chọn hai từ tiếng Nhật lần lượt tương ứng với “bóng đá” và “quần vợt”.', _utf8mb4'① 「サッカー」: bóng đá. ② 「テニス」: quần vợt.', _utf8mb4'{"options":["サッカー / テニス","りょこう / テニス","サッカー / どくしょ","テニス / サッカー"],"correctAnswer":"サッカー / テニス"}', _utf8mb4'サッカー'
    UNION ALL SELECT 21, _utf8mb4'HARD', _utf8mb4'Giải nghĩa hai từ trong ngoặc vuông theo thứ tự. ① 日曜日はラケットを持って［テニス］をしに行きます。 ② きのう友達と［えいが］を一本見ました。', _utf8mb4'① 「テニス」: quần vợt. ② 「えいが」: phim.', _utf8mb4'{"options":["đọc sách / phim","quần vợt / nấu ăn, món ăn","phim / quần vợt","quần vợt / phim"],"correctAnswer":"quần vợt / phim"}', _utf8mb4'テニス'
    UNION ALL SELECT 22, _utf8mb4'HARD', _utf8mb4'Điền hai từ theo đúng thứ tự. ① 夏休みにプールで＿を習います。 (Kỳ nghỉ hè tôi học bơi ở bể bơi.) ② 電車の中でよく＿を聞きます。 (Tôi hay nghe nhạc trên tàu.)', _utf8mb4'① 「すいえい」: bơi lội. ② 「おんがく」: âm nhạc.', _utf8mb4'{"options":["おんがく / すいえい","すいえい / おんがく","りょうり / おんがく","すいえい / こうこう"],"correctAnswer":"すいえい / おんがく"}', _utf8mb4'すいえい'
    UNION ALL SELECT 23, _utf8mb4'HARD', _utf8mb4'Giải nghĩa hai từ trong ngoặc vuông theo thứ tự. ① きのう友達と［えいが］を一本見ました。 ② 雨の日は家で［どくしょ］を楽しみます。', _utf8mb4'① 「えいが」: phim. ② 「どくしょ」: đọc sách.', _utf8mb4'{"options":["trường trung học phổ thông / đọc sách","phim / trường đại học","đọc sách / phim","phim / đọc sách"],"correctAnswer":"phim / đọc sách"}', _utf8mb4'えいが'
